# ★ AI Provider 統一介面(v1.0 2026-05-15)
class _AIProxy:
    """Drop-in replacement for ai.chat.completions.create().
    文字翻譯由 ai_provider 自動路由到 OpenAI、Claude 或 Gemini。
    """
    class _Chat:
        class _Completions:
            @staticmethod
            def create(**kwargs):
                return ai_provider.chat_complete(**kwargs)
        completions = _Completions()
    chat = _Chat()

    class _Audio:
        class _Transcriptions:
            @staticmethod
            def create(model, file, **kwargs):
                # 音訊轉文字:Anthropic 不支援,active=anthropic 時拋例外讓上層 catch
                if ai_provider.get_active_provider() == "anthropic":
                    raise NotImplementedError(
                        "Anthropic 不支援語音轉文字,請切回 OpenAI 或回覆用戶改用文字"
                    )
                if oai is None:
                    raise RuntimeError("OpenAI client 未初始化(OPENAI_API_KEY 缺?)")
                # v3.21 治本:原寫 ai.audio...(呼叫自己=無限遞迴),改用原生 oai client。
                # Gemini active 時語音轉文字也照常走 OpenAI(gpt-4o-transcribe)。
                return oai.audio.transcriptions.create(model=model, file=file, **kwargs)
        transcriptions = _Transcriptions()
    audio = _Audio()

ai = _AIProxy()


def _has_ai_capability(capability="chat"):
    """統一判斷三家 AI 是否至少有一家可提供指定能力。"""
    try:
        return ai_provider.has_available_provider(capability)
    except Exception as exc:
        logger.warning("AI capability check failed (%s): %s", capability, exc)
        return False

