def _set_translation_outcome(status, reason="", **details):
    """Record the semantic outcome of the current translation attempt.

    ``None`` historically represented two incompatible states: a genuine
    translation failure and an intentional no-translation decision (currently
    used for pure equipment-code messages).  LINE's visible-failure boundary
    cannot safely infer which state occurred from the return value alone.  Keep
    the public return contract unchanged while carrying an explicit outcome in
    request-local state.
    """
    payload = {
        "status": str(status or "unknown"),
        "reason": str(reason or ""),
    }
    if details:
        payload.update(details)
    _tl.translation_outcome = payload
    return payload


def _get_translation_outcome():
    outcome = getattr(_tl, "translation_outcome", None)
    return dict(outcome) if isinstance(outcome, dict) else {}


def _translation_was_intentionally_skipped():
    return _get_translation_outcome().get("status") == "skipped"

def get_group_tone(group_id):
    """Return (preset, custom_text) for a group."""
    if group_id and group_id in group_tone_settings:
        gs = group_tone_settings[group_id]
        return gs.get("tone", translation_tone), gs.get("custom", "")
    return translation_tone, translation_tone_custom


def _translation_needs_upgrade_model(text):
    """Return True for short requests whose operational risk justifies the quality model.

    Length alone is a weak routing signal: a six-character factory instruction can
    be more consequential than a long casual message.  This local classifier does
    not call an AI and therefore adds effectively no network latency.  It reuses
    the request-wide semantic contract and the existing quality-critical flag,
    then applies only conservative factory/safety structure heuristics.
    """
    source = str(text or "")
    if not source.strip():
        return False

    if bool(getattr(_tl, "quality_gate_critical", False)):
        return True
    contract = getattr(_tl, "semantic_contract", None)
    if isinstance(contract, dict) and (
        contract.get("has_risk") or contract.get("requires_llm")
    ):
        return True

    compact = re.sub(r"\s+", "", source)
    line_count = len([line for line in source.splitlines() if line.strip()])
    # Multi-row instructions and code/measurement-heavy messages are more prone
    # to omissions and deserve the stronger model even when under the char limit.
    technical_atoms = re.findall(
        r"(?:[A-Z]{1,6}[-_/.:]?[A-Z0-9]{1,16}|\d+(?:\.\d+)?(?:mm|cm|kg|g|t|%|°C|℃)?)",
        source,
        re.I,
    )
    if line_count >= 4 or (len(compact) >= 32 and len(technical_atoms) >= 4):
        return True

    # Safety, quality and irreversible-operation messages should not be routed to
    # the cheapest model solely because they are short.
    critical_cues = (
        "禁止", "不得", "務必", "必須", "危險", "安全", "停機", "停線",
        "異常", "報廢", "客訴", "混料", "錯料", "工傷", "立即", "緊急",
        "dilarang", "wajib", "bahaya", "keselamatan", "stop mesin",
        "abnormal", "scrap", "salah material", "segera", "darurat",
    )
    lowered = source.casefold()
    return len(compact) >= 6 and any(cue.casefold() in lowered for cue in critical_cues)


def pick_model(text):
    """v3.32.1: Pick by provider, length and local translation risk.
    
    Anthropic 路徑(切到 Anthropic 且 claude_auto_switch_enabled=True):
      - 字數 < threshold 或 threshold=0 → claude_model_default(預設 Haiku 4.5)
      - 字數 ≥ threshold → claude_model_upgrade(預設 Sonnet 4.6)
    
    OpenAI 路徑(原邏輯):
      - 字數 ≥ threshold → model_upgrade(預設 gpt-5.4)
      - 否則 → model_default(預設 gpt-5.4-mini)
    
    特例:
      - claude_auto_switch_enabled=False 時,Anthropic 路徑仍回傳 OpenAI model name
        → 走 _AIProxy 的 model_mapping 機制(舊「套用模型」單一映射行為)
      - 這給歐那一個 fallback:若新邏輯出問題,後台關掉 toggle 即恢復舊行為
    """
    # v3.13: thread-local 強制模型(translate_multi 並行 fallback 用)。
    # 取代原本 monkey-patch globals()['pick_model'] 的做法 — 那在並行下會互相污染。
    _forced = getattr(_tl, 'force_model', None)
    if _forced:
        return _forced

    # v3.36 translation CP router: keep one canonical OpenAI model name as the
    # cross-provider quality tier.  ai_provider maps that tier to Gemini/OpenAI/
    # Claude per attempt.  Returning provider-specific names here made failover
    # brittle (for example a Gemini model id sent to OpenAI after a failover).
    if os.environ.get("TRANSLATION_CP_ROUTER_ENABLED", "1").strip().lower() not in {
        "0", "false", "off", "no"
    }:
        if (
            model_threshold > 0
            and (len(text) if isinstance(text, str) else 0) >= model_threshold
        ) or _translation_needs_upgrade_model(text):
            return ai_provider.normalize_translation_model(
                model_upgrade, ai_provider.DEFAULT_OPENAI_UPGRADE_MODEL)
        return ai_provider.normalize_translation_model(
            model_default, ai_provider.DEFAULT_OPENAI_MODEL)
    try:
        provider = ai_provider.get_active_provider()
    except Exception:
        provider = "openai"
    # v3.9.33: text 型別安全保護
    text_len = len(text) if isinstance(text, str) else 0
    
    if provider == "anthropic" and claude_auto_switch_enabled:
        # Anthropic 路徑:直接回傳 Claude model name,_AIProxy 看到 claude-* 會原樣使用,不查 mapping
        if model_threshold > 0 and (text_len >= model_threshold or _translation_needs_upgrade_model(text)):
            return claude_model_upgrade
        return claude_model_default

    # v3.21: Gemini 路徑 — 同 Claude 模式,直接回 gemini-* 名稱
    # v3.22: 改讀 ai_provider 後台設定(後台改模型立即生效,不用重啟)
    if provider == "gemini":
        try:
            _g_default, _g_upgrade = ai_provider.get_gemini_models()
        except Exception:
            _g_default, _g_upgrade = gemini_model_default, gemini_model_upgrade
        if model_threshold > 0 and (text_len >= model_threshold or _translation_needs_upgrade_model(text)):
            return _g_upgrade
        return _g_default

    # OpenAI 路徑(或 Anthropic + 關閉自動切換)
    if model_threshold > 0 and (text_len >= model_threshold or _translation_needs_upgrade_model(text)):
        return ai_provider.normalize_translation_model(
            model_upgrade, ai_provider.DEFAULT_OPENAI_UPGRADE_MODEL)
    return ai_provider.normalize_translation_model(
        model_default, ai_provider.DEFAULT_OPENAI_MODEL)


def _translation_provider_preference(text=None, src=None, tgt=None):
    """Strict real-time translation failover order.

    The admin-selected active provider is always first.  With the production
    default (Claude), recovery is Claude -> OpenAI(ChatGPT) -> Gemini.  After an
    automatic quota switch, ai_provider persistently suppresses the depleted
    provider, so subsequent requests start directly from the new primary.
    """
    override = os.environ.get("TRANSLATION_PROVIDER_ORDER", "").strip()
    canonical = ["anthropic", "openai", "gemini"]
    if override:
        requested = [p.strip().lower() for p in override.split(",") if p.strip()]
        valid = [p for p in requested if p in canonical]
        if valid:
            return list(dict.fromkeys(valid + canonical))
    try:
        active = ai_provider.get_active_provider()
    except Exception:
        active = "anthropic"
    if active not in canonical:
        active = "anthropic"
    idx = canonical.index(active)
    return canonical[idx:] + canonical[:idx]


def _active_upgrade_model():
    """Return the quality model for the active OpenAI/Gemini/Claude provider."""
    try:
        provider = ai_provider.get_active_provider()
    except Exception:
        provider = "openai"
    if provider == "anthropic":
        return claude_model_upgrade
    if provider == "gemini":
        try:
            _default, upgrade = ai_provider.get_gemini_models()
            return upgrade
        except Exception:
            return gemini_model_upgrade
    return ai_provider.normalize_translation_model(
        model_upgrade, ai_provider.DEFAULT_OPENAI_UPGRADE_MODEL
    )


def _translation_quality_check(original, translation, back_translation):
    """v3.3 多維度翻譯品質檢查,取代純 Jaccard 相似度。
    
    回傳 (passes, reason, details_dict)
    
    檢查項目:
      1. 譯文長度比 - 譯文/原文,< 0.33 視為災難性壓縮
      2. 反譯長度比 - 反譯/原文,< 0.4 視為譯文丟失資訊
      3. Jaccard 字元相似度
    """
    orig_len = len(re.sub(r"\s+", "", original or ""))
    trans_len = len(re.sub(r"\s+", "", translation or ""))
    back_len = len(re.sub(r"\s+", "", back_translation or ""))
    
    if orig_len == 0:
        return True, "empty_source", {}
    
    details = {"orig_len": orig_len, "trans_len": trans_len, "back_len": back_len}
    
    # 檢查 1:譯文長度比過低 → 必定丟資訊
    trans_ratio = trans_len / orig_len
    details["trans_ratio"] = round(trans_ratio, 3)
    if trans_ratio < 0.33:
        return False, f"catastrophic_compression(ratio={trans_ratio:.2f})", details
    
    # 檢查 2:反譯長度比 - 譯文資訊已丟失
    if back_len > 0:
        back_ratio = back_len / orig_len
        details["back_ratio"] = round(back_ratio, 3)
        if back_ratio < 0.4:
            return False, f"backtrans_too_short(ratio={back_ratio:.2f})", details
    
    # 檢查 3:Jaccard 字元相似度
    if back_translation:
        sim = _text_similarity(original, back_translation)
        details["jaccard"] = round(sim, 3)
        if sim < double_check_threshold:
            return False, f"low_similarity(jaccard={sim:.2f})", details
    
    return True, "ok", details


def _round_trip_check(original_text, translated_text, src_lang, tgt_lang):
    """Compatibility shim: round-trip model calls are disabled permanently."""
    return True, 1.0, ""



