def _mention_has_visible_name(value):
    """Return True when an @mention contains a non-empty visible label."""
    if not isinstance(value, str):
        return False
    value = value.strip()
    if not value.startswith("@"):
        return False
    body = value[1:].strip()
    if ((body.startswith("(") and body.endswith(")"))
            or (body.startswith("（") and body.endswith("）"))):
        body = body[1:-1].strip()
    return bool(body)


def extract_mentions(text):
    """Extract textual @mentions without requiring LINE mention metadata.

    Besides native ``@name`` mentions, workers frequently paste the display-name
    form ``@(杰弗)`` / ``@（杰弗）`` as ordinary text.  The old parser did not
    recognize that form, so the name was sent to the translation model and could
    be deleted while only ``@()`` survived.  Keep the exact source substring.
    """
    if not text or not isinstance(text, str):
        return []
    _id_skip = {
        'tolong','semua','untuk','yang','dan','ini','itu','ada','tidak','akan',
        'sudah','bisa','juga','saya','kami','kita','mereka','dia','apa','belum',
        'sedang','harus','boleh','mau','bukan','jangan','terima','kasih','baik',
        'bagus','benar','salah','kerja','pulang','pergi','karena','tapi','atau',
        'kalau','masih','lagi','nanti','sekarang','siap','izin','minta','cepat',
        'capek','sakit','gak','udah','gimana','dong','banget','kipas','mesin',
        'rusak','bocor','macet','stok','habis','ganti','pasang','gudang','masuk',
        'keluar','tutup','buka','material','selesai','beres','datang','besok',
        'kemarin','libur','lembur','cuti','proses','produksi','diperhatikan',
        'selalu','mohon','pakai','pake','cek','lihat','bilang','ambil','kirim',
        'tunggu','bantu','butuh','perlu','panggil','suruh','hati','awas',
        'bahaya','lantai','mesin','pompa','pipa','oli','besi','baja','batang',
    }
    mentions = []

    # Plain-text LINE-style display names: @(杰弗), @（杰弗）, @(John Doe).
    # Require a non-empty body so a damaged literal @() is never treated as a
    # valid identity-bearing mention.
    for match in re.finditer(
        r'@\((?=[^)\r\n]{1,80}\))(?=[^)\r\n]*\S)[^)\r\n]{1,80}\)'
        r'|@（(?=[^）\r\n]{1,80}）)(?=[^）\r\n]*\S)[^）\r\n]{1,80}）',
        text,
    ):
        mention = match.group(0)
        if _mention_has_visible_name(mention) and mention not in mentions:
            mentions.append(mention)

    # English @mentions: grab @word + up to 2 more, trim Indonesian words from end.
    for m in re.finditer(r'@([A-Za-z0-9][A-Za-z0-9_.-]*)(?:\s+([A-Za-z0-9_.-]+))?(?:\s+([A-Za-z0-9_.-]+))?', text):
        first = m.group(1)
        if first.lower() in _id_skip:
            continue
        # ``@All`` is a reserved LINE broadcast mention, never a person's
        # multi-word display name.  The generic Latin-name parser used to
        # greedily swallow the next two Indonesian words (for example,
        # ``@All Harap perhatikan``), causing those words to bypass translation
        # and sometimes trip the purity/fidelity guards.  Bound it exactly even
        # when webhook mention metadata is absent or malformed.
        if first.lower() == 'all':
            mention = text[m.start():m.start() + len(first) + 1]
            if mention not in mentions:
                mentions.append(mention)
            continue
        parts = [first]
        for g in [m.group(2), m.group(3)]:
            if g and g.lower() not in _id_skip:
                parts.append(g)
            else:
                break
        mention = '@' + ' '.join(parts)
        if mention not in mentions:
            mentions.append(mention)
    # Chinese/Japanese @mentions, optionally followed by a parenthesized role.
    #
    # LINE metadata frequently marks only the CJK part as the actual mention,
    # while workers append the person's Latin display name as plain text, e.g.
    # ``@蘇比 sobirin``.  Protecting only ``@蘇比`` leaves ``sobirin`` inside the
    # translatable sentence.  The Chinese-target purity gate then (correctly for
    # ordinary source words, incorrectly for this name) rejects it as an
    # untranslated Indonesian word.  Extend the textual mention by up to two
    # conservative lowercase Latin name tokens, but stop before common
    # Indonesian sentence words so ``@阿明 jika ...`` never swallows ``jika``.
    for m in re.finditer(
        r'@[\u4e00-\u9fff\u3040-\u30ff]+(?:\s*[\uff08(][^\uff09)]*[\uff09)])?',
        text,
    ):
        end = m.end()
        tail_end = end
        for _ in range(2):
            tail = re.match(r'\s+([a-z][a-z0-9_.-]{1,31})', text[tail_end:])
            if not tail:
                break
            token = tail.group(1)
            _mention_stopwords = _id_skip | set(
                getattr(tqg_module, "_COMMON_ID_WORDS", set()) or set()
            )
            if token.lower() in _mention_stopwords:
                break
            tail_end += tail.end()
        mention = text[m.start():tail_end].rstrip()
        if mention and len(mention) > 1 and mention not in mentions:
            mentions.append(mention)
    # @All
    for m in re.findall(r'@[Aa][Ll][Ll]', text):
        if m not in mentions:
            mentions.append(m)
    return list(dict.fromkeys(mentions))


def _line_span_to_python_indices(text, index, length):
    """Convert a LINE mention span to Python indices.

    LINE documents the values as character positions.  The direct Python slice
    is therefore authoritative.  A UTF-16-code-unit fallback protects against
    webhook producers/SDK versions that count astral emoji as two units.
    """
    try:
        index = int(index)
        length = int(length)
    except (TypeError, ValueError):
        return None
    if index < 0 or length <= 0:
        return None

    direct_end = index + length
    if index <= len(text) and direct_end <= len(text):
        direct = text[index:direct_end]
        if direct.startswith('@'):
            return index, direct_end

    unit_pos = 0
    py_start = py_end = None
    wanted_end = index + length
    for py_idx, char in enumerate(text):
        if unit_pos == index:
            py_start = py_idx
        unit_pos += len(char.encode('utf-16-le')) // 2
        if unit_pos == wanted_end:
            py_end = py_idx + 1
            break
        if unit_pos > wanted_end:
            break
    if py_start is not None and py_end is not None:
        candidate = text[py_start:py_end]
        if candidate.startswith('@'):
            return py_start, py_end

    if index <= len(text):
        return index, min(len(text), direct_end)
    return None


def normalize_line_mentions(text, message, group_id=None):
    """Return ``(normalized_text, exact_mentions)`` from webhook metadata.

    Valid webhook text is preserved byte-for-byte.  If a webhook contains a
    damaged empty shell such as ``@()`` but provides ``userId``, resolve the
    display name from the group profile and repair the text before translation.
    Textual mentions not present in metadata are merged as a fallback.
    """
    if not text or not isinstance(text, str):
        return text or "", []

    edits = []
    metadata_mentions = []
    try:
        mention_data = getattr(message, 'mention', None)
        mentionees = list(getattr(mention_data, 'mentionees', None) or [])
    except Exception:
        mentionees = []

    for mentionee in mentionees:
        span = _line_span_to_python_indices(
            text,
            getattr(mentionee, 'index', None),
            getattr(mentionee, 'length', None),
        )
        if not span:
            continue
        start, end = span
        raw = text[start:end]
        replacement = raw
        mention_type = str(getattr(mentionee, 'type', '') or '').lower()

        if not _mention_has_visible_name(raw):
            if mention_type == 'all':
                replacement = '@All'
            else:
                user_id = (getattr(mentionee, 'user_id', None)
                           or getattr(mentionee, 'userId', None))
                display_name = None
                if user_id:
                    try:
                        display_name = get_display_name(group_id, user_id)
                    except Exception as exc:
                        logger.debug("mention profile lookup failed: %s", exc)
                if display_name:
                    if raw.startswith('@（'):
                        replacement = '@（' + display_name + '）'
                    elif raw.startswith('@('):
                        replacement = '@(' + display_name + ')'
                    else:
                        replacement = '@' + display_name
                else:
                    logger.warning(
                        "[Mention] malformed webhook mention could not be repaired "
                        "group=%s raw=%r type=%s",
                        group_id, raw, mention_type,
                    )

        if replacement != raw:
            edits.append((start, end, replacement))
        if _mention_has_visible_name(replacement) and replacement not in metadata_mentions:
            metadata_mentions.append(replacement)

    normalized = text
    for start, end, replacement in sorted(edits, key=lambda item: item[0], reverse=True):
        normalized = normalized[:start] + replacement + normalized[end:]

    mentions = list(metadata_mentions)
    for mention in extract_mentions(normalized):
        if mention not in mentions:
            mentions.append(mention)
    return normalized, mentions


def extract_line_mentions(text, message, group_id=None):
    """Extract exact mention strings using LINE metadata plus text fallback."""
    _normalized, mentions = normalize_line_mentions(text, message, group_id)
    return mentions


def protect_mentions(text, line_mentions=None):
    """Replace every mention occurrence with a unique stable placeholder."""
    if not text or not isinstance(text, str):
        return text or "", {}

    candidates = []
    for mention in list(line_mentions or []) + extract_mentions(text):
        if (isinstance(mention, str) and mention and mention in text
                and _mention_has_visible_name(mention)
                and mention not in candidates):
            candidates.append(mention)

    # Find all non-overlapping occurrences, preferring the longest mention when
    # one textual mention is a prefix of another.
    spans = []
    occupied = []
    for mention in sorted(candidates, key=len, reverse=True):
        pos = 0
        while True:
            idx = text.find(mention, pos)
            if idx < 0:
                break
            end = idx + len(mention)
            if not any(idx < used_end and end > used_start for used_start, used_end in occupied):
                spans.append((idx, end, mention))
                occupied.append((idx, end))
            pos = end

    spans.sort(key=lambda item: item[0])
    placeholders = {}
    chunks = []
    cursor = 0
    for i, (start, end, mention) in enumerate(spans):
        ph = f"__MENTION_{i}__"
        chunks.append(text[cursor:start])
        chunks.append(ph)
        placeholders[ph] = mention
        cursor = end
    chunks.append(text[cursor:])
    return ''.join(chunks), placeholders


def restore_mentions(text, placeholders):
    restored = text or ""
    index_to_original = {}
    for ph, original in (placeholders or {}).items():
        idx = ph.replace("__MENTION_", "").replace("__", "")
        index_to_original[str(idx)] = original
        variants = [
            ph,
            ph.replace("_", " "),
            ph.replace("__", ""),
            f"MENTION_{idx}",
            f"MENTION {idx}",
            f"__MENTION {idx}__",
            f"[[MENTION_{idx}]]",
            f"__提及_{idx}__",
            f"提及_{idx}",
            f"_提及_{idx}_",
            f"提及{idx}",
            f"__SEBUTAN_{idx}__",
            f"SEBUTAN_{idx}",
            f"__sebutan_{idx}__",
        ]
        for variant in variants:
            restored = restored.replace(variant, original)

    if placeholders:
        def _replace_indexed_residual(match):
            return index_to_original.get(match.group(1), match.group(0))

        restored = re.sub(
            r'_{0,2}提及[_\s]?(\d+)_{0,2}',
            _replace_indexed_residual,
            restored,
        )
        restored = re.sub(
            r'_{0,2}MENTION[_\s]?(\d+)_{0,2}',
            _replace_indexed_residual,
            restored,
            flags=re.IGNORECASE,
        )
        restored = re.sub(
            r'_{0,2}SEBUTAN[_\s]?(\d+)_{0,2}',
            _replace_indexed_residual,
            restored,
            flags=re.IGNORECASE,
        )

    # If a provider removed a placeholder entirely, restore each missing mention
    # instance rather than merely checking whether the name appears once.
    remaining_counts = {}
    for original in (placeholders or {}).values():
        remaining_counts[original] = restored.count(original)
    missing_instances = []
    for original in (placeholders or {}).values():
        if remaining_counts.get(original, 0) > 0:
            remaining_counts[original] -= 1
        else:
            missing_instances.append(original)
    if missing_instances:
        restored = (" ".join(missing_instances) + " " + restored).strip()
    return restored


def _repair_pipeline_identity_placeholders(source_text, candidate):
    """Recover mention and protected-person tokens before quality validation.

    Identity placeholders are application-owned metadata.  Providers may echo
    the visible name, simplify ``__PERSON_1__`` to ``PN`` or remove a token.
    This function canonicalizes those variants and deterministically reinserts
    missing identities.  It never repairs work-order codes, quantities, dates or
    other business data; those remain strict quality-gate failures.
    """
    if not candidate or not isinstance(candidate, str):
        return candidate
    source = str(source_text or "")
    repaired = candidate
    protected_entities = dict(getattr(_tl, "protected_name_map", None) or {})

    # Convert any visible identity echoed from context back to its exact token.
    for token, original in protected_entities.items():
        if token not in source:
            continue
        if isinstance(original, str) and original and original in repaired:
            repaired = repaired.replace(original, token, source.count(token))

    repaired = tqg_module.repair_identity_tokens(source, repaired)
    if repaired != candidate:
        logger.warning(
            "[IdentityRecovery] repaired provider identity tokens before=%r after=%r",
            candidate[:220], repaired[:220],
        )
        try:
            last_translate_debug["identity_recovery_applied"] = True
            last_translate_debug["candidate_after_identity_recovery"] = repaired[:2000]
        except Exception:
            pass
    else:
        try:
            last_translate_debug.setdefault("identity_recovery_applied", False)
        except Exception:
            pass
    return repaired


def _repair_pipeline_mention_placeholders(source_text, candidate):
    """Backward-compatible alias for the unified identity recovery boundary."""
    return _repair_pipeline_identity_placeholders(source_text, candidate)


def strip_mentions_for_detect(text, line_mentions=None):
    """Strip mentions only for language detection, never for translation."""
    if not text or not isinstance(text, str):
        return ""

    clean = text
    candidates = []
    for mention in list(line_mentions or []) + extract_mentions(text):
        if isinstance(mention, str) and mention and mention not in candidates:
            candidates.append(mention)
    for mention in sorted(candidates, key=len, reverse=True):
        clean = clean.replace(mention, ' ')

    _id_skip = {
        'tolong','semua','untuk','yang','dan','ini','itu','ada','tidak','akan',
        'sudah','bisa','juga','saya','kami','kita','mereka','dia','apa','belum',
        'sedang','harus','boleh','mau','bukan','jangan','terima','kasih','baik',
        'kerja','pulang','pergi','karena','tapi','atau','kalau','masih','lagi',
        'siap','izin','minta','capek','sakit','gak','udah','gimana','dong',
        'kipas','mesin','rusak','bocor','macet','stok','habis','ganti','pasang',
        'gudang','masuk','keluar','tutup','buka','material','selesai','beres',
        'datang','besok','kemarin','libur','lembur','cuti','proses','produksi',
        'selalu','mohon','pakai','pake','cek','lihat','bilang','ambil','kirim',
        'tunggu','bantu','butuh','perlu','panggil','suruh','hati','awas',
    }
    def _replace_en(match):
        first_word = re.match(r'@([A-Za-z0-9]+)', match.group(0))
        if first_word and first_word.group(1).lower() in _id_skip:
            return match.group(0)
        return ' '
    clean = re.sub(
        r'@[A-Za-z0-9][A-Za-z0-9 _.-]*(?:\s+[\u4e00-\u9fff]{1,4})?'
        r'(?=(?:\s|[\n,\uff0c\u3002!\uff01?\uff1f:\uff1a;\uff1b()\uff08\uff09\[\]{}<>\u201c\u201d]|$))',
        _replace_en,
        clean,
    )
    clean = re.sub(r'@[\u4e00-\u9fff]+(?:\s*[\uff08(][^\uff09)]*[\uff09)])?', ' ', clean)
    clean = re.sub(r'@\([^)]*\)|@（[^）]*）', ' ', clean)
    return clean


# @mention-only / name-call guard.
#
# Root rule:
#   1. LINE's webhook mention metadata is the authority for real blue @mentions.
#   2. Plain text after the mention is considered a name ONLY when it exactly
#      matches a protected name or a cached LINE group display name.
#   3. Never infer "1~4 Chinese characters == a person name".  That heuristic
#      silently swallowed valid factory messages such as「第一把」「第二把」.
#
# The protected-name list has two separate responsibilities:
#   - this guard may use an exact match to suppress a pure name call;
#   - protect_names() preserves a name inside a real sentence during translation.
# It must never suppress an otherwise unknown short message merely because it is short.


def _normalize_person_name(value):
    """Normalize a LINE/protected display name for exact name-call comparison."""
    value = str(value or '').strip()
    if not value:
        return ''
    # Normalize full-width/half-width surrounding whitespace and remove a trailing
    # role label such as「（研磨股班長）」for base-name comparison.
    value = re.sub(r'\s+', '', value)
    value = re.sub(r'[（(][^）)]*[）)]$', '', value).strip()
    return value


def _normalized_known_names_for_group(group_id):
    """Return exact protected names and cached LINE display names for a group."""
    names = set()
    try:
        for item in CUSTOMER_NAMES:
            raw = str(item or '').strip()
            normalized = _normalize_person_name(raw)
            if raw:
                names.add(raw)
            if normalized:
                names.add(normalized)
    except Exception:
        pass

    try:
        for value in (group_user_names.get(group_id, {}) or {}).values():
            raw = str(value or '').strip()
            normalized = _normalize_person_name(raw)
            if raw:
                names.add(raw)
            if normalized:
                names.add(normalized)
    except Exception:
        pass

    return names


def is_mention_only_or_name_call(text, line_mentions=None, group_id=None):
    """Return True only for a pure LINE mention or an exact known-name call.

    Reliable evidence accepted by this guard:
      - after removing LINE-reported @mention spans, nothing remains;
      - the remaining text exactly matches a protected name or a cached LINE
        group display name;
      - every separated remainder chunk is an exact known name.

    Unknown short Chinese text is always allowed through to translation.  This
    intentionally prefers an occasional translated unknown name over silently
    dropping a real work instruction.
    """
    if not text or not isinstance(text, str):
        return False

    # line_mentions comes from message.mention.mentionees index/length data.
    # Regex extraction is only a compatibility fallback when that metadata is
    # unavailable in an older event/SDK path.
    mentions = list(line_mentions or extract_mentions(text))
    if not mentions:
        return False

    remainder = text
    for mention in sorted(set(mentions), key=len, reverse=True):
        remainder = remainder.replace(mention, ' ')

    raw_tail = remainder.strip()
    compact_tail = re.sub(r'[\s,，、。.!！?？:：;；/\\|·•]+', '', raw_tail)
    if not compact_tail:
        return True

    known_names = _normalized_known_names_for_group(group_id)
    normalized_tail = _normalize_person_name(compact_tail)
    if compact_tail in known_names or (normalized_tail and normalized_tail in known_names):
        return True

    chunks = [c for c in re.split(r'[\s,，、/|]+', raw_tail) if c]
    if chunks:
        normalized_chunks = [_normalize_person_name(c) for c in chunks]
        if all(c and (c in known_names or n in known_names)
               for c, n in zip(chunks, normalized_chunks)):
            return True

    # No authoritative name evidence: translate it.  Do not guess from length.
    return False


def has_chinese(text):
    return len(re.findall(r'[\u4e00-\u9fff]', text)) >= 2


def has_translatable_content(text):
    """v3.9.56: 判斷訊息是否含「可翻譯的語言內容」。

    全面短文翻譯:取代散落各處的 `len(text) < 2` 無條件門檻。
    原本 len<2 會漏掉單字中文(好/對/是/懂)、單個假名/韓文/泰文字。

    回 True 的條件(任一):
      - 含至少 1 個 CJK/假名/韓文/泰文/天城文字
      - 含至少 1 個「2 字母以上」的拉丁詞(maaf/ok/sudah...)
      - 含至少 2 個拉丁字母(救 hi/no/ya 這類 2 字母詞)
    回 False(跳過,不翻):
      - 純 emoji / 純標點 / 純數字 / 純空白
      - 單個拉丁字母(a/i/x 這類無意義)
    """
    if not text:
        return False
    s = text.strip()
    if not s:
        return False
    # 任何 CJK / 假名 / 韓文 / 泰文 / 天城文 → 有內容
    if re.search(r'[\u4e00-\u9fff\u3040-\u309f\u30a0-\u30ff'
                 r'\uac00-\ud7af\u0e00-\u0e7f\u0900-\u097f]', s):
        return True
    # 2 字母以上的拉丁詞 → 有內容(maaf, ok, sudah)
    if re.search(r'[a-zA-Z]{2,}', s):
        return True
    # 至少 2 個拉丁字母(救 "hi"=2字母已被上面抓,這裡兜底如 "a b")
    if len(re.findall(r'[a-zA-Z]', s)) >= 2:
        return True
    return False


def has_japanese(text):
    hira = len(re.findall(r'[\u3040-\u309f]', text))
    kata = len(re.findall(r'[\u30a0-\u30ff]', text))
    return (hira + kata) >= 2


def has_korean(text):
    return len(re.findall(r'[\uac00-\ud7af]', text)) >= 2


def has_thai(text):
    return len(re.findall(r'[\u0e00-\u0e7f]', text)) >= 2


def has_vietnamese(text):
    vi_special = re.findall(r'[\u01a0\u01a1\u01af\u01b0\u0110\u0111]', text)
    vi_chars = re.findall(r'[\u00e0-\u00ff\u1ea0-\u1ef9]', text.lower())
    vi_marks = re.findall(r'[\u0300-\u036f]', text)
    words = text.lower().split()
    vi_markers = set([
        'cua', 'nhung', 'trong', 'duoc', 'khong', 'nhu', 'mot',
        'toi', 'ban', 'anh', 'chi', 'em', 'ong', 'ba',
        'la', 'va', 'cac', 'cho', 'voi', 'tai', 'nay', 'khi',
        'con', 'roi', 'lam', 'biet', 'muon', 'den', 'di',
        'xin', 'cam', 'chao', 'dep', 'ngon', 'tot', 'xau',
    ])
    marker_count = sum(1 for w in words if w in vi_markers)
    if len(vi_special) >= 1:
        return True
    if len(vi_chars) >= 3 and marker_count >= 1:
        return True
    if len(vi_marks) >= 2 and marker_count >= 1:
        return True
    return False


