_FACTORY_REASON_ID_RE = re.compile(
    r"^\s*(?P<id>(?=[A-Z0-9._/-]*\d)(?=[A-Z0-9._/-]*[A-Z])[A-Z0-9][A-Z0-9._/-]{4,30})"
    r"\s*(?:\||｜|\t|,|，|:|：|\s+)\s*(?P<reason>.+?)\s*$",
    re.I,
)

# v3.18: ERP 圖片表格 fail-closed sentinel. 這不是給使用者看的譯文，
# 而是 OCR 邊界層通知 LINE handler：不要再把不可靠 OCR 丟進一般翻譯管線。
_FACTORY_REASON_OCR_FAIL_SENTINEL = "__FACTORY_REASON_OCR_UNRELIABLE__"


def _compact_factory_reason_text(text):
    """Normalize OCR/table reason cells without losing Tag case semantics."""
    if not text or not isinstance(text, str):
        return ""
    t = text.strip().lower()
    t = t.replace("ｔａｇ", "tag")
    t = re.sub(r"[\s|｜,，。.:：;；/\\\\()（）\[\]【】{}<>《》『』「」'\"`·・_-]+", "", t)
    return t


def _factory_reason_action_map():
    return {e["key"]: e for e in _FACTORY_REASON_ACTIONS}


def _match_factory_reason_action(cell, reason_context=False):
    """Return a reason-action entry for exact/near-exact factory reason cells.

    reason_context=True is allowed only after deterministic context is present
    (原因欄、ID 列、短標籤、圖片 OCR 表格). This gives OCR tolerance without
    rewriting normal sentences such as「削皮那邊優先放行」.
    """
    c = _compact_factory_reason_text(cell)
    if not c:
        return None
    for entry in _FACTORY_REASON_ACTIONS:
        variants = list(entry.get("variants", (entry["key"],)))
        if reason_context:
            variants.extend(entry.get("reason_only_variants", ()))
        for v in variants:
            vc = _compact_factory_reason_text(v)
            if not vc:
                continue
            if c == vc:
                return entry
            # OCR reason cell sometimes contains one extra marker, e.g.「原因:削皮」 or「削皮?」.
            if reason_context and vc in c and len(c) <= len(vc) + 4:
                return entry
    return None

def _is_factory_reason_header_line(line):
    s = line or ""
    if not re.search(r"(?<![A-Za-z0-9])ID(?![A-Za-z0-9])", s, re.I):
        return False
    # OCR may read 原因 as 原囚/原因欄, but it must remain a reason column, not 爐號/料號.
    return bool(re.search(r"原\s*[因囚困]|原因|理由|原因欄|原因栏|處理原因|处理原因", s))

def _parse_factory_reason_table_row(line):
    if not line or _is_factory_reason_header_line(line):
        return None
    m = _FACTORY_REASON_ID_RE.match(line.strip())
    if not m:
        return None
    material_id = m.group("id").strip()
    reason_cell = m.group("reason").strip()
    entry = _match_factory_reason_action(reason_cell, reason_context=True)
    if not entry:
        return None
    return material_id, entry



def _factory_reason_line_id_only(line):
    """Return ID/code when a table row was OCR'd as code-only in one line."""
    if not line or not isinstance(line, str):
        return None
    t = line.strip()
    if not t or _is_factory_reason_header_line(t):
        return None
    # Must be one compact code token. Avoid treating normal sentences as IDs.
    if re.fullmatch(r"(?=[A-Z0-9._/-]*\d)(?=[A-Z0-9._/-]*[A-Z])[A-Z0-9][A-Z0-9._/-]{4,30}", t, re.I):
        return t
    return None


def _parse_factory_reason_split_rows(lines):
    """Parse OCR tables where left/right columns were emitted as alternating lines.

    Examples:
        ID | 原因\n7H385503A\n改端漆\n7H347507\n補毛重
    """
    if not lines:
        return []
    rows = []
    i = 0
    while i < len(lines):
        cur = (lines[i] or "").strip()
        # Normal same-line row first.
        row = _parse_factory_reason_table_row(cur)
        if row:
            rows.append(row)
            i += 1
            continue
        code = _factory_reason_line_id_only(cur)
        if code and i + 1 < len(lines):
            nxt = (lines[i + 1] or "").strip()
            entry = _match_factory_reason_action(nxt, reason_context=True)
            if entry:
                rows.append((code, entry))
                i += 2
                continue
        i += 1
    return rows


def _parse_factory_reason_column_major_rows(lines):
    """Parse OCR tables where the model emitted the left ID column first, then 原因 column.

    Vision OCR sometimes reads an Excel screenshot column-by-column instead of row-by-row:
        ID | 原因
        7H385503A
        7H347507
        ...
        改端漆
        補毛重
        ...

    Pairing is allowed only when counts are exactly equal. If OCR skipped any ID or
    reason cell, we fail closed instead of shifting reasons onto the wrong IDs.
    """
    if not lines:
        return []
    cells = []
    for raw in lines:
        s = (raw or "").strip()
        if not s or _is_factory_reason_header_line(s):
            continue
        # Same-line rows are handled by the safer row parser. Do not double count them here.
        if _parse_factory_reason_table_row(s):
            continue
        code = _factory_reason_line_id_only(s)
        if code:
            cells.append(("id", code))
            continue
        entry = _match_factory_reason_action(s, reason_context=True)
        if entry:
            cells.append(("reason", entry))
            continue
        # Ignore obvious UI/status residue; any other unknown text makes this shape unsafe.
        if re.fullmatch(r"[-–—_=+*#．.。\s]+", s):
            continue
        return []
    if len(cells) < 4:
        return []
    kinds = [k for k, _ in cells]
    # Require exactly one transition ID...ID -> reason...reason. Interleaved rows are split_rows.
    try:
        first_reason = kinds.index("reason")
    except ValueError:
        return []
    if first_reason == 0:
        return []
    if any(k != "id" for k in kinds[:first_reason]) or any(k != "reason" for k in kinds[first_reason:]):
        return []
    ids = [v for k, v in cells[:first_reason]]
    entries = [v for k, v in cells[first_reason:]]
    if len(ids) != len(entries) or len(ids) < 2:
        return []
    return list(zip(ids, entries))


def _factory_reason_table_alignment_issue(text):
    """Detect unsafe ERP reason table OCR where ID and reason columns cannot be aligned.

    Returning a reason here is intentionally fail-closed: a shifted table is worse than
    asking for a clearer crop, because it assigns the wrong operation to a material ID.
    """
    if not text or not isinstance(text, str):
        return ""
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    if not lines or not any(_is_factory_reason_header_line(ln) for ln in lines[:6]):
        return ""
    same = [_parse_factory_reason_table_row(ln) for ln in lines]
    same = [r for r in same if r]
    # If we have reliable same-line rows, let the deterministic translator use them.
    if len(same) >= 2:
        return ""
    ids = []
    reasons = []
    unknown = []
    for ln in lines:
        if _is_factory_reason_header_line(ln):
            continue
        if _factory_reason_line_id_only(ln):
            ids.append(ln)
        elif _match_factory_reason_action(ln, reason_context=True):
            reasons.append(ln)
        elif not re.fullmatch(r"[-–—_=+*#．.。\s]+", ln):
            unknown.append(ln)
    if ids and reasons and len(ids) != len(reasons):
        return "id_reason_count_mismatch"
    if ids and reasons and unknown:
        return "unknown_cells_in_split_table"
    return ""


def _factory_reason_alignment_failure_message(tgt="id"):
    if (tgt or "").lower().startswith("zh"):
        return "OCR 無法可靠對齊 ID 與原因欄，請重拍較清楚，或只裁切表格後再傳。"
    return "OCR tabel tidak cukup jelas untuk mencocokkan ID dan Alasan. Mohon kirim foto yang lebih jelas, atau crop hanya bagian tabel lalu kirim ulang."


def _factory_reason_ocr_failure_payload(reason="unreliable_alignment"):
    """Internal OCR failure payload for ERP ID/原因 screenshots.

    Image handlers intercept this before language detection.  Returning this is
    safer than falling back to generic OCR, because generic OCR can silently shift
    operations onto the wrong material IDs.
    """
    return f"{_FACTORY_REASON_OCR_FAIL_SENTINEL}:{reason}"


def _is_factory_reason_ocr_failure_text(text):
    return bool(isinstance(text, str) and text.strip().startswith(_FACTORY_REASON_OCR_FAIL_SENTINEL))


def _factory_reason_user_failure_reply():
    return (
        "🖼️ ⚠️\n"
        "OCR 無法可靠對齊 ID 與原因欄，已停止翻譯，避免把錯誤製程套到錯誤 ID。\n"
        "請重拍較清楚，或只裁切表格後再傳。\n\n"
        "OCR tabel tidak cukup jelas untuk mencocokkan ID dan Alasan.\n"
        "Terjemahan dihentikan agar proses tidak dipasang ke ID yang salah.\n"
        "Mohon foto ulang lebih jelas, atau crop hanya bagian tabel lalu kirim ulang."
    )


def _is_factory_reason_header_only_text(text):
    if not text or not isinstance(text, str):
        return False
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    return len(lines) == 1 and _is_factory_reason_header_line(lines[0])

def _factory_reason_entries_in_text(text, reason_context=False):
    """Collect distinct reason-action entries grounded in source text."""
    if not text or not isinstance(text, str):
        return []
    found = []
    seen = set()
    table_like = _looks_like_factory_reason_table_text(text)
    effective_reason_context = reason_context or table_like or ("原因" in text)
    # Row-level matching first: high precision for screenshots / copied Excel rows.
    for line in text.splitlines():
        row = _parse_factory_reason_table_row(line)
        if row:
            key = row[1]["key"]
            if key not in seen:
                seen.add(key)
                found.append(row[1])
    # Short label / reason column text matching. Keep it narrow outside reason context.
    chunks = re.split(r"[\n\r,，;；、/]+", text)
    for chunk in chunks:
        stripped = chunk.strip()
        if not stripped:
            continue
        entry = _match_factory_reason_action(stripped, reason_context=effective_reason_context)
        if entry and entry["key"] not in seen:
            seen.add(entry["key"])
            found.append(entry)
    if effective_reason_context:
        compact = _compact_factory_reason_text(text)
        for entry in _FACTORY_REASON_ACTIONS:
            if entry["key"] in seen:
                continue
            _variants = list(entry.get("variants", (entry["key"],)))
            if effective_reason_context:
                _variants.extend(entry.get("reason_only_variants", ()))
            for v in _variants:
                vc = _compact_factory_reason_text(v)
                if vc and vc in compact:
                    seen.add(entry["key"])
                    found.append(entry)
                    break
    return found


def _looks_like_factory_reason_table_text(text):
    if not text or not isinstance(text, str):
        return False
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    if not lines:
        return False
    has_header = any(_is_factory_reason_header_line(ln) for ln in lines[:6])
    row_hits = sum(1 for ln in lines if _parse_factory_reason_table_row(ln))
    split_hits = len(_parse_factory_reason_split_rows(lines))
    column_hits = len(_parse_factory_reason_column_major_rows(lines))
    return bool((has_header and (row_hits >= 1 or split_hits >= 1 or column_hits >= 1))
                or row_hits >= 2 or split_hits >= 2 or column_hits >= 2)

def _factory_reason_semantic_translate_zh_id(text):
    """Deterministic translation for ERP reason labels and reason tables.

    This is intentionally source-grounded and format-preserving:
    - ID/code cells are copied verbatim;
    - 原因 header becomes Alasan;
    - reason cells become the user-provided factory action semantics;
    - OCR split-column tables are repaired structurally;
    - unknown/non-table prose is not rewritten here, it goes through LLM with
      semantic_contract hints instead.
    """
    if not text or not isinstance(text, str):
        return None
    lines = [ln.rstrip() for ln in text.splitlines()]
    nonempty = [ln.strip() for ln in lines if ln.strip()]

    if _is_factory_reason_header_only_text(text):
        return "ID | Alasan"

    has_header = any(_is_factory_reason_header_line(ln) for ln in lines[:6])
    same_line_rows = []
    for line in lines:
        row = _parse_factory_reason_table_row(line)
        if row:
            same_line_rows.append(row)
    split_rows = _parse_factory_reason_split_rows(nonempty)
    column_rows = _parse_factory_reason_column_major_rows(nonempty)
    parsed_rows = max((same_line_rows, split_rows, column_rows), key=len)

    if (has_header and parsed_rows) or len(parsed_rows) >= 2:
        out = ["ID | Alasan"]
        seen = set()
        # Preserve OCR row order. split_rows already includes same-line rows when present.
        source_rows = parsed_rows
        for material_id, entry in source_rows:
            key = (material_id, entry["key"])
            if key in seen:
                continue
            seen.add(key)
            out.append(f"{material_id} | {entry['id']}")
        return "\n".join(out).strip() or None

    # Single table row / line row. Critical for paragraph-split image OCR.
    if len(nonempty) == 1:
        row = _parse_factory_reason_table_row(nonempty[0])
        if row:
            return f"{row[0]} | {row[1]['id']}"

    # Two-line split single row: code line + reason line.
    if len(nonempty) == 2:
        split_one = _parse_factory_reason_split_rows(nonempty)
        if len(split_one) == 1:
            return f"{split_one[0][0]} | {split_one[0][1]['id']}"

    # Standalone short reason labels, including multiple labels sent as separate lines.
    chunks = [c.strip() for c in re.split(r"[\n\r,，;；、/]+", text) if c.strip()]
    if chunks and len("".join(chunks)) <= 40:
        mapped = []
        for chunk in chunks:
            entry = _match_factory_reason_action(chunk, reason_context=True)
            if not entry:
                mapped = []
                break
            mapped.append(entry["id"])
        if mapped:
            return "\n".join(mapped)
    return None

def _factory_reason_translation_contains(entry, translation_lower):
    for group in entry.get("required_groups", ()): 
        if not any(token.lower() in translation_lower for token in group):
            return False
    return True


def _factory_reason_contract_risk(text):
    table_like = _looks_like_factory_reason_table_text(text)
    reason_context = table_like or ("原因" in (text or ""))
    entries = _factory_reason_entries_in_text(text, reason_context=reason_context)
    if not entries:
        return None
    # Avoid over-constraining ordinary prose like「削皮那邊」unless it is really a reason/list context.
    if not reason_context:
        compact = _compact_factory_reason_text(text)
        short_exact = any(compact == _compact_factory_reason_text(v)
                          for e in _FACTORY_REASON_ACTIONS for v in e.get("variants", (e["key"],)))
        if not short_exact:
            return None
    return {
        "term": "ERP原因欄",
        "sense": "factory_reason_action_semantics",
        "entries": [e["key"] for e in entries],
        "table_like": table_like,
        "tm_bypass_allowed": False,
        "nmt_allowed": False,
    }


def _build_factory_reason_contract_lines(risk):
    keys = set(risk.get("entries") or [])
    amap = _factory_reason_action_map()
    lines = ["<risk term='ERP原因欄' sense='factory_reason_action_semantics'>"]
    lines.append("The source contains ERP/Excel reason labels. These labels are not generic nouns; they are factory action instructions. Preserve ID/code cells verbatim.")
    lines.append("Translate header 原因 as Alasan. Never translate ID header as Nomor Material.")
    for key in keys:
        e = amap.get(key)
        if not e:
            continue
        variants = "/".join(e.get("variants", ())[:4])
        lines.append(f"{key} (variants: {variants}) => {e['id']} ; meaning: {e['note']}.")
    lines.append("Forbidden wrong outputs for these labels: Nomor Material, Sedang, Air Palsu, Mengubah Cetakan, Mengalir, Hentikan Furnace.")
    lines.append("</risk>")
    return lines


def detect_factory_semantic_error_zh_id(src_text, id_text):
    """Detect Chinese->Indonesian factory semantic errors that normal confidence misses."""
    if not id_text:
        return True, "empty", []
    src = src_text or ""
    low = id_text.lower()
    factory_src = any(k in src for k in ["料", "品保", "清洗", "研磨", "進料", "刮傷", "吊", "偷跑", "工單", "包裝", "站別",
                                          # v3.9.37: 加入「消化/分流/異型棒」等口語觸發詞
                                          "消化", "分流", "異型棒", "急單", "出貨",
                                          # v3.20: 工單公告/短尺維護術語
                                          "短尺", "來料尺寸", "表面品質", "重量確認", "噴漆"])
    if not factory_src:
        return False, "", []
    domains = ["factory"]
    if any(k in src for k in ["品保", "刮傷", "異常", "損傷"]):
        domains.append("quality_issue")
    if any(k in src for k in ["清洗", "研磨", "吊", "偷跑", "進料"]):
        domains.append("material_flow")
    if "偷跑" in src and any(x in low for x in ["dicuri", "mencuri", "pencuri"]):
        return True, "factory_theft_literal:偷跑不可翻成偷竊", domains
    if "吊" in src and "derek qc" in low:
        return True, "factory_crane_qc_literal:品保不是吊車", domains
    if "反應" in src and "bereaksi" in low:
        return True, "factory_response_literal:反應應為回報/通報", domains
    if "吃掉" in src and "tertelan" in low:
        return True, "factory_swallowed_literal:被吃掉不可直譯吞掉", domains
    if "工單" in src and any(x in low for x in ["tempat buku bahan", "buku bahan", "perintah kerja", "lembar kerja", "order kerja"]):
        return True, "factory_work_order_literal:工單固定用 work order", domains
    if "短尺" in src and "penggaris" in low:
        return True, "factory_short_material_literal:短尺不可翻成 penggaris", domains
    # v3.9.37: 「消化」≠「去化」誤譯偵測
    # 去化 = 有新單接走 → serap material (合法)
    # 消化 = 分批處理掉現有 → diproses bertahap / dihabiskan (正確)
    # Claude 常把「消化」串聯誤譯為「serap material」
    if "消化" in src and "去化" not in src and "serap material" in low:
        return True, "factory_consume_vs_absorb_literal:消化不可譯為 serap material(serap material 是去化用語)", domains
    for bad, reason in FACTORY_ZH_ID_BAD_PATTERNS.items():
        b = bad.lower()
        if b in low:
            if b in ("dicuri", "mencuri", "pencuri") and "偷跑" not in src:
                continue
            if b == "bereaksi" and "反應" not in src:
                continue
            if b == "tertelan" and "吃掉" not in src:
                continue
            # v3.9.37: serap material 只在「消化 in src 且 去化 not in src」時才算 bad
            # 已在上方 if 處理過,for 迴圈內一律 skip 避免重複誤殺合法情況
            if b == "serap material":
                continue
            return True, reason + ":" + bad, domains
    return False, "", domains


def post_fix_factory_zh_to_id(src_text, id_text):
    """Fix literal Indonesian outputs for Taiwan factory Chinese->ID translation.
    
    v3.9.29: 擴大 trigger keyword 範圍。之前只有「料/品保/清洗/研磨」等 11 個工廠製程詞,
    導致「鹽水廠/職安署/警告/重大職災/interlock」這類安全/法規類訊息**完全沒套用詞庫**。
    現在加入廠區地名、安全術語、法規詞,確保詞庫能命中 v3.9.27 加的全部規則。
    
    v3.9.29 修補 8: 加入 idempotent 處理 — 廠區名「Yanshui」可能已經被 GPT 翻成
    「Pabrik Yanshui」或還是「Yanshui」,要避免重複套用「(鹽水廠)」標註。
    """
    if not id_text:
        return id_text
    src = src_text or ""
    result = id_text.strip()
    # v3.9.29: 大幅擴充 trigger 詞庫
    factory_keywords = [
        # 製程(原本就有)
        "料", "品保", "清洗", "研磨", "進料", "刮傷", "吊", "偷跑", "工單", "包裝", "站別",
        # v3.9.29 新增:廠區/地名
        "鹽水廠", "鹽水", "台中廠", "冷精棒", "冷抽課",
        # v3.9.29 新增:安全/法規
        "職安", "工安", "職災", "重大職災", "警告", "罰單", "記過", "違規", "列管", "停工",
        # v3.9.29 新增:設備/英文術語
        "interlock", "bypass", "PMI", "MSDS", "SOP", "PPE", "LOTO", "K3",
        # v3.9.29 新增:管理/操作
        "班長", "副總", "巡視", "操作", "作業", "抓到", "帽扣",
        # v3.9.29 新增:OCR 圖片常見的訊息類用語
        "公告", "通知", "提醒", "今年", "目前",
        # v3.9.30d B22 新增:薪資相關(夜點費誤譯案例)
        "夜點", "夜點費", "日點費", "夜班津貼", "中班津貼",
        "薪資", "薪水", "薪", "減項", "加項", "扣項",
        "獎金", "底薪", "本薪", "勞保", "健保", "夜班費",
        # v3.9.37 新增:訂單流動口語(分流消化誤譯案例)
        "消化", "分流", "異型棒", "急單", "出貨", "去化", "有好處理",
        # v3.20: 工單公告與短尺維護語義
        "工單資訊", "來料尺寸", "表面品質", "短尺", "短尺維護", "重量確認", "噴漆",
        # v3.9.58: 飲食/飲料福利場景的「請客 / X請的」
        "請客", "請的", "飲料", "罐裝", "便當", "咖啡", "點心", "一人一罐", "每人一罐",
    ]
    # 也檢查譯文(if 原文沒命中但譯文有 Yanshui / Dinas K3 等典型錯翻)
    id_trigger_words = ["Yanshui", "Dinas K3", "tilang", "kena tangkap", "kepala shift",
                        "bereaksi", "dicuri", "tertelan", "interlock di-bypass",
                        "diminta", "permintaan", "dipesan",
                        "perintah kerja", "lembar kerja", "Tempat Buku bahan", "penggaris pendek"]
    factory_src = any(k in src for k in factory_keywords)
    factory_id = any(k in result for k in id_trigger_words)
    if not factory_src and not factory_id:
        return result
    # v3.9.29 修補 8/10: idempotent 處理 — 避免「(鹽水廠) (鹽水廠)」重複註解
    # Step 1: 把已經完整的版本暫存,套用詞庫時不會被重複處理
    placeholders = []
    def _stash(match):
        placeholders.append(match.group(0))
        return f"\x00PH{len(placeholders)-1}\x00"
    # 先把已完整的詞藏起來
    result = re.sub(r"Pabrik Yanshui\s*\(鹽水廠\)", _stash, result, flags=re.I)
    result = re.sub(r"Pabrik Taichung\s*\(台中廠\)", _stash, result, flags=re.I)
    result = re.sub(r"Departemen Keselamatan Kerja\s*\(職安署\)", _stash, result, flags=re.I)
    
    # Step 2: 套用詞庫(由長到短,避免短詞先吃掉長詞的部分)
    for wrong, correct in sorted(FACTORY_ZH_ID_POST_FIX.items(), key=lambda x: -len(x[0])):
        result = re.sub(re.escape(wrong), correct, result, flags=re.I)
    # v3.20: source-grounded factory term repair.  This uses the same semantic contract
    # as the pre-LLM route and is not a blind global replacement.
    try:
        _domain_risk = _classify_factory_domain_terms_zh_id(src)
        if _domain_risk:
            result = _repair_factory_domain_term_translation(result, _domain_risk)
    except Exception:
        pass
    
    # Step 3: 處理 standalone Yanshui — 沒中文標註的 Yanshui 都升級成完整名稱
    # 不管前面有沒有 "Pabrik",只要後面沒接 "(" 就升級
    # 「Pabrik Yanshui sudah」→「Pabrik Yanshui (鹽水廠) sudah」(前面 Pabrik 被吃掉,重新加)
    # 「Yanshui sudah」→「Pabrik Yanshui (鹽水廠) sudah」
    # 「Pabrik Yanshui (鹽水廠)」→ 不變(已被 stash)
    result = re.sub(
        r"(?:Pabrik\s+|pabrik\s+)?\bYanshui\b(?!\s*\()",
        "Pabrik Yanshui (鹽水廠)",
        result
    )
    result = re.sub(
        r"(?:Pabrik\s+|pabrik\s+)?\bTaichung\b(?!\s*\()",
        "Pabrik Taichung (台中廠)",
        result
    )
    
    # Step 4: 把 placeholder 還原
    for i, ph_text in enumerate(placeholders):
        result = result.replace(f"\x00PH{i}\x00", ph_text)
    
    # v3.9.30d B22 修補:夜點費條件式翻譯
    # 「夜點費」在台灣勞基法 = 因輪到夜班領的固定津貼,不論加班(uang shift malam)
    # 「夜班加班費」才是 uang lembur malam
    # GPT 常把兩者混淆,這裡只在原文明確含「夜點費」/「日點費」/「夜班津貼」時修
    if "夜點費" in src or "夜班津貼" in src or "夜點" in src:
        # 把譯文裡的 uang lembur malam 改成 uang shift malam
        result = re.sub(r'\buang\s+lembur\s+malam\b', 'uang shift malam', result, flags=re.I)
        # 處理變體:uang lembur shift malam / lembur shift malam(連 uang 一起包以免重複)
        result = re.sub(r'\b(?:uang\s+)?lembur\s+shift\s+malam\b', 'uang shift malam', result, flags=re.I)
        # 處理已經是 shift 但前面誤加 lembur 的:lembur uang shift malam
        result = re.sub(r'\blembur\s+uang\s+shift\s+malam\b', 'uang shift malam', result, flags=re.I)
    if "日點費" in src or "日班津貼" in src:
        result = re.sub(r'\buang\s+lembur\s+siang\b', 'uang shift siang', result, flags=re.I)
        result = re.sub(r'\b(?:uang\s+)?lembur\s+shift\s+siang\b', 'uang shift siang', result, flags=re.I)
    if "中班津貼" in src:
        result = re.sub(r'\buang\s+lembur\s+sore\b', 'uang shift sore', result, flags=re.I)
        result = re.sub(r'\b(?:uang\s+)?lembur\s+shift\s+sore\b', 'uang shift sore', result, flags=re.I)
    
    # v3.9.37: 「消化」≠「去化」reactive fix
    # 去化 = 有新單接走 → serap material (合法保留)
    # 消化 = 分批處理掉現有 → diproses bertahap / dihabiskan (要改)
    # 只在「原文有消化、且沒有去化」時才改,避免誤殺合法的「去化→serap material」
    if "消化" in src and "去化" not in src:
        # alihkan/dialihkan untuk serap material → dialihkan untuk diproses bertahap
        result = re.sub(
            r'\b(di)?alihkan\s+untuk\s+serap\s+material\b',
            'dialihkan untuk diproses bertahap',
            result, flags=re.I
        )
        # untuk serap material → untuk diproses bertahap
        result = re.sub(
            r'\buntuk\s+serap\s+material\b',
            'untuk diproses bertahap',
            result, flags=re.I
        )
        # 單獨 serap material → habiskan secara bertahap
        result = re.sub(
            r'\bserap\s+material\b',
            'habiskan secara bertahap',
            result, flags=re.I
        )
    
    # v3.9.37: 「有好處理的」≠「sudah selesai」reactive fix
    # 「有好處理的料」= 容易處理的料(yang mudah/gampang diproses)
    # 常被誤譯為 sudah selesai(已完成)— 完全相反意思
    if "有好處理" in src or "好處理的" in src:
        # batang ... yang sudah selesai → batang ... yang mudah diproses
        result = re.sub(
            r'\byang\s+sudah\s+selesai\b',
            'yang mudah diproses',
            result, flags=re.I
        )
    
    # v3.9.58: 飲食/飲料福利場景的「請客 / X請的」不可被翻成 request/diminta
    result = fix_qing_treat_translation_zh_id(src, result)
    result = result.replace("\r\n", "\n").replace("\r", "\n")
    result = re.sub(r"[^\S\n]+", " ", result).strip()
    return result



