def _compact_zh_for_work_order(text):
    return re.sub(r"\s+", "", text or "")


def _classify_factory_work_order_zh_id(text):
    compact = _compact_zh_for_work_order(text)
    if "工單" not in compact:
        return None
    # UI labels such as「工單訂單資訊『訂單編號』」are not announcements/process rules.
    context_hits = [term for term in _FACTORY_WORK_ORDER_CONTEXT_ZH if term in compact]
    process_shape = any(term in compact for term in (
        "不要", "不寫", "按照", "執行", "各站", "基本工作", "流程", "宣導", "規定",
    ))
    if not process_shape or len(context_hits) < 2:
        return None
    entries = ["work_order"]
    source_map = (
        ("工單資訊", "work_order_info"),
        ("來料尺寸", "incoming_material_size"),
        ("表面品質", "surface_quality"),
        ("短尺維護", "short_material_handling"),
        ("重量確認", "weight_confirmation"),
        ("作業流程", "workflow"),
    )
    for source_term, key in source_map:
        if source_term in compact:
            entries.append(key)
    return {
        "term": "factory_work_order",
        "sense": "factory_work_order_terms",
        "entries": entries,
        "evidence": context_hits[:10],
        "tm_bypass_allowed": False,
        "nmt_allowed": False,
        "requires_validation": True,
    }


def _translation_has_any(translation, candidates):
    low = (translation or "").lower()
    return any((candidate or "").lower() in low for candidate in (candidates or ()))


def _repair_factory_work_order_terms_zh_id(src_text, translation):
    """Source-gated deterministic repair for established factory work-order terms."""
    risk = _classify_factory_work_order_zh_id(src_text)
    result = (translation or "").strip()
    if not risk or not result:
        return result

    def sub(pattern, replacement):
        nonlocal result
        result = re.sub(pattern, replacement, result, flags=re.I)

    for pattern in (
        r"\btempat\s+buku\s+bahan\b", r"\bbuku\s+bahan\b",
        r"\bsurat\s+perintah\s+kerja\b", r"\bperintah\s+kerja\b",
        r"\blembar\s+kerja\b", r"\border\s+kerja\b",
    ):
        sub(pattern, "work order")
    if "work_order_info" in risk["entries"]:
        sub(r"\binformasi\s+(?:pesanan|order|perintah\s+kerja|work order)\b",
            "informasi pada work order")
    if "incoming_material_size" in risk["entries"]:
        sub(r"\bukuran\s+(?:bahan|material)(?:\s+yang)?\s+masuk\b", "ukuran material masuk")
    if "surface_quality" in risk["entries"]:
        sub(r"\b(?:mutu|kualitas)\s+permukaan\b", "kualitas permukaan")
    if "short_material_handling" in risk["entries"]:
        for pattern in (
            r"\b(?:pemeliharaan|perawatan)\s+(?:penggaris|ukuran|material)\s+pendek\b",
            r"\bpenggaris\s+pendek\b",
        ):
            sub(pattern, "penanganan material pendek")
    if "weight_confirmation" in risk["entries"]:
        sub(r"\bkonfirmasi\s+(?:bobot|berat\s+badan)\b", "konfirmasi berat")
    if "workflow" in risk["entries"]:
        sub(r"\b(?:proses\s+operasi|proses\s+kerja|workflow)\b", "alur kerja")
    return re.sub(r"\s+", " ", result).strip()


def _semantic_compact_zh(text):
    return re.sub(r"\s+", "", text or "")

def _semantic_hits(compact, words):
    return [w for w in words if w and w in compact]

def _extract_semantic_sponsor_before_qing(text):
    """抽出 X請的 / X請客 的 X；只做語義證據，不直接決定翻譯。"""
    compact = _semantic_compact_zh(text)
    patterns = [
        r"[（(]([^（）()，,。；;：:\s]{1,24})請的[）)]",
        r"([^，,。；;：:\s]{1,18})請的",
        r"([^，,。；;：:\s]{1,18})請客",
        r"([^，,。；;：:\s]{1,18})請喝",
        r"([^，,。；;：:\s]{1,18})請吃",
    ]
    for pat in patterns:
        m = re.search(pat, compact)
        if not m:
            continue
        sponsor = m.group(1).strip("：:，,。；;()（）")
        sponsor = re.sub(r"^.*?(台北總部|總部|公司|廠長|副總|班長|組長|主管)$", r"\1", sponsor)
        return sponsor
    return ""

def _semantic_sponsor_to_id(sponsor_zh):
    if not sponsor_zh:
        return ""
    return _SEM_SPONSOR_ID_MAP.get(sponsor_zh, sponsor_zh)

def _extract_semantic_item_brand_zh(text):
    src = text or ""
    m = re.search(r"飲料\s*[-－—:：]?\s*([^，,。；;（）()\s]{1,16})", src)
    if m:
        brand = m.group(1).strip()
        return _SEM_BRAND_ID_MAP.get(brand, brand)
    for zh, idn in _SEM_BRAND_ID_MAP.items():
        if zh in src:
            return idn
    return ""

def _classify_qing_sense_zh_id(text):
    """把中文『請』分類成 request / treat_sponsor / none。
    這是語義分類器，不是譯文替換器。
    """
    compact = _semantic_compact_zh(text)
    if "請" not in compact:
        return None
    request_hits = _semantic_hits(compact, _SEM_QING_REQUEST_WORDS)
    food_hits = _semantic_hits(compact, _SEM_QING_TREAT_FOOD_WORDS)
    explicit_treat = any(k in compact for k in ("請客", "請的", "請喝", "請吃"))

    # 明確請求動作，且沒有「請客/X請的」形態 → request。
    if request_hits and not explicit_treat:
        return {
            "term": "請",
            "sense": "request_action",
            "confidence": 0.93,
            "evidence": request_hits[:6],
            "tm_bypass_allowed": True,
            "nmt_allowed": True,
        }

    # 飲食/福利發放 + 請客形態 → treat/sponsor/pay for。
    if explicit_treat and (food_hits or "請客" in compact):
        sponsor_zh = _extract_semantic_sponsor_before_qing(text)
        sponsor_id = _semantic_sponsor_to_id(sponsor_zh)
        return {
            "term": "請",
            "sense": "treat_sponsor_pay_for",
            "confidence": 0.99 if sponsor_zh else 0.94,
            "evidence": (food_hits + (["explicit_treat_shape"] if explicit_treat else []))[:8],
            "sponsor_zh": sponsor_zh,
            "sponsor_id": sponsor_id,
            "preferred_id_terms": list(_SEM_QING_PREFERRED_ID),
            "forbidden_id_terms": list(_SEM_QING_FORBIDDEN_ID),
            "tm_bypass_allowed": False,   # 舊 TM 容易把這類句子污染成 diminta；必須驗證才可 bypass
            "nmt_allowed": False,         # Google/NMT 最容易把「請」當 request；高風險時一律走 LLM+contract
            "requires_validation": True,
        }

    return {
        "term": "請",
        "sense": "ambiguous_qing",
        "confidence": 0.60,
        "evidence": (request_hits + food_hits)[:8],
        "tm_bypass_allowed": False,
        "nmt_allowed": False,
        "requires_validation": False,
    }

def _classify_factory_station_alias_zh_id(text):
    """辨識中文現場站名簡稱，產生固定站名語義契約。"""
    normalized, alias_matches = resolve_factory_station_aliases(text)
    canonical = "異型包裝站"
    if canonical not in (normalized or ""):
        return None
    return {
        "term": canonical,
        "sense": "factory_station_canonical_name",
        "confidence": 1.0,
        "evidence": [m.get("original", canonical) for m in alias_matches] or [canonical],
        "canonical_zh": canonical,
        "required_id": "stasiun packing barang bentuk khusus",
        "tm_bypass_allowed": False,
        "nmt_allowed": False,
        "requires_validation": True,
    }



def _factory_domain_terms_in_text_zh_id(text):
    """Return domain term rules that are grounded in the Chinese source.

    This is source-side concept matching, not target-side find/replace.  The goal is to
    prevent the model from splitting compact factory terms into wrong dictionary senses.
    """
    if not text or not isinstance(text, str):
        return []
    compact = _semantic_compact_zh(text)
    if not compact:
        return []
    # Only activate inside manufacturing / work-order context, so general non-factory wording
    # does not get over-constrained.
    if not any(k in compact for k in _FACTORY_DOMAIN_CONTEXT_ZH):
        return []
    found = []
    seen = set()
    for rule in _FACTORY_DOMAIN_TERM_RULES_ZH_ID:
        if rule["key"] in seen:
            continue
        for term in rule.get("source_terms", ()): 
            if term and term in compact:
                found.append(rule)
                seen.add(rule["key"])
                break
    return found


def _classify_factory_domain_terms_zh_id(text):
    entries = _factory_domain_terms_in_text_zh_id(text)
    if not entries:
        return None
    return {
        "term": "factory_domain_terms",
        "sense": "factory_domain_term_semantics",
        "entries": [e["key"] for e in entries],
        "preferred": {e["key"]: e.get("preferred_id", "") for e in entries},
        "tm_bypass_allowed": False,
        "nmt_allowed": False,
        "requires_validation": True,
    }


def _factory_domain_translation_contains(entry, translation_lower):
    if not entry:
        return True
    for bad in entry.get("forbidden_id_terms", ()):
        if bad and bad.lower() in translation_lower:
            return False
    for group in entry.get("required_groups", ()): 
        if not any(token.lower() in translation_lower for token in group):
            return False
    return True


def _factory_domain_forbidden_hit(entry, translation_lower):
    for bad in entry.get("forbidden_id_terms", ()):
        if bad and bad.lower() in translation_lower:
            return bad.lower()
    return ""


def _build_factory_domain_term_contract_lines(risk):
    lines = ["<risk term='factory_domain_terms' sense='factory_domain_term_semantics'>"]
    lines.append("The source contains Taiwan factory work-order / process-control terms. Do not split compact Chinese terms into generic dictionary meanings.")
    for key in risk.get("entries", []):
        e = _FACTORY_DOMAIN_TERM_MAP_ZH_ID.get(key)
        if not e:
            continue
        src_terms = "/".join(e.get("source_terms", ())[:4])
        bad_terms = ", ".join(e.get("forbidden_id_terms", ())[:8])
        lines.append(f"{src_terms} => {e.get('preferred_id', '')}; meaning: {e.get('note', '')}.")
        if bad_terms:
            lines.append(f"Forbidden for {src_terms}: {bad_terms}.")
    lines.append("</risk>")
    return lines


def _repair_factory_domain_term_translation(translation, risk):
    """Repair only target fragments that violate an active factory-domain term contract.

    This is the last deterministic safety net for already-classified source terms.  It is
    deliberately driven by the source-side risk entries above, not by a global blind replace.
    """
    result = (translation or "").strip()
    if not result:
        return result
    active = set((risk or {}).get("entries") or [])

    def sub(pattern, repl):
        nonlocal result
        result = re.sub(pattern, repl, result, flags=re.I)

    if "work_order" in active:
        for pattern in (
            r"\btempat\s+buku\s+bahan\b",
            r"\bbuku\s+bahan\b",
            r"\bsurat\s+perintah\s+kerja\b",
            r"\bperintah\s+kerja\b",
            r"\blembar\s+kerja\b",
            r"\border\s+kerja\b",
            r"\bbook\s+order\b",
            r"\border\s+book\b",
        ):
            sub(pattern, "work order")
    if "spray_cat" in active:
        # Repair stale prompt/TM/model output into the central glossary policy
        # before the delivery gate.  Longer malformed phrases must be handled
        # first so a generic replacement does not create bad grammar.
        sub(r"\btidak\s+(?:melakukan\s+)?spray\s+cat\b", "tidak melakukan pengecatan semprot")
        sub(r"\bdi-?spray\s+cat\b", "disemprot cat")
        sub(r"\bmelakukan\s+spray\s+cat\b", "melakukan pengecatan semprot")
        sub(r"\bspray\s+cat\b", "pengecatan semprot")
        sub(r"\bpenyemprotan\s+cat\b", "pengecatan semprot")
        sub(r"\bcat\s+semprot\b", "pengecatan semprot")
    if "incoming_material_size" in active:
        sub(r"\bukuran\s+material\s+yang\s+masuk\b", "ukuran material masuk")
        sub(r"\bukuran\s+bahan\s+yang\s+masuk\b", "ukuran material masuk")
    if "grinding_rod" in active:
        sub(r"\bbatang\s+gerinda\b", "grinding rod")
    if "short_material_handling" in active:
        for pattern in (
            r"\bpemeliharaan\s+penggaris\s+pendek\b",
            r"\bperawatan\s+penggaris\s+pendek\b",
            r"\bpemeliharaan\s+ukuran\s+pendek\b",
            r"\bperawatan\s+ukuran\s+pendek\b",
            r"\bpemeliharaan\s+material\s+pendek\b",
            r"\bperawatan\s+material\s+pendek\b",
            r"\bpenggaris\s+pendek\b",
        ):
            sub(pattern, "penanganan material pendek")
    if "weight_confirmation" in active:
        sub(r"\bkonfirmasi\s+berat\s+badan\b", "konfirmasi berat")
    if "workflow" in active:
        sub(r"\bproses\s+operasi\b", "alur kerja")
    result = result.replace("\r\n", "\n").replace("\r", "\n")
    result = re.sub(r"[^\S\n]+", " ", result).strip()
    return result



# v3.35.0: plant-specific workflow semantics are loaded by factory_knowledge.py
# from factory_knowledge.json.  Do not add new sentence-specific classifiers here.


def _current_work_order_media_context():
    """Return the work-order relation for the current measurement request.

    Translation-action buttons can be pressed long after the short media-context
    TTL expires.  When the original translation stored an explicit semantic
    decision, preserve that decision instead of reinterpreting the same sentence
    from whatever image happens to be recent at click time.  Ordinary messages
    still resolve the live per-user media context below.

    The media helper is defined later in this module.  Looking it up dynamically
    keeps semantic-contract unit tests independent from the LINE/image stack.
    """
    try:
        override = getattr(_tl, "measurement_work_order_context_override", None)
        if isinstance(override, bool):
            return override
        fn = globals().get("get_recent_work_order_media_context")
        if not callable(fn):
            return False
        return bool(fn(
            getattr(_tl, "group_id", None),
            getattr(_tl, "user_id", None),
        ))
    except Exception:
        return False


def _resolve_pending_work_order_context_for_measurement():
    """Resolve the narrow image/text race for terse measurement shorthand.

    Image OCR runs in a background thread.  A worker can therefore receive
    ``Mesin I5 mikro kecil`` a fraction of a second after the photo while the
    work-order classifier is still running.  For this one high-risk, complete
    semantic frame we briefly poll the shared disk context.  Ordinary text never
    waits, and a non-work-order scene ends the wait immediately.
    """
    gid = getattr(_tl, "group_id", None)
    uid = getattr(_tl, "user_id", None)
    if not gid or not uid:
        return False

    cache = getattr(_tl, "measurement_media_context_resolution", None)
    if not isinstance(cache, dict):
        cache = {}
        try:
            _tl.measurement_media_context_resolution = cache
        except Exception:
            pass
    key = (str(gid), str(uid))
    if key in cache:
        return bool(cache[key])

    work_order_fn = globals().get("get_recent_work_order_media_context")
    pending_fn = globals().get("get_recent_pending_image_media_context")
    state_fn = globals().get("get_recent_media_context_state")
    if not callable(work_order_fn):
        cache[key] = False
        return False
    try:
        if work_order_fn(gid, uid):
            cache[key] = True
            return True
        if not callable(pending_fn) or not pending_fn(gid, uid):
            cache[key] = False
            return False
    except Exception:
        cache[key] = False
        return False

    try:
        wait_s = max(0.0, min(5.0, float(os.environ.get(
            "MEASUREMENT_MEDIA_CONTEXT_WAIT_SECONDS", "3.0"
        ))))
    except Exception:
        wait_s = 3.0
    if wait_s <= 0:
        cache[key] = False
        return False

    deadline = time.monotonic() + wait_s
    while time.monotonic() < deadline:
        time.sleep(0.10)
        try:
            if work_order_fn(gid, uid):
                cache[key] = True
                return True
            # Once OCR/scene classification replaced the pending marker with a
            # non-work-order scene, there is nothing left to wait for.
            if callable(state_fn) and state_fn(gid, uid) not in ("pending", "work_order"):
                break
        except Exception:
            break
    cache[key] = False
    return False


def _build_id_zh_measurement_frame(text):
    """Build the shared terse measurement frame using the canonical equipment asset.

    Normalize known code spellings inside the helper as well as at the public
    translation boundary.  This keeps every caller safe, including validation
    paths that may receive raw ``i 5`` / ``bf 3`` text directly.
    """
    try:
        normalized_text, _ = normalize_known_equipment_codes(
            text, getattr(_tl, "line_mentions", None)
        )
        codes = _extract_known_equipment_codes(normalized_text)
        work_order_context = _current_work_order_media_context()
        # Parse once without media context so only a complete, high-confidence
        # measurement shorthand is allowed to wait for an in-flight image OCR.
        preliminary = factory_measurement_semantics_module.build_frame(
            normalized_text,
            equipment_codes=codes,
            work_order_context=work_order_context,
        )
        if (not work_order_context
                and preliminary.get("active")
                and preliminary.get("complete")):
            work_order_context = _resolve_pending_work_order_context_for_measurement()
        if work_order_context != bool(preliminary.get("work_order_context")):
            return factory_measurement_semantics_module.build_frame(
                normalized_text,
                equipment_codes=codes,
                work_order_context=work_order_context,
            )
        return preliminary
    except Exception as exc:
        _logger = globals().get("logger")
        if _logger is not None and hasattr(_logger, "warning"):
            _logger.warning("[FactoryMeasurementSemantics] frame failed open: %s", exc)
        return {"active": False, "complete": False}


def build_translation_semantic_contract(text, src, tgt):
    """Build one runtime contract for the current translation request.
    Contract is intentionally plain dict so every legacy module can consume it without new dependencies.
    """
    contract = {
        "version": _SEMANTIC_CONTRACT_VERSION,
        "src": src,
        "tgt": tgt,
        "has_risk": False,
        "risks": [],
        "tm_bypass_allowed": True,
        "vector_bypass_allowed": True,
        "nmt_allowed": True,
        "requires_llm": False,
        "context_bound": False,
    }
    if src == "id" and tgt == "zh":
        # Several dependency-free regression tests intentionally execute this
        # function in an AST-isolated namespace.  Resolve the optional factory
        # measurement helper dynamically so unrelated semantic contracts remain
        # testable without importing the full LINE/image stack.
        _measurement_frame_fn = globals().get("_build_id_zh_measurement_frame")
        measurement_frame = (
            _measurement_frame_fn(text)
            if callable(_measurement_frame_fn)
            else {"active": False, "complete": False}
        )
        if measurement_frame.get("active"):
            contract["has_risk"] = True
            contract["risks"].append({
                "term": "id_zh_measurement_shorthand",
                "sense": "id_zh_measurement_shorthand",
                "frame": measurement_frame,
                "tm_bypass_allowed": False,
                "nmt_allowed": False,
                "requires_validation": True,
            })
            contract["tm_bypass_allowed"] = False
            contract["vector_bypass_allowed"] = False
            contract["nmt_allowed"] = False
            contract["requires_llm"] = True
            contract["requires_independent_review"] = True
            if measurement_frame.get("work_order_context"):
                # The omitted order object comes from recent media, not source
                # text.  Source-only cache/TM keys must never learn this result.
                contract["context_bound"] = True

        try:
            t_id = _clean_factory_id(text)
            preop_direction = (
                _has_factory_pre_operation_marker(t_id)
                and any(re.search(r"(?<![a-z])" + re.escape(k) + r"(?![a-z])", t_id) for k in FACTORY_ID_ZH_POSITIONS.keys())
                and (
                    _factory_material_subject_zh_id_to_zh(t_id) is not None
                    or any(re.search(r"(?<![a-z])" + re.escape(k) + r"(?![a-z])", t_id) for k in FACTORY_ID_ZH_DEFECTS.keys())
                )
            )
            if preop_direction:
                contract["has_risk"] = True
                contract["risks"].append({
                    "term": "sebelum+belakang/depan",
                    "sense": "id_zh_temporal_direction_boundary",
                    "tm_bypass_allowed": False,
                    "nmt_allowed": False,
                })
                contract["tm_bypass_allowed"] = False
                contract["vector_bypass_allowed"] = False
                contract["nmt_allowed"] = False
                contract["requires_llm"] = True
        except Exception:
            pass

    if src == "zh" and tgt == "id":
        # Some isolated unit tests execute this function without importing the
        # whole application module.  Fail open there; production startup always
        # verifies and loads the shared terminology engine above.
        _ft_module = globals().get("factory_terminology_module")
        _org_matches = (
            _ft_module.collect_organization_matches(text, src, tgt, globals().get("GLOSSARY_LOOKUP") or {})
            if _ft_module is not None else []
        )
        if _org_matches:
            contract["has_risk"] = True
            contract["risks"].append({
                "term": "factory_organization_unit",
                "sense": "factory_organization_terms",
                "pairs": [(m.matched_text, m.target_term) for m in _org_matches],
                "tm_bypass_allowed": False,
                "nmt_allowed": False,
                "requires_validation": True,
            })
            contract["tm_bypass_allowed"] = False
            contract["vector_bypass_allowed"] = False
            contract["nmt_allowed"] = False
            contract["requires_llm"] = True

        _work_order_fn = globals().get("_classify_factory_work_order_zh_id")
        work_order = _work_order_fn(text) if callable(_work_order_fn) else None
        if work_order:
            contract["has_risk"] = True
            contract["risks"].append(work_order)
            contract["tm_bypass_allowed"] = False
            contract["vector_bypass_allowed"] = False
            contract["nmt_allowed"] = False
            contract["requires_llm"] = True

        qing = _classify_qing_sense_zh_id(text)
        if qing and qing.get("sense") in ("treat_sponsor_pay_for", "ambiguous_qing"):
            contract["has_risk"] = True
            contract["risks"].append(qing)
            if not qing.get("tm_bypass_allowed", True):
                contract["tm_bypass_allowed"] = False
                contract["vector_bypass_allowed"] = False
            if not qing.get("nmt_allowed", True):
                contract["nmt_allowed"] = False
                contract["requires_llm"] = True

        station = _classify_factory_station_alias_zh_id(text)
        if station:
            contract["has_risk"] = True
            contract["risks"].append(station)
            contract["tm_bypass_allowed"] = False
            contract["vector_bypass_allowed"] = False
            contract["nmt_allowed"] = False
            contract["requires_llm"] = True

        _factory_terms_fn = globals().get("_classify_factory_domain_terms_zh_id")
        factory_terms = _factory_terms_fn(text) if callable(_factory_terms_fn) else None
        if factory_terms:
            contract["has_risk"] = True
            contract["risks"].append(factory_terms)
            contract["tm_bypass_allowed"] = False
            contract["vector_bypass_allowed"] = False
            contract["nmt_allowed"] = False
            contract["requires_llm"] = True

        _reason_contract_fn = globals().get("_factory_reason_contract_risk")
        reason_risk = _reason_contract_fn(text) if callable(_reason_contract_fn) else None
        if reason_risk:
            contract["has_risk"] = True
            contract["risks"].append(reason_risk)
            contract["tm_bypass_allowed"] = False
            contract["vector_bypass_allowed"] = False
            contract["nmt_allowed"] = False
            contract["requires_llm"] = True

    # Source-claim semantic frame.  Unlike a keyword glossary, this records the
    # operational relationships that must survive translation: time/scope,
    # machine assignment, material contrast, priority, prohibition and whether
    # the source actually names crane/RPM details.
    try:
        _fsa_module = globals().get("factory_semantic_audit_module")
        source_frame = (
            _fsa_module.build_source_frame(text, src, tgt)
            if _fsa_module is not None else {"active": False}
        )
    except Exception as exc:
        _logger = globals().get("logger")
        if _logger is not None and hasattr(_logger, "warning"):
            _logger.warning("[FactorySemanticAudit] source frame failed open: %s", exc)
        source_frame = {"active": False}
    if source_frame.get("active"):
        contract["has_risk"] = True
        contract["risks"].append({
            "term": "factory_source_claims",
            "sense": "factory_source_semantic_frame",
            "frame": source_frame,
            "tm_bypass_allowed": False,
            "nmt_allowed": False,
            "requires_validation": True,
        })
        contract["tm_bypass_allowed"] = False
        contract["vector_bypass_allowed"] = False
        contract["nmt_allowed"] = False
        contract["requires_llm"] = True
        if _fsa_module is not None and _fsa_module.should_force_review(source_frame):
            contract["requires_independent_review"] = True

    # Direction-neutral source relations. These frames bind values to their
    # devices, reports to their role/ID owner, and inspection actions to an
    # explicit movement/destination. They prevent a fluent target from passing
    # merely because it contains the right isolated nouns and numbers.
    try:
        _fmr_module = globals().get("factory_message_semantics_module")
        relation_frame = (
            _fmr_module.build_frame(text, src, tgt)
            if _fmr_module is not None else {"active": False}
        )
    except Exception as exc:
        _logger = globals().get("logger")
        if _logger is not None and hasattr(_logger, "warning"):
            _logger.warning("[FactoryMessageSemantics] source frame failed open: %s", exc)
        relation_frame = {"active": False}
    if relation_frame.get("active"):
        contract["has_risk"] = True
        contract["risks"].append({
            "term": "factory_message_source_relations",
            "sense": "factory_message_source_relations",
            "frame": relation_frame,
            "tm_bypass_allowed": False,
            "nmt_allowed": False,
            "requires_validation": True,
        })
        contract["tm_bypass_allowed"] = False
        contract["vector_bypass_allowed"] = False
        contract["nmt_allowed"] = False
        contract["requires_llm"] = True
        contract["requires_independent_review"] = True

    # Compositional number/classifier semantics. This is generated from atoms
    # and relations, not from sentence matches, and therefore protects paraphrases
    # such as 一包又六雙 / 每人半包 / 不是兩箱而是一箱半.
    try:
        quantity_frame = factory_quantity_semantics_module.build_frame(text, src, tgt)
    except Exception as exc:
        _logger = globals().get("logger")
        if _logger is not None and hasattr(_logger, "warning"):
            _logger.warning("[FactoryQuantitySemantics] source frame failed open: %s", exc)
        quantity_frame = {"active": False}
    if quantity_frame.get("active"):
        contract["has_risk"] = True
        contract["risks"].append({
            "term": "factory_quantities",
            "sense": "factory_quantity_semantics",
            "frame": quantity_frame,
            "tm_bypass_allowed": False,
            "nmt_allowed": False,
            "requires_validation": True,
        })
        contract["tm_bypass_allowed"] = False
        contract["vector_bypass_allowed"] = False
        contract["nmt_allowed"] = False
        contract["requires_llm"] = True
        contract["requires_independent_review"] = True

    # Generic plant-context retrieval.  This is direction-neutral and data-driven:
    # adding a new workflow means editing factory_knowledge.json, not app.py.
    try:
        _fk_module = globals().get("factory_knowledge_module")
        knowledge_cards = _fk_module.retrieve(text, src, tgt, limit=5) if _fk_module is not None else []
    except Exception as exc:
        _logger = globals().get("logger")
        if _logger is not None and hasattr(_logger, "warning"):
            _logger.warning("[FactoryKnowledge] retrieval failed open: %s", exc)
        knowledge_cards = []
    if knowledge_cards:
        contract["has_risk"] = True
        contract["risks"].append({
            "term": "factory_context_knowledge",
            "sense": "factory_knowledge_context",
            "source_text": text,
            "cards": knowledge_cards,
            "tm_bypass_allowed": False,
            "nmt_allowed": False,
            "requires_validation": True,
        })
        contract["tm_bypass_allowed"] = False
        contract["vector_bypass_allowed"] = False
        contract["nmt_allowed"] = False
        contract["requires_llm"] = True

    # Verified examples and human corrections are one semantic asset.  A strong
    # casebook match protects paraphrases, not only the exact sentence stored in
    # TM.  It therefore disables stale bypass routes and requests independent
    # source review for the final candidate.
    try:
        casebook_cases = _retrieve_verified_translation_cases(text, src, tgt, max_cases=4)
    except Exception as exc:
        _logger = globals().get("logger")
        if _logger is not None and hasattr(_logger, "warning"):
            _logger.warning("[TranslationCasebook] retrieval failed open: %s", exc)
        casebook_cases = []
    _casebook_module = globals().get("translation_casebook_module")
    if (_casebook_module is not None
            and _casebook_module.casebook_requires_review(casebook_cases)):
        contract["has_risk"] = True
        contract["risks"].append({
            "term": "verified_translation_cases",
            "sense": "verified_correction_cases",
            "cases": casebook_cases,
            "tm_bypass_allowed": False,
            "nmt_allowed": False,
            "requires_validation": True,
        })
        contract["tm_bypass_allowed"] = False
        contract["vector_bypass_allowed"] = False
        contract["nmt_allowed"] = False
        contract["requires_llm"] = True
        contract["requires_independent_review"] = True
    return contract

def semantic_contract_requires_llm(contract):
    return bool(contract and contract.get("requires_llm"))

def build_translation_semantic_contract_prompt(contract):
    """Turn contract into a compact XML prompt block. Empty when no risk."""
    if not contract or not contract.get("has_risk"):
        return ""
    lines = ["<semantic_contract>"]
    lines.append("This block is generated by deterministic pre-translation semantic analysis. It overrides TM/NMT/examples/general dictionary meanings.")
    for risk in contract.get("risks", []):
        if risk.get("sense") == "factory_source_semantic_frame":
            _fsa_module = globals().get("factory_semantic_audit_module")
            frame_prompt = (_fsa_module.build_prompt(risk.get("frame") or {})
                            if _fsa_module is not None else "")
            if frame_prompt:
                lines.append(frame_prompt)
        elif risk.get("sense") == "factory_message_source_relations":
            _fmr_module = globals().get("factory_message_semantics_module")
            relation_prompt = (
                _fmr_module.build_prompt(risk.get("frame") or {})
                if _fmr_module is not None else ""
            )
            if relation_prompt:
                lines.append(relation_prompt)
        elif risk.get("sense") == "factory_quantity_semantics":
            quantity_prompt = factory_quantity_semantics_module.build_prompt(risk.get("frame") or {})
            if quantity_prompt:
                lines.append(quantity_prompt)
        elif risk.get("sense") == "id_zh_measurement_shorthand":
            measurement_prompt = factory_measurement_semantics_module.build_prompt(risk.get("frame") or {})
            if measurement_prompt:
                lines.append(measurement_prompt)
        elif risk.get("sense") == "factory_knowledge_context":
            knowledge_prompt = factory_knowledge_module.build_prompt(risk.get("cards", []))
            if knowledge_prompt:
                lines.append(knowledge_prompt)
        elif risk.get("sense") == "verified_correction_cases":
            _casebook_module = globals().get("translation_casebook_module")
            case_prompt = (_casebook_module.build_prompt(risk.get("cases", []))
                           if _casebook_module is not None else "")
            if case_prompt:
                lines.append(case_prompt)
        elif risk.get("sense") == "factory_organization_terms":
            lines.append("<risk term='factory_organization_unit' sense='factory_organization_terms'>")
            lines.append("These are factory organization levels, not names. Use the plant ERP/glossary mapping for 股 units. In this plant 一股 means Bagian Cold Drawing 1; never translate it as Yigu, Regu 1, or Subseksi 1. 一課 means Seksi 1.")
            for source_term, target_term in risk.get("pairs", []):
                lines.append(f"Use exactly: {source_term} => {target_term}.")
            lines.append("</risk>")
        elif risk.get("term") == "請" and risk.get("sense") == "treat_sponsor_pay_for":
            sponsor = risk.get("sponsor_id") or "the sponsor/person/company"
            ev = ", ".join(risk.get("evidence", [])[:6])
            lines.append("<risk term='請' sense='treat_sponsor_pay_for'>")
            lines.append(f"Evidence: {ev}.")
            lines.append("Chinese 請 here means treat/sponsor/pay for, NOT request/ask/order.")
            lines.append(f"Use Indonesian meaning: ditraktir/dibayarin/disponsori oleh {sponsor}.")
            lines.append("Forbidden Indonesian words for this sense: diminta, minta, meminta, permintaan, dimohon, mohon, dipesan, pesanan, requested, request.")
            lines.append("</risk>")
        elif risk.get("term") == "請" and risk.get("sense") == "ambiguous_qing":
            lines.append("<risk term='請' sense='ambiguous_qing'>")
            lines.append("Decide 請 by context before translating; do not default to request if the surrounding words describe food, drinks, welfare distribution, or sponsorship.")
            lines.append("</risk>")
        elif risk.get("sense") == "id_zh_temporal_direction_boundary":
            lines.append("<risk term='sebelum+belakang/depan' sense='id_zh_temporal_direction_boundary'>")
            lines.append("For Indonesian source containing sebelum di-jalankan/diproses and belakang/depan, keep time and material direction separate in Chinese.")
            lines.append("Correct pattern: 加工前，後端/前端... Forbidden merged pattern: 加工前後端 / 啟動前後端 / 運行前後端.")
            lines.append("Use material terminology: barang=料件, batang=棒材, belakang=後端, depan=前端, masalah=問題/異常.")
            lines.append("</risk>")
        elif risk.get("sense") == "factory_station_canonical_name":
            lines.append("<risk term='異型包裝站' sense='factory_station_canonical_name'>")
            lines.append("In this factory context, 異型那站/異型那邊 is the official station name 異型包裝站, not a product category and not a generic 'special goods station'.")
            lines.append("Translate the station name exactly as: Stasiun packing barang bentuk khusus.")
            lines.append("Keep 異型棒 separate: 異型棒 means batang bentuk khusus.")
            lines.append("</risk>")
        elif risk.get("sense") == "factory_work_order_terms":
            lines.append("<risk term='factory_work_order' sense='factory_work_order_terms'>")
            for key in risk.get("entries", []):
                note = _FACTORY_WORK_ORDER_TERM_NOTES.get(key)
                if note:
                    lines.append(note)
            lines.append("Do not use material-book, ruler, generic order, or body-weight meanings.")
            lines.append("</risk>")
        elif risk.get("sense") == "factory_domain_term_semantics":
            lines.extend(_build_factory_domain_term_contract_lines(risk))
        elif risk.get("sense") == "factory_reason_action_semantics":
            lines.extend(_build_factory_reason_contract_lines(risk))
    lines.append("</semantic_contract>")
    return " ".join(lines)

def translation_satisfies_semantic_contract(contract, translation):
    if not contract or not contract.get("has_risk"):
        return True, ""
    t = (translation or "").strip()
    low = t.lower()
    for risk in contract.get("risks", []):
        if risk.get("sense") == "factory_source_semantic_frame":
            _fsa_module = globals().get("factory_semantic_audit_module")
            if _fsa_module is not None:
                ok, issues = _fsa_module.validate_translation(risk.get("frame") or {}, t)
                if not ok:
                    return False, issues[0] if issues else "factory_source_semantic_frame_failed"
        elif risk.get("sense") == "factory_message_source_relations":
            _fmr_module = globals().get("factory_message_semantics_module")
            if _fmr_module is not None:
                ok, issues = _fmr_module.validate_translation(
                    risk.get("frame") or {}, t
                )
                if not ok:
                    return False, issues[0] if issues else "factory_message_source_relations_failed"
        elif risk.get("sense") == "factory_quantity_semantics":
            ok, issues = factory_quantity_semantics_module.validate_translation(risk.get("frame") or {}, t)
            if not ok:
                return False, issues[0] if issues else "factory_quantity_semantics_failed"
        elif risk.get("sense") == "id_zh_measurement_shorthand":
            ok, issues = factory_measurement_semantics_module.validate_translation(risk.get("frame") or {}, t)
            if not ok:
                return False, issues[0] if issues else "id_zh_measurement_shorthand_failed"
        elif risk.get("sense") == "factory_knowledge_context":
            ok, issues = factory_knowledge_module.validate_translation(
                risk.get("cards", []), risk.get("source_text", ""), t
            )
            if not ok:
                return False, issues[0] if issues else "factory_knowledge_validation_failed"
        elif risk.get("sense") == "factory_organization_terms":
            for source_term, target_term in risk.get("pairs", []):
                if target_term and target_term.casefold() not in t.casefold():
                    return False, "factory_organization_term_missing:" + str(source_term)
            if re.search(r"\byigu\b", low, flags=re.I):
                return False, "factory_organization_romanization_leak"
        elif risk.get("term") == "請" and risk.get("sense") == "treat_sponsor_pay_for":
            has_good = any(g in low for g in _SEM_QING_PREFERRED_ID)
            has_bad = any(b in low for b in _SEM_QING_FORBIDDEN_ID)
            if has_bad:
                return False, "qing_treat_translated_as_request"
            if not has_good:
                return False, "qing_treat_missing_treat_sponsor_marker"
        elif risk.get("sense") == "id_zh_temporal_direction_boundary":
            if re.search(r"(加工|處理|作業|生產|啟動|運行|操作|使用)前(?:後端|前端|尾端|自由端|夾頭端|中段|側邊)", t):
                return False, "id_zh_temporal_direction_boundary_missing"
            if re.search(r"(加工|處理|作業|生產|啟動|運行|操作|使用)之前(?:後端|前端|尾端|自由端|夾頭端|中段|側邊)", t):
                return False, "id_zh_temporal_direction_boundary_missing"
            if not any(d in t for d in ("後端", "前端", "尾端", "自由端", "夾頭端", "中段", "側邊")):
                return False, "id_zh_temporal_direction_missing"
        elif risk.get("sense") == "factory_station_canonical_name":
            required = (risk.get("required_id") or "").lower().strip()
            if required and required not in low:
                return False, "factory_station_canonical_name_missing"
        elif risk.get("sense") == "factory_work_order_terms":
            for pattern in _FACTORY_WORK_ORDER_BAD_ID_PATTERNS:
                if re.search(pattern, low, flags=re.I):
                    return False, "factory_work_order_forbidden_term"
            for key in risk.get("entries", []):
                required = _FACTORY_WORK_ORDER_REQUIRED_ID.get(key, ())
                if required and not _translation_has_any(low, required):
                    return False, "factory_work_order_missing:" + key
        elif risk.get("sense") == "factory_domain_term_semantics":
            for key in risk.get("entries", []):
                entry = _FACTORY_DOMAIN_TERM_MAP_ZH_ID.get(key)
                if not entry:
                    continue
                bad_hit = _factory_domain_forbidden_hit(entry, low)
                if bad_hit:
                    return False, "factory_domain_forbidden:" + key + ":" + bad_hit
                if not _factory_domain_translation_contains(entry, low):
                    return False, "factory_domain_term_missing:" + key
        elif risk.get("sense") == "factory_reason_action_semantics":
            for bad in _FACTORY_REASON_WRONG_ID_PATTERNS:
                if bad in low:
                    return False, "factory_reason_wrong_output:" + bad
            amap = _factory_reason_action_map()
            for key in risk.get("entries", []):
                entry = amap.get(key)
                if entry and not _factory_reason_translation_contains(entry, low):
                    return False, "factory_reason_action_missing:" + key
    return True, ""

def _semantic_rebuild_qing_treat_translation(src_text, contract, current_translation=""):
    """Build a safe translation when every model route violates the contract.
    This is not an exact-sentence replacement; it uses the classified sense + extracted slots.
    """
    compact = _semantic_compact_zh(src_text)
    risk = None
    for r in (contract or {}).get("risks", []):
        if r.get("term") == "請" and r.get("sense") == "treat_sponsor_pay_for":
            risk = r
            break
    if not risk:
        return current_translation
    sponsor_id = risk.get("sponsor_id") or _semantic_sponsor_to_id(_extract_semantic_sponsor_before_qing(src_text)) or "pihak yang traktir"
    brand = _extract_semantic_item_brand_zh(src_text)

    # Slot-based reconstruction for welfare announcements.
    if "冰箱" in compact and any(k in compact for k in ("飲料", "罐裝", "罐")):
        if "一人一罐" in compact or "每人一罐" in compact:
            item = "minuman kaleng" + ((" " + brand) if brand else "")
            return f"Di kulkas ada {item}, satu orang satu kaleng (ditraktir oleh {sponsor_id})."
        if "一人一瓶" in compact or "每人一瓶" in compact:
            item = "minuman botol" + ((" " + brand) if brand else "")
            return f"Di kulkas ada {item}, satu orang satu botol (ditraktir oleh {sponsor_id})."
        item = "minuman" + ((" " + brand) if brand else "")
        return f"Di kulkas ada {item} (ditraktir oleh {sponsor_id})."

    if "請客" in compact:
        return f"Ini traktiran dari {sponsor_id}." if sponsor_id else "Ini traktiran."

    # Generic safety: preserve model translation as much as possible, but remove request sense and add classified sponsor sense.
    result = (current_translation or "").strip()
    if result:
        result = re.sub(r"\s*[（(]?\s*(?:diminta|minta|meminta|permintaan|dimohon|mohon|dipesan|pesanan|requested|request)[^）)]*[）)]?\s*", " ", result, flags=re.I).strip()
        result = result.replace("\r\n", "\n").replace("\r", "\n")
        result = re.sub(r"[^\S\n]+", " ", result).strip()
        if result:
            return f"{result} (ditraktir oleh {sponsor_id})"
    return f"Ini ditraktir oleh {sponsor_id}."

def _repair_factory_station_canonical_name(translation, required_id):
    """最後安全網：只修正已分類為異型包裝站的目標站名片段。

    正常路徑應由來源正規化 + glossary 完成；此函式只處理模型仍輸出
    「stasiun barang khusus」等同義誤名的情況，不改動句中其他內容。
    """
    result = (translation or "").strip()
    if not result or not required_id:
        return result
    if required_id.lower() in result.lower():
        return result
    variants = (
        r"stasiun\s+barang\s+khusus",
        r"stasiun\s+bentuk\s+khusus",
        r"stasiun\s+khusus",
        r"stasiun\s+packing\s+khusus",
        r"bagian\s+barang\s+khusus",
        r"bagian\s+packing\s+khusus",
        r"station\s+barang\s+khusus",
    )
    for pattern in variants:
        repaired, count = re.subn(pattern, required_id, result, count=1, flags=re.I)
        if count:
            return repaired
    return result


def enforce_translation_semantic_contract(contract, src_text, translation):
    """Validate a produced translation against contract; rebuild only if contract is violated."""
    if not translation:
        return translation
    ok, reason = translation_satisfies_semantic_contract(contract, translation)
    if ok:
        return translation
    logger.warning("[SemanticContract] enforce: %s src=%r out=%r", reason, (src_text or '')[:80], (translation or '')[:120])
    try:
        _event_log_write("semantic_contract_enforced", {
            "reason": reason,
            "src_text": (src_text or '')[:160],
            "bad_translation": (translation or '')[:200],
            "contract": contract,
        })
    except Exception:
        pass
    for risk in (contract or {}).get("risks", []):
        if risk.get("sense") == "id_zh_measurement_shorthand":
            deterministic = factory_measurement_semantics_module.deterministic_translation(
                risk.get("frame") or {}
            )
            if deterministic:
                return deterministic
            return translation
        if risk.get("sense") == "factory_knowledge_context":
            # Do not fabricate a fixed sentence locally.  Keep the provider
            # candidate available and let the one-shot semantic repair path below
            # ask the model again with the retrieved knowledge.
            try:
                _tl.factory_knowledge_issues = [reason]
            except Exception:
                pass
            return translation
        elif risk.get("term") == "請" and risk.get("sense") == "treat_sponsor_pay_for":
            return _semantic_rebuild_qing_treat_translation(src_text, contract, translation)
        if risk.get("sense") == "id_zh_temporal_direction_boundary":
            fixed = _fix_zh_temporal_direction_boundary(src_text, translation)
            ok2, _ = translation_satisfies_semantic_contract(contract, fixed)
            if ok2:
                return fixed
            fallback = factory_semantic_translate_pre_operation_issue_id_zh(src_text)
            if fallback:
                return fallback
            return fixed
        if risk.get("sense") == "factory_station_canonical_name":
            return _repair_factory_station_canonical_name(
                translation,
                risk.get("required_id") or "stasiun packing barang bentuk khusus",
            )
        if risk.get("sense") == "factory_work_order_terms":
            fixed = _repair_factory_work_order_terms_zh_id(src_text, translation)
            ok2, _ = translation_satisfies_semantic_contract(contract, fixed)
            return fixed if ok2 else fixed
        if risk.get("sense") == "factory_domain_term_semantics":
            fixed = _repair_factory_domain_term_translation(translation, risk)
            ok2, _ = translation_satisfies_semantic_contract(contract, fixed)
            if ok2:
                return fixed
            return fixed
        if risk.get("sense") == "factory_reason_action_semantics":
            deterministic = _factory_reason_semantic_translate_zh_id(src_text)
            if deterministic:
                return deterministic
            return translation
    return translation

def _factory_knowledge_cards_from_contract(contract):
    cards = []
    for risk in (contract or {}).get("risks", []):
        if risk.get("sense") == "factory_knowledge_context":
            cards.extend(risk.get("cards", []) or [])
    return cards


def _verified_cases_from_contract(contract):
    cases = []
    for risk in (contract or {}).get("risks", []):
        if risk.get("sense") == "verified_correction_cases":
            cases.extend(risk.get("cases", []) or [])
    return cases


def _maybe_repair_factory_knowledge_translation(src_text, translation, src, tgt, contract):
    """Record semantic defects and reserve the single repair call for final audit.

    Older builds performed a generic repair here and therefore consumed the only
    second provider call before the source-grounded quality gate could run.  The
    final gate now performs the one structured source-claim adjudication, so this
    stage is intentionally local-only.
    """
    cards = _factory_knowledge_cards_from_contract(contract)
    if not cards or not translation:
        return translation
    ok, issues = factory_knowledge_module.validate_translation(cards, src_text, translation)
    if not ok:
        try:
            _tl.factory_knowledge_issues = list(issues)
        except Exception:
            pass
        try:
            _event_log_write("factory_knowledge_deferred_to_source_audit", {
                "src_text": (src_text or "")[:200],
                "card_ids": [card.get("id") for card in cards],
                "issues": list(issues)[:20],
            })
        except Exception:
            pass
    return translation


def filter_semantic_contract_references(contract, refs):
    """Remove TM/Vector references whose target side violates the active semantic contract."""
    if not contract or not contract.get("has_risk"):
        return refs
    filtered = []
    dropped = 0
    for item in refs:
        try:
            score, src_t, tgt_t, kind = item
            ok, _reason = translation_satisfies_semantic_contract(contract, tgt_t)
            if ok:
                filtered.append(item)
            else:
                dropped += 1
        except Exception:
            filtered.append(item)
    if dropped:
        logger.warning("[SemanticContract] dropped %d TM/Vec references violating semantic contract", dropped)
    return filtered

# Backward-compatible wrapper names used by older code/admin debug.
def build_qing_treat_context_hint_zh_id(text):
    return build_translation_semantic_contract_prompt(build_translation_semantic_contract(text, "zh", "id"))

def factory_semantic_translate_qing_treat_zh_id(text):
    contract = build_translation_semantic_contract(text, "zh", "id")
    if not contract.get("has_risk"):
        return None
    for risk in contract.get("risks", []):
        if risk.get("term") == "請" and risk.get("sense") == "treat_sponsor_pay_for":
            return _semantic_rebuild_qing_treat_translation(text, contract, "")
    return None

def fix_qing_treat_translation_zh_id(src_text, id_text):
    contract = build_translation_semantic_contract(src_text, "zh", "id")
    return enforce_translation_semantic_contract(contract, src_text, id_text)

def factory_semantic_translate_zh_id(text):
    """Deterministic Chinese->Indonesian factory translation for high-risk known factory shapes.
    Note: Chinese polysemy like『請』is handled by runtime semantic_contract, not by exact direct bypass here.
    """
    reason_semantic = _factory_reason_semantic_translate_zh_id(text)
    if reason_semantic:
        return reason_semantic
    src = text or ""
    compact = re.sub(r"\s+", "", src)
    # High-risk physical-placement reply.  The repeated「放」means putting
    # material into a storage slot / overflow location, not ERP data release.
    # Keep the customer identifier 大成 exactly as written.
    if (("週末" in compact or "周末" in compact)
            and "大成" in compact
            and ("儲格" in compact or "储格" in compact)
            and "放不下" in compact
            and ("照片" in compact or "圖片" in compact or "图片" in compact)
            and ("位置" in compact or "地方" in compact)):
        return (
            "Pada akhir pekan, jika slot penyimpanan 大成 masih dapat menampung material, "
            "letakkan material di sana. Jika tidak muat, letakkan material di lokasi-lokasi "
            "yang ditunjukkan pada foto-foto ini."
        )
    # Material storage instruction: keep the customer name and storage code
    # verbatim; 「集中放這格」is a physical slot assignment, not awkward
    # word-for-word "dikumpulkan taruh" and not a data operation.
    if (("入儲" in compact or "入庫" in compact or "入库" in compact)
            and "EH33" in compact and "峰作金屬" in compact
            and ("集中放" in compact or "統一放" in compact or "统一放" in compact)
            and ("這格" in compact or "这格" in compact)):
        return (
            "Saat material masuk ke area penyimpanan, semua material EH33 milik 峰作金屬 "
            "ditempatkan bersama di slot ini."
        )
    if all(k in compact for k in ["清洗前", "料", "品保"]) and ("偷跑" in compact or "吊去" in compact) and "刮傷" in compact:
        return (
            "Kalau material sebelum dicuci ditemukan sudah dibawa QC duluan, harus segera lapor. "
            "Sebelum dicuci, perhatikan dulu apakah material masuk ada goresan; "
            "kalau tidak, setelah dicuci goresannya bisa hilang atau tertutup."
        )
    if "偷跑" in compact and "品保" in compact:
        return "Kalau material sudah dibawa QC duluan tanpa konfirmasi, harus segera lapor."
    if "吊去" in compact and "品保" in compact:
        return "Material sudah dibawa oleh QC, harus segera dikonfirmasi."
    return None


def build_factory_context_hint_zh_id(text):
    src = text or ""
    # v3.11(2026-05-26): 加上「放了/放好了/都放了」這類 ERP 放行口語化簡寫的觸發詞,
    # 工廠裡這幾個是「資料已放行到下一站」的縮略,不是「東西放下了」。
    triggers = ["料", "品保", "清洗", "研磨", "噴漆", "進料", "出料", "產出", "入庫", "刮傷", "吊", "偷跑",
                "工單", "包裝", "裝箱", "木箱", "站別", "放了", "放好了", "都放了", "已放",
                "放行", "過帳", "退庫", "抓帳", "結帳", "關帳", "到料", "陸續到料",
                "儲格", "储格", "放不下", "放不下再放", "照片裡", "照片里", "照片位置",
                "入儲", "入庫", "集中放這格", "峰作金屬", "電子系統", "自然拉動"]
    if not any(k in src for k in triggers):
        return ""
    return (
        "【繁中→印尼工廠語義提示】這是台灣不鏽鋼棒材工廠群組訊息，不可逐字翻。"
        "料/進料=material/bahan masuk；品保=QC；材料清洗=cuci/dicuci/proses pencucian，環境打掃才用 pembersihan；"
        "出料需依語境判斷：出料口/夾輪出料/材料退出=keluarkan/pengeluaran material；出料狀況/出料量/每日出料/設備出料=hasil produksi mesin/output produksi，禁止 kondisi material keluar；"
        "吊去=被吊走/移走/帶走，譯為 dibawa/diangkat，不可譯成 dicuri；"
        "偷跑=未照正常流程先拿走/先做/先跑，譯為 dibawa/diproses duluan tanpa konfirmasi，不是偷竊；"
        "反應=回報/通報，譯為 lapor/beri tahu，不是 bereaksi；"
        "被吃掉=痕跡被清洗/加工後消失或被蓋掉，譯為 hilang/tertutup，不是 tertelan。"
        # v3.11: 「放了」家族(ERP 放行口語縮寫)
        "放了/放好了/都放了/已放/放完了=ERP 系統放行(release data ke stasiun berikutnya)的口語縮寫，"
        "在工廠群組裡幾乎都是這個意思，"
        "譯為 sudah di-release ke stasiun berikutnya 或 sudah lulus untuk dilanjutkan，"
        "**不要**譯為 sudah di-taruh / sudah dilepas / sudah ditempatkan(這些是字面物理放置，會誤導印尼工人)；"
        "但若來源同時有儲格/儲位/位置/照片/放不下/能放就放等空間容量詞，『放』就是材料的物理放置，"
        "應譯為 letakkan/taruh/masukkan；『儲格』=slot penyimpanan，『放不下』=tidak muat，"
        "『照片裡這些位置』=lokasi-lokasi yang ditunjukkan pada foto，這類句子禁止翻成 release data；"
        "放行(站別/物料放行)=release data ke stasiun berikutnya；"
        "放行(品保/QC放行,如「品保放行/品保有放行/QC放行」)=QC release / di-release oleh QC(不加 data)；"
        "過帳=input data produksi ke sistem；"
        "退庫=kembalikan ke gudang。"
        "工單=work order(不是 perintah kerja/lembar kerja/buku bahan)；"
        "工單資訊=informasi pada work order；噴漆=pengecatan semprot/mengecat；禁止 spray cat；"
        "來料尺寸=ukuran material masuk；表面品質=kualitas permukaan；"
        "短尺維護=penanganan material pendek(短尺材料處理,不是 penggaris/尺規)；"
        "重量確認=konfirmasi berat；作業流程=alur kerja。"
        "抓帳/會計結帳/關帳=tutup buku，嚴禁 cek data/periksa data/rekap data；"
        "木箱=peti kayu(工業出貨木箱)，嚴禁 kotak kayu；裝箱=把材料放入 peti kayu，否定句也必須保留 peti kayu 範圍；"
        "陸續到料=material akan tiba secara bertahap，必須保留未來與分批到貨；"
        "入儲/入庫=material masuk ke area penyimpanan；集中放這格=ditempatkan bersama di slot ini；"
        "峰作金屬是客戶名稱，必須原樣保留，嚴禁 Peng Zuo Metal/Feng Zuo Metal；"
        "自然拉動=tarikan alami/pasif，不等於 manual；來源未寫手動/人工時，嚴禁自行補 ditarik secara manual。"
    )


