        # User ID hash (always supported)
        _user_id = getattr(_tl, 'user_id', '')
        if send_user_id_to_openai and _user_id:
            import hashlib as _h
            _kwargs["user"] = _h.sha256(_user_id.encode()).hexdigest()[:32]
