def _build_expression_visual_message(source_text, translated_text, source_lang, group_id, *, from_image_ocr=False):
    """Build one optional local image or image-card without an AI request.

    Selection is context-aware, manifest-driven and cooldown-limited. Any error
    returns ``None`` so a valid translation is never blocked by decoration.
    """
    if not ImageMessage or not get_auto_tone_emoji_enabled(group_id):
        return None
    settings = get_expressive_runtime_settings(group_id, include_images=True)
    if not settings.images_enabled:
        return None
    if from_image_ocr and not settings.ocr_enabled:
        return None
    try:
        expressive = expressive_engine_module.enhance_translation(
            source_text,
            translated_text,
            source_language=source_lang,
            context_id=str(group_id or "global"),
            settings=expressive_engine_module.ExpressiveSettings(
                enabled=settings.enabled,
                display_mode=settings.display_mode,
                intensity=settings.intensity,
                visual_style=settings.visual_style,
                emoji_enabled=False,
                images_enabled=settings.images_enabled,
                short_message_image_enabled=settings.short_message_image_enabled,
                short_message_max_chars=settings.short_message_max_chars,
                formal_safety_enabled=settings.formal_safety_enabled,
                ocr_enabled=settings.ocr_enabled,
            ),
            from_image_ocr=from_image_ocr,
        )
    except Exception as exc:
        logger.debug("expression visual planning unavailable: %s", exc)
        return None
    selection = expressive.visual
    if not selection:
        return None
    public_url = (
        os.environ.get("PUBLIC_URL")
        or os.environ.get("RENDER_EXTERNAL_URL")
        or ""
    ).rstrip("/")
    if not public_url and has_request_context():
        public_url = request.url_root.rstrip("/")
    if not public_url:
        return None
    url = public_url + selection.relative_url
    try:
        if selection.presentation == "image":
            return ImageMessage(originalContentUrl=url, previewImageUrl=url)
        zh_title, id_title = _EXPRESSION_VISUAL_TITLES.get(
            selection.title_key, ("智慧情境卡", "Kartu konteks")
        )
        title = id_title if source_lang == "zh" else zh_title
        subtitle = "情境圖片為輔助，譯文仍以文字為準 / Visual hanya pelengkap"
        preview = re.sub(r"\s+", " ", str(translated_text or "")).strip()
        if len(preview) > 260:
            preview = preview[:257].rstrip() + "..."
        body_contents = [
            {"type": "text", "text": title, "weight": "bold", "size": "md", "color": "#FFFFFF"},
        ]
        if preview:
            body_contents.extend([
                {"type": "separator", "margin": "md", "color": "#374151"},
                {
                    "type": "text",
                    "text": preview,
                    "size": "sm",
                    "color": "#F9FAFB",
                    "margin": "md",
                    "wrap": True,
                    "maxLines": 6,
                },
            ])
        body_contents.append(
            {"type": "text", "text": subtitle, "size": "xxs", "color": "#9CA3AF", "margin": "md", "wrap": True}
        )
        bubble = {
            "type": "bubble",
            "size": "mega",
            "hero": {
                "type": "image",
                "url": url,
                "size": "full",
                "aspectRatio": "1200:630",
                "aspectMode": "cover",
            },
            "body": {
                "type": "box",
                "layout": "vertical",
                "paddingAll": "16px",
                "backgroundColor": "#111827",
                "contents": body_contents,
            },
        }
        alt_preview = (" — " + preview) if preview else ""
        return FlexMessage(
            alt_text=(title + alt_preview)[:400],
            contents=FlexContainer.from_dict(bubble),
        )
    except Exception as exc:
        logger.debug("expression visual card unavailable: %s", exc)
        return None


def _send_reply_with_push_fallback(
    *,
    reply_token,
    target_id,
    message_obj,
    fallback_text,
    retry_key=None,
    notification_disabled=False,
    append_messages=None,
):
    """Send through LINE reply API, then fall back to push if token expired.

    Long translations can legitimately finish after the reply token is no
    longer usable.  Delivery fallback is independent from AI failover and does
    not trigger another translation request.
    """
    try:
        with ApiClient(configuration) as api_client:
            api_line = MessagingApi(api_client)
            # Keep the actual translation first. Optional mood visuals follow it,
            # so users never need to scroll past a decorative image to read text.
            _messages = [message_obj] + list(append_messages or [])
            req = ReplyMessageRequest(reply_token=reply_token, messages=_messages)
            if notification_disabled:
                req.notification_disabled = True
            try:
                if retry_key:
                    response = api_line.reply_message(req, x_line_retry_key=retry_key)
                else:
                    response = api_line.reply_message(req)
            except TypeError:
                response = api_line.reply_message(req)
        return response, "reply"
    except Exception as reply_exc:
        logger.warning(
            "LINE reply failed; falling back to push target=%s error=%s",
            target_id, str(reply_exc)[:300],
        )
        try:
            _event_log_write("line_reply_fallback_push", {
                "target": str(target_id or "")[-16:],
                "error": str(reply_exc)[:300],
            })
        except Exception:
            pass
        with ApiClient(configuration) as api_client:
            api_line = MessagingApi(api_client)
            push_msg = TextMessage(text=_clip_line_text(fallback_text))
            _push_messages = [push_msg] + list(append_messages or [])
            response = api_line.push_message(PushMessageRequest(
                to=target_id,
                messages=_push_messages,
            ))
        return response, "push"


def _translation_retry_delays():
    """Return the initial retry delays, defaulting to 2s/8s/20s."""
    raw = str(os.environ.get("TRANSLATION_RETRY_DELAYS", "2,8,20") or "2,8,20")
    delays = []
    for part in raw.split(","):
        try:
            value = max(1, min(300, int(float(part.strip()))))
        except Exception:
            continue
        if value not in delays:
            delays.append(value)
    return tuple(delays[:8] or (2, 8, 20))


def _translation_retry_backoff(completed_attempts):
    """Delay after a failed attempt; retries continue until delivery succeeds."""
    initial = _translation_retry_delays()
    completed = max(1, int(completed_attempts or 1))
    if completed < len(initial):
        return initial[completed]
    try:
        cap = max(60, min(3600, int(os.environ.get("TRANSLATION_RETRY_MAX_DELAY", "300"))))
    except Exception:
        cap = 300
    exponent = max(0, completed - len(initial))
    return min(cap, 60 * (2 ** min(exponent, 6)))


def _translation_retry_key(ctx, source_text, src_lang, target_langs):
    message_id = str((ctx or {}).get("message_id") or "").strip()
    target_id = str((ctx or {}).get("group_id") or (ctx or {}).get("user_id") or "").strip()
    if message_id:
        return target_id + ":" + message_id
    payload = "\x1f".join([
        target_id,
        str(src_lang or ""),
        ",".join(str(x) for x in (target_langs or [])),
        str(source_text or ""),
    ])
    return target_id + ":sha256:" + hashlib.sha256(payload.encode("utf-8")).hexdigest()[:24]


def _translation_retry_push(job_key, payload, reply_text):
    """Push one completed retry with a stable LINE idempotency key."""
    import uuid

    target_id = payload.get("group_id") or payload.get("user_id")
    if not target_id:
        raise ValueError("translation retry has no LINE target")
    text = _clip_line_text(reply_text)
    quote_token = payload.get("quote_token")
    stable_retry_key = str(uuid.uuid5(uuid.NAMESPACE_URL, "jy-translation-retry:" + str(job_key)))

    def _push(message):
        with ApiClient(configuration) as api_client:
            api = MessagingApi(api_client)
            request_obj = PushMessageRequest(to=target_id, messages=[message])
            try:
                return api.push_message(request_obj, x_line_retry_key=stable_retry_key)
            except TypeError:
                return api.push_message(request_obj)

    message = TextMessage(text=text)
    if quote_token:
        try:
            message.quote_token = quote_token
        except Exception:
            pass
    try:
        return _push(message)
    except Exception:
        # A quote token can expire while a durable retry is waiting.  The
        # translation itself must still be delivered, so retry the push without
        # quote metadata and with the same stable retry key.
        return _push(TextMessage(text=text))



def _translation_retry_push_chunks(job_key, payload, text, *, max_messages=5):
    """Push a long durable result without truncating supported document text."""
    target_id = payload.get("group_id") or payload.get("user_id")
    if not target_id:
        raise ValueError("translation retry has no LINE target")
    value = str(text or "")
    chunks = []
    while value and len(chunks) < max(1, int(max_messages or 5)):
        cut = min(4700, len(value))
        if cut < len(value):
            boundary = max(value.rfind("\n", 0, cut), value.rfind(" ", 0, cut))
            if boundary >= 1000:
                cut = boundary + 1
        chunks.append(value[:cut])
        value = value[cut:]
    if value:
        # TEXT_FILE_MAX_CHARS keeps normal jobs below this limit. Preserve a
        # clear continuation marker rather than silently slicing mid-sentence.
        chunks[-1] = chunks[-1][:4650] + "\n…"
    messages = [TextMessage(text=_clip_line_text(chunk)) for chunk in chunks if chunk]
    if not messages:
        raise ValueError("translation retry has empty LINE payload")
    quote_token = payload.get("quote_token")
    if quote_token:
        try:
            messages[0].quote_token = quote_token
        except Exception:
            pass
    stable_retry_key = str(uuid.uuid5(uuid.NAMESPACE_URL, "jy-translation-retry:" + str(job_key)))
    with ApiClient(configuration) as api_client:
        api = MessagingApi(api_client)
        request_obj = PushMessageRequest(to=target_id, messages=messages)
        try:
            return api.push_message(request_obj, x_line_retry_key=stable_retry_key)
        except TypeError:
            return api.push_message(request_obj)


def _translation_retry_attempt(job, lease_owner=None):
    """Process one durable text job. Returns True only after LINE delivery."""
    payload = dict((job or {}).get("payload") or {})
    job_key = str((job or {}).get("job_key") or "")
    source_text = str(payload.get("source_text") or "").strip()
    src_lang = str(payload.get("src_lang") or "auto").strip() or "auto"
    targets = [str(x or "").strip() for x in payload.get("target_langs") or []]
    targets = list(dict.fromkeys(x for x in targets if x))
    target_id = payload.get("group_id") or payload.get("user_id")
    if not job_key or not source_text or not targets or not target_id:
        translation_retry_queue_module.remove(job_key)
        return True

    previous = {}
    missing = object()
    attrs = (
        "group_id", "user_id", "line_mentions", "tone", "tone_custom",
        "disable_tone_emoji", "quoted_context_source", "quoted_context_message_id",
        "from_image_ocr",
    )
    try:
        for attr in attrs:
            previous[attr] = getattr(_tl, attr, missing)
        group_id = payload.get("group_id")
        _tl.group_id = group_id or "__dm_retry__"
        _tl.user_id = str(payload.get("user_id") or "")
        _tl.line_mentions = list(payload.get("line_mentions") or [])
        _tl.quoted_context_source = str(payload.get("quoted_context_source") or "")
        _tl.quoted_context_message_id = str(payload.get("quoted_context_message_id") or "")
        _tl.from_image_ocr = bool(payload.get("from_image_ocr"))
        if group_id:
            try:
                _tone, _tone_custom = get_group_tone(group_id)
            except Exception:
                _tone, _tone_custom = translation_tone, translation_tone_custom
        else:
            _tone, _tone_custom = translation_tone, translation_tone_custom
        _tl.tone = _tone
        _tl.tone_custom = _tone_custom

        if payload.get("from_file"):
            primary_target = targets[0]
            translated_parts = []
            for part in _split_text_for_translation(source_text):
                translated = translate(part, src_lang, primary_target)
                if not translated:
                    return False
                translated_parts.append(translated)
            translated_file = "".join(translated_parts)
            reply_text = "📄 %s → %s\n%s" % (
                str(payload.get("file_name") or "file"),
                LANG_NAMES_ZH.get(primary_target, primary_target),
                translated_file,
            )
            delivered_map = {primary_target: translated_file}
        elif src_lang == "zh":
            translated_rows = translate_multi(source_text, "zh", targets, {})
            reply_text = format_multi_reply(translated_rows) if translated_rows else None
            delivered_map = {lang: text for lang, text in (translated_rows or []) if text}
        else:
            primary_target = targets[0]
            translated = translate(source_text, src_lang, primary_target)
            if translated:
                if payload.get("from_image_ocr"):
                    reply_text = "🖼️ " + LANG_FLAGS.get(primary_target, "") + "\n" + translated
                else:
                    reply_text = (LANG_FLAGS.get(primary_target, "") + " " + translated).strip()
            else:
                reply_text = None
            delivered_map = {primary_target: translated} if translated else {}

        if not reply_text or _is_translation_failure_sentinel(reply_text):
            return False

        if payload.get("from_file"):
            _translation_retry_push_chunks(job_key, payload, reply_text)
        else:
            _translation_retry_push(job_key, payload, reply_text)
        message_id = str(payload.get("message_id") or "")
        if message_id and message_id in message_cache:
            try:
                message_cache[message_id].setdefault("tr", {}).update(delivered_map)
            except Exception:
                pass
        _stats_inc("text_translations", max(1, len(delivered_map)))
        translation_retry_queue_module.mark_delivered(job_key, owner=lease_owner)
        with _TRANSLATION_RETRY_LOCK:
            _TRANSLATION_RETRY_INFLIGHT.discard(job_key)
        _event_log_write("translation_retry_delivered", {
            "target": str(target_id)[-16:],
            "attempt": int((job or {}).get("attempts") or 0) + 1,
            "src": src_lang,
            "targets": targets,
            "message_id": message_id,
            "durable": True,
        })
        return True
    finally:
        for attr, value in previous.items():
            try:
                if value is missing:
                    if hasattr(_tl, attr):
                        delattr(_tl, attr)
                else:
                    setattr(_tl, attr, value)
            except Exception:
                pass


def _translation_retry_image_attempt(job, lease_owner=None):
    """Re-download, OCR, translate and deliver one durable image job."""
    payload = dict((job or {}).get("payload") or {})
    job_key = str((job or {}).get("job_key") or "")
    message_id = str(payload.get("message_id") or "")
    target_id = payload.get("group_id") or payload.get("user_id")
    if not job_key or not message_id or not target_id:
        translation_retry_queue_module.remove(job_key)
        return True

    previous = dict(getattr(_tl, "__dict__", {}))
    try:
        group_id = payload.get("group_id")
        user_id = payload.get("user_id")
        _tl.group_id = group_id or "__dm_image_retry__"
        _tl.user_id = str(user_id or "")
        _tl.from_image_ocr = True
        try:
            _tl.tone, _tl.tone_custom = get_group_tone(group_id)
        except Exception:
            _tl.tone, _tl.tone_custom = translation_tone, translation_tone_custom

        img_base64, img_raw = download_line_image(message_id)
        if not img_base64 or not img_raw:
            return False
        mime = detect_image_mime(img_raw)
        extracted = ocr_image_openai(img_base64, mime_type=mime)
        if _is_factory_reason_ocr_failure_text(extracted):
            extracted = None
        if not extracted or len(str(extracted).strip()) < 2:
            # A successful vision call can legitimately find no text.  Avoid an
            # immortal queue row after several independent attempts; this path
            # remains silent because there is nothing to translate.
            if int((job or {}).get("attempts") or 0) >= 2 and _has_ai_capability("vision"):
                translation_retry_queue_module.mark_delivered(job_key, owner=lease_owner)
                with _TRANSLATION_RETRY_LOCK:
                    _TRANSLATION_RETRY_INFLIGHT.discard(job_key)
                return True
            return False

        extracted = str(extracted).strip()
        lang = detect_language(extracted) or ("zh" if has_chinese(extracted) else "auto")
        preferred = str(payload.get("tgt") or group_target_lang.get(group_id, "id") or "id")
        actual_tgt = preferred if lang == "zh" else "zh"
        result = translate(extracted, lang, actual_tgt)
        if not result:
            return False
        reply_text = "🖼️ " + LANG_FLAGS.get(actual_tgt, "") + "\n" + result
        _translation_retry_push(job_key, payload, reply_text)
        try:
            message_cache.setdefault(message_id, {}).setdefault("tr", {})[actual_tgt] = result
            message_cache[message_id]["ocr_text"] = extracted
            message_cache[message_id]["text"] = extracted
        except Exception:
            pass
        _stats_inc("image_translations")
        translation_retry_queue_module.mark_delivered(job_key, owner=lease_owner)
        with _TRANSLATION_RETRY_LOCK:
            _TRANSLATION_RETRY_INFLIGHT.discard(job_key)
        _event_log_write("image_retry_delivered", {
            "target": str(target_id)[-16:],
            "attempt": int((job or {}).get("attempts") or 0) + 1,
            "src": lang,
            "target_lang": actual_tgt,
            "message_id": message_id,
            "durable": True,
        })
        return True
    finally:
        try:
            _tl.__dict__.clear()
            _tl.__dict__.update(previous)
        except Exception:
            pass



def _translation_retry_audio_attempt(job, lease_owner=None):
    """Re-download, transcribe, translate and deliver one durable audio job."""
    payload = dict((job or {}).get("payload") or {})
    job_key = str((job or {}).get("job_key") or "")
    message_id = str(payload.get("message_id") or "")
    target_id = payload.get("group_id") or payload.get("user_id")
    if not job_key or not message_id or not target_id:
        translation_retry_queue_module.remove(job_key)
        return True
    audio_bytes = download_line_audio(message_id)
    if not audio_bytes:
        return False
    transcribed = transcribe_audio_openai(audio_bytes)
    if not transcribed or len(str(transcribed).strip()) < 2:
        # Silence/no speech is not a translation failure.  Confirm it across
        # several independent attempts, then close the silent job.
        if int((job or {}).get("attempts") or 0) >= 2:
            translation_retry_queue_module.mark_delivered(job_key, owner=lease_owner)
            with _TRANSLATION_RETRY_LOCK:
                _TRANSLATION_RETRY_INFLIGHT.discard(job_key)
            return True
        return False
    transcribed = str(transcribed).strip()
    lang = detect_language(transcribed) or ("zh" if has_chinese(transcribed) else "auto")
    preferred = str(payload.get("tgt") or group_target_lang.get(payload.get("group_id"), "id") or "id")
    actual_tgt = preferred if lang == "zh" else "zh"
    result = translate(transcribed, lang, actual_tgt)
    if not result:
        # Preserve the already-extracted source independently from LINE media
        # retention, then retire this media job.
        _schedule_text_translation_retry(
            payload,
            source_text=transcribed,
            src_lang=lang,
            target_langs=[actual_tgt],
            from_image_ocr=False,
        )
        translation_retry_queue_module.mark_delivered(job_key, owner=lease_owner)
        with _TRANSLATION_RETRY_LOCK:
            _TRANSLATION_RETRY_INFLIGHT.discard(job_key)
        return True
    reply_text = "🎤 " + LANG_FLAGS.get(actual_tgt, "") + "\n💬 " + transcribed + "\n📝 " + result
    _translation_retry_push(job_key, payload, reply_text)
    _stats_inc("voice_translations")
    translation_retry_queue_module.mark_delivered(job_key, owner=lease_owner)
    with _TRANSLATION_RETRY_LOCK:
        _TRANSLATION_RETRY_INFLIGHT.discard(job_key)
    return True


def _translation_retry_video_attempt(job, lease_owner=None):
    """Re-download a video preview, OCR, translate and deliver it."""
    payload = dict((job or {}).get("payload") or {})
    job_key = str((job or {}).get("job_key") or "")
    message_id = str(payload.get("message_id") or "")
    target_id = payload.get("group_id") or payload.get("user_id")
    if not job_key or not message_id or not target_id:
        translation_retry_queue_module.remove(job_key)
        return True
    with ApiClient(configuration) as api_client:
        content = MessagingApiBlob(api_client).get_message_content_preview(message_id)
    content = _coerce_blob_bytes(content)
    if not content or len(content) <= 100:
        return False
    b64 = base64.b64encode(content).decode()
    extracted = ocr_image_openai(b64, mime_type="image/jpeg")
    if not extracted or len(str(extracted).strip()) < 2:
        if int((job or {}).get("attempts") or 0) >= 2:
            translation_retry_queue_module.mark_delivered(job_key, owner=lease_owner)
            with _TRANSLATION_RETRY_LOCK:
                _TRANSLATION_RETRY_INFLIGHT.discard(job_key)
            return True
        return False
    extracted = str(extracted).strip()
    lang = detect_language(extracted) or ("zh" if has_chinese(extracted) else "auto")
    preferred = str(payload.get("tgt") or group_target_lang.get(payload.get("group_id"), "id") or "id")
    actual_tgt = preferred if lang == "zh" else "zh"
    result = translate(extracted, lang, actual_tgt)
    if not result:
        _schedule_text_translation_retry(
            payload,
            source_text=extracted,
            src_lang=lang,
            target_langs=[actual_tgt],
            from_image_ocr=True,
        )
        translation_retry_queue_module.mark_delivered(job_key, owner=lease_owner)
        with _TRANSLATION_RETRY_LOCK:
            _TRANSLATION_RETRY_INFLIGHT.discard(job_key)
        return True
    _translation_retry_push(job_key, payload, "🎬 " + LANG_FLAGS.get(actual_tgt, "") + " " + result)
    _stats_inc("image_translations")
    translation_retry_queue_module.mark_delivered(job_key, owner=lease_owner)
    with _TRANSLATION_RETRY_LOCK:
        _TRANSLATION_RETRY_INFLIGHT.discard(job_key)
    return True


def _translation_retry_file_attempt(job, lease_owner=None):
    """Re-download and translate one durable text-file job."""
    payload = dict((job or {}).get("payload") or {})
    job_key = str((job or {}).get("job_key") or "")
    message_id = str(payload.get("message_id") or "")
    target_id = payload.get("group_id") or payload.get("user_id")
    if not job_key or not message_id or not target_id:
        translation_retry_queue_module.remove(job_key)
        return True
    with ApiClient(configuration) as api_client:
        raw = _coerce_blob_bytes(MessagingApiBlob(api_client).get_message_content(message_id))
    text = _extract_uploaded_document(raw, str(payload.get("ext") or ""))
    if text is None or not text.strip():
        # Encoding/content is deterministic; repeated network retries cannot
        # make binary data translatable. Close silently after confirmation.
        if int((job or {}).get("attempts") or 0) >= 1:
            translation_retry_queue_module.mark_delivered(job_key, owner=lease_owner)
            with _TRANSLATION_RETRY_LOCK:
                _TRANSLATION_RETRY_INFLIGHT.discard(job_key)
            return True
        return False
    text = text[:_TEXT_FILE_MAX_CHARS]
    lang = detect_language(text[:4000]) or ("zh" if has_chinese(text) else "auto")
    preferred = str(payload.get("tgt") or group_target_lang.get(payload.get("group_id"), "id") or "id")
    actual_tgt = preferred if lang == "zh" else "zh"
    translated_parts = []
    for part in _split_text_for_translation(text):
        translated = translate(part, lang, actual_tgt)
        if not translated:
            # Persist the complete extracted document, not only the failed row,
            # so later delivery remains ordered and complete after LINE media
            # retention expires.
            _schedule_text_translation_retry(
                payload,
                source_text=text,
                src_lang=lang,
                target_langs=[actual_tgt],
                from_file=True,
                file_name=str(payload.get("file_name") or "file"),
            )
            translation_retry_queue_module.mark_delivered(job_key, owner=lease_owner)
            with _TRANSLATION_RETRY_LOCK:
                _TRANSLATION_RETRY_INFLIGHT.discard(job_key)
            return True
        translated_parts.append(translated)
    if not translated_parts:
        return False
    fname = str(payload.get("file_name") or "file")
    _translation_retry_push_chunks(
        job_key,
        payload,
        "📄 %s → %s\n%s" % (fname, LANG_NAMES_ZH.get(actual_tgt, actual_tgt), "".join(translated_parts)),
    )
    _stats_inc("file_translations")
    translation_retry_queue_module.mark_delivered(job_key, owner=lease_owner)
    with _TRANSLATION_RETRY_LOCK:
        _TRANSLATION_RETRY_INFLIGHT.discard(job_key)
    return True


def _translation_retry_worker_loop():
    """Drain the durable queue with cross-process leases and infinite retry."""
    global _TRANSLATION_RETRY_WORKER
    owner = f"pid-{os.getpid()}-thread-{threading.get_ident()}-{uuid.uuid4().hex[:8]}"
    try:
        while True:
            if translation_retry_queue_module.pending_count() == 0:
                return
            claimed = translation_retry_queue_module.claim_due_jobs(
                owner=owner, limit=20, lease_seconds=240
            )
            if not claimed:
                pending = translation_retry_queue_module.list_pending(limit=500)
                if not pending:
                    return
                now = time.time()
                next_due = min(
                    max(float(job.get("next_attempt_at") or now),
                        float(job.get("lease_until") or 0) if job.get("status") == "leased" else 0)
                    for job in pending
                )
                _TRANSLATION_RETRY_WAKE.wait(max(0.2, min(30.0, next_due - now)))
                _TRANSLATION_RETRY_WAKE.clear()
                continue

            for job in claimed:
                job_key = str(job.get("job_key") or "")
                kind = str(job.get("job_kind") or (job.get("payload") or {}).get("job_kind") or "text")
                try:
                    if kind == "image":
                        delivered = _translation_retry_image_attempt(job, lease_owner=owner)
                    elif kind == "audio":
                        delivered = _translation_retry_audio_attempt(job, lease_owner=owner)
                    elif kind == "video":
                        delivered = _translation_retry_video_attempt(job, lease_owner=owner)
                    elif kind == "file":
                        delivered = _translation_retry_file_attempt(job, lease_owner=owner)
                    else:
                        delivered = _translation_retry_attempt(job, lease_owner=owner)
                    if delivered:
                        continue
                    completed = int(job.get("attempts") or 0) + 1
                    delay = _translation_retry_backoff(completed)
                    translation_retry_queue_module.reschedule(
                        job_key,
                        delay_seconds=delay,
                        error="empty_translation_or_media_not_ready",
                        owner=owner,
                    )
                    _event_log_write("translation_retry_attempt_empty", {
                        "kind": kind,
                        "attempt": completed,
                        "message_id": str((job.get("payload") or {}).get("message_id") or ""),
                        "next_delay": delay,
                        "durable": True,
                    })
                except Exception as exc:
                    completed = int(job.get("attempts") or 0) + 1
                    delay = _translation_retry_backoff(completed)
                    translation_retry_queue_module.reschedule(
                        job_key,
                        delay_seconds=delay,
                        error=type(exc).__name__ + ":" + str(exc)[:1200],
                        owner=owner,
                    )
                    logger.warning(
                        "[TranslationRetry] durable attempt=%s kind=%s job=%s failed: %s",
                        completed, kind, job_key[-24:], str(exc)[:300],
                    )
    finally:
        with _TRANSLATION_RETRY_LOCK:
            _TRANSLATION_RETRY_WORKER = None
            try:
                if translation_retry_queue_module.pending_count() == 0:
                    _TRANSLATION_RETRY_INFLIGHT.clear()
            except Exception:
                pass

def _ensure_translation_retry_worker():
    global _TRANSLATION_RETRY_WORKER
    with _TRANSLATION_RETRY_LOCK:
        worker = _TRANSLATION_RETRY_WORKER
        try:
            alive = bool(worker and worker.is_alive())
        except Exception:
            alive = bool(worker)
        if alive:
            _TRANSLATION_RETRY_WAKE.set()
            return False
        worker = threading.Thread(
            target=_translation_retry_worker_loop,
            name="translation-retry-durable",
            daemon=True,
        )
        _TRANSLATION_RETRY_WORKER = worker
        worker.start()
        return True


def _resume_persisted_translation_retries():
    """Resume pending jobs after deploy/restart without requiring user resend."""
    try:
        pending = translation_retry_queue_module.list_pending(limit=5000)
    except Exception as exc:
        logger.warning("[TranslationRetry] durable queue init failed: %s", exc)
        return False
    if not pending:
        return True
    with _TRANSLATION_RETRY_LOCK:
        _TRANSLATION_RETRY_INFLIGHT.update(str(job.get("job_key") or "") for job in pending)
    _ensure_translation_retry_worker()
    logger.warning("[TranslationRetry] resumed %d persisted jobs", len(pending))
    return True


def _schedule_text_translation_retry(
    ctx,
    *,
    source_text,
    src_lang,
    target_langs,
    line_mentions=None,
    quoted_context_source=None,
    quoted_context_message_id=None,
    from_image_ocr=False,
    from_file=False,
    file_name="",
    delay_seconds=None,
):
    """Persist an empty translation and retry until it is delivered.

    Unlike the previous three-attempt in-memory timer, this queue survives
    restarts and has no terminal exhausted state.  The user is not asked to
    resend and no status-only message is posted into the conversation.
    """
    ctx = dict(ctx or {})
    target_id = ctx.get("group_id") or ctx.get("user_id")
    source_text = str(source_text or "").strip()
    targets = [str(value or "").strip() for value in (target_langs or [])]
    targets = list(dict.fromkeys(value for value in targets if value))
    if not target_id or not source_text or not targets:
        return False
    src_lang = str(src_lang or "auto").strip() or "auto"

    retry_key = _translation_retry_key(ctx, source_text, src_lang, targets)
    payload = {
        "group_id": ctx.get("group_id"),
        "user_id": ctx.get("user_id"),
        "message_id": str(ctx.get("message_id") or ""),
        "quote_token": ctx.get("quote_token"),
        "source_text": source_text,
        "src_lang": str(src_lang),
        "target_langs": targets,
        "line_mentions": list(line_mentions or []),
        "quoted_context_source": str(quoted_context_source or ""),
        "quoted_context_message_id": str(quoted_context_message_id or ""),
        "from_image_ocr": bool(from_image_ocr),
        "from_file": bool(from_file),
        "file_name": str(file_name or ""),
        "job_kind": "text",
    }
    first_delay = (_translation_retry_delays()[0] if delay_seconds is None
                   else max(0.0, float(delay_seconds or 0.0)))
    try:
        inserted = translation_retry_queue_module.enqueue(
            retry_key, payload, delay_seconds=first_delay, job_kind="text"
        )
    except Exception as exc:
        logger.exception("[TranslationRetry] durable enqueue failed: %s", exc)
        return False
    with _TRANSLATION_RETRY_LOCK:
        _TRANSLATION_RETRY_INFLIGHT.add(retry_key)
    _ensure_translation_retry_worker()
    _TRANSLATION_RETRY_WAKE.set()
    try:
        _event_log_write("translation_retry_persisted", {
            "target": str(target_id)[-16:],
            "src": src_lang,
            "targets": targets,
            "message_id": str(ctx.get("message_id") or ""),
            "inserted": bool(inserted),
        })
    except Exception:
        pass
    return True


def _complete_durable_text_job(job_key):
    """Remove a pre-persisted text intent only after LINE accepted delivery."""
    key = str(job_key or "").strip()
    if not key:
        return False
    try:
        translation_retry_queue_module.mark_delivered(key)
        with _TRANSLATION_RETRY_LOCK:
            _TRANSLATION_RETRY_INFLIGHT.discard(key)
        return True
    except Exception as exc:
        logger.warning("[TranslationOutbox] completion failed job=%s: %s", key[-24:], exc)
        return False


def _schedule_media_translation_retry(ctx, job_kind, *, delay_seconds=75, **extra):
    """Persist an audio/video/file intent before transient processing."""
    ctx = dict(ctx or {})
    kind = str(job_kind or "").strip().lower()
    target_id = ctx.get("group_id") or ctx.get("user_id")
    message_id = str(ctx.get("message_id") or "").strip()
    if kind not in {"audio", "video", "file"} or not target_id or not message_id:
        return False
    job_key = f"{target_id}:{message_id}:{kind}"
    payload = {
        "job_kind": kind,
        "group_id": ctx.get("group_id"),
        "user_id": ctx.get("user_id"),
        "message_id": message_id,
        "quote_token": ctx.get("quote_token"),
        "tgt": str(ctx.get("tgt") or group_target_lang.get(ctx.get("group_id"), "id") or "id"),
    }
    payload.update({str(k): v for k, v in extra.items()})
    try:
        translation_retry_queue_module.enqueue(
            job_key, payload, delay_seconds=max(1, float(delay_seconds or 1)), job_kind=kind
        )
    except Exception as exc:
        logger.exception("[MediaRetry] durable enqueue failed kind=%s: %s", kind, exc)
        return False
    with _TRANSLATION_RETRY_LOCK:
        _TRANSLATION_RETRY_INFLIGHT.add(job_key)
    _ensure_translation_retry_worker()
    _TRANSLATION_RETRY_WAKE.set()
    return job_key


def _complete_durable_media_job(job_key):
    return _complete_durable_text_job(job_key)


def _schedule_image_translation_retry(ctx, *, delay_seconds=75):
    """Persist an image OCR/translation intent before transient processing.

    The LINE message ID is sufficient to re-download the media while LINE keeps
    it available.  Jobs survive deploys and are retried by the same lease-based
    worker as text jobs.  No operational warning is posted to the conversation.
    """
    ctx = dict(ctx or {})
    target_id = ctx.get("group_id") or ctx.get("user_id")
    message_id = str(ctx.get("message_id") or "").strip()
    if not target_id or not message_id:
        return False
    job_key = f"{target_id}:{message_id}:image"
    payload = {
        "job_kind": "image",
        "group_id": ctx.get("group_id"),
        "user_id": ctx.get("user_id"),
        "message_id": message_id,
        "quote_token": ctx.get("quote_token"),
        "tgt": str(ctx.get("tgt") or group_target_lang.get(ctx.get("group_id"), "id") or "id"),
    }
    try:
        inserted = translation_retry_queue_module.enqueue(
            job_key, payload, delay_seconds=max(1, float(delay_seconds or 1)), job_kind="image"
        )
    except Exception as exc:
        logger.exception("[ImageRetry] durable enqueue failed: %s", exc)
        return False
    with _TRANSLATION_RETRY_LOCK:
        _TRANSLATION_RETRY_INFLIGHT.add(job_key)
    _ensure_translation_retry_worker()
    _TRANSLATION_RETRY_WAKE.set()
    try:
        _event_log_write("image_retry_persisted", {
            "target": str(target_id)[-16:],
            "message_id": message_id,
            "inserted": bool(inserted),
        })
    except Exception:
        pass
    return job_key


def _complete_durable_image_job(ctx):
    job_key = str((ctx or {}).get("durable_job_key") or "")
    if not job_key:
        target_id = (ctx or {}).get("group_id") or (ctx or {}).get("user_id")
        message_id = str((ctx or {}).get("message_id") or "")
        if target_id and message_id:
            job_key = f"{target_id}:{message_id}:image"
    if not job_key:
        return False
    try:
        translation_retry_queue_module.mark_delivered(job_key)
        with _TRANSLATION_RETRY_LOCK:
            _TRANSLATION_RETRY_INFLIGHT.discard(job_key)
        return True
    except Exception:
        return False


def _send_background_failure_notice(ctx, *, kind="translation", detail=""):
    """Compatibility shim: operational translation failures are never user text.

    Every translatable text/media job is either delivered immediately or kept in
    the durable queue.  This function records diagnostics only, preventing a
    status sentence from being mistaken for the requested translation.
    """
    target_id = (ctx or {}).get("group_id") or (ctx or {}).get("user_id")
    try:
        _event_log_write("background_text_failure_suppressed", {
            "kind": str(kind or "translation"),
            "detail": str(detail or "")[:300],
            "target": str(target_id or "")[-16:],
        })
    except Exception:
        pass
    return False

def translate(text, src, tgt):
    """Public translate wrapper — 邊界層正規化與保護。

    中文→印尼文先把有明確站別語法的現場簡稱正規化為正式站名。
    人名與客戶名保持可見，不再轉成脆弱 placeholder；只有 LINE mention
    使用可恢復代碼。品質檢查負責記錄與阻止髒快取，不再把可用譯文丟棄。
    """
    _set_translation_outcome("started")
    try:
        # Prevent a previous request on the same worker thread from reusing a
        # media-context decision.  Multiple validators within this request may
        # share the result, but every new message resolves context afresh.
        _tl.measurement_media_context_resolution = {}
        # Explicit overrides are scoped only to one action-button execution.
        # A normal message must always consult its own current media context.
        _tl.measurement_work_order_context_override = None
    except Exception:
        pass
    _replace_last_translate_debug({
        "ts": int(time.time()),
        "src_text": text,
        "src_lang": src,
        "tgt_lang": tgt,
        "pipeline_status": "translation_pipeline_started",
        "openai_status": "not_called_yet",
    })
    canonical_text = text
    # v3.33.4: normalize only known factory equipment codes before every cache,
    # TM, NMT, LLM, glossary and quality-gate route.  This prevents inputs such
    # as ``Mesin i 9 ...`` from being treated as ordinary words and later
    # surfacing as a misleading generic translation failure.
    if src == "id":
        canonical_text, _equipment_code_replacements = normalize_known_equipment_codes(
            canonical_text,
            getattr(_tl, 'line_mentions', None),
        )
        if _equipment_code_replacements:
            logger.info(
                "[EquipmentCode] normalized %r -> %r replacements=%s",
                text[:120], canonical_text[:120], _equipment_code_replacements[:10],
            )
            try:
                _tl.equipment_code_normalization = list(_equipment_code_replacements)
            except Exception:
                pass
        if tgt == "zh":
            # Compact inspection/measurement reports are source-verifiable: every
            # output field comes directly from a recognized row label, numeric
            # value or explicit OK/NG status. Translate these locally before TM,
            # providers and the mandatory second-review path so a transient AI
            # outage can never turn an intact quality report into a generic
            # "safe translation unavailable" notice. Unrecognized/partial rows
            # fail closed and continue through the normal translation pipeline.
            _structured_report = factory_structured_report_module.translate_id_zh_measurement_report(
                canonical_text
            )
            if _structured_report:
                logger.info(
                    "[StructuredReport] deterministic measurement translation hit: %r -> %r",
                    canonical_text[:160], _structured_report[:240],
                )
                _structured_report = _final_delivery_guard(
                    canonical_text, _structured_report, src, tgt
                )
                if _structured_report:
                    try:
                        cache_set(canonical_text, src, tgt, _structured_report, force=True)
                    except Exception:
                        pass
                _update_last_translate_debug(
                    pipeline_status=(
                        "deterministic_structured_measurement_report"
                        if _structured_report else
                        "deterministic_structured_report_rejected_fallback_to_provider"
                    ),
                    final_candidate=(_structured_report[:2000] if _structured_report else ""),
                    openai_status=("not_needed" if _structured_report else "pending_provider_fallback"),
                )
                if _structured_report:
                    _set_translation_outcome("delivered", "deterministic_structured_measurement_report")
                    return _structured_report
                logger.error(
                    "[DeterministicShortcut] structured report rejected; continuing to provider pipeline"
                )

            # Terse dimensional shorthand is compositional, not a sentence patch.
            # The parser consumes the existing canonical equipment-code asset and
            # only renders locally when every source token belongs to supported
            # measurement slots.  This prevents ``mikro kecil`` from ever being
            # interpreted as a miniature/small machine.  A recently confirmed
            # work-order photo supplies the otherwise omitted order object.
            _measurement_frame = _build_id_zh_measurement_frame(canonical_text)
            _measurement_short = factory_measurement_semantics_module.deterministic_translation(
                _measurement_frame
            )
            if _measurement_short:
                _measurement_ok, _measurement_issues = (
                    factory_measurement_semantics_module.validate_translation(
                        _measurement_frame, _measurement_short
                    )
                )
                if not _measurement_ok:
                    logger.error(
                        "[FactoryMeasurementSemantics] deterministic candidate failed self-validation: %s",
                        _measurement_issues,
                    )
                    _measurement_short = None
            if _measurement_short:
                logger.info(
                    "[FactoryMeasurementSemantics] deterministic shorthand hit: %r -> %r frame=%s",
                    canonical_text[:160], _measurement_short[:240], _measurement_frame,
                )
                _measurement_short = _final_delivery_guard(
                    canonical_text, _measurement_short, src, tgt
                )
                if _measurement_short and not _measurement_frame.get("work_order_context"):
                    try:
                        cache_set(canonical_text, src, tgt, _measurement_short, force=True)
                    except Exception:
                        pass
                _update_last_translate_debug(
                    pipeline_status=(
                        "deterministic_id_zh_measurement_shorthand"
                        if _measurement_short else
                        "deterministic_measurement_shorthand_rejected_fallback_to_provider"
                    ),
                    final_candidate=(_measurement_short[:2000] if _measurement_short else ""),
                    openai_status=("not_needed" if _measurement_short else "pending_provider_fallback"),
                    factory_measurement_frame=_measurement_frame,
                )
                if _measurement_short:
                    _set_translation_outcome("delivered", "deterministic_id_zh_measurement_shorthand")
                    return _measurement_short
                logger.error(
                    "[DeterministicShortcut] measurement shorthand rejected; continuing to provider pipeline"
                )

            _equipment_status = factory_semantic_translate_equipment_status_id_zh(
                canonical_text
            )
            if _equipment_status:
                logger.info(
                    "[EquipmentStatus] deterministic translation hit: %r -> %r",
                    canonical_text[:120], _equipment_status[:120],
                )
                _equipment_status = _final_delivery_guard(
                    canonical_text, _equipment_status, src, tgt
                )
                if _equipment_status:
                    try:
                        cache_set(canonical_text, src, tgt, _equipment_status, force=True)
                    except Exception:
                        pass
                _update_last_translate_debug(
                    pipeline_status=(
                        "deterministic_equipment_status"
                        if _equipment_status else
                        "deterministic_equipment_status_rejected_fallback_to_provider"
                    ),
                    final_candidate=(_equipment_status[:2000] if _equipment_status else ""),
                    openai_status=("not_needed" if _equipment_status else "pending_provider_fallback"),
                )
                if _equipment_status:
                    _set_translation_outcome("delivered", "deterministic_equipment_status")
                    return _equipment_status
                logger.error(
                    "[DeterministicShortcut] equipment status rejected; continuing to provider pipeline"
                )
    # Bidirectional source-first translation. A complete source relation is
    # rendered before mention placeholders, TM, NMT, providers or post-editing.
    # The established handover frame remains a second source-derived route for
    # ZH->ID. Neither route consumes or repairs a provider candidate.
    _source_first_translation = ""
    _source_first_route = ""
    try:
        _source_first_translation = (
            factory_message_semantics_module.translate_source_directly(
                canonical_text, src, tgt
            )
        )
        if _source_first_translation:
            _source_first_route = "bidirectional_source_relations"
        elif src == "zh" and tgt == "id":
            _source_first_translation = (
                factory_semantic_audit_module.translate_source_directly(
                    canonical_text, src, tgt
                )
            )
            if _source_first_translation:
                _source_first_route = "handover_source_relations"
    except Exception as _source_first_exc:
        logger.exception(
            "[SourceFirstTranslation] source-frame translation failed: %s",
            _source_first_exc,
        )
        _source_first_translation = ""
        _source_first_route = ""
    if _source_first_translation:
        _source_first_translation = finalize_factory_translation(
            canonical_text, _source_first_translation, src, tgt
        )
        _source_first_translation = _final_delivery_guard(
            canonical_text, _source_first_translation, src, tgt
        )
        if _source_first_translation:
            try:
                _tl.factory_audit = {
                    "src": canonical_text,
                    "type": f"factory_source_semantic_direct_{src}_{tgt}",
                    "reason": _source_first_route,
                    "raw_translation": "",
                    "corrected_translation": _source_first_translation,
                    "domain": ["factory", "source_relations"],
                    "auto_corrected": False,
                }
                cache_set(
                    canonical_text, src, tgt, _source_first_translation,
                    force=True,
                )
            except Exception:
                pass
            _update_last_translate_debug(
                pipeline_status="source_first_relation_translation",
                source_first_route=_source_first_route,
                final_candidate=_source_first_translation[:2000],
                openai_status="not_needed",
            )
            _set_translation_outcome(
                "delivered", "source_first_relation_translation"
            )
            return _source_first_translation
        logger.error(
            "[SourceFirstTranslation] internally generated translation failed the final consistency check; continuing to provider"
        )

    # v3.15: ERP「原因」欄是強語義表格/短標籤，必須在任何站別 alias、
    # cache、TM、NMT、LLM、final guard 之前先決定。這是文字與圖片共用的
    # 邊界層，不是圖片補丁。
    if src == "zh" and tgt == "id":
        reason_semantic = _factory_reason_semantic_translate_zh_id(canonical_text)
        if reason_semantic:
            _expected_rows = getattr(_tl, 'factory_reason_image_expected_rows', 0) if getattr(_tl, 'from_image_ocr', False) else 0
            if _factory_reason_ocr_incomplete_against_visual_count(canonical_text, _expected_rows):
                logger.warning(
                    "[FactoryReasonOCR] deterministic route skipped after visual row mismatch expected=%s actual=%s",
                    _expected_rows, _factory_reason_ocr_row_count(canonical_text)
                )
                try:
                    _tl.factory_reason_ocr_degraded = "visual_row_mismatch"
                except Exception:
                    pass
                reason_semantic = None
            if reason_semantic:
                reason_semantic = _final_delivery_guard(
                    canonical_text, reason_semantic, src, tgt
                )
            if reason_semantic:
                try:
                    cache_set(canonical_text, src, tgt, reason_semantic, force=True)
                except Exception:
                    pass
            _update_last_translate_debug(
                pipeline_status=(
                    "deterministic_factory_reason"
                    if reason_semantic else
                    "deterministic_factory_reason_rejected_fallback_to_provider"
                ),
                final_candidate=(reason_semantic[:2000] if reason_semantic else ""),
                openai_status=("not_needed" if reason_semantic else "pending_provider_fallback"),
            )
            if reason_semantic:
                _set_translation_outcome("delivered", "deterministic_factory_reason")
                return reason_semantic
            logger.error(
                "[DeterministicShortcut] factory reason rejected; continuing to provider pipeline"
            )
        canonical_text, _station_alias_matches = resolve_factory_station_aliases(text)
    # Mentions are immutable identity data, not translatable language.  Protect
    # them at the public translation boundary so every caller (group, DM,
    # postback, API, tests) gets the same behavior instead of relying on one
    # message-handler branch to remember a special pre-processing step.
    _explicit_mentions = getattr(_tl, 'line_mentions', None)
    _mention_protected_text, _mention_map = protect_mentions(
        canonical_text, _explicit_mentions
    )
    # Keep ordinary protected names visible.  Opaque __PERSON__/__CUST__ tokens
    # were the common dependency behind many false failures.  We still route
    # name-bearing messages through the LLM (no fuzzy TM/NMT bypass), but the
    # source and cache key now contain the real name.
    protected_text = _mention_protected_text
    _name_map = {}
    _visible_names = collect_visible_protected_names(canonical_text)
    _prev_pnm = getattr(_tl, 'protected_name_map', None)
    _expression_gid = getattr(_tl, 'group_id', None)
    _from_image_ocr = bool(getattr(_tl, 'from_image_ocr', False))
    _auto_tone_enabled = (
        bool(get_auto_tone_emoji_enabled(_expression_gid))
        and get_expressive_translation_mode(_expression_gid) != "off"
        and not bool(getattr(_tl, 'disable_tone_emoji', False))
        and (not _from_image_ocr or bool(get_image_ocr_expressive_enabled(_expression_gid)))
    )
    _auto_tone_analysis = (
        translation_extras_module.analyze_message_tone(canonical_text, src)
        if _auto_tone_enabled else None
    )
    _tone_state_missing = object()
    _prev_auto_tone = getattr(_tl, 'auto_tone_analysis', _tone_state_missing)
    try:
        _protected_entities = {name: name for name in _visible_names}
        _protected_entities.update(_mention_map)
        _protected_entities.update(
            dict(getattr(_tl, 'external_mention_placeholders', None) or {})
        )
        _tl.protected_name_map = _protected_entities
        _tl.auto_tone_analysis = _auto_tone_analysis
        result = _translate_core(protected_text, src, tgt)
    finally:
        # 還原 thread-local 狀態,避免污染同 thread 後續無保護名的翻譯
        try:
            if _prev_pnm is None:
                if hasattr(_tl, 'protected_name_map'):
                    delattr(_tl, 'protected_name_map')
            else:
                _tl.protected_name_map = _prev_pnm
        except Exception:
            pass
        try:
            if _prev_auto_tone is _tone_state_missing:
                if hasattr(_tl, 'auto_tone_analysis'):
                    delattr(_tl, 'auto_tone_analysis')
            else:
                _tl.auto_tone_analysis = _prev_auto_tone
        except Exception:
            pass
    _emergency_attempted = False
    if not result and not _translation_was_intentionally_skipped():
        _emergency_attempted = True
        result = _emergency_translation_fallback(protected_text, src, tgt)
    if _is_translation_failure_sentinel(result):
        logger.warning("[LegacyFailurePurge] blocked failure payload at public translate boundary")
        result = None
    if result and isinstance(result, str):
        if _mention_map:
            result = restore_mentions(result, _mention_map)
            result = _post_restore_mentions_guard(result, _mention_map)
            if not result:
                _set_translation_outcome("failed", "mention_restoration_guard")
                return None
        result = _normalize_factory_operation_question(
            canonical_text, result, src, tgt
        )
        result = _final_delivery_guard(canonical_text, result, src, tgt)
        if (
            not result
            and not _emergency_attempted
            and not _translation_was_intentionally_skipped()
        ):
            # The primary provider returned text, but objective integrity checks
            # rejected it.  Try independent NMT routes immediately before
            # falling back to the detached retry worker.
            _emergency_attempted = True
            result = _emergency_translation_fallback(protected_text, src, tgt)
            if result and _mention_map:
                result = restore_mentions(result, _mention_map)
                result = _post_restore_mentions_guard(result, _mention_map)
            if result:
                result = _normalize_factory_operation_question(
                    canonical_text, result, src, tgt
                )
                result = _final_delivery_guard(canonical_text, result, src, tgt)
        # Absolute last boundary: if the source is an ERP reason table/label,
        # deterministic factory semantics outrank any reviewer/cache/model output.
        if src == "zh" and tgt == "id":
            reason_semantic = _factory_reason_semantic_translate_zh_id(canonical_text)
            if reason_semantic:
                _expected_rows = getattr(_tl, 'factory_reason_image_expected_rows', 0) if getattr(_tl, 'from_image_ocr', False) else 0
                if _factory_reason_ocr_incomplete_against_visual_count(canonical_text, _expected_rows):
                    logger.warning(
                        "[FactoryReasonOCR] final deterministic override skipped after visual row mismatch expected=%s actual=%s",
                        _expected_rows, _factory_reason_ocr_row_count(canonical_text)
                    )
                    try:
                        _tl.factory_reason_ocr_degraded = "visual_row_mismatch"
                    except Exception:
                        pass
                    reason_semantic = None
                if reason_semantic:
                    _reason_final = _final_delivery_guard(canonical_text, reason_semantic, src, tgt)
                    if _reason_final:
                        _set_translation_outcome("delivered", "deterministic_factory_reason_final_boundary")
                        return _reason_final
        # Sentence-aware expressive decoration runs only after every semantic,
        # glossary, identity and format guard.  It never creates another AI call.
        # Visual selection is handled later at the LINE delivery boundary, so this
        # pass only decorates text and cannot consume the image cooldown.
        _expressive_enabled = (
            bool(get_auto_tone_emoji_enabled(_expression_gid))
            and get_expressive_translation_mode(_expression_gid) != "off"
            and not bool(getattr(_tl, 'disable_tone_emoji', False))
            and (not _from_image_ocr or bool(get_image_ocr_expressive_enabled(_expression_gid)))
        )
        try:
            _runtime_settings = get_expressive_runtime_settings(
                _expression_gid, include_images=False
            )
            _runtime_settings = expressive_engine_module.ExpressiveSettings(
                enabled=_expressive_enabled,
                display_mode=_runtime_settings.display_mode,
                intensity=_runtime_settings.intensity,
                visual_style=_runtime_settings.visual_style,
                emoji_enabled=_runtime_settings.emoji_enabled,
                images_enabled=False,
                short_message_image_enabled=_runtime_settings.short_message_image_enabled,
                short_message_max_chars=_runtime_settings.short_message_max_chars,
                formal_safety_enabled=_runtime_settings.formal_safety_enabled,
                ocr_enabled=_runtime_settings.ocr_enabled,
            )
            _expressive_result = expressive_engine_module.enhance_translation(
                canonical_text,
                result,
                source_language=src,
                context_id=str(_expression_gid or "global"),
                settings=_runtime_settings,
                from_image_ocr=_from_image_ocr,
            )
            result = _expressive_result.text
            logger.info(
                "[ExpressiveText] group=%s mode=%s intensity=%s emoji=%s decorated=%s tone=%s",
                _expression_gid or "global",
                _runtime_settings.display_mode,
                _runtime_settings.intensity,
                _runtime_settings.emoji_enabled,
                _expressive_result.decorated_count,
                _expressive_result.tone,
            )
            _update_last_translate_debug(
                expressive_mode=_runtime_settings.display_mode,
                expressive_intensity=_runtime_settings.intensity,
                expressive_emoji_enabled=bool(_runtime_settings.emoji_enabled),
                expressive_decorated_count=int(_expressive_result.decorated_count or 0),
                expressive_tone=str(_expressive_result.tone or "neutral"),
            )
        except Exception as _expressive_exc:
            # Expression is optional. A valid paid translation must still be sent.
            logger.warning("expressive text enhancement skipped: %s", _expressive_exc)
        # Expressive decoration is also untrusted output.  Re-run the absolute
        # boundary after it so no optional formatting step can bypass factory
        # facts, identities, quantities or terminology.
        if result:
            result = _final_delivery_guard(canonical_text, result, src, tgt)
    if _is_translation_failure_sentinel(result):
        result = None
    if result:
        _set_translation_outcome("delivered")
    elif not _translation_was_intentionally_skipped():
        _set_translation_outcome("failed", "empty_or_rejected_translation")
    _update_last_translate_debug(
        final_candidate=(str(result)[:2000] if result else ""),
        pipeline_status=(
            "translation_deliverable"
            if result else
            "translation_intentionally_skipped"
            if _translation_was_intentionally_skipped() else
            "translation_empty_or_rejected"
        ),
    )
    return result


# v3.12 治本(2026-06-09):工廠材料/吊運語境偵測。
#   根因:這類句(如「二股吊完料就放這樣」)不含 glossary 詞時,會被判為「簡單句」走 NMT
#   (Google/DeepL)。NMT 缺工廠語境,把「料」直譯成 pakan(飼料)、「吊」吃掉;且 NMT 結果
#   會回存 lexical+vector TM → 之後相似句被 vector/lexical bypass 直接吐舊錯誤,繞過 glossary/
#   prompt 修正(這就是「之前修正卻無效」的主因)。
#   治本:命中此語境 → 與「有保護名」同等待遇,跳過所有 bypass + NMT,強制走 LLM(LLM 看上下文
#   + 工廠 prompt 能正確理解「吊料=吊運鋼材」),且不注入可能污染的 TM 參考。
#   採語境路由而非窮舉詞條:glossary 是 substring 精確匹配,「吊料」配不到「吊完料」,變體無窮。
_FACTORY_CTX_PAT = re.compile(
    r'吊[^。，！？\s]{0,4}[料棒材鋼管貨捆包盤胚件]'      # 吊運材料:吊料/吊完料/吊鋼捲/吊棒材
    r'|[上下入出置退來捆堆送]料'                          # 材料動作:上料/下料/入料/出料/置料/退料/來料/捆料/堆料/送料
    r'|研磨|冷抽|退火|倒角|矯直|拋光|削皮|改端漆|補毛重|改\s*[Tt][Aa][Gg]|取樣|併包|改包裝|盤元|母材|棒材|線材|解捲|料床|無心|砂帶|砂光|盤條|盤捲|抓帳|結帳|關帳|木箱|裝箱|電子系統|自然拉動'
)
def _is_factory_context(text):
    """中文工廠材料/吊運/製程語境 → 強制走 LLM(避免 NMT 誤譯與舊快取 bypass)。
    只偵測中文模式;印尼文原文不會誤觸,ID→ZH 仍走正常路徑。"""
    if not text or not isinstance(text, str):
        return False
    return bool(_FACTORY_CTX_PAT.search(text))


def _should_query_vector_tm(text, src, tgt, *, factory_ctx=False,
                            quality_critical=False, has_protected_names=False,
                            semantic_contract=None):
    """Vector TM is optional acceleration/reference, never a required stage.

    Skip requests that cannot legally use vector bypass/references anyway. This
    prevents one embedding call and up to hundreds of milliseconds of waiting on
    most short factory messages.
    """
    if os.environ.get("VECTOR_TM_ENABLED", "1").strip().lower() in ("0", "false", "off", "no"):
        return False
    compact = re.sub(r"\s+", "", text or "")
    if len(compact) < int(os.environ.get("VECTOR_TM_MIN_CHARS", "12")):
        return False
    if factory_ctx or quality_critical or has_protected_names:
        return False
    if semantic_contract and (semantic_contract.get("has_risk") or not semantic_contract.get("vector_bypass_allowed", True)):
        return False
    if _is_pure_equipment_code(text):
        return False
    return True


def _tm_bypass_integrity_ok(source_text, candidate, src, tgt):
    """Validate a historical translation before any early return.

    TM/vector rows are untrusted unless they satisfy the current immutable,
    glossary and versioned factory acceptance assets.
    """
    try:
        issues = []
        leaked_label = ge_module.find_reverse_glossary_ui_leak(
            source_text, candidate,
            GLOSSARY_LOOKUP if 'GLOSSARY_LOOKUP' in globals() else {},
            src, tgt,
        )
        if leaked_label:
            issues.append("reverse_glossary_ui_label_leak:" + leaked_label)
        envelope = tqg_module.protect_immutable_spans(source_text)
        pairs = ge_module.collect_applicable_pairs(
            source_text,
            GLOSSARY_LOOKUP if 'GLOSSARY_LOOKUP' in globals() else {},
            src, tgt,
        )
        report = tqg_module.validate_translation(
            source_text, candidate, src, tgt,
            immutable_literals=envelope.mapping.values(),
            glossary_pairs=pairs,
            require_paragraph_fidelity=False,
        )
        if not report.ok:
            issues.extend(str(item) for item in report.hard_issues)
        factory_report = _factory_guard_report(source_text, candidate, src, tgt)
        if not factory_report.ok:
            issues.extend(factory_report.hard_issues)
        issues.extend(_measurement_semantic_issues(source_text, candidate, src, tgt))
        issues = list(dict.fromkeys(item for item in issues if item))
        return not issues, issues
    except Exception as exc:
        logger.warning("[TMIntegrity] validation failed closed: %s", exc)
        return False, ["integrity_check_exception"]


def _translate_core(text, src, tgt):
    """v3.9.39 業界全面技術 hybrid pipeline(被 translate() wrapper 包覆)
    
    路由順序(命中越早,成本越低,延遲越低):
      0. 已驗證且來源完全相同的工廠修正案例             → 本地驗證後 bypass
      1. 非統一工廠模式：Lexical TM exact/fuzzy         → 本地驗證後 bypass
      2. 非統一工廠模式：Vector TM semantic bypass      → 本地驗證後 bypass
      3. 非統一工廠模式：TM references / NMT            → 依規則注入或翻譯
      4. 統一工廠模式：工廠 prompt + 詞庫 + 知識 + 案例  → LLM 主翻

    統一工廠模式不允許 legacy custom example、cache、一般 TM、向量 TM
    或通用 NMT 在現行語義契約前提前回傳。
    
    後處理:
      - QE 評分 → < 70 分 → APE 自動修正
      - 翻譯成功 → store back lexical TM + vector TM(累積資產)
    """
    _gid_for_tm = getattr(_tl, 'group_id', '') or ''
    # v3.18 速度根治:per-stage 計時。每句記一行 [Perf],之後再慢可直接從
    # Render log 看出卡在哪一段,不再用猜的。
    _perf = {"t0": time.time()}
    try:
        _tl.llm_api_ms = 0.0  # v3.31: 本句 API 純耗時歸零
    except Exception:
        pass
    # v3.9.60: 本次訊息是否含保護名(由 translate() wrapper 設定)。
    # 有保護名時強制走 LLM:NMT 會音譯人名、語義/模糊 bypass 會誤配到別句舊譯文。
    _has_protected_names = bool(getattr(_tl, 'protected_name_map', None))
    # Determine quality-critical messages structurally.  Long announcements,
    # multi-paragraph instructions and checklist-style factory messages bypass
    # stale TM/NMT routes and receive an independent review before send.
    _factory_heuristic_ctx = _is_factory_context(text)
    _factory_ctx = factory_translation_policy_module.should_force_factory_pipeline(
        text, src, tgt, heuristic_match=_factory_heuristic_ctx
    )
    try:
        _factory_domain_ctx = bool(detect_factory_domain(text, src, tgt).get("is_factory"))
    except Exception:
        _factory_domain_ctx = False
    try:
        _message_type = classify_factory_message(text, src=src).get("type")
    except Exception:
        _message_type = None
    _quality_critical = tqg_module.is_quality_critical(
        text, src, tgt, message_type=_message_type, factory_domain=_factory_domain_ctx or _factory_ctx
    )

    # v3.14: ERP 原因欄 / 短標籤可完全由 source-grounded semantic layer 翻譯。
    # 這一步放在 quality-critical clean document 前，避免圖片 OCR 多行表格被文件翻譯路徑
    # 重新解讀成「Nomor Material / Sedang / Air Palsu」。普通句子不會命中，仍走 LLM。
    if src == "zh" and tgt == "id":
        _reason_semantic = _factory_reason_semantic_translate_zh_id(text)
        if (not _reason_semantic) and getattr(_tl, 'from_image_ocr', False):
            _align_issue = _factory_reason_table_alignment_issue(text)
            if _align_issue:
                logger.warning("[FactoryReasonOCR] fail-closed: %s text=%r", _align_issue, text[:200])
                try:
                    _event_log_write("factory_reason_ocr_alignment_failed", {
                        "group_id": _gid_for_tm,
                        "reason": _align_issue,
                        "ocr_text": text[:500],
                    })
                except Exception:
                    pass
                try:
                    _tl.factory_reason_ocr_degraded = _align_issue
                except Exception:
                    pass
                # Continue through the normal provider translation path.  The
                # alignment diagnostic blocks caching, not user delivery.
        if _reason_semantic:
            _expected_rows = getattr(_tl, 'factory_reason_image_expected_rows', 0) if getattr(_tl, 'from_image_ocr', False) else 0
            if _factory_reason_ocr_incomplete_against_visual_count(text, _expected_rows):
                logger.warning(
                    "[FactoryReasonOCR] fail-closed visual row mismatch expected=%s actual=%s",
                    _expected_rows, _factory_reason_ocr_row_count(text)
                )
                try:
                    _event_log_write("factory_reason_ocr_visual_count_failed", {
                        "group_id": _gid_for_tm,
                        "expected_rows": _expected_rows,
                        "actual_rows": _factory_reason_ocr_row_count(text),
                        "ocr_text": text[:500],
                    })
                except Exception:
                    pass
                try:
                    _tl.factory_reason_ocr_degraded = "visual_row_mismatch"
                except Exception:
                    pass
                _reason_semantic = None
            if _reason_semantic and is_translation_acceptable(text, _reason_semantic, src, tgt):
                logger.info(
                    "Factory reason semantic translation accepted: %r -> %r",
                    text[:80],
                    _reason_semantic[:80],
                )
                try:
                    _tl.factory_audit = {
                        "src": text,
                        "type": "factory_reason_semantic_direct_zh_id",
                        "reason": "deterministic_erp_reason_action_semantics",
                        "raw_translation": "",
                        "corrected_translation": _reason_semantic,
                        "domain": ["factory", "erp_reason"],
                        "auto_corrected": False,
                    }
                    _log_translation(
                        text, _reason_semantic, src, tgt,
                        "factory-reason-semantic", 0, 1.0, False, 1.0,
                        _gid_for_tm,
                    )
                    cache_set(text, src, tgt, _reason_semantic)
                except Exception:
                    pass
                return _reason_semantic
            logger.error(
                "[DeterministicShortcut] ERP reason translation rejected; continuing to provider pipeline"
            )
            _update_last_translate_debug(
                pipeline_status="deterministic_erp_reason_rejected_fallback_to_provider",
                final_candidate=str(_reason_semantic)[:2000],
            )

    # v3.32.6: Quality-critical messages stay in the same one-call pipeline.
    # They bypass stale TM/NMT and are routed to the quality model, but they are
    # never reviewed, retranslated or split into multiple billable requests.

    # v3.33: vector lookup is started only after cheap lexical bypass checks.
    # Factory/critical/protected-name messages never consume its result, so an
    # eager embedding call there only added cost and tail latency.
    _vec_future = None
    
    # v3.11 (2026-05-26 18:16 截圖): 純設備代碼訊息直接 bypass,不送 LLM
    # 例:'BF 2', 'BF 3 i 16', 'I5/i15', 'E6', 'PM160', 'CYA', 'K8'
    # 工人傳這種訊息通常只是讓同事知道某設備代碼,沒有翻譯需求。
    # 送 LLM 會讓 Claude 自發加元注釋(『這是設備代碼,不翻譯』之類),污染群組。
    # ``None`` alone is ambiguous at the LINE boundary, so explicitly classify
    # this as an intentional skip before returning.  Genuine empty/rejected
    # translations remain visible failures; equipment-code chatter stays silent.
    if _is_pure_equipment_code(text):
        logger.info("[Pipeline] pure equipment code bypass: %r", text[:60])
        try:
            _event_log_write("pure_code_bypass", {
                "group_id": _gid_for_tm,
                "text": text[:100],
            })
        except Exception:
            pass
        _set_translation_outcome("skipped", "pure_equipment_code")
        _update_last_translate_debug(
            pipeline_status="translation_intentionally_skipped",
            skip_reason="pure_equipment_code",
            final_candidate="",
            openai_status="not_needed",
        )
        return None
    
    # ─── 0. Phase O: Language Auto-Detection ───
    # 偵測訊息實際語言,若與宣告的 src 不符,記到 _tl 供日誌(不主動修正避免破壞使用者設定)
    try:
        _ld_result = ld_module.detect_language(text)
        _detected_lang = _ld_result.get("primary", "unknown")
        _tl.detected_lang = _detected_lang
        _tl.detected_confidence = _ld_result.get("confidence", 0.0)
        if (_detected_lang not in ("unknown", "mixed") and 
            not src.lower().startswith(_detected_lang) and 
            not _detected_lang.startswith(src.lower()) and
            _ld_result.get("confidence", 0) > 0.7):
            logger.warning("[LD] 語言不一致:宣告 src=%s 但偵測到 %s (conf=%.2f) text=%r",
                           src, _detected_lang, _ld_result["confidence"], text[:60])
    except Exception as _ld_e:
        logger.debug("[LD] detect exception: %s", _ld_e)
    
    # ─── 0.5: Runtime semantic contract (根治多義詞，不靠單句補丁) ───
    # 高風險語義先分類，後面 TM / Vector TM / NMT / LLM / QE / APE 全部吃同一份 contract。
    _semantic_contract = build_translation_semantic_contract(text, src, tgt)
    _context_bound_translation = bool((_semantic_contract or {}).get("context_bound"))
    try:
        _tl.semantic_contract = _semantic_contract
    except Exception:
        pass

    # The versioned guard owns the authoritative exact-correction index.  It
    # accepts punctuation/spacing variants only; semantic paraphrases still go
    # through the full source-grounded translation route.
    try:
        _guard_exact = factory_translation_guard_module.exact_verified_target(text, src, tgt)
    except Exception as _guard_exact_exc:
        logger.error("[FactoryGuard] exact lookup failed closed: %s", _guard_exact_exc)
        _guard_exact = None
    if _guard_exact:
        _guard_candidate = finalize_factory_translation(text, _guard_exact, src, tgt)
        _guard_sem_ok, _guard_sem_reason = translation_satisfies_semantic_contract(
            _semantic_contract, _guard_candidate
        )
        _guard_integrity_ok, _guard_integrity_issues = _tm_bypass_integrity_ok(
            text, _guard_candidate, src, tgt
        )
        if _guard_sem_ok and _guard_integrity_ok:
            try:
                _log_translation(text, _guard_candidate, src, tgt,
                                 "factory_guard_exact", 0, 1.0, False, 1.0, _gid_for_tm)
                if _gid_for_tm:
                    _conv_buffer_add(_gid_for_tm, text, _guard_candidate, src, tgt)
            except Exception:
                pass
            _update_last_translate_debug(
                pipeline_status="factory_guard_exact",
                final_candidate=str(_guard_candidate)[:2000],
                openai_status="not_needed",
                factory_guard_fingerprint=factory_translation_guard_module.asset_fingerprint(),
            )
            return _guard_candidate
        logger.error(
            "[FactoryGuard] approved exact correction failed current boundary: %s %s",
            _guard_sem_reason, _guard_integrity_issues[:8],
        )
        if _factory_route_is_strict(text, src, tgt):
            logger.error(
                "[DeterministicShortcut] invalid approved exact correction ignored; continuing to provider pipeline"
            )
            _update_last_translate_debug(
                pipeline_status="invalid_guard_exact_fallback_to_provider",
                final_candidate=str(_guard_candidate)[:2000],
            )

    # Verified exact corrections are the only historical translations allowed to
    # bypass the unified factory route. They are source-identical, then checked
    # against the current semantic contract, glossary and immutable data before
    # delivery. Fuzzy TM/vector/NMT can never override them.
    try:
        _exact_cases = _retrieve_verified_translation_cases(text, src, tgt, max_cases=8)
        _exact_verified = translation_casebook_module.exact_verified_target(text, _exact_cases)
    except Exception as _exact_exc:
        logger.warning("[FactoryPolicy] exact verified lookup failed open: %s", _exact_exc)
        _exact_verified = None
    if _exact_verified:
        _exact_candidate = finalize_factory_translation(text, _exact_verified, src, tgt)
        _exact_sem_ok, _exact_sem_reason = translation_satisfies_semantic_contract(
            _semantic_contract, _exact_candidate
        )
        _exact_integrity_ok, _exact_integrity_issues = _tm_bypass_integrity_ok(
            text, _exact_candidate, src, tgt
        )
        if _exact_sem_ok and _exact_integrity_ok:
            try:
                _log_translation(text, _exact_candidate, src, tgt,
                                 "verified_exact_factory_case", 0, 1.0, False, 1.0, _gid_for_tm)
                if _gid_for_tm:
                    _conv_buffer_add(_gid_for_tm, text, _exact_candidate, src, tgt)
            except Exception:
                pass
            _update_last_translate_debug(
                pipeline_status="verified_exact_factory_case",
                final_candidate=str(_exact_candidate)[:2000],
                openai_status="not_needed",
            )
            return _exact_candidate
        logger.warning(
            "[FactoryPolicy] exact verified correction blocked by current contract: %s %s",
            _exact_sem_reason, _exact_integrity_issues[:8],
        )

    # ─── 1+2: Lexical TM lookup ───
    _tm_result = None
    try:
        _tm_result = tm_module.tm_lookup(text, src, tgt, _gid_for_tm)
        if _tm_result:
            if _is_translation_failure_sentinel(_tm_result.get("tgt_text", "")):
                logger.warning("[LegacyFailurePurge] ignored failure payload from lexical TM")
                _tm_result = None
            elif isinstance(_tm_result.get("references"), list):
                _tm_result["references"] = [
                    ref for ref in _tm_result["references"]
                    if len(ref) < 3 or not _is_translation_failure_sentinel(ref[2])
                ]
    except Exception as _tm_e:
        logger.warning("[TM] lookup exception: %s", _tm_e)
    
    # v3.9.60: 有保護名時只允許 exact bypass(key 精確相符,placeholder 化文字本就名稱無關);
    # fuzzy_bypass 會在 placeholder 化文字上模糊配對 → 可能配到「同形不同名」的舊譯文 → 名字錯。
    # v3.12: 工廠語境連 exact bypass 都跳過(舊快取可能含 NMT 誤譯的 pakan),強制重新 LLM 翻譯。
    _tm_bypass_types = () if (_factory_ctx or _quality_critical or not _semantic_contract.get("tm_bypass_allowed", True)) else (("exact",) if _has_protected_names else ("exact", "fuzzy_bypass"))
    if _tm_result and _tm_result.get("match_type") in _tm_bypass_types:
        _bypass_result = _tm_result["tgt_text"]
        _tm_sem_ok, _tm_sem_reason = translation_satisfies_semantic_contract(_semantic_contract, _bypass_result)
        _tm_integrity_ok, _tm_integrity_issues = _tm_bypass_integrity_ok(text, _bypass_result, src, tgt)
        if _tm_sem_ok and _tm_integrity_ok:
            try:
                _log_translation(text, _bypass_result, src, tgt,
                                 f"tm_{_tm_result['match_type']}", 0, 1.0, False, 1.0, _gid_for_tm)
            except Exception:
                pass
            try:
                if _gid_for_tm:
                    _conv_buffer_add(_gid_for_tm, text, _bypass_result, src, tgt)
            except Exception:
                pass
            logger.info("[Pipeline] LexTM bypass: type=%s score=%d", _tm_result["match_type"], _tm_result["score"])
            return _bypass_result
        else:
            _tm_block_reason = _tm_sem_reason or ",".join(_tm_integrity_issues[:6]) or "integrity_failed"
            logger.warning("[TMIntegrity] LexTM bypass blocked: %s text=%r tm=%r",
                           _tm_block_reason, text[:80], (_bypass_result or '')[:120])
            try:
                _event_log_write("semantic_tm_bypass_blocked", {
                    "group_id": _gid_for_tm,
                    "reason": _tm_block_reason,
                    "src_text": text[:120],
                    "tm_text": (_bypass_result or '')[:160],
                })
            except Exception:
                pass
    
    # ─── 3+4: Vector TM lookup ───
    _perf["tm"] = time.time()
    if _should_query_vector_tm(
        text, src, tgt,
        factory_ctx=_factory_ctx,
        quality_critical=_quality_critical,
        has_protected_names=_has_protected_names,
        semantic_contract=_semantic_contract,
    ):
        try:
            _vec_future = _VEC_LOOKUP_EXECUTOR.submit(
                vec_tm_module.vector_lookup, text, src, tgt, _gid_for_tm)
        except Exception as _vec_submit_e:
            logger.debug("[VecTM] submit skipped: %s", _vec_submit_e)
            _vec_future = None
    _vec_result = None
    try:
        if _vec_future is not None:
            # Vector TM must never dominate the real-time path. 50 ms is enough
            # to collect a warm/local result; otherwise continue immediately.
            _vec_wait = max(0.0, min(0.25, float(os.environ.get("VECTOR_TM_WAIT_SECONDS", "0.05"))))
            _vec_result = _vec_future.result(timeout=_vec_wait)
    except TimeoutError:
        logger.debug("[VecTM] not ready within realtime wait window; continue without it")
    except Exception as _vec_e:
        logger.warning("[VecTM] lookup exception: %s", _vec_e)
    _perf["vec"] = time.time()
    
    # v3.9.60: 有保護名時跳過語義 bypass(placeholder 化後語義中性,
    # 「只差人名」的兩句會被當成幾乎相同 → 可能回傳別人名字的舊譯文)。
    if _vec_result and _is_translation_failure_sentinel(_vec_result.get("tgt_text", "")):
        logger.warning("[LegacyFailurePurge] ignored failure payload from vector TM")
        _vec_result = None
    elif _vec_result and isinstance(_vec_result.get("references"), list):
        _vec_result["references"] = [
            ref for ref in _vec_result["references"]
            if len(ref) < 3 or not _is_translation_failure_sentinel(ref[2])
        ]

    if (not _has_protected_names) and (not _factory_ctx) and (not _quality_critical) and _semantic_contract.get("vector_bypass_allowed", True) and _vec_result and _vec_result.get("match_type") == "vector_bypass":
        _bypass_result = _vec_result["tgt_text"]
        _vec_sem_ok, _vec_sem_reason = translation_satisfies_semantic_contract(_semantic_contract, _bypass_result)
        _vec_integrity_ok, _vec_integrity_issues = _tm_bypass_integrity_ok(text, _bypass_result, src, tgt)
        if _vec_sem_ok and _vec_integrity_ok:
            try:
                _log_translation(text, _bypass_result, src, tgt,
                                 "vec_tm_bypass", 0, 1.0, False, _vec_result["similarity"], _gid_for_tm)
            except Exception:
                pass
            try:
                if _gid_for_tm:
                    _conv_buffer_add(_gid_for_tm, text, _bypass_result, src, tgt)
            except Exception:
                pass
            logger.info("[Pipeline] VecTM bypass: sim=%.3f", _vec_result["similarity"])
            return _bypass_result
        else:
            _vec_block_reason = _vec_sem_reason or ",".join(_vec_integrity_issues[:6]) or "integrity_failed"
            logger.warning("[TMIntegrity] VecTM bypass blocked: %s text=%r vec=%r",
                           _vec_block_reason, text[:80], (_bypass_result or '')[:120])
            try:
                _event_log_write("semantic_vec_bypass_blocked", {
                    "group_id": _gid_for_tm,
                    "reason": _vec_block_reason,
                    "src_text": text[:120],
                    "vec_text": (_bypass_result or '')[:160],
                })
            except Exception:
                pass
    
    # ─── 5: 收集要注入的 references (lexical + vector inject) ───
    _all_refs = []
    if _tm_result and _tm_result.get("match_type") == "fuzzy_inject":
        for s, src_t, tgt_t in _tm_result["references"]:
            _all_refs.append((s, src_t, tgt_t, "lexical"))
    if _vec_result and _vec_result.get("match_type") == "vector_inject":
        for s, src_t, tgt_t in _vec_result["references"]:
            _all_refs.append((int(s * 100), src_t, tgt_t, "semantic"))
    
    # v3.12: 工廠語境不注入 TM 參考(舊譯可能含 NMT 誤譯 pakan),純靠 glossary hint + 工廠 prompt。
    if _factory_ctx or _quality_critical:
        _all_refs = []
    if _all_refs:
        try:
            if _semantic_contract.get("has_risk"):
                _all_refs = filter_semantic_contract_references(_semantic_contract, _all_refs)
            _tl.tm_references = [(s, sr, tg) for s, sr, tg, _ in _all_refs[:5]]  # top-5 dedup
        except Exception:
            pass
    
    # ─── 6: NMT routing(短句 → Google/DeepL) ───
    _factory_glossary_set = set()
    try:
        if 'GLOSSARY_LOOKUP' in globals():
            _factory_glossary_set = set(GLOSSARY_LOOKUP.keys())
    except Exception:
        pass
    
    _use_nmt = False
    try:
        # v3.9.60: 有保護名時禁用 NMT(Google/DeepL 會把 placeholder 弄壞或音譯人名),強制走 LLM。
        _use_nmt = (not _has_protected_names) and (not _factory_ctx) and (not _quality_critical) and _semantic_contract.get("nmt_allowed", True) and (not semantic_contract_requires_llm(_semantic_contract)) and nmt_module.should_use_nmt(text, src, tgt, _factory_glossary_set)
    except Exception:
        _use_nmt = False
    
    if _use_nmt:
        try:
            nmt_result = nmt_module.nmt_translate(text, src, tgt)
            if nmt_result:
                # NMT 成功後只做本地品質檢查，不再呼叫 QE/APE 模型
                logger.info("[Pipeline] NMT route success: %d chars", len(text))
                result = nmt_result
                # 跳過 LLM 全翻,直接進後處理
                _skip_to_post = True
            else:
                _skip_to_post = False
                try:
                    nmt_module.nmt_record_llm_route()
                except Exception:
                    pass
        except Exception as _nmt_e:
            logger.warning("[NMT] failed, fallback to LLM: %s", _nmt_e)
            _skip_to_post = False
    else:
        try:
            nmt_module.nmt_record_llm_route()
        except Exception:
            pass
        _skip_to_post = False
    
    # ─── 7: LLM 全翻 (預設路徑) ───
    _perf["pre_llm"] = time.time()
    if not _skip_to_post:
        _len_before = len(translation_log)
        _prev_qg = getattr(_tl, 'quality_gate_pending', None)
        _prev_qgc = getattr(_tl, 'quality_gate_critical', None)
        _prev_force_model = getattr(_tl, 'force_model', None)
        try:
            # Defer every new cache write until the final deterministic gate.
            _tl.quality_gate_pending = True
            _tl.quality_gate_critical = _quality_critical
            if _quality_critical:
                _tl.force_model = _active_upgrade_model()
            result = _translate_inner(text, src, tgt)
        finally:
            try:
                if _prev_qg is None:
                    if hasattr(_tl, 'quality_gate_pending'):
                        delattr(_tl, 'quality_gate_pending')
                else:
                    _tl.quality_gate_pending = _prev_qg
                if _prev_qgc is None:
                    if hasattr(_tl, 'quality_gate_critical'):
                        delattr(_tl, 'quality_gate_critical')
                else:
                    _tl.quality_gate_critical = _prev_qgc
                if _prev_force_model is None:
                    if hasattr(_tl, 'force_model'):
                        delattr(_tl, 'force_model')
                else:
                    _tl.force_model = _prev_force_model
            except Exception:
                pass
        try:
            if result is not None and len(translation_log) == _len_before:
                _log_translation(text, result, src, tgt, "wrapper", 0, 1.0, False, 1.0,
                                 getattr(_tl, 'group_id', ''))
        except Exception as e:
            import traceback
            logger.error("[TLOG] wrapper log failed: %s\n%s", e, traceback.format_exc())
    
    # Runtime plant-context repair + semantic contract enforcement after NMT/LLM/TM-inject.
    if result and isinstance(result, str):
        result = _maybe_repair_factory_knowledge_translation(text, result, src, tgt, _semantic_contract)
        result = enforce_translation_semantic_contract(_semantic_contract, text, result)

    # ─── 後處理 0.5: Phase H Glossary Enforcement (在 QE 之前) ───
    # 強制術語對照:譯文有無遵守 glossary
    if result and isinstance(result, str) and not result.startswith("⚠"):
        try:
            _glossary_for_ge = GLOSSARY_LOOKUP if 'GLOSSARY_LOOKUP' in globals() else {}
            if _glossary_for_ge:
                _ge_result = ge_module.enforce_glossary(
                    text, result, _glossary_for_ge, src, tgt,
                    ai_client=None,
                )
                if _ge_result.get("action_taken") == "fixed":
                    logger.info("[Pipeline] GE auto-fixed %d violations",
                                len(_ge_result.get("violations", [])))
                    result = _ge_result["final_text"]
                elif _ge_result.get("action_taken") == "blocked":
                    result = _ge_result["final_text"]
                elif _ge_result.get("action_taken") == "warned" and _ge_result.get("violations"):
                    # 把 violations 存 thread-local,供 QE 參考
                    try:
                        _tl.ge_violations = _ge_result["violations"]
                    except Exception:
                        pass
        except Exception as _ge_e:
            logger.warning("[GE] enforcement exception: %s", _ge_e)
    
    if result and isinstance(result, str):
        result = enforce_translation_semantic_contract(_semantic_contract, text, result)

    # ═══ v3.13 速度根治:以下全部移出使用者等待路徑 ═══
    # 原本順序:QE(1 次 LLM)→ APE(可能再 1 次 LLM)→ TM 入庫 → 向量入庫(1 次 embedding API)
    # 全部跑完才 return → 才回 LINE。一句話多等 2~6 秒,純粹是內部品管/資產累積,
    # 使用者完全感覺不到好處。業界 chat MT 標準:譯文一好就送,評分入庫走背景。
    # 確定性防線(glossary 強制、semantic contract、工廠 finalize、語言洩漏重試)
    # 全部保留在主路徑 — 擋錯的還在擋,只把「事後評分與資產累積」移走。
    #
    # 注意:APE 改在背景跑後,修正結果不再回到本次訊息(LINE 訊息本來就不能編輯,
    # 原本 blocking APE 換到的只是「偶爾低分句多等幾秒換修正版」)。
    # 修正版現在會更新 cache + TM,同句下次直接命中好譯文 — 資產品質不變。

    # Mention placeholders are recoverable identity metadata.  Repair them
    # before meta/quality checks so a provider omission is not misreported as a
    # translation-service outage.  Non-mention immutable tokens remain strict.
    if result and isinstance(result, str):
        result = _repair_pipeline_identity_placeholders(text, result)

    # ─── 主路徑收尾 1: <thinking> tag 過濾(v3.11,移到入庫前 — 原本在入庫後,
    #      導致 TM 可能存進含 thinking tag 的髒文字,順手治本) ───
    if result and isinstance(result, str):
        try:
            _stripped = _strip_thinking_tags(result)
            if _stripped:
                result = _stripped
            else:
                logger.warning("[Thinking] strip 後 result 為空,保留原 result(可能整段都是 thinking): %r",
                               result[:200])
        except Exception as _ste:
            logger.warning("[Thinking] strip exception: %s", _ste)

    # ─── 主路徑收尾 2: 元注釋洩漏偵測(v3.11) ───
    # 先記錄並禁止入庫；後續同步品質閘門與最終工廠邊界會再次檢查，
    # 統一工廠模式下不可交付含元注釋的譯文。
    _meta_leak_detected = False
    try:
        if _is_meta_commentary_leak(result):
            _meta_leak_detected = True
            logger.warning(
                "[MetaLeak] 偵測到元注釋洩漏;候選禁止入庫並交由最終邊界裁決: %r",
                result[:200],
            )
            try:
                _event_log_write("meta_commentary_leak_delivered", {
                    "group_id": _gid_for_tm,
                    "src_text": text[:100],
                    "leaked": result[:200],
                })
            except Exception:
                pass
    except Exception as _mle:
        logger.warning("[MetaLeak] 偵測 exception: %s", _mle)

    _quality_cacheable = not _meta_leak_detected

    # ─── 主路徑收尾 2.5:同步品質閘門 ───
    # Newly generated high-risk factory translations may receive one
    # source-grounded review. Exact verified corrections have already returned
    # above. Review is an additional quality signal, not a single point of
    # failure: a locally valid first candidate remains deliverable as degraded
    # and non-cacheable when the reviewer is unavailable or returns bad text.
    if result and isinstance(result, str):
        _pre_gate_result = result
        try:
            _immutable_env = tqg_module.protect_immutable_spans(text)
            _safe_pairs = ge_module.collect_applicable_pairs(
                text, GLOSSARY_LOOKUP if 'GLOSSARY_LOOKUP' in globals() else {}, src, tgt
            )
            _immutable_literals = list(_immutable_env.mapping.values())
            for _identity_value in dict(getattr(_tl, 'protected_name_map', None) or {}).values():
                _identity_value = str(_identity_value or '').strip()
                if _identity_value and _identity_value in text and _identity_value not in _immutable_literals:
                    _immutable_literals.append(_identity_value)
            _review_already_attempted = bool(
                getattr(_tl, "source_review_already_attempted", False)
            )
            _adaptive_review_risk = bool(
                _quality_critical
                or (_semantic_contract or {}).get("requires_independent_review")
            )
            _factory_review_required = factory_translation_policy_module.require_source_review(
                text, src, tgt, adaptive_risk=_adaptive_review_risk
            )
            _force_source_review = bool(
                (_adaptive_review_risk or _factory_review_required)
                and not _review_already_attempted
            )
            _require_review_success = bool(
                _factory_review_required
                and factory_translation_policy_module.require_review_success(src, tgt)
                and not _review_already_attempted
            )
            _review_context = build_translation_semantic_contract_prompt(_semantic_contract)
            _verified_cases = _verified_cases_from_contract(_semantic_contract)
            def _runtime_semantic_validator(candidate):
                _issues = []
                if _verified_cases:
                    _case_ok, _case_issues = translation_casebook_module.validate_translation_cases(
                        _verified_cases, candidate
                    )
                    if not _case_ok or _case_issues:
                        _issues.extend(str(x) for x in (_case_issues or []) if str(x).strip())
                _contract_ok, _contract_reason = translation_satisfies_semantic_contract(
                    _semantic_contract, candidate
                )
                if not _contract_ok and _contract_reason:
                    _issues.append(str(_contract_reason))
                try:
                    _factory_report = _factory_guard_report(text, candidate, src, tgt)
                    if not _factory_report.ok:
                        _issues.extend(_factory_report.hard_issues)
                except Exception as _factory_guard_exc:
                    if _factory_route_is_strict(text, src, tgt):
                        _issues.append("factory_guard_exception:" + type(_factory_guard_exc).__name__)
                _issues = list(dict.fromkeys(_issues))
                return not _issues, _issues

            _gate = tqg_module.gate_and_revise(
                text, result, src, tgt,
                critical=_quality_critical,
                model=_active_upgrade_model(),
                immutable_literals=_immutable_literals,
                glossary_pairs=_safe_pairs,
                # At most one extra source-grounded call.  If the dedicated
                # factory-knowledge repair already ran, keep this gate local so
                # a single message can never cascade into three provider calls.
                ai_client=(None if _review_already_attempted else ai_provider),
                force_review=_force_source_review,
                used_provider=getattr(_tl, "last_provider_used", None),
                review_context=_review_context,
                semantic_validator=_runtime_semantic_validator,
                require_review_success=_require_review_success,
            )
            if _gate.get("reviewed"):
                _tl.source_review_already_attempted = True
            if not _gate.get("ok") or not _gate.get("text"):
                # Only a source-identical, locally approved correction may
                # replace a rejected provider result.  Fuzzy cases are prompt
                # evidence, never sentence-level fallbacks.
                _exact_verified = factory_translation_guard_module.exact_verified_target(
                    text, src, tgt
                )
                if not _exact_verified and _verified_cases:
                    _exact_verified = translation_casebook_module.exact_verified_target(
                        text, _verified_cases
                    )
                _exact_candidate = None
                if _exact_verified:
                    _candidate = finalize_factory_translation(text, _exact_verified, src, tgt)
                    _candidate_ok, _candidate_issues = _tm_bypass_integrity_ok(
                        text, _candidate, src, tgt
                    )
                    if _candidate_ok:
                        _exact_candidate = _candidate
                    else:
                        logger.error(
                            "[FactoryGuard] exact gate fallback rejected: %s",
                            _candidate_issues[:12],
                        )
                if _exact_candidate:
                    result = _exact_candidate
                    _quality_cacheable = True
                    _gate = dict(_gate)
                    _gate.update({
                        "ok": True,
                        "text": result,
                        "cacheable": True,
                        "degraded": False,
                        "path": "factory_guard_exact_fallback",
                    })
                else:
                    # The first provider candidate remains available to the one
                    # authoritative public delivery boundary.  Internal review
                    # may disable cache/TM admission, but it must never erase the
                    # only translation and manufacture a service outage.
                    logger.warning(
                        "[QualityGate] review disagreement; preserving first candidate for final boundary issues=%s",
                        _gate.get("issues"),
                    )
                    result = _pre_gate_result
                    _quality_cacheable = False
                try:
                    last_translate_debug["final_pipeline_status"] = (
                        "factory_guard_exact_fallback"
                        if _exact_candidate else
                        ("factory_guard_rejected" if result is None else "quality_gate_warning_delivered")
                    )
                    last_translate_debug["quality_gate_path"] = _gate.get("path")
                    last_translate_debug["quality_gate_issues"] = list(_gate.get("issues", []))[:20]
                    last_translate_debug["final_candidate"] = str(result or "")[:2000]
                    _persist_last_translate_debug()
                except Exception:
                    pass
            else:
                result = _gate["text"].strip()
                _quality_cacheable = (not _meta_leak_detected) and bool(_gate.get("cacheable", True))
                try:
                    last_translate_debug["final_pipeline_status"] = (
                        "quality_gate_warning_delivered"
                        if _gate.get("degraded")
                        else "quality_gate_passed"
                    )
                    last_translate_debug["quality_gate_path"] = _gate.get("path")
                    last_translate_debug["quality_gate_issues"] = list(_gate.get("issues", []))[:20]
                    last_translate_debug["final_candidate"] = result[:2000]
                    _persist_last_translate_debug()
                except Exception:
                    pass
            if result:
                result = _strip_thinking_tags(result) or result
                if _is_meta_commentary_leak(result):
                    _quality_cacheable = False
                    if _factory_route_is_strict(text, src, tgt):
                        logger.error("[QualityGate] meta commentary blocked by factory guard")
                        result = _factory_exact_fallback(text, src, tgt)
                    else:
                        logger.warning("[QualityGate] reviewer returned meta commentary; keeping first provider result")
                        result = _pre_gate_result
                if result:
                    result = enforce_translation_semantic_contract(_semantic_contract, text, result)
                    _final_guard_report = _factory_guard_report(text, result, src, tgt)
                    if not _final_guard_report.ok:
                        _quality_cacheable = False
                        _exact_candidate = _factory_exact_fallback(text, src, tgt)
                        if _exact_candidate:
                            result = _exact_candidate
                            _quality_cacheable = True
                        else:
                            logger.warning(
                                "[FactoryGuard] post-gate disagreement; preserving provider candidate for final boundary issues=%s",
                                _final_guard_report.issues[:20],
                            )
                            result = _pre_gate_result
                if _context_bound_translation:
                    _quality_cacheable = False
                if result and _quality_cacheable:
                    cache_set(text, src, tgt, result, force=True)
        except Exception as _qge:
            try:
                last_translate_debug["final_pipeline_status"] = "quality_gate_exception"
                last_translate_debug["quality_gate_exception"] = str(_qge)[:500]
                _persist_last_translate_debug()
            except Exception:
                pass
            _quality_cacheable = False
            logger.exception(
                "[QualityGate] validation exception; preserving first provider candidate without caching: %s",
                _qge,
            )
            result = _factory_exact_fallback(text, src, tgt) or _pre_gate_result
            _quality_cacheable = bool(result and result != _pre_gate_result)

    # One final in-core boundary also covers deterministic/NMT/provider paths
    # that may not have entered the quality-gate branch above.
    if result:
        try:
            _core_guard_report = _factory_guard_report(text, result, src, tgt)
            if not _core_guard_report.ok:
                logger.warning(
                    "[FactoryGuard] in-core disagreement deferred to authoritative final boundary issues=%s",
                    _core_guard_report.issues[:20],
                )
                _exact = _factory_exact_fallback(text, src, tgt)
                if _exact:
                    result = _exact
                    _quality_cacheable = True
                else:
                    _quality_cacheable = False
        except Exception as _core_guard_exc:
            logger.exception("[FactoryGuard] in-core validation exception; preserving candidate: %s", _core_guard_exc)
            _quality_cacheable = False

    # ─── 主路徑收尾 3: 對話 buffer(純記憶體 deque,零成本,留在主路徑) ───
    try:
        if result is not None and _gid_for_tm:
            _conv_buffer_add(_gid_for_tm, text, result, src, tgt)
    except Exception as e:
        try:
            logger.debug("conv buffer add failed: %s", e)
        except Exception:
            pass

    # 把背景需要的 thread-local 值先抓成普通變數(背景執行緒看不到本執行緒的 _tl)
    _conf_for_bg = getattr(_tl, 'last_confidence', None)
    _model_for_bg = getattr(_tl, 'last_model_used', '') or 'unknown'

    # 清掉 _tl 暫存避免污染下一次翻譯
    for _attr in ('tm_references', 'last_confidence', 'last_provider_used',
                  'last_model_used', 'source_review_already_attempted',
                  'factory_knowledge_issues', 'detected_lang',
                  'detected_confidence', 'ge_violations', 'semantic_contract'):
        try:
            if hasattr(_tl, _attr):
                delattr(_tl, _attr)
        except Exception:
            pass

    # Media-resolved ellipsis is context-bound.  Never teach source-only
    # cache/TM/vector stores that an omitted work-order noun is always present.
    if _context_bound_translation:
        _quality_cacheable = False

    # ─── 背景後處理:本地品質訊號 → TM store → 向量 store（0 次翻譯 API） ───
    if result and isinstance(result, str) and not result.startswith("⚠") and _quality_cacheable:
        try:
            _BG_POST_EXECUTOR.submit(
                _post_translation_async,
                text, result, src, tgt, _gid_for_tm,
                _model_for_bg, _conf_for_bg, _semantic_contract,
            )
        except Exception as _bg_e:
            logger.warning("[BG] submit post-processing failed: %s", _bg_e)

    # v3.18: per-stage 計時 — 每句一行,慢的時候直接看這行抓兇手
    try:
        _t_end = time.time()
        logger.info(
            "[Perf] total=%.0fms | prep+lex=%.0fms vec_wait=%.0fms api=%.0fms local_post=%.0fms | src=%s tgt=%s len=%d",
            (_t_end - _perf["t0"]) * 1000,
            (_perf.get("tm", _perf["t0"]) - _perf["t0"]) * 1000,
            (_perf.get("vec", _perf["t0"]) - _perf.get("tm", _perf["t0"])) * 1000,
            float(getattr(_tl, "llm_api_ms", 0) or 0),
            max(0.0, (_t_end - _perf.get("pre_llm", _t_end)) * 1000 - float(getattr(_tl, "llm_api_ms", 0) or 0)),
            src, tgt, len(text or ""),
        )
    except Exception:
        pass

    return result


def _post_translation_async(text, result, src, tgt, gid, model_used, conf, semantic_contract):
    """Store only translations accepted by the current deterministic assets."""
    final = result
    quality_for_tm = int(conf * 100) if conf is not None else None
    try:
        pairs = ge_module.collect_applicable_pairs(
            text, GLOSSARY_LOOKUP if 'GLOSSARY_LOOKUP' in globals() else {}, src, tgt
        )
        report = tqg_module.validate_translation(
            text, final, src, tgt,
            glossary_pairs=pairs,
            require_paragraph_fidelity=tqg_module.is_quality_critical(text, src, tgt),
        )
        factory_report = _factory_guard_report(text, final, src, tgt)
        issues = list(report.hard_issues or []) + list(factory_report.hard_issues or [])
        issues = list(dict.fromkeys(str(item) for item in issues if str(item).strip()))
        if issues:
            logger.warning("[TM-bg] rejected unverified translation issues=%s", issues[:20])
            return
        if quality_for_tm is None:
            quality_for_tm = 100
    except Exception as exc:
        logger.warning("[TM-bg] validation failed closed: %s", exc)
        return
    try:
        tm_module.tm_store(text, final, src, tgt, gid, model_used, quality_for_tm)
    except Exception as exc:
        logger.warning("[TM-bg] store exception: %s", exc)
    try:
        vec_tm_module.vector_store(text, final, src, tgt, gid, model_used, quality_for_tm)
    except Exception as exc:
        logger.warning("[VecTM-bg] store exception: %s", exc)


# =====================================================================
# v3.7 段落結構保留(分段翻譯)
# =====================================================================
# 問題:GPT 即使在 prompt 中要求保留段落,長訊息仍可能合併段落
# 解法:把訊息以 \n\n 切段,每段獨立翻譯,再用相同分隔符拼接
# 原理:每段獨立翻譯 = GPT 不可能合併不同的 API 呼叫的結果

def _has_paragraph_structure(text):
    """偵測訊息是否含分段結構
    
    判斷標準:
      - 含 \n\n (空行分隔)
      - 或含多個 \n 且總長度 > 閾值
    """
    if not text:
        return False
    # 優先:有空行分隔
    if "\n\n" in text:
        return True
    # 次要:訊息夠長且含多個換行
    char_len = len(re.sub(r"\s+", "", text))
    if char_len >= paragraph_split_threshold and text.count("\n") >= 2:
        return True
    return False


def _split_into_paragraphs(text):
    """把訊息切成段落 list,保留分隔符資訊以便還原
    
    回傳: [(paragraph_text, separator_after), ...]
      separator_after = "\n\n" / "\n" / ""
    """
    # 用空行分段(優先),保留分隔符
    # 把連續空行視為一個分隔符,不加入空段
    parts = []
    current = ""
    i = 0
    while i < len(text):
        # 偵測 \n\n+(連續空行)
        m = re.match(r"\n{2,}", text[i:])
        if m:
            if current.strip():
                parts.append((current, "\n\n"))
            current = ""
            i += m.end()
            continue
        # 偵測單個 \n
        if text[i] == "\n":
            if current.strip():
                parts.append((current, "\n"))
                current = ""
            i += 1
            continue
        current += text[i]
        i += 1
    
    if current.strip():
        parts.append((current, ""))
    
    return parts


def _translate_single_paragraph(text, src, tgt):
    """v3.7 單段翻譯(供分段翻譯使用,跳過分段邏輯避免無窮迴圈)

    統一工廠模式下不讀一般 custom example / cache；只有 _translate_core
    前置的「來源完全相同且重新驗證通過」案例可以直接回傳。
    """
    # v3.15: 圖片 OCR 表格被分段時，每一列仍必須先跑 ERP 原因語義層。
    # 否則單列會繞過 _translate_core 的整表判斷，回到 LLM/快取而重現
    # Nomor Material / Air Palsu / Gerinda 等舊錯譯。
    if src == "zh" and tgt == "id":
        reason_semantic = _factory_reason_semantic_translate_zh_id(text)
        if reason_semantic:
            return reason_semantic

    _force_factory = factory_translation_policy_module.should_force_factory_pipeline(
        text, src, tgt, heuristic_match=_is_factory_context(text)
    )

    _guard_exact = factory_translation_guard_module.exact_verified_target(text, src, tgt)
    if _guard_exact:
        _guard_candidate = finalize_factory_translation(text, _guard_exact, src, tgt)
        if is_translation_acceptable(text, _guard_candidate, src, tgt):
            return _guard_candidate
        logger.error(
            "[DeterministicShortcut] invalid single-paragraph exact correction ignored; continuing to provider"
        )

    # 1. Legacy custom examples are not verified against the current factory
    # contract. They remain available only outside the unified factory route.
    exact = None if _force_factory else _check_custom_example_exact(text.strip(), src, tgt)
    if exact:
        return exact

    # 2. Legacy cache rows have no policy/glossary build metadata. Never let
    # them bypass the current factory contract; a fresh accepted output may be
    # cached for diagnostics but is not trusted as an authoritative factory case.
    cached = None if _force_factory else cache_get(text, src, tgt)
    if cached:
        return cached
    
    # 3. 統一 AI 協調層已處理三家接力；此處不可再做外層重試，否則會倍增呼叫。
    result = translate_openai(text, src, tgt)
    if result:
        result = finalize_factory_translation(text, result, src, tgt)
        # This function is a provider stage, not a delivery boundary.  Returning
        # None here used to convert any local heuristic warning into a fake
        # provider outage before the whole-document authoritative gate could
        # review, repair, or classify the candidate.  Defer acceptance and cache
        # admission to _translate_core/_final_delivery_guard.
        try:
            if not is_translation_acceptable(text, result, src, tgt):
                logger.warning(
                    "[QualityGate] single-paragraph candidate deferred to authoritative gate"
                )
                _update_last_translate_debug(
                    pipeline_status="single_paragraph_candidate_deferred",
                    final_candidate=str(result)[:2000],
                )
            else:
                cache_set(text, src, tgt, result)
        except Exception as exc:
            logger.warning(
                "[QualityGate] single-paragraph diagnostic validation failed; deferred: %s",
                exc,
            )
        return result
    return None


def _snapshot_translation_thread_context():
    """複製目前翻譯 thread-local 狀態，供段落工作執行緒沿用。

    多執行緒若沒有複製 group/tone/semantic-contract/TM 等上下文，速度雖快，
    但各段可能失去同一套術語與語氣。這裡只搬移執行緒本身已有的資料，
    不改 prompt、不換模型，因此並行化不會犧牲翻譯品質。
    """
    snapshot = {}
    for key, value in getattr(_tl, "__dict__", {}).items():
        try:
            snapshot[key] = copy.deepcopy(value)
        except Exception:
            snapshot[key] = value
    return snapshot


def _translate_with_thread_context(translate_fn, para_text, src, tgt, context_snapshot):
    """在可重用 worker 內乾淨地套用/還原翻譯上下文，避免跨訊息污染。"""
    previous = dict(getattr(_tl, "__dict__", {}))
    try:
        _tl.__dict__.clear()
        _tl.__dict__.update(context_snapshot)
        return translate_fn(para_text, src, tgt)
    finally:
        _tl.__dict__.clear()
        _tl.__dict__.update(previous)


def _translate_paragraphs_separately(text, src, tgt, translate_fn):
    """Compatibility shim: paragraphs are preserved in one whole-message request."""
    return None



def _translate_inner(text, src, tgt):
    _quality_critical = bool(getattr(_tl, 'quality_gate_critical', False))
    _force_factory = factory_translation_policy_module.should_force_factory_pipeline(
        text, src, tgt, heuristic_match=_is_factory_context(text)
    )
    # ★ v3.6 印尼文預處理:在所有後續路徑之前先標準化
    _preprocessing_log = None
    if src == "id" and id_preprocessing_enabled:
        normalized, n_replacements = normalize_indonesian_text(text)
        if n_replacements > 0:
            logger.info("ID preprocessing: %d replacements. %r → %r", 
                       n_replacements, text[:60], normalized[:60])
            _preprocessing_log = {"original": text, "normalized": normalized, "count": n_replacements}
            # 把標準化結果存到 thread-local 供日誌記錄
            try:
                _tl.id_preprocessing = _preprocessing_log
            except Exception:
                pass
            # 用標準化版本後續處理
            text = normalized
        # 進階:nano 模型語意級規範化(成本高)
        if id_preprocessing_nano:
            text_nano = normalize_indonesian_text_with_nano(text)
            if text_nano and text_nano != text:
                text = text_nano
    
    _guard_exact = factory_translation_guard_module.exact_verified_target(text, src, tgt)
    if _guard_exact:
        _guard_candidate = finalize_factory_translation(text, _guard_exact, src, tgt)
        if is_translation_acceptable(text, _guard_candidate, src, tgt):
            return _guard_candidate
        logger.error(
            "[DeterministicShortcut] invalid inner exact correction ignored; continuing to provider"
        )
        _update_last_translate_debug(
            pipeline_status="invalid_inner_exact_fallback_to_provider",
            final_candidate=str(_guard_candidate)[:2000],
        )

    # ★ v3.7 段落結構保留:訊息含分段時走分段翻譯路徑
    # 這個路徑不影響短訊息(沒分段就直接走原本流程)
    # v3.9.27: 來自圖片 OCR 的文字一律走分段路徑(段落保留是首要需求)
    _is_from_image = getattr(_tl, 'from_image_ocr', False)
    if False and (not _quality_critical) and paragraph_split_translate and _has_paragraph_structure(text):
        char_len = len(re.sub(r"\s+", "", text))
        # v3.9.27: 圖片 OCR 不看 threshold,直接分段
        if _is_from_image or char_len >= paragraph_split_threshold:
            try:
                # 用內部 helper 來處理單段(會走 cache + custom_example)
                def _single_para_translate(para, s, t):
                    # 重新進入 _translate_inner 但跳過分段路徑(避免無窮迴圈)
                    return _translate_single_paragraph(para, s, t)
                
                multi_result = _translate_paragraphs_separately(text, src, tgt, _single_para_translate)
                if multi_result:
                    logger.info("Paragraph-split SUCCESS: orig=%d chars, result=%d chars",
                                len(text), len(multi_result))
                    return multi_result
                else:
                    logger.info("Paragraph-split returned None, falling back to single-shot")
            except Exception as _e:
                logger.error("Paragraph-split exception: %s", _e)
    
    # Legacy UI custom examples are not enough to bypass the unified factory
    # contract. Exact verified factory/human cases were already handled in
    # _translate_core before any TM/cache route.
    exact = None if (_quality_critical or _force_factory) else _check_custom_example_exact(text.strip(), src, tgt)
    if exact:
        checked = finalize_factory_translation(text, exact, src, tgt)
        if checked and is_translation_acceptable(text, checked, src, tgt):
            logger.info("Custom example exact match: %s -> %s", src, tgt)
            return checked
        logger.warning("[QualityGate] invalid custom example ignored")

    # Deterministic factory semantic engine before cache/OpenAI.
    # This prevents short factory defect/direction reports from being treated as daily language.
    if (not _quality_critical) and src == "id" and tgt == "zh":
        semantic = factory_semantic_translate_id_zh(text)
        if semantic:
            if is_translation_acceptable(text, semantic, src, tgt):
                logger.info(
                    "Factory semantic translation accepted: %r -> %r",
                    text[:80],
                    semantic[:80],
                )
                _tl.factory_audit = {
                    "src": text,
                    "type": "factory_semantic_direct",
                    "reason": "deterministic_factory_slot_translation",
                    "raw_translation": "",
                    "corrected_translation": semantic,
                    "domain": detect_factory_domain(text, src, tgt).get("domains", []),
                    "auto_corrected": False,
                }
                _log_translation(
                    text, semantic, src, tgt, "factory-semantic", 0, 1.0,
                    False, 1.0, getattr(_tl, 'group_id', '')
                )
                cache_set(text, src, tgt, semantic)
                return semantic
            logger.error(
                "[DeterministicShortcut] ID->ZH semantic output rejected; continuing to provider"
            )
            _update_last_translate_debug(
                pipeline_status="deterministic_id_zh_rejected_fallback_to_provider",
                final_candidate=str(semantic)[:2000],
            )

    if (not _quality_critical) and src == "zh" and tgt == "id":
        semantic = factory_semantic_translate_zh_id(text)
        if semantic:
            if is_translation_acceptable(text, semantic, src, tgt):
                logger.info(
                    "Factory ZH->ID semantic translation accepted: %r -> %r",
                    text[:80],
                    semantic[:80],
                )
                _tl.factory_audit = {
                    "src": text,
                    "type": "factory_semantic_direct_zh_id",
                    "reason": "deterministic_factory_zh_id_translation",
                    "raw_translation": "",
                    "corrected_translation": semantic,
                    "domain": detect_factory_domain(text, src, tgt).get("domains", []),
                    "auto_corrected": False,
                }
                _log_translation(
                    text, semantic, src, tgt, "factory-semantic-zh-id", 0,
                    1.0, False, 1.0, getattr(_tl, 'group_id', '')
                )
                cache_set(text, src, tgt, semantic)
                return semantic
            logger.error(
                "[DeterministicShortcut] ZH->ID semantic output rejected; continuing to provider"
            )
            _update_last_translate_debug(
                pipeline_status="deterministic_zh_id_rejected_fallback_to_provider",
                final_candidate=str(semantic)[:2000],
            )

    # Legacy cache entries do not carry policy/glossary build IDs. In unified
    # factory mode they cannot be trusted as an early-return source.
    cached = None if (_quality_critical or _force_factory) else cache_get(text, src, tgt)
    if cached:
        cached = finalize_factory_translation(text, cached, src, tgt)
        if cached and is_translation_acceptable(text, cached, src, tgt):
            _log_translation(text, cached, src, tgt, "cache", 0, 1.0, False, 1.0, getattr(_tl, 'group_id', ''))
            return cached
        logger.warning("[QualityGate] invalid cache entry ignored")

    # ★ v3.4:長 ID→ZH 訊息嘗試 pivot via English(若啟用)
    pivot_result = None
    if False and should_use_pivot(text, src, tgt):
        try:
            pivot_result = translate_id_zh_with_pivot(text, src, tgt)
        except Exception as _e:
            logger.warning("Pivot attempt failed: %s", _e)
    
    # 三家 provider 的接力、總期限與熔斷均由 ai_provider 統一處理。
    # 這裡只發出一次主翻譯，避免外層 retry 再把整條 provider chain 重跑。
    result = translate_openai(text, src, tgt)
    if _is_translation_failure_sentinel(result):
        logger.warning("[LegacyFailurePurge] provider returned a legacy failure payload; treating as empty")
        result = None
    if not result:
        # Generic consumer NMT is intentionally disabled for the unified factory
        # route: a fluent but wrong accounting/process/equipment instruction is
        # unsafe. Operators may opt in only with FACTORY_ALLOW_GENERIC_NMT_FALLBACK=1.
        if factory_translation_policy_module.allow_generic_nmt_fallback(src, tgt):
            try:
                result = translate_google(text, src, tgt)
            except Exception as _nmt_fallback_exc:
                logger.warning("[FreeNMTFallback] exception: %s", _nmt_fallback_exc)
                result = None
            if result and not _is_translation_failure_sentinel(result):
                logger.warning("[FreeNMTFallback] delivered Google fallback after empty paid response")
                _update_last_translate_debug(
                    fallback_used="google_gtx",
                    fallback_status="success",
                    final_candidate=str(result)[:2000],
                    pipeline_status="free_nmt_fallback_success",
                )
            else:
                result = None
                _update_last_translate_debug(
                    fallback_used="google_gtx",
                    fallback_status="empty",
                    pipeline_status="all_translation_results_empty",
                )
        else:
            logger.error("[FactoryPolicy] generic NMT fallback blocked after empty provider response")
            result = None
            _update_last_translate_debug(
                fallback_used="disabled_by_factory_policy",
                fallback_status="blocked",
                pipeline_status="factory_translation_provider_empty",
            )
    
    # ★ v3.4:雙翻 ensemble - 比較 pivot 和直譯,選較完整的
    if pivot_result and result:
        result = select_better_translation(result, pivot_result, text)

    # v3.32.6: no quality repair request.  The first pass is accepted or blocked locally.

    if result:
        result = finalize_factory_translation(text, result, src, tgt)
        # _translate_inner is only the provider stage.  It must never decide that
        # a non-empty provider response is a service failure.  The former local
        # fail-close happened before gate_and_revise(), so recoverable terminology
        # or language-purity diagnostics (for example repeated technical labels)
        # bypassed review and surfaced as the generic LINE failure notice.
        #
        # Keep diagnostics and cache discipline here, but always pass the candidate
        # to the one authoritative whole-document gate.  Semantic/factory defects
        # can still be repaired by review or rejected at the final boundary.
        try:
            if is_translation_acceptable(text, result, src, tgt):
                cache_set(text, src, tgt, result)
            else:
                logger.warning(
                    "[QualityGate] inner provider candidate deferred to authoritative gate"
                )
                _update_last_translate_debug(
                    pipeline_status="inner_candidate_deferred_to_authoritative_gate",
                    final_candidate=str(result)[:2000],
                )
        except Exception as exc:
            logger.warning(
                "[QualityGate] inner diagnostic validation failed; candidate deferred: %s",
                exc,
            )
            _update_last_translate_debug(
                pipeline_status="inner_candidate_validation_exception_deferred",
                final_candidate=str(result)[:2000],
            )
        return result

    # No second translation API for quality recovery.
    # Last chance: deterministic semantic fallback before returning None.
    if src == "id" and tgt == "zh":
        semantic = factory_semantic_translate_id_zh(text)
        if semantic and is_translation_acceptable(text, semantic, src, tgt):
            cache_set(text, src, tgt, semantic)
            return semantic

    return None

WORK_ORDER_OCR_KEYWORDS = (
    "冷精棒製造指示書", "製造指示書", "訂單編號", "客戶名稱", "成品尺寸",
    "FINAL流程", "FINAL", "MIC_NO", "ID_NO", "HRITABPDIL", "退火代碼",
    "冷精棒", "收貨人", "短尺", "品保", "特殊", "削皮", "訂單資訊",
    "成品尺寸MIN", "成品尺寸MAX", "製造指示",
)


def analyze_work_order(ocr_text):
    """Classify OCR text as a work order independently of customer extraction.

    Older code used the customer string as the work-order boolean.  That meant a
    real 製造指示書 with unreadable/absent customer name was treated as an
    ordinary image, so the next terse text message lost its order context.
    """
    if not ocr_text:
        return {"is_work_order": False, "customer": None, "keyword_count": 0}
    keyword_count = sum(1 for kw in WORK_ORDER_OCR_KEYWORDS if kw in ocr_text)
    logger.info(
        "Work order detection: %d keywords matched in OCR text (%d chars)",
        keyword_count, len(ocr_text),
    )
    if keyword_count < 2:
        return {"is_work_order": False, "customer": None, "keyword_count": keyword_count}

    customer = None
    patterns = [
        r'客戶名稱[:\s：]*([^\s\n|,，]+)',
        r'客戶[:\s：]*([^\s\n|,，]+)',
        r'客[户戶]名[称稱][:\s：]*([^\s\n|,，]+)',
    ]
    for pat in patterns:
        m = re.search(pat, ocr_text)
        if m:
            candidate = m.group(1).strip()
            if candidate and len(candidate) >= 2:
                customer = candidate
                logger.info("Work order customer detected: %s", customer)
                break
    if not customer:
        for name in CUSTOMER_NAMES:
            if len(name) >= 2 and name in ocr_text:
                customer = name
                logger.info("Work order customer matched from list: %s", customer)
                break
    if not customer:
        logger.info("Work order detected but no customer name found")
    return {
        "is_work_order": True,
        "customer": customer,
        "keyword_count": keyword_count,
    }


def detect_work_order(ocr_text):
    """Backward-compatible customer extractor for a detected work order."""
    analysis = analyze_work_order(ocr_text)
    return analysis.get("customer") if analysis.get("is_work_order") else None


def format_length_zh(code):
    """Convert length code to Chinese."""
    if code == "<=3200":
        return "未滿3200"
    elif code == ">4200":
        return "超過4200"
    elif code == ">3200<=4200":
        return "3200～4200"
    elif code == ">4000":
        return "超過4000"
    else:
        c = code.replace("<=", "未滿").replace(">=", "超過").replace(">", "超過").replace("<", "未滿")
        return c


def format_storage_for_work_order(customer_name):
    """Format storage lookup for work order image detection."""
    entries = STORAGE_LOOKUP.get(customer_name)
    if not entries:
        for key in STORAGE_LOOKUP:
            if key.lower() == customer_name.lower() or customer_name in key or key in customer_name:
                entries = STORAGE_LOOKUP[key]
                customer_name = key
                break
    if not entries:
        return None
    lines = []
    lines.append("\U0001f4cb \u5de5\u55ae\u5075\u6e2c")
    lines.append("\u5ba2\u6236\uff1a" + customer_name)
    lines.append("")
    lines.append("\U0001f4e6 \u5132\u5340\u67e5\u8a62")
    lines.append("=" * 18)
    for length, area in entries:
        zh = format_length_zh(length)
        lines.append(zh + " \u2192 " + area)
    lines.append("=" * 18)
    return "\n".join(lines)


