# Vision / OCR：GPT-5.6 Terra 為預設，跨三家視覺模型自動接力。
# 環境變數若仍填舊型號，啟動時會自動遷移到現行白名單。
VISION_MODEL = ai_provider.normalize_vision_model(
    os.environ.get("VISION_MODEL", ai_provider.DEFAULT_OPENAI_VISION_MODEL))
VISION_FALLBACK_MODEL = ai_provider.DEFAULT_OPENAI_VISION_FALLBACK_MODEL


def _vision_call(messages, max_tokens, cache_key=None,
                 task_type="ocr", reasoning_override=None):
    """統一圖片/OCR 呼叫：三家 vision 共用期限、熔斷與自動接力。

    不再直接綁定 OpenAI client，也不在此層重跑第二個模型；模型映射與
    provider 接力全部交給 ai_provider.chat_complete，避免重複重試。
    """
    active = ai_provider.get_active_provider()
    use_claude = ai_provider.should_use_claude_for_images()
    if active == "anthropic" and not use_claude:
        # 開關 OFF 代表成本偏好，不再代表「Claude-only 時整個圖片功能失效」。
        preference = ["openai", "gemini", "anthropic"]
    elif active == "gemini":
        preference = ["gemini", "openai", "anthropic"]
    elif active == "anthropic":
        preference = ["anthropic", "openai", "gemini"]
    else:
        preference = ["openai", "gemini", "anthropic"]

    if not _has_ai_capability("vision"):
        raise RuntimeError("沒有已設定且支援圖片辨識的 AI provider")

    model = VISION_MODEL
    kwargs = {
        "model": model,
        "messages": messages,
        "timeout": 24,
        "required_capability": "vision",
        "provider_preference": preference,
        "latency_profile": "vision",
        "translation_fast_quality": True,
    }

    # OCR 需要完整輸出；場景描述只需短句。OpenAI 參數會在 provider 層按模型
    # 過濾，Claude/Gemini 路徑只接收它們實際支援的欄位。
    if model_supports(model, "max_completion_tokens"):
        if task_type == "scene":
            budget = max(max_tokens if max_tokens > 0 else 300, 512)
        else:
            # OCR needs room for dense tables, but GPT-5.6 translation runs with
            # reasoning=none; a fixed extra 4K reasoning allowance is unnecessary.
            budget = min(max(max_tokens, 3200), 12000)
        kwargs["max_completion_tokens"] = budget
    else:
        kwargs["max_tokens"] = max_tokens

    if model_supports(model, "temperature"):
        kwargs["temperature"] = 0.0
    if model_supports(model, "reasoning_effort"):
        effort = reasoning_override or optimal_reasoning_for_translation(model)
        if effort:
            kwargs["reasoning_effort"] = effort
    if model_supports(model, "verbosity"):
        kwargs["verbosity"] = "low" if task_type == "scene" else "high"
    if cache_key:
        kwargs["prompt_cache_key"] = cache_key

    try:
        _event_log_write("vision_call_start", {
            "model": model,
            "provider_preference": preference,
            "task_type": task_type,
            "kwargs_keys": list(kwargs.keys()),
        })
    except Exception:
        pass

    try:
        response = ai.chat.completions.create(**kwargs)
        provider_used = getattr(response, "_jy_provider", active)
        content = response.choices[0].message.content if response.choices else None
        finish = response.choices[0].finish_reason if response.choices else None
        try:
            usage = response.usage.model_dump() if hasattr(response, "usage") and hasattr(response.usage, "model_dump") else None
            _event_log_write("vision_call_done", {
                "model": getattr(response, "model", model),
                "provider": provider_used,
                "finish": finish,
                "content_len": len(content) if content else 0,
                "usage": usage,
            })
        except Exception:
            pass
        logger.info("[Vision] provider=%s model=%s finish=%s content_len=%d",
                    provider_used, getattr(response, "model", model), finish,
                    len(content) if content else 0)
        if finish == "length":
            logger.warning("[Vision] output truncated (finish_reason=length)")
        return response
    except Exception as exc:
        try:
            _event_log_write("vision_call_failed", {
                "model": model,
                "provider_preference": preference,
                "error": str(exc)[:300],
                "error_type": type(exc).__name__,
            })
        except Exception:
            pass
        logger.error("[Vision] all providers failed: %r", exc)
        raise


def _clean_ocr_status_bar(text):
    """v3.9.29: 改用 token-based 偵測,精準移除手機螢幕狀態列。
    
    判斷邏輯:把每行拆成 tokens,如果**所有 tokens 都是狀態元素**就移除整行。
    只要有一個 token 不是狀態元素就保留(避免誤殺正常內容)。
    
    狀態元素:
    - 時間: "09:40", "12:43", "23:59"  
    - 訊號: "4G", "5G", "Wi-Fi", "wifi", "LTE", "VoLTE"
    - 電量: "99+", "100%", "63%", "<99+", ">99+"
    - LINE 介面: "已讀 1/2/...", "輸入訊息", "換行", "中/英/符"
    - 注音
    """
    if not text:
        return text
    
    import re
    
    # 單一 token 是否為狀態元素
    def is_status_token(tok):
        if not tok:
            return True  # 空 token 視為狀態(允許)
        # 純時間
        if re.match(r'^\d{1,2}:\d{2}$', tok):
            return True
        # 訊號
        if re.match(r'^[345]G$', tok):
            return True
        if re.match(r'^(Wi[-]?Fi|wifi|WIFI|LTE|VoLTE|HSPA|5G\+|5GE)$', tok, re.I):
            return True
        # 純數字 / 99+ / 帶 + 號
        if re.match(r'^\d{1,3}\+?$', tok):
            return True
        # 百分比
        if re.match(r'^\d{1,3}%$', tok):
            return True
        # <99+ / >99+
        if re.match(r'^[<>]\d{1,3}\+?$', tok):
            return True
        return False
    
    # 整行匹配的特殊狀態
    line_status_patterns = [
        r'^已讀\s*\d+$',
        r'^輸入訊息$',
        r'^換行$',
        r'^(中|英|符|空白鍵|語音輸入|注音|倉頡|嘸蝦米)$',
        r'^[\u3105-\u3129]+$',  # 純注音字母
    ]
    
    cleaned_lines = []
    for line in text.split('\n'):
        stripped = line.strip()
        if not stripped:
            cleaned_lines.append(line)  # 保留空行(段落分隔)
            continue
        
        # 整行匹配檢查
        is_status_line = False
        for pat in line_status_patterns:
            if re.match(pat, stripped):
                is_status_line = True
                break
        
        if not is_status_line:
            # Token-based 檢查:用空白切 tokens,看是否每個都是狀態元素
            tokens = re.split(r'\s+', stripped)
            tokens = [t for t in tokens if t]  # 過濾空字串
            if tokens and all(is_status_token(t) for t in tokens):
                is_status_line = True
        
        if not is_status_line:
            cleaned_lines.append(line)
    
    return '\n'.join(cleaned_lines)


def _factory_reason_ocr_row_count(text):
    if not text or not isinstance(text, str):
        return 0
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    return max(
        sum(1 for ln in lines if _parse_factory_reason_table_row(ln)),
        len(_parse_factory_reason_split_rows(lines)),
        len(_parse_factory_reason_column_major_rows(lines)),
    )


def _factory_reason_ocr_incomplete_against_visual_count(text, expected_rows):
    """Fail closed when visual row segmentation saw more ERP rows than OCR text.

    The dangerous failure mode is not a bad Indonesian word; it is an omitted or
    duplicated source row.  Once an ID/原因 screenshot loses rows, the deterministic
    reason semantic layer will faithfully translate the wrong source table.  This
    guard compares parsed source rows with the row count estimated from the
    image's visible row bands.  One row of tolerance is allowed for bottom-edge
    partial crops, but larger gaps are blocked instead of shifted onto IDs.
    """
    try:
        expected = int(expected_rows or 0)
    except Exception:
        expected = 0
    if expected < 4:
        return False
    actual = _factory_reason_ocr_row_count(text)
    if actual <= 0:
        return False
    return actual < max(2, expected - 1)


def _should_run_factory_reason_table_ocr(text):
    if not text or not isinstance(text, str):
        return False
    compact = _compact_factory_reason_text(text)
    has_id = bool(re.search(r"(?<![A-Za-z0-9])ID(?![A-Za-z0-9])", text or "", re.I))
    has_reason_header = bool(re.search(r"原\s*[因囚困]|原因|理由", text or ""))
    has_reason_word = any(_compact_factory_reason_text(v) in compact
                          for e in _FACTORY_REASON_ACTIONS
                          for v in (list(e.get("variants", ())) + list(e.get("reason_only_variants", ()))))
    has_code = bool(re.search(r"(?=[A-Z0-9._/-]*\d)(?=[A-Z0-9._/-]*[A-Z])[A-Z0-9][A-Z0-9._/-]{4,30}", text or "", re.I))
    return bool(has_code and (has_reason_header or (has_id and has_reason_word)))


def _factory_reason_parsed_rows(text):
    """Return parsed source rows as [(id, reason_key)] without translating."""
    if not text or not isinstance(text, str):
        return []
    lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
    same_raw = [_parse_factory_reason_table_row(ln) for ln in lines]
    same = [(row[0], row[1]["key"]) for row in same_raw if row and row[0] and row[1]]
    split = [(mid, entry["key"]) for mid, entry in _parse_factory_reason_split_rows(lines)]
    column = [(mid, entry["key"]) for mid, entry in _parse_factory_reason_column_major_rows(lines)]
    return max((same, split, column), key=len)


def _factory_reason_ocr_has_uncertain_cells(text):
    if not text or not isinstance(text, str):
        return True
    for mid, key in _factory_reason_parsed_rows(text):
        if "?" in (mid or "") or "？" in (mid or "") or not key:
            return True
    return False


def _factory_reason_ocr_rows_conflict(left_text, right_text):
    """Compare two independent OCR readings.  Shared IDs must agree.

    Generic OCR is not trusted as the final source, but when it already contains
    same-line rows and disagrees with strict row OCR, that is positive evidence
    of row/cell instability, so we fail closed instead of choosing a side.
    """
    left = _factory_reason_parsed_rows(left_text)
    right = _factory_reason_parsed_rows(right_text)
    if len(left) < 2 or len(right) < 2:
        return False
    lm = {}
    for mid, key in left:
        lm.setdefault(mid, key)
    for mid, key in right:
        if mid in lm and lm[mid] != key:
            return True
    return False


def _factory_reason_ocr_strict_safety_issue(generic_text, strict_text, expected_rows=0):
    """Return empty string only when strict ERP reason OCR is safe to translate.

    Safety means source-grounded rows only.  If the image looked like an ID/原因
    table but strict OCR did not produce a complete, source-Chinese table, the
    caller must not fall back to generic OCR/translation.
    """
    if not strict_text or not isinstance(strict_text, str):
        return "strict_ocr_empty"
    st = strict_text.strip()
    if not st or "NO_TABLE" in st.upper():
        return "strict_ocr_no_table"
    low = st.lower()
    if any(bad in low for bad in _FACTORY_REASON_WRONG_ID_PATTERNS):
        return "strict_ocr_translated_or_bad_source"
    if not _should_run_factory_reason_table_ocr(st):
        return "strict_ocr_not_reason_table"
    rows = _factory_reason_parsed_rows(st)
    if len(rows) < 2:
        return "strict_ocr_too_few_rows"
    if _factory_reason_ocr_has_uncertain_cells(st):
        return "strict_ocr_uncertain_cells"
    try:
        expected = int(expected_rows or 0)
    except Exception:
        expected = 0
    if expected >= 4 and len(rows) < expected:
        return "strict_ocr_visual_row_mismatch"
    # If generic OCR independently read same-line rows and disagrees, neither
    # source is reliable enough for an ID/process assignment.
    if _factory_reason_ocr_rows_conflict(generic_text, st):
        return "strict_ocr_conflicts_with_generic"
    return ""


def _strict_factory_reason_ocr_is_better(generic_text, strict_text):
    _tls = globals().get('_tl', None)
    _expected = getattr(_tls, 'factory_reason_image_expected_rows', 0) if _tls is not None else 0
    if _factory_reason_ocr_strict_safety_issue(generic_text, strict_text, _expected):
        return False
    strict_rows = _factory_reason_ocr_row_count(strict_text)
    generic_rows = _factory_reason_ocr_row_count(generic_text)
    # Prefer the strict row-grid pass only when it produces a complete real
    # reason table and does not lose rows compared with generic OCR.
    return strict_rows >= 2 and strict_rows >= generic_rows


def _factory_reason_visual_row_bands_from_image(image_base64, mime_type="image/jpeg"):
    """Return visible data-row bands for an ID/原因 table using local image geometry.

    This is an optional CV pre-pass used only to prevent row-shift OCR.  It does
    not read text and it does not translate.  It estimates the horizontal row
    bands, then the row-crop OCR pass asks Vision to read each cropped row as an
    independent item.  If OpenCV/Pillow are unavailable, callers fall back to the
    normal full-image OCR path.
    """
    try:
        import base64 as _b64
        import io as _io
        from PIL import Image as _Image
        import cv2 as _cv2
        import numpy as _np
    except Exception as exc:
        logger.info("[FactoryReasonOCR] CV row segmentation unavailable: %s", exc)
        return []
    try:
        raw = _b64.b64decode(image_base64)
        img = _Image.open(_io.BytesIO(raw)).convert("RGB")
        # Upscale narrow phone crops before line detection; coordinates are kept
        # in the processed image and row crops are made from that same image.
        w0, h0 = img.size
        scale = 1.0
        if w0 < 1200:
            scale = 1200.0 / float(max(1, w0))
            img = img.resize((int(round(w0 * scale)), int(round(h0 * scale))), _Image.Resampling.LANCZOS)
        arr = _np.array(img)
        gray = _cv2.cvtColor(arr, _cv2.COLOR_RGB2GRAY)
        h, w = gray.shape[:2]

        def _candidate_lines(_gray):
            scores = {}
            widths = [max(60, min(140, w // 7)), max(80, min(220, w // 4))]
            for block, cval in ((31, 10), (41, 12), (51, 15)):
                try:
                    bw = _cv2.adaptiveThreshold(_gray, 255, _cv2.ADAPTIVE_THRESH_MEAN_C, _cv2.THRESH_BINARY_INV, block, cval)
                except Exception:
                    continue
                for kw in widths:
                    kernel = _cv2.getStructuringElement(_cv2.MORPH_RECT, (kw, 1))
                    hline = _cv2.morphologyEx(bw, _cv2.MORPH_OPEN, kernel, iterations=1)
                    hline = _cv2.dilate(hline, _cv2.getStructuringElement(_cv2.MORPH_RECT, (3, 2)), iterations=1)
                    proj = (hline > 0).mean(axis=1)
                    # Low threshold catches faint lower grid lines; later sequencing
                    # rejects text-stroke false positives by expected row pitch.
                    ys = _np.where(proj > 0.05)[0]
                    if len(ys) == 0:
                        continue
                    groups = []
                    start = int(ys[0]); prev = int(ys[0])
                    for yv in ys[1:]:
                        yv = int(yv)
                        if yv <= prev + 2:
                            prev = yv
                        else:
                            groups.append((start, prev))
                            start = prev = yv
                    groups.append((start, prev))
                    for a, b in groups:
                        cy = int((a + b) // 2)
                        sc = float(proj[cy]) if 0 <= cy < len(proj) else 0.0
                        # Merge near-duplicates, preserving the strongest candidate.
                        merged_y = None
                        for old_y in list(scores.keys()):
                            if abs(old_y - cy) <= 4:
                                merged_y = old_y
                                break
                        if merged_y is None or sc > scores.get(merged_y, 0.0):
                            if merged_y is not None:
                                scores.pop(merged_y, None)
                            scores[cy] = sc
            return sorted(scores.items())

        cands = _candidate_lines(gray)
        if len(cands) < 5:
            return []
        ys = [y for y, _sc in cands]
        score = {y: sc for y, sc in cands}

        # Find the first stable header/data grid triple.  For ID/原因 tables this
        # normally corresponds to: header top, header bottom, first data-row bottom.
        start_idx = None
        for i in range(len(ys) - 3):
            d1 = ys[i + 1] - ys[i]
            d2 = ys[i + 2] - ys[i + 1]
            d3 = ys[i + 3] - ys[i + 2]
            if 35 <= d1 <= 140 and 35 <= d2 <= 140 and 35 <= d3 <= 140 and abs(d2 - d3) <= 28:
                start_idx = i
                break
        if start_idx is None:
            return []

        seq = [ys[start_idx], ys[start_idx + 1], ys[start_idx + 2]]
        pitch = float(max(35, ys[start_idx + 2] - ys[start_idx + 1]))
        inferred = 0
        while True:
            last = seq[-1]
            expected = last + pitch
            if expected >= h - 3:
                break
            lo = last + max(24, int(round(0.55 * pitch)))
            hi = last + min(160, int(round(1.60 * pitch)))
            window = [y for y in ys if lo <= y <= hi]
            if window:
                # Prefer real gridline strength, but reject weak far-away false
                # positives; inserting the expected boundary is safer than
                # accepting a text-stroke as a row line.
                cand = min(window, key=lambda yy: abs(yy - expected) - 60.0 * score.get(yy, 0.0))
                gap = cand - last
                if (abs(cand - expected) > 0.25 * pitch or gap > 1.28 * pitch) and score.get(cand, 0.0) < 0.16:
                    nxt = int(round(expected)); inferred += 1
                else:
                    nxt = int(cand)
                    pitch = 0.90 * pitch + 0.10 * float(max(20, gap))
            else:
                nxt = int(round(expected)); inferred += 1
            if nxt <= last + 15:
                break
            seq.append(nxt)
            if len(seq) > 80:
                break

        # Convert boundaries to data-row bands.  First band is header, so skip it.
        bands = []
        for y0, y1 in zip(seq[1:-1], seq[2:]):
            if y1 - y0 < 18:
                continue
            # Fail-safe: a row cut by the bottom edge must not be OCR'd and
            # assigned a guessed reason.  The user can resend a lower crop if
            # that partial row is needed.
            if y1 >= h - max(6, int(round(0.12 * pitch))):
                continue
            bands.append((max(0, y0 - 2), min(h, y1 + 2)))
        if len(bands) < 4:
            return []
        # Use a broad crop from the visible ID column through the reason column.
        x0 = max(0, int(w * 0.035))
        x1 = w
        return [(x0, y0, x1, y1, img) for (y0, y1) in bands]
    except Exception as exc:
        logger.warning("[FactoryReasonOCR] visual row-band detection failed: %s", exc)
        return []


def _factory_reason_visual_expected_rows_from_image(image_base64, mime_type="image/jpeg"):
    try:
        return len(_factory_reason_visual_row_bands_from_image(image_base64, mime_type=mime_type))
    except Exception:
        return 0


def _factory_reason_row_contact_sheets(image_base64, mime_type="image/jpeg", rows_per_sheet=8):
    """Build row-numbered contact sheets from detected table rows.

    Each strip contains exactly one original table row.  The row labels are only
    anchors for the OCR model, not source cells.  The returned expected count is
    later used to fail closed if OCR still drops rows.
    """
    try:
        import base64 as _b64
        import io as _io
        from PIL import Image as _Image, ImageDraw as _ImageDraw, ImageEnhance as _ImageEnhance
    except Exception:
        return 0, []
    bands = _factory_reason_visual_row_bands_from_image(image_base64, mime_type=mime_type)
    if not bands:
        return 0, []
    sheets = []
    target_row_width = 1350
    label_w = 115
    pad = 10
    for chunk_start in range(0, len(bands), max(1, int(rows_per_sheet))):
        chunk = bands[chunk_start:chunk_start + rows_per_sheet]
        row_imgs = []
        for idx, (x0, y0, x1, y1, img) in enumerate(chunk, start=chunk_start + 1):
            crop = img.crop((x0, y0, x1, y1))
            # Strengthen text/grid contrast for phone-photo moiré screenshots.
            crop = _ImageEnhance.Contrast(crop).enhance(1.55)
            crop = _ImageEnhance.Sharpness(crop).enhance(1.8)
            scale = min(4.0, max(1.4, float(target_row_width - label_w) / float(max(1, crop.width))))
            crop = crop.resize((int(round(crop.width * scale)), int(round(crop.height * scale))), _Image.Resampling.LANCZOS)
            strip_h = crop.height + pad * 2
            strip_w = label_w + crop.width + pad * 2
            strip = _Image.new("RGB", (strip_w, strip_h), "white")
            draw = _ImageDraw.Draw(strip)
            draw.rectangle((0, 0, label_w - 1, strip_h - 1), outline="black", width=2)
            draw.text((12, max(4, strip_h // 2 - 10)), f"R{idx:02d}", fill="black")
            strip.paste(crop, (label_w + pad, pad))
            draw.line((0, strip_h - 1, strip_w, strip_h - 1), fill="black", width=2)
            row_imgs.append(strip)
        if not row_imgs:
            continue
        sheet_w = max(im.width for im in row_imgs)
        sheet_h = sum(im.height for im in row_imgs)
        sheet = _Image.new("RGB", (sheet_w, sheet_h), "white")
        y = 0
        for im in row_imgs:
            sheet.paste(im, (0, y))
            y += im.height
        bio = _io.BytesIO()
        sheet.save(bio, format="PNG")
        sheets.append({
            "start_row": chunk_start + 1,
            "end_row": chunk_start + len(chunk),
            "mime_type": "image/png",
            "base64": _b64.b64encode(bio.getvalue()).decode("ascii"),
        })
    return len(bands), sheets


def ocr_factory_reason_table_rows_openai(image_base64, mime_type="image/jpeg"):
    """Row-crop OCR for ERP ID/原因 tables.

    Full-table Vision OCR can silently skip visually crowded rows or smear one
    reason label down several rows.  This pass first slices the table by visible
    row bands, then asks Vision to OCR each isolated row.  The result is still
    source OCR only; translation is handled later by the shared factory reason
    semantic layer.
    """
    if not _has_ai_capability("vision"):
        return None
    expected_rows, sheets = _factory_reason_row_contact_sheets(image_base64, mime_type=mime_type)
    try:
        _tl.factory_reason_image_expected_rows = expected_rows or 0
    except Exception:
        pass
    if not sheets or expected_rows < 4:
        return None
    parsed_lines = []
    try:
        for sheet in sheets:
            msgs = [
                {
                    "role": "system",
                    "content": (
                        "你是工廠 ERP / Excel 的逐列 OCR 引擎，只負責轉錄原文，不得翻譯。\n"
                        "圖片是原表格逐列裁切後的 contact sheet，每一條 Rxx 橫列就是原表格的一列。\n"
                        "規則:\n"
                        "1. 每個 Rxx 都要輸出一行，格式: Rxx | <ID> | <原因>。\n"
                        "2. ID 逐字 OCR，保留 7H/7G/7I/7B、A/B/C/D 尾碼，不得校正或猜測。\n"
                        "3. 原因只輸出中文原文，不得翻譯；常見值包含 改端漆、補毛重、退火、倒角、削皮、拋光、併包、改包裝、改Tag、取樣。\n"
                        "4. 看不清楚的單一字元用 ?；整格看不清楚用 ?。不要把上一列原因複製到下一列。\n"
                        "5. Rxx 是輔助列號，不是表格內容。不要輸出說明。"
                    ),
                },
                {
                    "role": "user",
                    "content": [
                        {
                            "type": "image_url",
                            "image_url": {
                                "url": f"data:{sheet['mime_type']};base64," + sheet["base64"],
                                "detail": "high",
                            },
                        },
                        {
                            "type": "text",
                            "text": f"請逐列 OCR R{sheet['start_row']:02d} 到 R{sheet['end_row']:02d}。只輸出 Rxx | ID | 原因。",
                        },
                    ],
                },
            ]
            r = _vision_call(
                msgs,
                max_tokens=1800,
                cache_key=_build_cache_key(getattr(_tl, 'group_id', ''), "img", "txt", f"ocr_factory_reason_rows_{sheet['start_row']}_{sheet['end_row']}"),
                task_type="ocr",
            )
            track_tokens(r)
            raw = (r.choices[0].message.content or "").strip()
            logger.info("[FactoryReasonOCR] row-crop raw R%02d-R%02d (%d chars): %s", sheet['start_row'], sheet['end_row'], len(raw), raw[:300])
            for line in raw.splitlines():
                s = (line or "").strip()
                if not s:
                    continue
                # Drop the OCR helper row label R01/R1 if present.
                s = re.sub(r"^R\s*\d{1,3}\s*(?:\||｜|:|：|-|—)\s*", "", s, flags=re.I).strip()
                if _is_factory_reason_header_line(s):
                    continue
                row = _parse_factory_reason_table_row(s)
                if row:
                    parsed_lines.append(f"{row[0]} | {row[1]['key']}")
        if not parsed_lines:
            return None
        # Deduplicate consecutive duplicate OCR lines only; do not remove repeated
        # reasons or similar IDs because each visible row matters.
        cleaned = []
        for ln in parsed_lines:
            if not cleaned or cleaned[-1] != ln:
                cleaned.append(ln)
        result = "ID | 原因\n" + "\n".join(cleaned)
        actual_rows = _factory_reason_ocr_row_count(result)
        if actual_rows >= max(2, expected_rows - 1):
            logger.info("[FactoryReasonOCR] row-crop OCR accepted expected_rows=%d actual_rows=%d", expected_rows, actual_rows)
            return result
        logger.warning("[FactoryReasonOCR] row-crop OCR incomplete expected_rows=%d actual_rows=%d", expected_rows, actual_rows)
        return None
    except Exception as exc:
        logger.warning("[FactoryReasonOCR] row-crop OCR failed: %s", exc)
        return None


def ocr_factory_reason_table_openai(image_base64, mime_type="image/jpeg"):
    """Dedicated source-OCR for ERP ID/原因 tables. Does not translate.

    Generic vision OCR can read narrow Excel screenshots by columns, or skip a few
    visually crowded rows. That shifts reasons onto the wrong material IDs. This
    second pass is used only when the first OCR result indicates an ERP reason
    table; it instructs the model to read by horizontal grid row, not by column.
    """
    if not _has_ai_capability("vision"):
        return None
    if mime_type == "image/heic":
        mime_type = "image/jpeg"
    # v3.17: root fix for row-shift/row-omission OCR.  Before asking Vision to
    # read the entire crowded Excel screenshot, locally slice visible row bands
    # and OCR each row strip.  This keeps ID and 原因 bound to the same row and
    # gives us a visual expected-row count for fail-closed validation.
    row_result = ocr_factory_reason_table_rows_openai(image_base64, mime_type=mime_type)
    if row_result:
        return row_result
    try:
        msgs = [
            {
                "role": "system",
                "content": (
                    "你是一個工廠 ERP / Excel 表格 OCR 引擎，只負責轉錄原文，不得翻譯。\n"
                    "目標表格通常有兩欄: ID 和 原因。\n"
                    "最重要規則:\n"
                    "1. 必須按照同一條水平格線逐列讀取: 左欄 ID 與右欄 原因 必須來自同一列。\n"
                    "2. 不可先讀完整 ID 欄再讀原因欄後自行配對；不可讓原因欄上移或下移。\n"
                    "3. 每一個看得到的資料列都要輸出；看不清楚的單一字元用 ?，看不清楚的原因用 ?。\n"
                    "4. 英數 ID 逐字 OCR，保留 7H/7G/7I/7B、A/B/C/D 等尾碼，不得自動校正。\n"
                    "5. 原因欄只輸出中文原文，例如 改端漆、補毛重、退火、倒角、削皮、拋光、併包、改包裝、改Tag、取樣。\n"
                    "6. 輸出格式只能是 compact table: 第一行 `ID | 原因`，下面每行 `<ID> | <原因>`。\n"
                    "7. 如果圖片不是 ID/原因 表格，輸出 NO_TABLE。"
                ),
            },
            {
                "role": "user",
                "content": [
                    {
                        "type": "image_url",
                        "image_url": {
                            "url": f"data:{mime_type};base64," + image_base64,
                            "detail": "high",
                        },
                    },
                    {
                        "type": "text",
                        "text": "請只轉錄 ID/原因 表格。逐列對齊，不翻譯，不要漏列。",
                    },
                ],
            },
        ]
        r = _vision_call(
            msgs,
            max_tokens=3000,
            cache_key=_build_cache_key(getattr(_tl, 'group_id', ''), "img", "txt", "ocr_factory_reason"),
            task_type="ocr",
        )
        track_tokens(r)
        result = (r.choices[0].message.content or "").strip()
        logger.info("[FactoryReasonOCR] strict raw result (%d chars): %s", len(result), result[:300])
        return _clean_ocr_status_bar(result).strip() if result else None
    except Exception as e:
        logger.warning("[FactoryReasonOCR] strict OCR failed: %s", e)
        return None


def ocr_image_openai(image_base64, mime_type="image/jpeg"):
    """Use OpenAI Vision to extract text from image. v3.8: model upgraded.
    
    v3.9.14: GPT-5 vision OCR 改良:
      - prompt 改為更明確的指令,避免 GPT-5 過度解讀回 NO_TEXT_FOUND
      - 失敗時詳細記錄 raw response,方便偵錯
    v3.9.17: 加 mime_type 參數 — 不能再寫死 jpeg,LINE 可能傳 PNG/HEIC
    """
    if not _has_ai_capability("vision"):
        return None
    # v3.9.17: HEIC OpenAI 不支援,改用 jpeg(雖然會失敗但至少 OpenAI 會給明確錯誤)
    if mime_type == "image/heic":
        logger.warning("[OCR] HEIC not supported by OpenAI, sending as jpeg (may fail)")
        mime_type = "image/jpeg"
    try:
        _factory_ocr_hint = factory_terminology_module.build_ocr_hint(
            GLOSSARY_LOOKUP if 'GLOSSARY_LOOKUP' in globals() else {},
            max_items=120,
        )
        msgs = [
                {
                    "role": "system",
                    "content": (
                        "你是一個 OCR 引擎。任務:把圖片中所有可見的訊息文字,逐字輸出。\n"
                        "規則:\n"
                        "1. **嚴格保留段落結構**:原文中的空行(段落分隔)用空行輸出;原文中的換行用換行輸出。\n"
                        "2. 不要加註解、不要翻譯、不要總結、不要編號\n"
                        "3. 中文、英文、數字、印尼文、日文都原樣輸出\n"
                        "3a. **表格 / Excel / ERP 截圖**:如果圖片是表格,請用 ` | ` 分隔欄位,每一列獨立一行輸出;欄位標題照原文輸出。必須依同一水平格線逐列配對,不可先讀整欄再自行配對。\n"
                        "3b. **ID / 料號 / 爐號 / TAG / 批號保護**:英數代碼、尺寸、數量、日期、站號都只做 OCR,不得翻譯、不得自動校正、不得補字。\n"
                        "    讀代碼時逐字辨認 8/3/6/5/S、0/O、1/I/L、B/8、A/4;真的看不清楚的單一字元用 ? 取代,不要猜。\n"
                        "3c. **ERP 原因欄保護**:若表格標題是 ID / 原因,標題必須輸出 `ID | 原因`,不得改成爐號、料號、Nomor Material、Nomor Tungku。\n"
                        "    原因欄內容如 削皮/拋光/倒角/退火/改端漆/補毛重/改Tag/取樣/併包/改包裝 只做 OCR 原文輸出,不得翻譯。\n"
                        "4. **忽略手機螢幕介面元素**:狀態列(時間 / 4G / 5G / WiFi / 電量百分比 / 訊號)、\n"
                        "   未讀數(99+)、輸入框文字(輸入訊息)、鍵盤按鍵(注音、空白鍵、換行等)、\n"
                        "   應用程式名稱、底部 navigation bar — 這些都不要輸出\n"
                        "5. 只輸出訊息內容、貼文、文件、招牌、文章等實質文字\n"
                        "6. 如果圖片中真的完全沒有任何訊息文字,才輸出 NO_TEXT\n"
                        + (_factory_ocr_hint if _factory_ocr_hint else "")
                    )
                },
                {
                    "role": "user",
                    "content": [
                        {
                            "type": "image_url",
                            "image_url": {
                                "url": f"data:{mime_type};base64," + image_base64,
                                "detail": "high"
                            }
                        },
                        {
                            "type": "text",
                            "text": "請輸出這張圖中的訊息文字內容(忽略手機介面元素),嚴格保留段落結構。"
                        }
                    ]
                }
            ]
        r = _vision_call(msgs, max_tokens=2000,
                         cache_key=_build_cache_key(getattr(_tl, 'group_id', ''),
                                                    "img", "txt", "ocr"))
        track_tokens(r)
        result = (r.choices[0].message.content or "").strip()
        # v3.9.14: 詳細 logging
        logger.info("[OCR] raw result (%d chars): %s", len(result), result[:200])
        # v3.9.14: 多種「沒文字」回應的辨識
        no_text_markers = ("NO_TEXT_FOUND", "NO_TEXT", "沒有文字", "no text",
                           "圖片中沒有", "圖中沒有")
        result_lower = result.lower()
        if not result:
            logger.warning("[OCR] empty result")
            return None
        # 結果過短且看起來像「沒文字」回應
        if len(result) < 30:
            for marker in no_text_markers:
                if marker.lower() in result_lower:
                    logger.info("[OCR] detected no-text marker: %s", marker)
                    return None
        # v3.9.27: 後處理 — 清掉殘留的狀態列文字(雙重保險)
        result = _clean_ocr_status_bar(result)
        # v3.40: normalize only lossless OCR spacing around factory organization
        # units (e.g. 一 股 股 長 -> 一股股長) before language detection and the
        # shared terminology matcher.  No characters or operational facts are guessed.
        result = factory_terminology_module.normalize_ocr_text(result)
        # 清完後若空,當沒文字
        if not result.strip():
            logger.info("[OCR] all content cleaned as status bar")
            return None

        # v3.16: ERP ID/原因 表格需要行級 OCR。通用 OCR 常會漏讀中間幾列或
        # 先讀整欄再配對，造成「倒角/削皮/拋光」套到錯誤 ID。偵測到此類
        # 表格時加跑一次 row-grid OCR；只接受仍為中文原文且列數不倒退的結果。
        if _should_run_factory_reason_table_ocr(result):
            strict_result = ocr_factory_reason_table_openai(image_base64, mime_type=mime_type)
            expected_rows = getattr(_tl, 'factory_reason_image_expected_rows', 0)
            safety_issue = _factory_reason_ocr_strict_safety_issue(result, strict_result, expected_rows)
            if not safety_issue and _strict_factory_reason_ocr_is_better(result, strict_result):
                logger.info(
                    "[FactoryReasonOCR] using strict row-grid OCR generic_rows=%d strict_rows=%d expected_rows=%s",
                    _factory_reason_ocr_row_count(result),
                    _factory_reason_ocr_row_count(strict_result),
                    expected_rows,
                )
                return strict_result
            logger.warning(
                "[FactoryReasonOCR] fail-closed; no generic fallback issue=%s generic_rows=%d strict_rows=%d expected_rows=%s",
                safety_issue or "strict_not_better",
                _factory_reason_ocr_row_count(result),
                _factory_reason_ocr_row_count(strict_result),
                expected_rows,
            )
            try:
                _event_log_write("factory_reason_ocr_fail_closed", {
                    "group_id": getattr(_tl, 'group_id', '') or '',
                    "issue": safety_issue or "strict_not_better",
                    "generic_rows": _factory_reason_ocr_row_count(result),
                    "strict_rows": _factory_reason_ocr_row_count(strict_result),
                    "expected_rows": expected_rows,
                    "generic_preview": (result or '')[:300],
                    "strict_preview": (strict_result or '')[:300],
                })
            except Exception:
                pass
            # Availability policy: keep the generic OCR transcript and mark it
            # non-cacheable instead of emitting a user-visible stop/warning.
            # The translation layer will still preserve IDs and quantities and
            # the diagnostic remains available to administrators.
            try:
                _tl.factory_reason_ocr_degraded = safety_issue or "strict_not_better"
            except Exception:
                pass
            return result
        return result
    except Exception as e:
        logger.exception("[OCR] OpenAI Vision OCR error: %s", e)
        return None


# ─── v3.9.39: 場景描述 + 媒體上下文儲存(根治 rusak 語意歧義)──────────
# 每張圖/影片進來,除了 OCR 抽字之外,額外做「主體+異常」場景描述。
# 文字訊息翻譯前會去查近期同人媒體場景,把場景注入 hint。
# 這樣 LLM 翻譯 "I15 rusak" 時就知道剛剛影片是「操作盤被燒毀」→ 譯成「損壞」。
#
# ⚠️ 跨 worker 共享:用 disk + file lock,符合 Render gunicorn 多 worker 架構
# (in-memory dict 會讓 A worker 寫 / B worker 讀不到,75%+ 失效率)。
# 模式照 _pending_img_set / _pending_img_pop(L440+)的 atomic write+rename。

def _media_ctx_path():
    """選擇可寫的暫存路徑 — 同 Render persistent disk"""
    for d in ("/var/data", "/data", "/tmp"):
        if os.path.isdir(d) and os.access(d, os.W_OK):
            return os.path.join(d, "media_context.json")
    return "media_context.json"


_MEDIA_CTX_FILE = None


def _load_media_ctx():
    """讀媒體場景檔。每次讀都過濾掉過期(TTL=MEDIA_CONTEXT_TTL)。"""
    global _MEDIA_CTX_FILE
    if _MEDIA_CTX_FILE is None:
        _MEDIA_CTX_FILE = _media_ctx_path()
    try:
        if not os.path.exists(_MEDIA_CTX_FILE):
            return {}
        with open(_MEDIA_CTX_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        if not isinstance(data, dict):
            return {}
        # 過濾過期 + 清理結構
        now = time.time()
        cleaned = {}
        for gid, users in data.items():
            if not isinstance(users, dict):
                continue
            user_dict = {}
            for uid, entries in users.items():
                if not isinstance(entries, list):
                    continue
                fresh = []
                for e in entries:
                    if isinstance(e, list) and len(e) == 3 and now - e[0] < MEDIA_CONTEXT_TTL:
                        fresh.append(e)
                if fresh:
                    user_dict[uid] = fresh[-MEDIA_CONTEXT_PER_USER:]
            if user_dict:
                cleaned[gid] = user_dict
        return cleaned
    except Exception:
        return {}


def _save_media_ctx(data):
    """原子寫入 — write+rename"""
    global _MEDIA_CTX_FILE
    if _MEDIA_CTX_FILE is None:
        _MEDIA_CTX_FILE = _media_ctx_path()
    try:
        tmp = _MEDIA_CTX_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(data, f)
        os.replace(tmp, _MEDIA_CTX_FILE)
        return True
    except Exception as e:
        try:
            logger.warning("[media_ctx] save failed: %s", e)
        except Exception:
            pass
        return False


def describe_scene_for_context(image_base64, mime_type="image/jpeg"):
    """以視覺方式描述工廠現場場景(主體+異常),供翻譯上下文使用。

    v3.9.39 雙系統相容:不直接檢查 oai,而是檢查「整體能否做 vision」
      - active=openai                    → 走 OpenAI(gpt-5.6-luna)
      - active=anthropic + use_claude=T  → 走 Claude vision(~$0.001-0.005)
      - active=anthropic + use_claude=F  → 優先走其他視覺 provider；失敗時仍由統一接力層處理
    走 _vision_call(task_type="scene") 拿到的是低 verbosity + 小 token budget。
    失敗或無法判讀 → 回 ""(不影響翻譯主流程)。
    """
    if not _has_ai_capability("vision"):
        return ""
    try:
        msgs = [
            {
                "role": "system",
                "content": (
                    "你是工廠現場視覺判讀。看圖,用一句話客觀描述「主體 + 狀態」:\n"
                    "1. 主體分類:設備類(機台/操作盤/控制盤/工具/儀表/管路/電線/感測器/按鈕/馬達)、"
                    "料件類(棒材/物料/包裝/料件)、人員、文件、其他\n"
                    "2. 狀態描述:正常/破損/燒毀/裂痕/凹陷/卡料/泄漏/熔斷/變形 等\n"
                    "規則:\n"
                    "- 嚴格 25 字內\n"
                    "- 只描述看得見的,不推測\n"
                    "- 用工廠術語(操作盤、按鈕、棒材、料件、機台)\n"
                    "- 看不出來 → 輸出「無法判讀」\n"
                    "範例:\n"
                    "「操作盤,綠色按鈕被燒焦」\n"
                    "「機台前棒材一捆,後端有刮痕」\n"
                    "「電線接頭,絕緣外皮裂開」\n"
                    "「控制盤,液晶顯示熄滅」\n"
                    "「料件包裝,綁帶鬆脫」"
                ),
            },
            {
                "role": "user",
                "content": [
                    {
                        "type": "image_url",
                        "image_url": {
                            "url": f"data:{mime_type};base64," + image_base64,
                            # detail=low 只對 OpenAI 有效;Claude path 由 ai_provider
                            # 自動忽略此欄位(Claude 自有 image 處理)
                            "detail": "low",
                        },
                    },
                    {"type": "text", "text": "請用 25 字內描述「主體+狀態」。"},
                ],
            },
        ]
        # task_type="scene" → verbosity=low, max_completion_tokens 緊縮
        # reasoning_override="minimal" → 場景描述不需要 reasoning,直出
        r = _vision_call(msgs, max_tokens=300,
                         cache_key=_build_cache_key(getattr(_tl, 'group_id', ''),
                                                    "scene", "ctx", "desc"),
                         task_type="scene",
                         reasoning_override="minimal")
        result = (r.choices[0].message.content or "").strip()
        # 清掉常見冗詞和引號
        result = re.sub(r'^[「『"\']+', '', result)
        result = re.sub(r'[」』"\']+$', '', result)
        result = result.strip()
        if not result or "無法判讀" in result:
            return ""
        # 安全上限(避免 LLM 不聽 25 字限制)
        return result[:60]
    except Exception as e:
        logger.warning("[scene_describe] failed: %s", e)
        return ""


def store_media_scene(group_id, user_id, msg_id, scene_summary):
    """把場景描述存進 disk(跨 worker 共享),供下一則文字翻譯查用。

    用 file lock 保 read-modify-write 原子;失敗 fallback 為 best-effort 非原子。
    """
    if not group_id or not user_id or not scene_summary:
        return
    global _MEDIA_CTX_FILE
    if _MEDIA_CTX_FILE is None:
        _MEDIA_CTX_FILE = _media_ctx_path()
    lock_path = _MEDIA_CTX_FILE + ".lock"
    entry = [time.time(), msg_id, scene_summary]
    try:
        with _file_lock(lock_path):
            data = _load_media_ctx()
            g = data.setdefault(group_id, {})
            u = g.setdefault(user_id, [])
            u.append(entry)
            now = time.time()
            fresh = [e for e in u if isinstance(e, list) and len(e) == 3 and now - e[0] < MEDIA_CONTEXT_TTL]
            g[user_id] = fresh[-MEDIA_CONTEXT_PER_USER:]
            _save_media_ctx(data)
    except Exception:
        # lock 失敗 → 非原子寫入(degraded)
        try:
            data = _load_media_ctx()
            g = data.setdefault(group_id, {})
            u = g.setdefault(user_id, [])
            u.append(entry)
            now = time.time()
            fresh = [e for e in u if isinstance(e, list) and len(e) == 3 and now - e[0] < MEDIA_CONTEXT_TTL]
            g[user_id] = fresh[-MEDIA_CONTEXT_PER_USER:]
            _save_media_ctx(data)
        except Exception:
            pass
    logger.info("[media_ctx] stored: group=%s user=%s scene=%r",
                (group_id or "")[-8:], (user_id or "")[-6:], scene_summary[:30])


def get_recent_media_scene(group_id, user_id):
    """從 disk 查同人同群最近 TTL 內的場景描述。沒有就回 ""。

    read-only,免 lock(write 用 atomic rename 確保讀到完整檔)。
    """
    if not group_id or not user_id:
        return ""
    data = _load_media_ctx()
    g = data.get(group_id, {})
    u = g.get(user_id, [])
    if not u:
        return ""
    now = time.time()
    fresh = [e for e in u if isinstance(e, list) and len(e) == 3 and now - e[0] < MEDIA_CONTEXT_TTL]
    if not fresh:
        return ""
    # 回最新一筆的 scene_summary
    return fresh[-1][2]


WORK_ORDER_MEDIA_SCENE_PREFIX = "【工單照片】"
PENDING_IMAGE_MEDIA_SCENE_PREFIX = "【圖片待辨識】"


def store_pending_image_media_context(group_id, user_id, msg_id):
    """Persist an image-arrival marker before background OCR starts.

    This is intentionally content-free.  It exists only so a following terse
    measurement message can distinguish "no photo" from "photo classification
    is still in flight" across Gunicorn workers.
    """
    store_media_scene(
        group_id, user_id, msg_id,
        PENDING_IMAGE_MEDIA_SCENE_PREFIX + "等待 OCR/場景分類",
    )


def store_work_order_media_context(group_id, user_id, msg_id):
    """Promote confirmed OCR work-order classification into shared media context."""
    store_media_scene(
        group_id, user_id, msg_id,
        WORK_ORDER_MEDIA_SCENE_PREFIX + "製造指示書／訂單資訊",
    )


def get_recent_media_context_state(group_id, user_id):
    """Return the latest shared media state without exposing guessed content."""
    scene = get_recent_media_scene(group_id, user_id)
    if not isinstance(scene, str) or not scene:
        return "none"
    if scene.startswith(WORK_ORDER_MEDIA_SCENE_PREFIX):
        return "work_order"
    if scene.startswith(PENDING_IMAGE_MEDIA_SCENE_PREFIX):
        return "pending"
    return "other"


def get_recent_pending_image_media_context(group_id, user_id):
    return get_recent_media_context_state(group_id, user_id) == "pending"


def get_recent_work_order_media_context(group_id, user_id):
    """True only if the user's latest fresh media item is a confirmed work order.

    Looking only at the newest entry prevents an older work-order photo from
    leaking into a later unrelated image/text exchange within the TTL window.
    """
    return get_recent_media_context_state(group_id, user_id) == "work_order"


def ocr_and_translate_image(image_base64, tgt_lang):
    """Compatibility wrapper: OCR first, then use the standard text pipeline.

    Image translation must never maintain a separate factory vocabulary prompt.
    OCR extracts source text only; ``translate()`` then applies the same indexed
    terminology, factory knowledge, TM integrity checks and quality gate used by
    ordinary text messages.
    """
    extracted = ocr_image_openai(image_base64, mime_type="image/jpeg")
    if not extracted:
        return None, None
    src_lang = detect_language(extracted)
    if not src_lang:
        return None, "language_detection_failed"
    actual_target = tgt_lang if src_lang == "zh" else "zh"
    previous_from_image = getattr(_tl, "from_image_ocr", False)
    try:
        _tl.from_image_ocr = True
        result = translate(extracted, src_lang, actual_target)
    except Exception as exc:
        logger.exception("OCR standard-pipeline translation failed: %s", exc)
        return None, str(exc)
    finally:
        _tl.from_image_ocr = previous_from_image
    if not result:
        return None, "translation_failed"
    return result, None


# ─── v3.12: 圖片翻譯標準管線根治 ──────────────────────────────
# 圖片處理的邊界責任只有「OCR 原文」。OCR 後一律呼叫 translate() 標準文字管線,
# 讓使用者提供的工廠用語、glossary、factory context、quality gate、TM/cache 後處理
# 全部生效。禁止另開圖片直譯 prompt 繞過標準管線。

def detect_image_mime(raw_bytes):
    """v3.9.29: 從 magic bytes 偵測圖片格式。
    回傳 'image/jpeg', 'image/png', 'image/gif', 'image/webp', 'image/heic' 之一。
    無法辨識時回 'image/jpeg'(safest fallback)。
    
    v3.9.29 修正:之前 hard-code 12 bytes 最低長度,導致 8-byte 的 PNG signature
    跟 6-byte 的 GIF 被當作未知。改成依格式分別判斷。
    """
    if not raw_bytes:
        return "image/jpeg"
    # JPEG: 3 bytes
    if len(raw_bytes) >= 3 and raw_bytes[:3] == b'\xff\xd8\xff':
        return "image/jpeg"
    # PNG: 8 bytes
    if len(raw_bytes) >= 8 and raw_bytes[:8] == b'\x89PNG\r\n\x1a\n':
        return "image/png"
    # GIF: 6 bytes
    if len(raw_bytes) >= 6 and raw_bytes[:6] in (b'GIF87a', b'GIF89a'):
        return "image/gif"
    # WebP: 12 bytes (RIFF...WEBP)
    if len(raw_bytes) >= 12 and raw_bytes[:4] == b'RIFF' and raw_bytes[8:12] == b'WEBP':
        return "image/webp"
    # HEIC/HEIF: 12 bytes (offset 4)
    if len(raw_bytes) >= 12 and raw_bytes[4:12] in (
        b'ftypheic', b'ftypheix', b'ftyphevc', b'ftypheim',
        b'ftypheis', b'ftyphevm', b'ftyphevs', b'ftypmif1'
    ):
        logger.warning("[Vision] HEIC/HEIF image detected, OpenAI may reject it")
        return "image/heic"
    logger.warning("[Vision] unknown image format, first bytes: %s",
                   raw_bytes[:16].hex() if raw_bytes else "<empty>")
    return "image/jpeg"  # safest fallback


def download_line_image(message_id):
    """Download image from LINE and return (base64_string, raw_bytes)."""
    try:
        with ApiClient(configuration) as api_client:
            blob_api = MessagingApiBlob(api_client)
            content = blob_api.get_message_content(message_id)
            # v3.9.17: 確保 content 是 bytes(不是 bytearray 或其他)
            if isinstance(content, bytearray):
                content = bytes(content)
            elif not isinstance(content, bytes):
                # 如果是 file-like object,讀出來
                if hasattr(content, 'read'):
                    content = content.read()
                else:
                    content = bytes(content)
            img_base64 = base64.b64encode(content).decode("utf-8")
            return img_base64, content
    except Exception as e:
        logger.error("LINE image download error: %s", e)
        return None, None


def download_line_audio(message_id):
    """Download audio from LINE and return bytes."""
    try:
        with ApiClient(configuration) as api_client:
            blob_api = MessagingApiBlob(api_client)
            content = blob_api.get_message_content(message_id)
            return content
    except Exception as e:
        logger.error("LINE audio download error: %s", e)
        return None


# v3.8: STT model upgrade. whisper-1 (2022) → gpt-4o-transcribe (2025).
# Lower WER, better noise robustness, semantic VAD, supports prompt hint.
# Critical for noisy factory-floor recordings with Indonesian-accented speech.
STT_MODEL = os.environ.get("STT_MODEL", "gpt-4o-transcribe")  # or gpt-4o-mini-transcribe (cheaper, slightly less accurate)
STT_FALLBACK_MODEL = "whisper-1"  # auto-fallback if primary unavailable

# Factory vocabulary hint passed to STT to bias recognition toward
# domain-specific terms, station numbers, and known names. Keep <224 tokens.
STT_PROMPT_HINT = (
    "工廠語音記錄。常見詞彙：無心研磨、研磨、拋光、削皮、退火、酸洗、冷抽、矯直、精整、"
    "棒鋼、盤元、不鏽鋼、削皮棒、冷精棒、料號、爐號、鋼種、混料、出貨、來料、"
    "400站、401站、420站、470站、480站、490站、801站、UT、PMI、AP、OL、"
    "工單、掛單、放行、過帳、退庫、入庫、無主、改制、去化、"
    "早班、夜班、中班、加班、點名、班股、堆高機、天車、"
    "Bahasa Indonesia istilah pabrik: as, kopel, patah, bengkok, retak, aus, bocor, "
    "macet, bearing, rantai, sabuk, baut, mur, kawat, motor, pompa, gerinda, las, bor, "
    "shift pagi, shift malam, lembur, work order."
)


def transcribe_audio_openai(audio_bytes, suffix=".m4a"):
    """Use the configured OpenAI transcription model with format-aware uploads.

    LINE voice messages are normally M4A, while the LIFF browser recorder commonly
    sends WebM or MP4.  The temporary filename extension must match the real
    container so the transcription endpoint can decode it reliably.

    v3.8: Use gpt-4o-transcribe (or fallback to whisper-1) to transcribe audio.

    Improvements over the old whisper-1 path:
      * gpt-4o-transcribe / gpt-4o-mini-transcribe have noticeably lower WER on
        noisy environments and accented speech (factory floor + Indonesian accent).
      * `prompt` parameter biases the model toward our factory vocabulary,
        station numbers, and Indonesian mechanical terms.
      * Auto-fallback to whisper-1 if the new model isn't available on the account.
    """
    if not oai:
        return None
    allowed_suffixes = {".m4a", ".mp4", ".mp3", ".mpeg", ".mpga", ".wav", ".webm"}
    suffix = (suffix or ".m4a").strip().lower()
    if not suffix.startswith("."):
        suffix = "." + suffix
    if suffix not in allowed_suffixes:
        suffix = ".m4a"
    primary = STT_MODEL
    last_err = None
    for attempt_model in (primary, STT_FALLBACK_MODEL):
        if attempt_model == STT_FALLBACK_MODEL and primary == STT_FALLBACK_MODEL:
            break  # already tried as primary
        try:
            with tempfile.NamedTemporaryFile(suffix=suffix, delete=True) as tmp:
                tmp.write(audio_bytes)
                tmp.flush()
                tmp.seek(0)
                kwargs = {
                    "model": attempt_model,
                    "file": tmp,
                    # v3.9.30c B16 修補: STT 也加 30 秒 timeout(其他 OpenAI 呼叫都有,只有這個沒)
                    "timeout": 30,
                }
                # Only the new gpt-4o-transcribe family accepts the `prompt`
                # vocabulary-bias parameter via the standard transcriptions endpoint.
                if attempt_model.startswith("gpt-4o"):
                    kwargs["prompt"] = STT_PROMPT_HINT
                r = ai.audio.transcriptions.create(**kwargs)
                # v3.9.30c B16 修補: 防 r 為 None / r.text 為 None
                if r is None:
                    logger.warning("STT model %s returned None", attempt_model)
                    continue
                text = (getattr(r, 'text', None) or "").strip() or None
                if attempt_model != primary:
                    logger.warning("STT fell back from %s to %s", primary, attempt_model)
                return text
        except Exception as e:
            last_err = e
            logger.warning("STT model %s failed: %s", attempt_model, e)
            continue
    logger.error("OpenAI STT error (all models failed): %s", last_err)
    return None


def make_notice(content, target="id"):
    tgt_text = translate(content, "zh", target)
    if not tgt_text:
        tgt_text = "(translation failed)"
    sep = "=" * 18
    lines = []
    lines.append("\U0001f4e2 \u516c\u544a / Pengumuman")
    lines.append(sep)
    lines.append("\U0001f1f9\U0001f1fc " + content)
    lines.append(LANG_FLAGS.get(target, "") + " " + tgt_text)
    lines.append(sep)
    return "\n".join(lines)


def make_notice_from_other(content, src, target="zh"):
    zh_text = translate(content, src, "zh")
    if not zh_text:
        zh_text = "(translation failed)"
    sep = "=" * 18
    lines = []
    lines.append("\U0001f4e2 \u516c\u544a / Pengumuman")
    lines.append(sep)
    lines.append("\U0001f1f9\U0001f1fc " + zh_text)
    lines.append(LANG_FLAGS.get(src, "") + " " + content)
    lines.append(sep)
    return "\n".join(lines)


