def handle_lang_command(text, group_id):
    """v3.10: 真正可用的 /lang 命令
    用法:
      /lang               → 顯示當前設定
      /lang id            → 設單一語言
      /lang id,th         → 設多語廣播
      /lang id th hi      → 同上,空白分隔也行
    """
    if not group_id:
        return "⚠️ /lang 只能在群組使用 / Hanya di grup"

    parts = text.strip().split(None, 1)
    arg = parts[1].strip() if len(parts) >= 2 else ""

    try:
        cur = get_group_target_langs(group_id)
    except NameError:
        cur = [group_target_lang.get(group_id, "id")]

    # 無參數 → 顯示當前 + 用法
    if not arg:
        cur_display = " + ".join(
            "{} {}".format(LANG_FLAGS.get(l, ""), LANG_NAMES_ZH.get(l, l)) for l in cur)
        return ("📋 當前翻譯語言 / Bahasa saat ini:\n"
                "中文 ⇄ " + cur_display + "\n\n"
                "用法 / Cara pakai:\n"
                "  /lang id            單語 印尼\n"
                "  /lang id,th         雙語 印尼+泰\n"
                "  /lang id,th,hi      三語\n\n"
                "可用代碼 / Kode tersedia:\n"
                "  id (印尼) th (泰) hi (印地)\n"
                "  vi (越南) ja (日) ko (韓) en (英)\n\n"
                "💡 可改用 /liff 圖形化設定")

    # 解析語言代碼 (逗號或空白分隔) - 用既有 module-level re
    codes = [c.strip().lower() for c in re.split(r'[,\s\u3000]+', arg) if c.strip()]
    valid = []
    invalid = []
    for c in codes:
        if c in VALID_TARGETS and c != "zh" and c not in valid:
            valid.append(c)
        elif c not in VALID_TARGETS or c == "zh":
            invalid.append(c)

    if invalid:
        return ("⚠️ 不支援的語言代碼 / Kode tidak didukung: " + ", ".join(invalid) +
                "\n可用 / Tersedia: id, th, hi, vi, ja, ko, en")
    if not valid:
        return "⚠️ 請輸入至少 1 種語言 / Minimal 1 bahasa"
    if len(valid) > 5:
        return "⚠️ 最多 5 種語言 / Maks 5 bahasa"

    try:
        set_group_target_langs(group_id, valid)
        new_cur = get_group_target_langs(group_id)
    except NameError:
        # fallback: 寫單一目標語言 (legacy)
        group_target_lang[group_id] = valid[0]
        try:
            save_settings()
        except Exception:
            pass
        new_cur = [valid[0]]

    display_zh = " + ".join(
        "{} {}".format(LANG_FLAGS.get(l, ""), LANG_NAMES_ZH.get(l, l)) for l in new_cur)
    display_id = " + ".join(LANG_NAMES.get(l, l) for l in new_cur)
    return ("✅ 翻譯語言已設為:中文 ⇄ " + display_zh + "\n"
            "✅ Bahasa diatur: Mandarin ⇄ " + display_id)


def handle_qry_command(text):
    """Handle /qry <customer_name> command to lookup storage area."""
    parts = text.strip().split(None, 1)
    if len(parts) < 2:
        return "⚠️ 請輸入客戶名稱 / Masukkan nama pelanggan\n範例 / Contoh: /qry ABE\n範例 / Contoh: /qry 佳東"
    query = parts[1].strip()
    # Try exact match first
    entries = STORAGE_LOOKUP.get(query)
    # Try case-insensitive match
    if not entries:
        for key in STORAGE_LOOKUP:
            if key.lower() == query.lower():
                entries = STORAGE_LOOKUP[key]
                query = key
                break
    # Try partial match
    if not entries:
        matches = [k for k in STORAGE_LOOKUP if query.lower() in k.lower() or query in k]
        if len(matches) == 1:
            query = matches[0]
            entries = STORAGE_LOOKUP[query]
        elif len(matches) > 1:
            result = "🔍 找到多筆符合 / Beberapa hasil ditemukan:\n"
            for m in matches[:10]:
                result += "  • " + m + "\n"
            if len(matches) > 10:
                result += "  ...(共 / Total " + str(len(matches)) + " 筆)\n"
            result += "\n請輸入完整客戶名稱 / Masukkan nama lengkap"
            return result
    if not entries:
        return "❌ 找不到客戶 / Pelanggan tidak ditemukan: " + query + "\n請確認名稱是否正確 / Mohon periksa nama"
    # Build response
    lines = []
    lines.append("📦 " + query + " 儲區查詢 / Cek gudang")
    lines.append("=" * 18)
    for length, area in entries:
        zh = format_length_zh(length)
        lines.append(zh + " \u2192 " + area)
    lines.append("=" * 18)
    return "\n".join(lines)


def handle_pkg_command(text):
    """Handle /pkg <code> command to lookup packaging info."""
    parts = text.strip().split(None, 1)
    if len(parts) < 2:
        return (
            "⚠️ 請輸入包裝碼 / Masukkan kode kemasan\n"
            "範例 / Contoh: /pkg U\n"
            "範例 / Contoh: /pkg G"
        )
    query = parts[1].strip()
    query_upper = query.upper()
    if not PACKAGING_LOOKUP:
        return "⚠️ 包裝碼資料尚未上傳\nData kode kemasan belum diupload"
    # Try exact match (case-insensitive)
    entry = PACKAGING_LOOKUP.get(query) or PACKAGING_LOOKUP.get(query_upper)
    matched_key = query if PACKAGING_LOOKUP.get(query) else query_upper
    if not entry:
        for k in PACKAGING_LOOKUP:
            if k.upper() == query_upper:
                entry = PACKAGING_LOOKUP[k]
                matched_key = k
                break
    # Try partial match
    if not entry:
        matches = [k for k in PACKAGING_LOOKUP if query_upper in k.upper()]
        if len(matches) == 1:
            matched_key = matches[0]
            entry = PACKAGING_LOOKUP[matched_key]
        elif len(matches) > 1:
            result = "🔍 找到多筆符合 / Beberapa hasil ditemukan:\n"
            for m in matches[:15]:
                result += "  • " + m + "\n"
            return result
    if not entry:
        return "❌ 找不到包裝碼 / Kode kemasan tidak ditemukan: " + query
    # Build response - show specific fields in order
    # Match Excel headers by keyword → display label
    PKG_DISPLAY = [
        ("簡稱",       ["簡稱"]),
        ("詳細包裝方式", ["詳細包裝", "包裝方式說明", "包裝方式"]),
        ("內包裝",     ["內包裝"]),
        ("外包裝",     ["外包裝"]),
        ("固定繩",     ["固定繩", "固定"]),
    ]
    lines = []
    lines.append("📦 包裝碼 / Kode kemasan: " + matched_key)
    lines.append("=" * 20)
    if isinstance(entry, dict):
        for display_label, keywords in PKG_DISPLAY:
            # Find matching field in entry
            for field_name, field_val in entry.items():
                if field_val and any(kw in field_name for kw in keywords):
                    lines.append(display_label + ": " + str(field_val))
                    break
    elif isinstance(entry, str):
        lines.append(entry)
    lines.append("=" * 20)
    return "\n".join(lines)


def get_display_name(group_id, user_id):
    """Get the author's LINE display name without exposing raw user IDs.

    Group, room and direct-profile APIs are tried in order because ``group_id``
    may actually be a room ID or a DM target in shared translation paths.
    Successful lookups are cached for sender-name and sender-avatar modes.
    """
    if not user_id:
        return None
    if group_id in group_user_names and user_id in group_user_names[group_id]:
        return group_user_names[group_id][user_id]

    profile = None
    try:
        with ApiClient(configuration) as api_client:
            api = MessagingApi(api_client)
            if group_id:
                try:
                    profile = api.get_group_member_profile(group_id, user_id)
                except Exception:
                    try:
                        profile = api.get_room_member_profile(group_id, user_id)
                    except Exception:
                        profile = None
            if profile is None:
                try:
                    profile = api.get_profile(user_id)
                except Exception:
                    profile = None
    except Exception as e:
        logger.debug("Failed to create LINE profile client for %s: %s", user_id, e)

    if profile is None:
        logger.warning("Failed to get display name for %s", user_id)
        return None

    name = str(getattr(profile, 'display_name', '') or '').strip()
    lang = getattr(profile, 'language', None)
    pic = str(getattr(profile, 'picture_url', '') or '').strip()
    if name and group_id:
        group_user_names.setdefault(group_id, {})[user_id] = name
    if lang and user_id not in user_languages:
        user_languages[user_id] = lang
        logger.info("User %s language: %s", name or "(unknown)", lang)
    if pic.startswith("https://"):
        user_pictures[user_id] = pic
    return name or None


def get_user_picture_url(chat_id, user_id):
    """Return the LINE profile picture URL for a group/room member.

    The URL is cached per user.  A cached display name alone is not enough:
    older settings may contain names but no picture URLs, so this function
    independently fills the avatar cache.  Group, room, and direct-profile
    APIs are tried in that order and all failures are non-fatal.
    """
    if not user_id:
        return ""
    cached = str(user_pictures.get(user_id, "") or "").strip()
    if cached.startswith("https://"):
        return cached

    profile = None
    try:
        with ApiClient(configuration) as api_client:
            api = MessagingApi(api_client)
            if chat_id:
                try:
                    profile = api.get_group_member_profile(chat_id, user_id)
                except Exception:
                    try:
                        profile = api.get_room_member_profile(chat_id, user_id)
                    except Exception:
                        profile = None
            if profile is None:
                try:
                    profile = api.get_profile(user_id)
                except Exception:
                    profile = None
    except Exception as e:
        logger.debug("Failed to create LINE profile client for %s: %s", user_id, e)

    if profile is None:
        return ""

    pic = str(getattr(profile, "picture_url", "") or "").strip()
    name = str(getattr(profile, "display_name", "") or "").strip()
    lang = getattr(profile, "language", None)
    if pic.startswith("https://"):
        user_pictures[user_id] = pic
    if name and chat_id:
        group_user_names.setdefault(chat_id, {})[user_id] = name
    if lang and user_id not in user_languages:
        user_languages[user_id] = lang
    return pic if pic.startswith("https://") else ""


def record_user_name(group_id, user_id):
    """Record user display name and avatar (best effort)."""
    if not group_id or not user_id:
        return
    has_name = user_id in group_user_names.get(group_id, {})
    has_picture = str(user_pictures.get(user_id, "") or "").startswith("https://")
    if not has_name:
        get_display_name(group_id, user_id)
    if not has_picture:
        get_user_picture_url(group_id, user_id)


def find_user_by_name(group_id, name_query):
    """Find user_id by display name (partial match). Returns list of (user_id, display_name)."""
    if group_id not in group_user_names:
        return []
    matches = []
    query_lower = name_query.lower().strip()
    for uid, dname in group_user_names[group_id].items():
        if query_lower == dname.lower() or query_lower in dname.lower() or dname.lower() in query_lower:
            matches.append((uid, dname))
    return matches


def mark_translation_wrong(group_id, correct_translation="", add_to_examples=True,
                           offset=1, entry_id=None):
    """v3.4: Mark a translation as wrong with multiple selection modes.

    Selection priority:
      1. If entry_id provided → find that exact entry (works across days)
      2. Else: pick the Nth most recent translation in this group (offset=1 means latest)

    Args:
      group_id: LINE group id (limits search to this group's translations)
      correct_translation: optional human-corrected version, added as training example
      add_to_examples: whether to append to custom_translation_examples
      offset: 1-based index from the most recent (1=latest, 2=2nd latest, ...)
      entry_id: exact translation_log entry id

    Returns: (ok: bool, info_text: str)
    """
    target = None
    if entry_id:
        for entry in translation_log:
            if entry.get("id") == entry_id:
                target = entry
                break
        if not target:
            return False, f"找不到指定 ID 的翻譯記錄：{entry_id}"
    else:
        # Walk most-recent-first, count down to the Nth in this group
        n = max(1, int(offset or 1))
        seen = 0
        for entry in reversed(translation_log):
            if not group_id or entry.get("group_id") == group_id:
                seen += 1
                if seen == n:
                    target = entry
                    break
        if not target:
            return False, f"找不到第 {n} 筆翻譯記錄。可能剛重啟，或翻譯日誌不夠長。"

    target["marked_wrong"] = True
    target["manual_marked_wrong"] = True
    if correct_translation:
        target["correct_translation"] = correct_translation
        src_lang = str(target.get("src_lang") or "zh").lower()
        tgt_lang = str(target.get("tgt_lang") or ("id" if src_lang == "zh" else "zh")).lower()
        source_text = str(target.get("src") or "").strip()
        original_tgt = str(target.get("tgt") or "").strip()
        correction_reason = "人工標記翻譯錯誤；以修正版為準，並泛化到相近語意句。"

        # One correction path, not four disconnected stores: /wrong now writes
        # the contrastive record, exact TM and vector TM through Active Learning.
        # Failure is non-fatal because the local custom case is still persisted.
        try:
            _al_result = al_module.submit_correction(
                src_text=source_text,
                original_tgt=original_tgt,
                corrected_tgt=correct_translation,
                src_lang=src_lang,
                tgt_lang=tgt_lang,
                correction_reason=correction_reason,
                corrected_by="line_wrong_command",
                group_id=target.get("group_id") or group_id,
            )
            target["active_learning_correction_id"] = _al_result.get("correction_id") if isinstance(_al_result, dict) else None
            translation_casebook_module.invalidate_active_cache()
        except Exception as _al_exc:
            logger.warning("[/wrong] active-learning persistence failed: %s", _al_exc)

        if add_to_examples and (src_lang, tgt_lang) in (("zh", "id"), ("id", "zh")):
            direction = "zh2id" if (src_lang, tgt_lang) == ("zh", "id") else "id2zh"
            new_ex = {
                "zh": source_text if direction == "zh2id" else correct_translation,
                "id": correct_translation if direction == "zh2id" else source_text,
                "dir": direction,
                "bad_id" if direction == "zh2id" else "bad_zh": original_tgt,
                "reason": correction_reason,
                "origin": "human_correction",
                "case_id": "wrong:" + str(target.get("id") or int(time.time())),
            }
            source_field = "zh" if direction == "zh2id" else "id"
            # Upsert by source+direction.  A newer human correction must replace,
            # not coexist with, an older contradictory target in the prompt.
            existing = None
            for ex in reversed(custom_translation_examples):
                if ex.get("dir") == direction and str(ex.get(source_field) or "").strip() == source_text:
                    existing = ex
                    break
            if existing is not None:
                existing.clear()
                existing.update(new_ex)
            else:
                custom_translation_examples.append(new_ex)
            if len(custom_translation_examples) > CUSTOM_EXAMPLES_MAX:
                custom_translation_examples[:] = custom_translation_examples[-CUSTOM_EXAMPLES_MAX:]
            _save_examples_to_disk()
    _save_translation_log_to_disk()
    save_settings()
    return True, target.get("src", "")[:80]


def mark_latest_translation_wrong(group_id, correct_translation="", add_to_examples=True):
    """Backward-compat wrapper. Old code/tests calling this still work."""
    return mark_translation_wrong(group_id, correct_translation, add_to_examples, offset=1)


def list_recent_translations(group_id, limit=10):
    """Return the N most recent translation log entries for this group, newest first.
    Used by /wrong list command so the user can pick which one to mark."""
    out = []
    for entry in reversed(translation_log):
        if not group_id or entry.get("group_id") == group_id:
            out.append(entry)
            if len(out) >= limit:
                break
    return out


def format_recent_translations_for_line(entries):
    """Format a recent-translations list as a readable LINE message."""
    if not entries:
        return "（沒有翻譯記錄 / Tidak ada riwayat）"
    lines = ["📋 最近翻譯（新→舊）/ Riwayat terjemahan:"]
    for i, e in enumerate(entries, 1):
        src = (e.get("src") or "").strip().replace("\n", " ")[:40]
        tgt = (e.get("tgt") or "").strip().replace("\n", " ")[:40]
        marked = "❌ " if e.get("marked_wrong") else ""
        lines.append(f"{i}. {marked}原: {src}")
        lines.append(f"   譯: {tgt}")
    lines.append("")
    lines.append("標記第 N 筆錯誤：/wrong N 正確翻譯")
    lines.append("Mark salah ke-N: /wrong N terjemahan benar")
    return "\n".join(lines)


def parse_wrong_command(text):
    """Parse the /wrong command body. Returns dict with parsed fields.

    Supported syntaxes:
      /wrong                          → {"mode": "mark_only", "offset": 1}
      /wrong list                     → {"mode": "list"}
      /wrong 正確翻譯                 → {"mode": "correct", "offset": 1, "correct": "..."}
      /wrong 3 正確翻譯               → {"mode": "correct", "offset": 3, "correct": "..."}
      /wrong id=abc123 正確翻譯       → {"mode": "correct", "entry_id": "abc123", "correct": "..."}

    The original `text` is the raw user message starting with the command keyword.
    """
    # Strip the leading command keyword. Accept several aliases.
    body = text.strip()
    for prefix in ("/wrong", "/markwrong", "/錯", "/標錯"):
        if body.lower().startswith(prefix.lower()):
            body = body[len(prefix):].strip()
            break

    # Empty → mark only, no correction
    if not body:
        return {"mode": "mark_only", "offset": 1}

    # /wrong list
    if body.lower() in ("list", "ls", "清單", "列表"):
        return {"mode": "list"}

    # /wrong id=xxx 正確翻譯
    m = re.match(r'^id\s*=\s*(\S+)\s*(.*)$', body, re.IGNORECASE)
    if m:
        eid = m.group(1)
        correct = m.group(2).strip()
        if not correct:
            return {"mode": "mark_only", "entry_id": eid}
        return {"mode": "correct", "entry_id": eid, "correct": correct}

    # /wrong N 正確翻譯  (N is 1-9)
    m = re.match(r'^(\d+)\s+(.+)$', body)
    if m:
        n = int(m.group(1))
        correct = m.group(2).strip()
        if 1 <= n <= 50:
            return {"mode": "correct", "offset": n, "correct": correct}

    # /wrong 正確翻譯
    return {"mode": "correct", "offset": 1, "correct": body}


# v3.4: short-lived JSONL export tokens for /export jsonl LINE command.
# Maps token → (filepath, expiry_ts). Tokens are wiped after use or expiry.
_export_tokens = {}


def export_examples_to_jsonl():
    """Export custom_translation_examples to OpenAI fine-tune JSONL format.
    Returns a public URL good for ~1 hour, or "" on failure.

    OpenAI chat fine-tune format expects:
      {"messages":[
         {"role":"system","content":"..."},
         {"role":"user","content":"中文原文"},
         {"role":"assistant","content":"印尼譯文"}
      ]}
    one JSON per line.
    """
    if not custom_translation_examples:
        return ""
    try:
        token = uuid.uuid4().hex[:12]
        # Use /tmp on Render — survives within container lifetime, which is enough for 1h links.
        path = os.path.join(tempfile.gettempdir(), f"finetune_{token}.jsonl")
        sys_prompt = ("You are a Taiwan-factory ZH↔ID translator. "
                      "Output only the translation, no commentary.")
        with open(path, "w", encoding="utf-8") as f:
            for ex in custom_translation_examples:
                zh = (ex.get("zh") or "").strip()
                idn = (ex.get("id") or "").strip()
                direction = ex.get("dir", "zh2id")
                if not zh or not idn:
                    continue
                if direction == "zh2id":
                    user_msg, assistant_msg = zh, idn
                else:
                    user_msg, assistant_msg = idn, zh
                row = {
                    "messages": [
                        {"role": "system", "content": sys_prompt},
                        {"role": "user", "content": user_msg},
                        {"role": "assistant", "content": assistant_msg},
                    ]
                }
                f.write(json.dumps(row, ensure_ascii=False) + "\n")
        _export_tokens[token] = (path, int(time.time()) + 3600)
        # Clean up expired tokens occasionally
        now = int(time.time())
        expired = [t for t, (_p, exp) in _export_tokens.items() if exp < now]
        for t in expired:
            try:
                os.remove(_export_tokens[t][0])
            except Exception:
                pass
            _export_tokens.pop(t, None)
        # Return a relative URL; LINE will let the user tap it.
        # Caller can prepend host if needed; we'll use the Render hostname through env.
        host = os.environ.get("PUBLIC_HOST", "").rstrip("/")
        if host:
            return f"{host}/export/finetune/{token}"
        # Fallback: absolute path note for the user
        return f"/export/finetune/{token}"
    except Exception as e:
        logger.error("export_examples_to_jsonl failed: %s", e)
        return ""


_PERSONAL_LANGUAGE_COMMAND_PREFIXES = (
    "/mylang", "/mylanguage", "/my-language", "/melange",
    "/language", "/bahasa", "/bahasaku", "/bahasa-saya",
    "/我的語言", "/我的语言", "/母語", "/母语",
)
_INTERPRETER_COMMANDS = (
    "/interpreter", "/voiceinterpreter", "/interpret", "/penerjemah",
    "/即時口譯", "/即时口译", "/口譯", "/口译",
)
_HANDOVER_COMMANDS = (
    "/handover", "/summary", "/serahterima", "/ringkasan",
    "/交班摘要", "/今天重點", "/今天重点", "/未完成事項", "/未完成事项",
)


def _command_has_prefix(text, prefixes):
    value = (text or "").strip().lower()
    return any(value == prefix or value.startswith(prefix + " ") for prefix in prefixes)


def _normalise_control_shortcut(text):
    """Normalise visible button text from old/new LINE messages.

    Older buttons used MessageAction while newer buttons use PostbackAction with
    displayText.  Accept both so a button does not become useless after deploy.
    """
    value = str(text or "").strip().lower()
    for mark in ("👤", "📋", "🎙️", "🎙", "✨", "🔎", "📢", "↩", "↩️"):
        value = value.replace(mark, "")
    value = re.sub(r"\s+", " ", value).strip(" \t\r\n-–—:：")
    return value


def _detect_control_shortcut(text):
    value = _normalise_control_shortcut(text)
    personal = {
        "我的語言", "我的语言", "母語", "母语", "語言", "语言",
        "bahasa saya", "bahasaku", "my language", "語言/bahasa", "语言/bahasa",
    }
    handover = {
        "交班摘要", "交班", "handover", "ringkasan shift",
        "ringkasan serah terima", "serah terima", "交班/serah",
    }
    interpreter = {
        "即時口譯", "即时口译", "口譯", "口译", "interpreter",
        "interpretasi", "penerjemah", "口譯/interpret", "口译/interpret",
    }
    if value in personal:
        return "personal_language"
    if value in handover:
        return "handover"
    if value in interpreter:
        return "interpreter"
    return ""


def _language_name_bilingual(code):
    names_id = {
        "zh": "中文 / Mandarin", "id": "印尼文 / Indonesia",
        "vi": "越南文 / Vietnam", "th": "泰文 / Thailand",
        "tl": "菲律賓文 / Filipino", "en": "英文 / Inggris",
        "ja": "日文 / Jepang", "ko": "韓文 / Korea", "hi": "印地文 / Hindi",
    }
    return "{} {}".format(LANG_FLAGS.get(code, "🌐"), names_id.get(code, code))


def handle_personal_language_command(text, user_id):
    """Read or set the caller's preferred language without requiring cryptic syntax."""
    if not user_id:
        return "⚠️ 無法取得你的 LINE 身分。\n⚠️ Identitas LINE tidak dapat dibaca."
    parts = (text or "").strip().split(None, 1)
    arg = parts[1].strip() if len(parts) > 1 else ""
    if not arg:
        return "__PERSONAL_LANGUAGE_MENU__"
    code = translation_extras_module.normalize_personal_language(arg)
    if not code:
        return (
            "⚠️ 不支援這個語言，請按下方語言按鈕。\n"
            "⚠️ Bahasa ini belum didukung. Silakan pilih melalui tombol bahasa."
        )
    user_languages[user_id] = code
    dm_target_lang[user_id] = code
    try:
        save_settings(force=True)
    except TypeError:
        save_settings()
    except Exception:
        pass
    display = _language_name_bilingual(code)
    return "✅ 閱讀語言已設定：{}\n✅ Bahasa bacaan diatur: {}".format(display, display)


def handle_interpreter_command(group_id, user_id):
    """Create a short-lived bilingual link for turn-by-turn voice interpreting."""
    scope_id = group_id or (("__dm__:" + user_id) if user_id else "__interpreter__")
    public_url = (os.environ.get("PUBLIC_URL") or "").rstrip("/")
    if not public_url and has_request_context():
        try:
            public_url = request.url_root.rstrip("/")
        except Exception:
            public_url = ""
    liff_id = (LIFF_ID or "").strip()
    if not public_url and not liff_id:
        return (
            "⚠️ 即時口譯連結目前無法建立。\n"
            "⚠️ Tautan interpretasi belum dapat dibuat. Hubungi admin bot."
        )
    nonce = issue_liff_nonce(scope_id, user_id or "")
    if liff_id:
        url = "https://liff.line.me/{}?nonce={}&view=interpreter".format(liff_id, nonce)
    else:
        url = "{}/liff/settings?nonce={}&view=interpreter".format(public_url, nonce)
    return (
        "🎙️ 即時雙向口譯 / Interpretasi dua arah\n"
        "點開連結後輪流說話。 / Buka tautan lalu bicara bergantian.\n"
        "{}\n\n⏳ 連結 10 分鐘內有效 / Berlaku 10 menit"
    ).format(url)


def _persisted_handover_rows(group_id, hours=12, max_messages=120):
    """Recover handover source rows from the persisted translation log.

    The original handover buffer was memory-only, so a Render restart or free
    instance sleep silently erased the data.  The translation log already keeps
    successful results and is therefore the safest restart-tolerant fallback.
    """
    cutoff = time.time() - max(1, min(48, int(hours or 12))) * 3600
    recovered = []
    for entry in list(translation_log or []):
        try:
            if str(entry.get("group_id", "") or "") != str(group_id or ""):
                continue
            ts = float(entry.get("ts", 0) or 0)
            if ts < cutoff:
                continue
            src = str(entry.get("src", "") or "").strip()
            tgt = str(entry.get("tgt", "") or "").strip()
            src_lang = str(entry.get("src_lang", "") or "").strip()
            tgt_lang = str(entry.get("tgt_lang", "") or "").strip()
            if not src or not tgt:
                continue
            recovered.append({
                "timestamp": ts,
                "sender": "",
                "source_language": src_lang,
                "source_text": src,
                "translations": {tgt_lang: tgt} if tgt_lang else {},
            })
        except Exception:
            continue
    return recovered[-max(1, int(max_messages or 120)):]


def build_group_handover_summary(group_id, hours=12, extra_rows=None):
    """Summarise recent successful group translations in Chinese and Indonesian.

    AI formatting or provider outages never make this button useless: when the
    model call fails, a deterministic bilingual digest is returned from the
    already-delivered translations without another paid request.
    """
    rows = _get_recent_group_messages(group_id, hours=hours, max_messages=120)
    rows.extend(_persisted_handover_rows(group_id, hours=hours, max_messages=120))
    try:
        rows.extend(_translation_action_handover_rows(group_id, max_rows=120))
    except Exception:
        pass
    if extra_rows:
        rows.extend([dict(row) for row in extra_rows if isinstance(row, dict)])

    # Dedupe the in-memory and persisted views of the same translation.
    deduped = []
    seen = set()
    for row in sorted(rows, key=lambda r: float(r.get("timestamp", r.get("ts", 0)) or 0)):
        key = (
            str(row.get("source_text", "") or "").strip(),
            json.dumps(row.get("translations", {}) or {}, ensure_ascii=False, sort_keys=True),
        )
        if not key[0] or key in seen:
            continue
        seen.add(key)
        deduped.append(row)

    compact = translation_extras_module.compact_handover_entries(
        deduped, max_entries=100, max_chars=12000)
    if not compact:
        return (
            "📋 最近沒有可整理的翻譯訊息。\n"
            "📋 Belum ada pesan terjemahan yang dapat diringkas."
        )

    # A short history does not need another paid AI call.  Use the deterministic
    # bilingual digest directly; for larger histories the AI may condense it, and
    # the same local fallback remains available on any provider error.
    parsed = None
    if len(compact) < 3:
        parsed = translation_extras_module.build_handover_fallback(
            compact, max_items=24, timezone_name=_HANDOVER_TIMEZONE_NAME)
    else:
        try:
            messages = translation_extras_module.build_handover_messages(
                compact, timezone_name=_HANDOVER_TIMEZONE_NAME)
            model = _pick_aux_model("handover")
            kwargs = _build_aux_kwargs(
                model, messages, max_out_tokens=1600, temperature=0.0,
                cache_key=_build_cache_key(group_id, "multi", "zh-id", "handover"),
            )
            response = ai.chat.completions.create(**kwargs)
            track_tokens(response)
            raw = response.choices[0].message.content if response and response.choices else ""
            parsed = translation_extras_module.parse_handover_response(raw)
        except Exception as exc:
            logger.exception("handover summary AI failed; using local fallback: %s", exc)

    if not parsed:
        parsed = translation_extras_module.build_handover_fallback(
            compact, max_items=24, timezone_name=_HANDOVER_TIMEZONE_NAME)
    if not parsed:
        return (
            "📋 最近沒有可整理的翻譯訊息。\n"
            "📋 Belum ada pesan terjemahan yang dapat diringkas."
        )
    return (
        "📋 交班摘要 / Ringkasan serah terima（最近 {} 小時・台灣時間 / {} jam terakhir・waktu Taiwan）\n\n"
        "🇹🇼 中文\n{}\n\n"
        "🇮🇩 Bahasa Indonesia\n{}"
    ).format(max(1, min(48, int(hours or 12))), max(1, min(48, int(hours or 12))), parsed["zh"], parsed["id"])


def handle_command(text, group_id, user_id=None):
    _stats_inc("commands")
    cmd = text.strip().lower()

    # ========================================================================
    # v3.10: Admin gate — 重要命令限管理員使用
    # ========================================================================
    # 判定為「群組裡」才執行 gate;DM (沒 group_id) 一律放行(只影響自己)
    if group_id:
        _gate_error = False
        try:
            _need_admin = _is_admin_only_command(text)
            _is_admin = is_group_admin(user_id)
        except NameError:
            # v310 ext 還沒載入 — 用 legacy 行為,不擋
            _need_admin = False
            _is_admin = True
        except Exception as _ge:
            # 其他例外 → fail safe (擋下),log 警告便於追蹤
            logger.error("admin gate check failed: %s; failing closed", _ge)
            _need_admin = True
            _is_admin = False
            _gate_error = True
        if _need_admin and not _is_admin:
            if _gate_error:
                return ("⚠️ 系統錯誤,命令暫時無法執行\n"
                        "⚠️ Kesalahan sistem,coba lagi nanti\n"
                        "(管理員請查 log)")
            return ("⚠️ 此命令僅限管理員使用\n"
                    "⚠️ Perintah ini khusus admin\n\n"
                    "(打 /whoami 取得你的 LINE ID,請管理員加你為 admin)")

    if cmd == "/help":
        # Return sentinel; caller detects this and sends Flex instead of Text
        return "__FLEX_HELP__"
    elif cmd == "/whoami":
        # v3.10: 讓使用者查自己的 LINE userID (給 bootstrap admin 用)
        if not user_id:
            return "⚠️ 無法取得你的 LINE ID / Tidak bisa ambil LINE ID"
        try:
            _is_a = "✅" if is_group_admin(user_id) else "❌"
        except NameError:
            _is_a = "?"
        return ("🪪 你的 LINE userID:\n" + user_id + "\n\n"
                "管理員身分 / Status admin: " + _is_a + "\n\n"
                "(把此 ID 加到環境變數 BOOTSTRAP_ADMIN_USER_IDS 即可成為管理員)")
    elif cmd.startswith("/wrong") or cmd.startswith("/markwrong") or cmd.startswith("/錯") or cmd.startswith("/標錯"):
        # v3.4: rich /wrong syntax (see parse_wrong_command for supported forms)
        parsed = parse_wrong_command(text)
        mode = parsed.get("mode")

        if mode == "list":
            entries = list_recent_translations(group_id, limit=10)
            return format_recent_translations_for_line(entries)

        if mode == "mark_only":
            ok, info = mark_translation_wrong(
                group_id,
                correct_translation="",
                add_to_examples=False,
                offset=parsed.get("offset", 1),
                entry_id=parsed.get("entry_id"),
            )
            if not ok:
                return "⚠️ " + info
            return ("✅ 已標記翻譯錯誤 / Terjemahan ditandai salah\n"
                    "若要同時加入正確譯文,請輸入 / Untuk menambahkan koreksi:\n"
                    "/wrong 正確翻譯(標最近一筆)\n"
                    "/wrong 2 正確翻譯(標倒數第 2 筆)\n"
                    "/wrong list(看最近 10 筆)")

        # mode == "correct"
        correct = parsed.get("correct", "").strip()
        ok, info = mark_translation_wrong(
            group_id,
            correct_translation=correct,
            add_to_examples=True,
            offset=parsed.get("offset", 1),
            entry_id=parsed.get("entry_id"),
        )
        if not ok:
            return "⚠️ " + info
        offset = parsed.get("offset", 1)
        position_label = "最近一筆" if offset == 1 else f"倒數第 {offset} 筆"
        if parsed.get("entry_id"):
            position_label = f"指定 ID 訊息"
        total = len(custom_translation_examples)
        return (f"✅ 已標記{position_label}錯誤,並加入修正範例 / Ditandai salah & ditambahkan ke contoh koreksi:\n"
                f"{correct}\n"
                f"📚 累積範例 / Total contoh: {total} / {CUSTOM_EXAMPLES_MAX}")

    elif cmd.startswith("/export"):
        # v3.4: export training data
        parts = text.strip().split()
        if len(parts) == 1:
            # /export → status
            total = len(custom_translation_examples)
            zh2id = sum(1 for e in custom_translation_examples if e.get("dir") == "zh2id")
            id2zh = sum(1 for e in custom_translation_examples if e.get("dir") == "id2zh")
            target = 300
            ready = "✅ 達到 fine-tune 建議門檻" if total >= target else f"再 {target-total} 筆達建議門檻"
            return (f"📊 訓練資料統計 / Statistik data\n"
                    f"總範例數 / Total: {total}\n"
                    f"中→印 / ZH→ID: {zh2id}\n"
                    f"印→中 / ID→ZH: {id2zh}\n"
                    f"狀態 / Status: {ready}\n\n"
                    f"匯出 jsonl: /export jsonl\n"
                    f"（產生下載連結 / generate link）")
        elif parts[1].lower() in ("jsonl", "json"):
            url = export_examples_to_jsonl()
            if not url:
                return "⚠️ 匯出失敗 / Export gagal（沒有範例 / no examples）"
            return f"📦 訓練資料已匯出 / Data ekspor:\n{url}\n\n（連結 1 小時內有效 / valid 1 hour）"
        else:
            return "用法 / Usage: /export 或 /export jsonl"

    elif cmd in ("/stats wrong", "/wrongstats", "/標記統計"):
        total = len(custom_translation_examples)
        wrong_count = sum(1 for e in translation_log if e.get("marked_wrong"))
        recent_30d = 0
        cutoff = int(time.time()) - 30*86400
        for e in translation_log:
            if e.get("marked_wrong") and e.get("ts", 0) > cutoff:
                recent_30d += 1
        return (f"📊 翻譯品質統計 / Statistik kualitas terjemahan\n"
                f"累積修正範例 / Contoh koreksi: {total} / {CUSTOM_EXAMPLES_MAX}\n"
                f"日誌中標錯 / Ditandai salah: {wrong_count} 筆\n"
                f"近 30 天標錯 / 30 hari terakhir: {recent_30d} 筆\n"
                f"距 fine-tune 門檻 / Sisa untuk fine-tune: {max(0, 300 - total)} 筆")

    elif cmd == "/on":
        group_settings[group_id] = True
        save_settings()
        return "\u2705 \u7ffb\u8b6f\u5df2\u958b\u555f / Penerjemah aktif"
    elif cmd == "/off":
        group_settings[group_id] = False
        save_settings()
        return "\u274c \u7ffb\u8b6f\u5df2\u95dc\u9589 / Penerjemah nonaktif"
    elif cmd == "/img on":
        group_img_settings[group_id] = True
        group_img_ask_settings.pop(group_id, None)  # 清掉 ask 旗標
        save_settings()
        return "\u2705 \u5716\u7247\u7ffb\u8b6f\u5df2\u958b\u555f(\u81ea\u52d5\u7ffb\u8b6f) / Terjemahan gambar otomatis"
    elif cmd == "/img off":
        group_img_settings[group_id] = False
        group_img_ask_settings.pop(group_id, None)  # 清掉 ask 旗標
        save_settings()
        return "\u274c \u5716\u7247\u7ffb\u8b6f\u5df2\u95dc\u9589 / Terjemahan gambar nonaktif"
    elif cmd == "/img ask":
        # v3.9.10: 詢問模式 — 收到圖片不自動翻,先問使用者按按鈕才翻
        group_img_settings[group_id] = False
        group_img_ask_settings[group_id] = True
        save_settings()
        return "\u2753 \u5716\u7247\u7ffb\u8b6f: \u8a62\u554f\u6a21\u5f0f\n\u6536\u5230\u5716\u7247\u6703\u51fa\u73fe\u300c\u7ffb\u8b6f\u9019\u5f35 / \u4e0d\u7528\u300d\u6309\u9215\nMode tanya: pesan gambar akan menanyakan dulu"
    elif cmd == "/voice on":
        group_audio_settings[group_id] = True
        save_settings()
        return "\u2705 \u8a9e\u97f3\u7ffb\u8b6f\u5df2\u958b\u555f / Terjemahan suara aktif"
    elif cmd == "/voice off":
        group_audio_settings[group_id] = False
        save_settings()
        return "\u274c \u8a9e\u97f3\u7ffb\u8b6f\u5df2\u95dc\u9589 / Terjemahan suara nonaktif"
    elif cmd == "/wo on":
        group_wo_settings[group_id] = True
        save_settings()
        return "✅ 拍工單查儲區已開啟 / Foto WO cek gudang aktif"
    elif cmd == "/wo off":
        group_wo_settings[group_id] = False
        save_settings()
        return "❌ 拍工單查儲區已關閉 / Foto WO cek gudang nonaktif"
    elif cmd == "/skip":
        if not user_id:
            return "⚠️ 無法識別你的身分 / Tidak bisa mengenali identitas Anda"
        if group_id not in group_skip_users:
            group_skip_users[group_id] = set()
        group_skip_users[group_id].add(user_id)
        save_settings()
        return "✅ 已將你加入白名單,你的訊息不會被翻譯\nAnda ditambahkan ke daftar skip, pesan Anda tidak akan diterjemahkan"
    elif cmd == "/unskip":
        if not user_id:
            return "⚠️ 無法識別你的身分 / Tidak bisa mengenali identitas Anda"
        if group_id in group_skip_users:
            group_skip_users[group_id].discard(user_id)
        save_settings()
        return "✅ 已將你移出白名單,你的訊息會被翻譯\nAnda dihapus dari daftar skip, pesan Anda akan diterjemahkan"
    # v3.10: 不翻譯詞動態管理
    elif text.strip().lower().startswith("/skipterm"):
        try:
            return handle_skipterm_command(text, group_id)
        except NameError:
            return "⚠️ v3.10 模組未載入 / v3.10 module not loaded"
    # v3.10: LIFF 設定頁
    elif cmd == "/liff":
        try:
            return handle_liff_command(group_id, user_id)
        except NameError:
            return "⚠️ v3.10 模組未載入 / v3.10 module not loaded"
    elif _command_has_prefix(text, _PERSONAL_LANGUAGE_COMMAND_PREFIXES):
        return handle_personal_language_command(text, user_id)
    elif cmd in _INTERPRETER_COMMANDS:
        return handle_interpreter_command(group_id, user_id)
    elif cmd in _HANDOVER_COMMANDS:
        if not group_id:
            return "⚠️ 交班摘要只能在群組使用。\n⚠️ Ringkasan serah terima hanya dapat digunakan di grup."
        return build_group_handover_summary(group_id, hours=12)
    # v3.14: 群組內語言設定面板
    elif cmd in ("/panel", "/lang", "/setting", "/settings"):
        return "__FLEX_PANEL__"
    elif text.strip().lower().startswith("/skipadd"):
        name_query = text.strip()[8:].strip()
        if not name_query:
            return "⚠️ 請輸入名字 / Masukkan nama\n範例 / Contoh: /skipadd 秋情"
        matches = find_user_by_name(group_id, name_query)
        if len(matches) == 0:
            return "❌ 找不到「" + name_query + "」 / Tidak ditemukan\n該用戶需先在群組發過訊息才能被認到\nUser harus pernah kirim pesan di grup dulu"
        if len(matches) > 1:
            names = "\n".join(["  • " + m[1] for m in matches])
            return "🔍 找到多人符合 / Beberapa user ditemukan:\n" + names + "\n請輸入更完整的名字 / Masukkan nama yang lebih lengkap"
        uid, dname = matches[0]
        if group_id not in group_skip_users:
            group_skip_users[group_id] = set()
        group_skip_users[group_id].add(uid)
        save_settings()
        return "✅ 已將「" + dname + "」加入白名單,訊息不會被翻譯\n" + dname + " ditambahkan ke daftar skip, pesan tidak akan diterjemahkan"
    elif text.strip().lower().startswith("/skipdel"):
        name_query = text.strip()[8:].strip()
        if not name_query:
            return "⚠️ 請輸入名字 / Masukkan nama\n範例 / Contoh: /skipdel 秋情"
        matches = find_user_by_name(group_id, name_query)
        if len(matches) == 0:
            return "❌ 找不到「" + name_query + "」 / Tidak ditemukan"
        if len(matches) > 1:
            names = "\n".join(["  • " + m[1] for m in matches])
            return "🔍 找到多人符合 / Beberapa user ditemukan:\n" + names + "\n請輸入更完整的名字 / Masukkan nama yang lebih lengkap"
        uid, dname = matches[0]
        if group_id in group_skip_users:
            group_skip_users[group_id].discard(uid)
        save_settings()
        return "✅ 已將「" + dname + "」移出白名單,訊息會被翻譯\n" + dname + " dihapus dari daftar skip, pesan akan diterjemahkan"
    elif cmd == "/skiplist":
        skipped = group_skip_users.get(group_id, set())
        if not skipped:
            return "\u76ee\u524d\u767d\u540d\u55ae\u662f\u7a7a\u7684 / Daftar skip kosong"
        names_cache = group_user_names.get(group_id, {})
        lines = ["\u23ed\ufe0f \u767d\u540d\u55ae / Daftar skip:"]
        for uid in skipped:
            dname = names_cache.get(uid)
            if dname:
                lines.append("  \u2022 " + dname)
            else:
                lines.append("  \u2022 (\u672a\u77e5\u7528\u6236)")
        return "\n".join(lines)
    elif cmd == "/status":
        is_on = group_settings.get(group_id, True)
        if is_on:
            img_on = group_img_settings.get(group_id, True)
            img_status = "✅ 開啟 / Aktif" if img_on else "❌ 關閉 / Nonaktif"
            audio_on = group_audio_settings.get(group_id, True)
            audio_status = "✅ 開啟 / Aktif" if audio_on else "❌ 關閉 / Nonaktif"
            wo_on = group_wo_settings.get(group_id, True)
            wo_status = "✅ 開啟 / Aktif" if wo_on else "❌ 關閉 / Nonaktif"
            return ("✅ 翻譯:開啟中 / Penerjemah aktif\n"
                    "中文 ⇄ 🇮🇩 印尼文 / Mandarin ⇄ Indonesia\n"
                    "🖼️ 圖片翻譯 / Terjemahan gambar:" + img_status + "\n"
                    "🎤 語音翻譯 / Terjemahan suara:" + audio_status + "\n"
                    "📋 拍工單查儲區 / Foto WO cek gudang:" + wo_status)
        else:
            return "❌ 翻譯:已關閉 / Penerjemah nonaktif"
    elif cmd == "/clearcache":
        # v3.9.3: clear translation cache (e.g. after fixing a bad translation
        # that got cached, or after switching to a new model). Anyone in the
        # group can run this — it only affects the in-memory cache, no data loss.
        with _cache_lock:
            n = len(translation_cache)
            translation_cache.clear()
        logger.info("Translation cache cleared (%d entries) by user in group %s", n, group_id)
        return f"🧹 已清除翻譯快取 / Cache terjemahan dibersihkan\n清除筆數 / Jumlah: {n}"
    elif cmd.startswith("/lang"):
        return handle_lang_command(text, group_id)
    elif text.strip().startswith("/notice ") or text.strip().startswith("/notice\u3000"):
        if not is_cmd_enabled(group_id, "notice"):
            return None
        content = text.strip()[8:].strip()
        if not content:
            return "⚠️ 請輸入公告內容 / Masukkan isi pengumuman\n例如 / Contoh: /notice 明天放假一天"
        tgt = group_target_lang.get(group_id, "id")
        if has_chinese(content):
            return make_notice(content, tgt)
        else:
            src = detect_language(content)
            if src and src != "zh":
                return make_notice_from_other(content, src)
            return make_notice(content, tgt)
    elif text.strip().lower().startswith("/qry"):
        if not is_cmd_enabled(group_id, "qry"):
            return None
        return handle_qry_command(text)
    elif cmd == "/pw1":
        if not is_cmd_enabled(group_id, "pw1"):
            return None
        return "🔑 班長密碼 / PW Shift Leader\n" + "=" * 18 + "\n" + pw1_text + "\n" + "=" * 18
    elif cmd == "/pw2":
        if not is_cmd_enabled(group_id, "pw2"):
            return None
        return "🏭 儲運密碼 / PW Gudang\n" + "=" * 18 + "\n" + pw2_text + "\n" + "=" * 18
    elif cmd == "/scrap":
        if not is_cmd_enabled(group_id, "scrap"):
            return None
        return scrap_text
    elif text.strip().lower().startswith("/pkg"):
        if not is_cmd_enabled(group_id, "pkg"):
            return None
        return handle_pkg_command(text)
    elif cmd == "/saran":
        # v3.9.39+: 改成可從後台變更的設定(external_links_settings)
        return _format_external_link_reply("saran")
    elif cmd == "/absen":
        # v3.9.39+: 改成可從後台變更的設定
        return _format_external_link_reply("absen")
    return None


@app.route("/callback", methods=["POST"])
def callback():
    sig = request.headers.get("X-Line-Signature", "")
    body = request.get_data(as_text=True)
    # v3.9.19: 記錄所有進來的 webhook(只記事件 type 跟 message type,不記內容)
    try:
        _b = json.loads(body) if body else {}
        _evts = _b.get("events", [])
        _summary = []
        for ev in _evts:
            _t = ev.get("type", "?")
            _msg = ev.get("message", {})
            _src = ev.get("source", {})
            _summary.append({
                "type": _t,
                "message_type": _msg.get("type") if _msg else None,
                "message_id": _msg.get("id") if _msg else None,
                "source_type": _src.get("type"),
                "group_id": _src.get("groupId") or _src.get("roomId"),
                "user_id_tail": (_src.get("userId") or "")[-6:] if _src.get("userId") else None,
            })
        _event_log_write("webhook_in", {"events_count": len(_evts), "events": _summary})
    except Exception as _le:
        _event_log_write("webhook_parse_error", {"error": str(_le)[:200]})
    try:
        handler.handle(body, sig)
    except InvalidSignatureError:
        _event_log_write("webhook_invalid_sig", {})
        abort(400)
    return "OK"


@handler.add(MessageEvent, message=TextMessageContent)
def handle_message(event):
    # v3.9.30c B15 修補: LINE webhook 重發保護
    if _is_redelivery(event) or _is_duplicate_message(getattr(event.message, 'id', None)):
        logger.warning("[handle_message] redelivery or duplicate, skipping msg_id=%s",
                       getattr(event.message, 'id', None))
        return
    
    text = event.message.text.strip()
    # v3.9.56: 全面短文翻譯 — 改用 has_translatable_content,
    # 放行單字中文(好/對/是)、單假名/韓/泰字;只擋純 emoji/標點/數字。
    if not has_translatable_content(text):
        return

    source = event.source
    is_dm = not getattr(source, 'group_id', None) and not getattr(source, 'room_id', None)
    group_id = getattr(source, 'group_id', None) or getattr(source, 'room_id', None) or getattr(source, 'user_id', None)
    user_id = getattr(source, 'user_id', None)

    # v3.9.30c B14 修補: 重置 _tl thread-local 殘留狀態
    # gunicorn worker 會重用 thread,前一次處理可能殘留 from_image_ocr=True 等狀態
    # 不重置會讓 text 訊息誤觸發 OCR 專用邏輯(例如強制分段翻譯)
    try:
        _tl.from_image_ocr = False
        _tl.factory_audit = None
        _tl.rtc_fail_reason = None
        _tl.last_entry_id = None
        _tl.gpt_says_announcement = None
        _tl.struct_self_check = None
        _tl.multi_path_fail = None
        _tl.quoted_context_source = ""
        _tl.quoted_context_message_id = ""
    except Exception:
        pass

    # Visible controls must remain usable across old MessageAction buttons,
    # current Postback display text, and both group languages.  Handle the
    # human-readable labels before the normal translation pipeline.
    _control_shortcut = _detect_control_shortcut(text)
    if _control_shortcut:
        if _control_shortcut == "personal_language":
            _current = user_languages.get(user_id) or dm_target_lang.get(user_id)
            _message = TextMessage(
                text=_personal_language_menu_text("id", _current),
                quick_reply=_build_personal_language_quick_reply("", "id"),
            )
        elif _control_shortcut == "handover":
            if is_dm:
                _shortcut_text = (
                    "⚠️ 交班摘要只能在群組使用。\n"
                    "⚠️ Ringkasan serah terima hanya dapat digunakan di grup."
                )
            else:
                _shortcut_text = build_group_handover_summary(group_id, hours=12)
            _message = TextMessage(text=_clip_line_text(_shortcut_text))
        else:
            _shortcut_text = handle_interpreter_command(None if is_dm else group_id, user_id)
            _message = TextMessage(text=_clip_line_text(_shortcut_text))
        try:
            with ApiClient(configuration) as api_client:
                MessagingApi(api_client).reply_message(ReplyMessageRequest(
                    reply_token=event.reply_token,
                    messages=[_message],
                ))
        except Exception as exc:
            logger.warning("control shortcut reply failed: %s", exc)
        return

    # --- DM (private message) mode ---
    if is_dm and user_id:
        # Record DM user for admin panel
        if user_id not in dm_known_users:
            try:
                with ApiClient(configuration) as api_client:
                    api = MessagingApi(api_client)
                    profile = api.get_profile(user_id)
                    dm_known_users[user_id] = profile.display_name or user_id
            except Exception:
                dm_known_users[user_id] = user_id

        # DM commands
        cmd = text.strip().lower()

        # ═══ v3.24: Rich Menu 商用按鈕回覆(販售版選單按鈕送出這些關鍵字)═══
        _menu_reply = None
        _t_exact = text.strip()
        if _t_exact in ("功能說明", "功能说明"):
            _menu_reply = (
                "🌐 翻譯小助手 功能一覽\n"
                "─────────────\n"
                "💬 文字即時翻譯:中文 ⇄ 印尼/越南/泰/菲律賓/英/日/韓/印地\n"
                "🌍 群組多語廣播(最多 5 語同時)\n"
                "📷 圖片翻譯:工單/告示拍照即譯,保留版面\n"
                "🎤 語音翻譯:語音訊息自動轉文字翻譯\n"
                "🔊 TTS 語音播報譯文\n"
                "📋 工單偵測 + 客戶儲區查詢(/qry)\n"
                "🏭 232 條工廠專業術語庫(吊運/製程/設備)\n"
                "🧠 翻譯記憶:重複句 0 秒即回\n"
                "⚙️ 群組打「設定」開語言面板;/help 看完整指令"
            )
        elif _t_exact in ("收費標準", "收费标准"):
            _menu_reply = service_price_text
        elif _t_exact in ("使用說明", "使用说明"):
            _menu_reply = (
                "📖 使用說明\n"
                "─────────────\n"
                "1️⃣ 請先與我聯絡開通服務\n"
                "　 LINE ID: moneyshop\n"
                "2️⃣ 加機器人好友 @764menna\n"
                "3️⃣ 把機器人邀進你的群組\n"
                "4️⃣ 群組打「設定」選擇翻譯語言,即可使用\n"
                "有任何問題隨時私訊我 🙌"
            )
        elif _t_exact in ("與我聯絡", "与我联络", "聯絡我"):
            _menu_reply = (
                "📞 與我聯絡\n"
                "─────────────\n"
                "LINE ID: moneyshop\n"
                "機器人好友:@764menna\n"
                "🛍️ 蝦皮賣場:https://tw.shp.ee/7f6j5kVT\n"
                "看到訊息會盡快回覆您!"
            )
        elif cmd.startswith("/setprice"):
            # 管理員修改收費標準文字(持久化,重啟不丟)
            if not is_group_admin(user_id):
                _menu_reply = "⚠️ 此指令僅限管理員"
            else:
                _new_price = text.strip()[9:].strip()
                if not _new_price:
                    _menu_reply = ("目前收費標準文字:\n─────\n" + service_price_text
                                   + "\n─────\n修改方式:/setprice 新的收費內容(可多行)")
                else:
                    globals()["service_price_text"] = "💰 收費標準 / Harga\n─────────────\n" + _new_price
                    try:
                        save_settings(force=True)
                    except Exception:
                        pass
                    _menu_reply = "✅ 收費標準已更新並保存:\n─────\n" + globals()["service_price_text"]
        # ═══ v3.26: 人工驗證工具(品質的最後一哩,做成可點可打的流程)═══
        # /audit [n]      抽最近 n 句(預設 10)翻譯讓懂雙語的人檢查
        # /mark 3 o       標第 3 句正確    /mark 3 x  標第 3 句錯誤
        # /auditstats     看累計人工準確率(persisted,重啟不丟)
        elif cmd.startswith("/audit") and not cmd.startswith("/auditstats"):
            if not is_group_admin(user_id):
                _menu_reply = "⚠️ 此指令僅限管理員"
            else:
                try:
                    _n = int(cmd.replace("/audit", "").strip() or "10")
                except Exception:
                    _n = 10
                _n = max(1, min(_n, 20))
                _marked_ids = set((bot_stats.get("audit_marks") or {}).keys())
                _sample = [e for e in reversed(translation_log)
                           if e.get("src") and e.get("tgt")
                           and str(e.get("id", "")) not in _marked_ids][:_n]
                if not _sample:
                    _menu_reply = "目前沒有可抽樣的翻譯紀錄(或全部已標註過)"
                else:
                    globals()["_audit_last_sample"] = _sample
                    _lines = ["🔍 人工抽檢 %d 句(請懂雙語的人核對):" % len(_sample), "─────"]
                    for _i, _e in enumerate(_sample, 1):
                        _lines.append("%d. [%s→%s] %s\n   → %s" % (
                            _i, _e.get("src_lang", "?"), _e.get("tgt_lang", "?"),
                            _e.get("src", "")[:60], _e.get("tgt", "")[:60]))
                    _lines.append("─────")
                    _lines.append("標註:/mark 編號 o(對)或 x(錯)")
                    _lines.append("例:/mark 1 o   /mark 3 x")
                    _menu_reply = "\n".join(_lines)
        elif cmd.startswith("/mark "):
            if not is_group_admin(user_id):
                _menu_reply = "⚠️ 此指令僅限管理員"
            else:
                _parts = cmd.split()
                _sample = globals().get("_audit_last_sample") or []
                if len(_parts) != 3 or _parts[2] not in ("o", "x") or not _parts[1].isdigit():
                    _menu_reply = "格式:/mark 編號 o|x(先用 /audit 抽樣)"
                elif not (1 <= int(_parts[1]) <= len(_sample)):
                    _menu_reply = "⚠️ 編號超出範圍,先用 /audit 重新抽樣"
                else:
                    _e = _sample[int(_parts[1]) - 1]
                    _marks = bot_stats.setdefault("audit_marks", {})
                    _marks[str(_e.get("id", _e.get("src", "")[:40]))] = _parts[2]
                    bot_stats["audit_ok"] = sum(1 for v in _marks.values() if v == "o")
                    bot_stats["audit_bad"] = sum(1 for v in _marks.values() if v == "x")
                    try:
                        save_settings(force=True)
                    except Exception:
                        pass
                    _tot = bot_stats["audit_ok"] + bot_stats["audit_bad"]
                    _menu_reply = "✅ 已標註第 %s 句為「%s」\n累計:%d 句標註,正確率 %.0f%%" % (
                        _parts[1], "正確" if _parts[2] == "o" else "錯誤",
                        _tot, bot_stats["audit_ok"] * 100.0 / _tot if _tot else 0)
        elif cmd == "/ttscheck":
            # v3.29: TTS 三關卡自我診斷 — 不用看 Render log,機器人自己報告
            if not is_group_admin(user_id):
                _menu_reply = "⚠️ 此指令僅限管理員"
            else:
                _lines = ["🔊 TTS 診斷報告", "─────"]
                _pu = (os.environ.get("PUBLIC_URL") or "").rstrip("/")
                _lines.append(("✅ PUBLIC_URL:" + _pu) if _pu
                              else "❌ PUBLIC_URL 未設定 → Render Environment 加 Key=PUBLIC_URL Value=你的 onrender.com 網址")
                _ff = _resolve_ffmpeg()
                _lines.append(("✅ ffmpeg:" + str(_ff)) if _ff
                              else "❌ ffmpeg 不存在 → requirements.txt 加一行 imageio-ffmpeg 後重新部署")
                _lines.append("✅ OpenAI key:已設定" if oai else "❌ OpenAI key 未設定(TTS 需要)")
                _on = [g[:8] for g, v in group_tts_settings.items() if v]
                _lines.append(("✅ 已開 TTS 的群組:" + ", ".join(_on)) if _on
                              else "❌ 沒有任何群組開啟 TTS → 後台 /admin → 群組 → TTS 開關")
                if _pu and _ff and oai:
                    _u, _d = generate_tts("測試 tes", "id")
                    _lines.append("─────")
                    _lines.append(("✅ 實測合成成功!" + str(_u)) if _u
                                  else "❌ 實測合成失敗 — 看 Render log 的 OpenAI TTS/ffmpeg 錯誤行")
                _menu_reply = "\n".join(_lines)
        elif cmd == "/auditstats":
            _ok = bot_stats.get("audit_ok", 0)
            _bad = bot_stats.get("audit_bad", 0)
            _tot = _ok + _bad
            if _tot == 0:
                _menu_reply = "尚無人工標註紀錄。用 /audit 抽樣開始。"
            else:
                _menu_reply = ("📊 人工驗證統計(累計)\n─────\n"
                               "已標註:%d 句\n✅ 正確:%d\n❌ 錯誤:%d\n"
                               "人工準確率:%.1f%%\n─────\n"
                               "這是 QE 自評以外唯一的真實品質基準。"
                               % (_tot, _ok, _bad, _ok * 100.0 / _tot))
        if _menu_reply:
            with ApiClient(configuration) as api_client:
                api = MessagingApi(api_client)
                api.reply_message(ReplyMessageRequest(
                    reply_token=event.reply_token,
                    messages=[TextMessage(text=_menu_reply)]
                ))
            return

        if cmd == "/help":
            # DM /help also uses Flex carousel (ZH + ID bilingual)
            # 非管理員不顯示 III / ADMIN 區塊
            send_help_flex(event.reply_token, primary_lang="zh",
                           is_admin=is_group_admin(user_id))
            return
        if cmd.startswith("/to"):
            with ApiClient(configuration) as api_client:
                api = MessagingApi(api_client)
                api.reply_message(ReplyMessageRequest(
                    reply_token=event.reply_token,
                    messages=[TextMessage(text=(
                        "ℹ️ DM 自動偵測語言並互譯\n"
                        "ℹ️ DM otomatis deteksi & terjemahkan\n\n"
                        "支援 / Didukung: 中文/印尼/泰/印地/越南/日/韓/英"))]
                ))
            return
        # DM: handle /qry command
        if text.strip().lower().startswith("/qry"):
            qry_result = handle_qry_command(text)
            if qry_result:
                with ApiClient(configuration) as api_client:
                    api = MessagingApi(api_client)
                    api.reply_message(ReplyMessageRequest(
                        reply_token=event.reply_token,
                        messages=[TextMessage(text=_clip_line_text(qry_result))]
                    ))
            return
        # DM: handle /pw1, /pw2, /scrap, /pkg commands
        dm_cmd_result = None
        if cmd == "/pw1":
            dm_cmd_result = "🔑 班長密碼 / PW Shift Leader\n" + "=" * 18 + "\n" + pw1_text + "\n" + "=" * 18
        elif cmd == "/pw2":
            dm_cmd_result = "🏭 儲運密碼 / PW Gudang\n" + "=" * 18 + "\n" + pw2_text + "\n" + "=" * 18
        elif cmd == "/scrap":
            dm_cmd_result = scrap_text
        elif text.strip().lower().startswith("/pkg"):
            dm_cmd_result = handle_pkg_command(text)
        if dm_cmd_result:
            with ApiClient(configuration) as api_client:
                api = MessagingApi(api_client)
                api.reply_message(ReplyMessageRequest(
                    reply_token=event.reply_token,
                    messages=[TextMessage(text=_clip_line_text(dm_cmd_result))]
                ))
            return
        # v3.10: DM 支援 /whoami (admin bootstrap 用)
        if cmd == "/whoami":
            try:
                _is_a = "✅" if is_group_admin(user_id) else "❌"
            except NameError:
                _is_a = "?"
            whoami_text = ("🪪 你的 LINE userID:\n" + (user_id or "(未知)") + "\n\n"
                           "管理員身分 / Status admin: " + _is_a + "\n\n"
                           "(把此 ID 加到環境變數 BOOTSTRAP_ADMIN_USER_IDS 即可成為管理員)")
            with ApiClient(configuration) as api_client:
                api = MessagingApi(api_client)
                api.reply_message(ReplyMessageRequest(
                    reply_token=event.reply_token,
                    messages=[TextMessage(text=whoami_text)]
                ))
            return
        # Personal language and interpreter commands must also work in DM.
        # Previously every unknown slash command was discarded before reaching
        # handle_command(), so /mylang appeared to do nothing in private chat.
        if _command_has_prefix(text, _PERSONAL_LANGUAGE_COMMAND_PREFIXES):
            _lang_result = handle_personal_language_command(text, user_id)
            with ApiClient(configuration) as api_client:
                api = MessagingApi(api_client)
                if _lang_result == "__PERSONAL_LANGUAGE_MENU__":
                    _current = user_languages.get(user_id) or dm_target_lang.get(user_id)
                    api.reply_message(ReplyMessageRequest(
                        reply_token=event.reply_token,
                        messages=[TextMessage(
                            text=_personal_language_menu_text("id", _current),
                            quick_reply=_build_personal_language_quick_reply("", "id"),
                        )],
                    ))
                else:
                    api.reply_message(ReplyMessageRequest(
                        reply_token=event.reply_token,
                        messages=[TextMessage(text=_clip_line_text(_lang_result))],
                    ))
            return
        if cmd in _INTERPRETER_COMMANDS:
            _interpreter_result = handle_interpreter_command(None, user_id)
            with ApiClient(configuration) as api_client:
                MessagingApi(api_client).reply_message(ReplyMessageRequest(
                    reply_token=event.reply_token,
                    messages=[TextMessage(text=_clip_line_text(_interpreter_result))],
                ))
            return
        if cmd in _HANDOVER_COMMANDS:
            with ApiClient(configuration) as api_client:
                MessagingApi(api_client).reply_message(ReplyMessageRequest(
                    reply_token=event.reply_token,
                    messages=[TextMessage(text=(
                        "⚠️ 交班摘要只能在群組使用。\n"
                        "⚠️ Ringkasan serah terima hanya dapat digunakan di grup."
                    ))],
                ))
            return

        # DM: skip other / commands
        if text.startswith("/"):
            return

        # DM master toggle check
        if not dm_master_enabled and user_id not in dm_whitelist:
            return

        # DM translation: mentions are removed only from language detection.
        # The normalized original text is translated so identity labels survive.
        text, _dm_line_mentions = normalize_line_mentions(
            text, event.message, None
        )
        text_clean = strip_mentions_for_detect(text, _dm_line_mentions).strip()
        # v3.9.56: 全面短文翻譯 — 放行單字內容
        if not has_translatable_content(text_clean):
            return

        lang = detect_language(text_clean) or ("zh" if has_chinese(text_clean) else "auto")
        tgt = user_languages.get(user_id) or dm_target_lang.get(user_id, "id")
        # A personal language is the preferred reading language, not a reason to
        # suppress a same-language message forever. Preserve the useful ZH↔ID DM
        # default when the sender writes in their own preferred language.
        if lang == tgt:
            tgt = "id" if lang == "zh" else "zh"

        # Durable outbox: persist the source before the first provider call.
        # If the process crashes or every provider is temporarily unavailable,
        # the same source survives and is delivered after recovery.
        _dm_outbox_ctx = {
            "reply_token": event.reply_token,
            "quote_token": get_quote_token(event.message),
            "user_id": user_id,
            "message_id": str(getattr(event.message, "id", "") or ""),
        }
        _dm_outbox_key = _translation_retry_key(_dm_outbox_ctx, text, lang, [tgt])
        _schedule_text_translation_retry(
            _dm_outbox_ctx,
            source_text=text,
            src_lang=lang,
            target_langs=[tgt],
            line_mentions=_dm_line_mentions,
            delay_seconds=90,
        )

        # Set translation tone for DM (use global default)
        _tl.tone = translation_tone
        _tl.tone_custom = translation_tone_custom
        _tl.group_id = "__dm__"
        _tl.user_id = user_id or ""

        _bp, _bc = bot_stats.get("tokens_prompt", 0), bot_stats.get("tokens_completion", 0)
        _bcost = bot_stats.get("ant_cost_usd", 0.0) + bot_stats.get("oai_cost_usd", 0.0)
        _previous_line_mentions = getattr(_tl, 'line_mentions', None)
        try:
            _tl.line_mentions = list(_dm_line_mentions or [])
            result = translate(text, lang, tgt)
        finally:
            try:
                if _previous_line_mentions is None:
                    if hasattr(_tl, 'line_mentions'):
                        delattr(_tl, 'line_mentions')
                else:
                    _tl.line_mentions = _previous_line_mentions
            except Exception:
                pass
        track_group_usage("__dm__", _bp, _bc, _bcost)
        if not result:
            logger.warning(
                "[DM] immediate translation empty; scheduling retry lang=%s tgt=%s text=%r",
                lang, tgt, text_clean[:60],
            )
            _dm_retry_ctx = {
                "reply_token": event.reply_token,
                "quote_token": get_quote_token(event.message),
                "user_id": user_id,
                "message_id": str(getattr(event.message, "id", "") or ""),
            }
            _dm_retry_scheduled = _schedule_text_translation_retry(
                _dm_retry_ctx,
                source_text=text,
                src_lang=lang,
                target_langs=[tgt],
                line_mentions=_dm_line_mentions,
            )
            if _dm_retry_scheduled:
                _send_background_failure_notice(
                    _dm_retry_ctx,
                    kind="translation_retry",
                    detail="dm_immediate_providers_empty_auto_retry",
                )
            return
        reply = LANG_FLAGS.get(tgt, "") + " " + result


        _stats_inc("text_translations")
        _dm_message = TextMessage(text=_clip_line_text(reply))
        _dm_quote = get_quote_token(event.message)
        if _dm_quote:
            try:
                _dm_message.quote_token = _dm_quote
            except Exception:
                pass
        try:
            _send_reply_with_push_fallback(
                reply_token=event.reply_token,
                target_id=user_id,
                message_obj=_dm_message,
                fallback_text=reply,
                retry_key=str(uuid.uuid5(uuid.NAMESPACE_URL, "jy-text-outbox:" + _dm_outbox_key)),
            )
            _complete_durable_text_job(_dm_outbox_key)
        except Exception as _dm_send_exc:
            logger.warning("[DM] immediate delivery failed; durable outbox retained: %s", _dm_send_exc)
        return

    # --- Group mode (original logic) ---
    # Record user display name for /skipadd lookup
    if group_id and user_id:
        record_user_name(group_id, user_id)
    # Track group for admin panel
    if group_id and not is_dm and group_id not in group_tracking:
        gname = ""
        try:
            with ApiClient(configuration) as api_client:
                api = MessagingApi(api_client)
                summary = api.get_group_summary(group_id)
                gname = summary.group_name or ""
        except Exception:
            pass
        group_tracking[group_id] = {"name": gname, "joined_at": time.time()}
        save_settings()

    if text.startswith("/"):
        # Set tone before commands that may translate (e.g. /notice)
        _tone, _tone_custom = get_group_tone(group_id)
        _tl.tone = _tone
        _tl.tone_custom = _tone_custom
        cmd_result = handle_command(text, group_id, user_id)
        if cmd_result == "__FLEX_HELP__":
            # /help uses Flex Message carousel (ZH + ID bilingual)
            # 非管理員不顯示 III / ADMIN 區塊
            send_help_flex(event.reply_token, primary_lang="zh",
                           is_admin=is_group_admin(user_id))
        elif cmd_result == "__PERSONAL_LANGUAGE_MENU__":
            current = user_languages.get(user_id) or dm_target_lang.get(user_id)
            with ApiClient(configuration) as api_client:
                MessagingApi(api_client).reply_message(ReplyMessageRequest(
                    reply_token=event.reply_token,
                    messages=[TextMessage(
                        text=_personal_language_menu_text("id", current),
                        quick_reply=_build_personal_language_quick_reply("", "id"),
                    )],
                ))
        elif cmd_result == "__FLEX_PANEL__":
            # v3.14: /panel /lang /setting → 語言設定面板
            try:
                send_lang_panel_flex(event.reply_token, group_id)
            except NameError:
                pass
        elif cmd_result:
            with ApiClient(configuration) as api_client:
                api = MessagingApi(api_client)
                api.reply_message(ReplyMessageRequest(
                    reply_token=event.reply_token,
                    messages=[TextMessage(text=_clip_line_text(cmd_result))]
                ))
        return

    # ─── v3.14 競品 UX 升級:非 / 開頭的設定入口(僅群組,DM 不適用) ───
    if group_id and not is_dm:
        # 1. 打「設定」「語言」直接開設定面板(參考 JFETEK 面板 / Ligo 指令的痛點:
        #    工人記不住指令,給一個最自然的中文入口)
        _t_strip = text.strip().lower()
        if _t_strip in ("設定", "设定", "語言設定", "语言设定", "setting", "settings",
                        "panel", "pengaturan"):
            try:
                if send_lang_panel_flex(event.reply_token, group_id):
                    return
            except NameError:
                pass
        # 2. Echonora 式自然語言設定:「翻譯 中文和印尼文」「設定語言 越南文 泰文」
        try:
            _nl = try_natural_lang_setup(text, group_id, getattr(source, 'user_id', None))
        except NameError:
            _nl = None
        if _nl is not None:
            _nl_status, _nl_langs = _nl
            if _nl_status == "not_admin":
                try:
                    with ApiClient(configuration) as api_client:
                        api = MessagingApi(api_client)
                        api.reply_message(ReplyMessageRequest(
                            reply_token=event.reply_token,
                            messages=[TextMessage(text="⚠️ 語言設定僅限管理員\n⚠️ Setelan bahasa khusus admin")],
                        ))
                except Exception:
                    pass
            else:
                _banner = "✅ 翻譯語言已設定:🇹🇼 中文 ⇄ " + " + ".join(
                    "{} {}".format(LANG_FLAGS.get(l, ""), LANG_NAMES_ZH.get(l, l))
                    for l in (_nl_langs or []))
                send_lang_panel_flex(event.reply_token, group_id, banner=_banner)
            return

    is_on = group_settings.get(group_id, True)
    if not is_on:
        return

    # Check skip list
    sender_id = getattr(source, 'user_id', None)
    if sender_id and sender_id in group_skip_users.get(group_id, set()):
        return

    if text.startswith("!"):
        return

    # Normalize LINE mention spans first.  This also repairs a malformed @()
    # shell from webhook metadata when the mentionee userId can be resolved, and
    # recognizes pasted/plain-text forms such as @(杰弗).
    text, line_mentions = normalize_line_mentions(text, event.message, group_id)

    # v3.17 根治：只有 @mention / 人名點名的訊息不送翻譯。
    # 實際案例：@小麥（研磨股班長） 君立。
    if is_mention_only_or_name_call(text, line_mentions, group_id):
        logger.info("[mention-guard] skip name-call message group=%s text=%r",
                    group_id, text[:80])
        return

    # Cache this message for future quote references
    msg_id = getattr(event.message, 'id', None)
    if msg_id:
        message_cache[msg_id] = {"text": text, "ts": time.time(), "tr": {}}
        # v3.30: "tr" = {目標語: 譯文}。翻譯完成後回填(見 _cache_translation),
        # 之後別人「回覆引用」這句時,引用框能顯示讀者語言的譯文而非原文。
        # Trim cache
        # v3.10+ 修補:加 lock 避免並發時 sorted+pop 期間被其他 webhook thread 加新項目
        # 造成 RuntimeError: dictionary changed size during iteration
        if len(message_cache) > MESSAGE_CACHE_MAX:
            with _message_cache_lock:
                # 再檢查一次(double-check pattern,可能另一 thread 剛剛已修剪)
                if len(message_cache) > MESSAGE_CACHE_MAX:
                    try:
                        # 用 list() 快照確保 sorted 期間不被改
                        oldest = sorted(list(message_cache.items()),
                                        key=lambda x: x[1].get("ts", 0))[:50]
                        for k, _ in oldest:
                            message_cache.pop(k, None)
                    except RuntimeError:
                        # 萬一還是 race,粗暴清掉前 50 個 key
                        for k in list(message_cache.keys())[:50]:
                            message_cache.pop(k, None)

    # Check if this is a reply to another message (quoted message)
    # v3.30: 引用框語言修正 — 原本永遠顯示「被引用句的原文」,
    # 印尼同事回覆中文句時,中文讀者在引用框看到的卻是…原中文沒錯,
    # 但中文同事回覆印尼句時引用框是印尼文、反之亦然 = 引用框對「看的人」常是外文。
    # 修正:出卡時依該卡的目標語言,優先取被引用句的「該語言譯文」(回填快取),
    # 沒有譯文才退回原文。
    # LINE quote/reply metadata is normalized across SDK object, dict and
    # alias representations.  A missing cached quoted message is context loss
    # only; it must never suppress translation of the current message.
    quoted_text = None
    _quote_meta = resolve_quote_context(event.message, message_cache)
    quoted_id = _quote_meta.get("quoted_message_id")
    _quoted_entry = _quote_meta.get("entry")
    if _quoted_entry:
        quoted_text = str(_quoted_entry.get("text") or "").strip() or None
    if quoted_id:
        try:
            _event_log_write("quoted_text_message_received", {
                "group_id": group_id or "",
                "message_id": str(getattr(event.message, 'id', '') or ''),
                "quoted_message_id": str(quoted_id),
                "quoted_context_cached": bool(_quoted_entry),
                "current_text_len": len(text or ""),
            })
        except Exception:
            pass

    def _quoted_for(tgt_lang):
        """Return the best cached quote context, including OCR/scene for photos."""
        if not _quoted_entry:
            return None
        translated = (_quoted_entry.get("tr") or {}).get(tgt_lang)
        if translated:
            return translated
        if _quoted_entry.get("media_type") == "image":
            return (
                _quoted_entry.get("ocr_text")
                or _quoted_entry.get("scene")
                or _quoted_entry.get("text", "")
            )
        return _quoted_entry.get("text", "")

    def _cache_translation(tgt_lang, translated):
        """翻譯完成回填快取,供未來引用使用。"""
        try:
            _mid = getattr(event.message, 'id', None)
            if _mid and _mid in message_cache and translated:
                message_cache[_mid].setdefault("tr", {})[tgt_lang] = translated
        except Exception:
            pass

    # Strip @mentions for language detection only
    text_for_detect = strip_mentions_for_detect(text, line_mentions).strip()
    # v3.9.56: 全面短文翻譯 — 放行單字內容,只擋純 emoji/標點
    if not has_translatable_content(text_for_detect):
        return

    lang = detect_language(text_for_detect) or ("zh" if has_chinese(text_for_detect) else "auto")

    # A LINE reply often omits the noun because it is visible in the quoted
    # message.  Feed that cached quote only as disambiguation context; the
    # current message remains the sole translation source.
    try:
        _tl.quoted_context_source = (_quoted_for(lang) or quoted_text or "").strip()
        _tl.quoted_context_message_id = str(quoted_id or "")
    except Exception:
        _tl.quoted_context_source = ""
        _tl.quoted_context_message_id = ""

    tgt = group_target_lang.get(group_id, "id")

    # Durable text outbox: persist before translation/provider work.  This is
    # the crash-safe boundary.  Successful LINE delivery removes the row;
    # otherwise a lease-based worker retries indefinitely after restart.
    if lang == "zh":
        try:
            _outbox_targets = get_group_target_langs(group_id)
        except NameError:
            _outbox_targets = [tgt]
    else:
        _outbox_targets = ["zh"]
    _outbox_ctx = {
        "reply_token": event.reply_token,
        "quote_token": get_quote_token(event.message),
        "group_id": group_id,
        "user_id": user_id,
        "message_id": str(getattr(event.message, "id", "") or ""),
    }
    _outbox_key = _translation_retry_key(_outbox_ctx, text, lang, _outbox_targets)
    _schedule_text_translation_retry(
        _outbox_ctx,
        source_text=text,
        src_lang=lang,
        target_langs=_outbox_targets,
        line_mentions=line_mentions,
        quoted_context_source=getattr(_tl, "quoted_context_source", ""),
        quoted_context_message_id=getattr(_tl, "quoted_context_message_id", ""),
        delay_seconds=90,
    )

    # Show typing indicator while translating
    show_loading(group_id)
    if get_group_feature(group_id, 'mark_read'):
        # v3.11: 帶 mark_as_read_token,新 SDK 會用 token-based 精準標讀
        mark_as_read(group_id, mark_as_read_token=getattr(event.message, 'mark_as_read_token', None))

    # Mention protection now lives at translate()'s public boundary.  Pass the
    # normalized source text through unchanged and provide exact LINE spans via
    # thread-local context so all translation routes share one implementation.
    text_to_translate = text
    mention_placeholders = {}

    reply = None
    _translation_failed = False
    _bp, _bc = bot_stats.get("tokens_prompt", 0), bot_stats.get("tokens_completion", 0)
    _bcost = bot_stats.get("ant_cost_usd", 0.0) + bot_stats.get("oai_cost_usd", 0.0)
    # Set translation tone for this group
    _tone, _tone_custom = get_group_tone(group_id)
    _tl.tone = _tone
    _tl.tone_custom = _tone_custom
    _tl.group_id = group_id
    # Media context is keyed by (group, sender).  Earlier text handling set only
    # group_id, so photo/video context lookup silently saw user_id=None and could
    # never connect a just-sent work-order photo to the sender's next message.
    _tl.user_id = user_id or ""
    _tl.line_mentions = list(line_mentions or [])
    # v3.10: 多語廣播 — 中文時翻成所有設定的目標語言
    _tts_text = None    # 給 TTS 用的主要翻譯文字
    _tts_lang = None
    if lang == "zh":
        try:
            _targets = get_group_target_langs(group_id)
        except NameError:
            _targets = [tgt]
        _trs = None
        try:
            _trs = translate_multi(text_to_translate, "zh", _targets, mention_placeholders)
        except Exception as _multi_ex:
            logger.error("[group %s] translate_multi exception: %s %s",
                         group_id, type(_multi_ex).__name__, str(_multi_ex)[:200])
            try:
                _event_log_write("translate_multi_exception", {
                    "group_id": group_id or "",
                    "text_len": len(text_to_translate or ""),
                    "error": str(_multi_ex)[:300],
                })
            except Exception:
                pass
        if _trs:
            reply = format_multi_reply(_trs)
            _tts_lang, _tts_text = _trs[0]   # 第一個翻譯拿來 TTS
    else:
        # v3.10: 安全保護 — 只有「該語言在此群組的目標語言清單中」才翻譯到中文。
        # 避免印尼工人偶爾打英文 "OK"/"thanks" 也被當外語翻譯造成困惑。
        # 群組要支援泰文工人 → 後台勾選泰文 → 泰文打字才會被翻譯。
        # Availability policy: any non-Chinese or auto-detected text is
        # translated to Chinese.  Group target configuration controls outbound
        # Chinese broadcasts; it no longer discards incoming languages.
        # ai_provider owns the only operational failover chain. Do not rerun the
        # entire translation pipeline with another model here; that duplicated
        # API cost and could consume the LINE reply-token window.
        try:
            result = translate(text_to_translate, lang, "zh")
        except Exception as _trans_ex:
            result = None
            logger.error("[group %s] translate exception: %s %s",
                         group_id, type(_trans_ex).__name__, str(_trans_ex)[:200])
            try:
                _event_log_write("translate_exception", {
                    "group_id": group_id or "",
                    "lang": lang,
                    "text_len": len(text_to_translate or ""),
                    "error": str(_trans_ex)[:300],
                    "error_type": type(_trans_ex).__name__,
                })
            except Exception:
                pass
        if result and mention_placeholders:
            result = restore_mentions(result, mention_placeholders)
            result = _post_restore_mentions_guard(result, mention_placeholders)
        # translate() already ran the full source-grounded quality boundary.  Do
        # not run it a second time on restored display names; only the mutation-
        # specific mention guard above is required.
        if result:
            reply = LANG_FLAGS.get("zh", "") + " " + result
            _tts_lang, _tts_text = "zh", result
    track_group_usage(group_id, _bp, _bc, _bcost)

    if reply is not None and _is_translation_failure_sentinel(reply):
        logger.error("[LegacyFailurePurge] blocked legacy failure payload at LINE send boundary")
        try:
            _event_log_write("legacy_failure_payload_blocked", {
                "group_id": group_id or "",
                "lang": lang,
                "payload": str(reply)[:240],
            })
        except Exception:
            pass
        return

    if reply is None:
        if _translation_was_intentionally_skipped():
            _skip_outcome = _get_translation_outcome()
            logger.info(
                "[group %s] translation intentionally skipped lang=%s reason=%s text=%r",
                group_id,
                lang,
                _skip_outcome.get("reason") or "unspecified",
                (text_to_translate or "")[:80],
            )
            try:
                _event_log_write("translation_intentionally_skipped", {
                    "group_id": group_id or "",
                    "lang": lang,
                    "reason": _skip_outcome.get("reason") or "unspecified",
                    "text_preview": (text_to_translate or "")[:100],
                })
            except Exception:
                pass
            _complete_durable_text_job(_outbox_key)
            return
        # A non-empty candidate is no longer discarded by quality heuristics.
        # Reaching this branch now means every immediate provider path was empty.
        # Schedule detached retries and tell the group that no resend is needed;
        # never emit the old "cannot translate safely" terminal state.
        logger.warning("[group %s] immediate translation empty; scheduling retry lang=%s text=%r",
                       group_id, lang, (text_to_translate or "")[:80])
        _retry_targets = list(_targets) if lang == "zh" else ["zh"]
        _retry_ctx = {
            "reply_token": event.reply_token,
            "quote_token": get_quote_token(event.message),
            "group_id": group_id,
            "user_id": user_id,
            "message_id": str(getattr(event.message, "id", "") or ""),
        }
        _retry_scheduled = _schedule_text_translation_retry(
            _retry_ctx,
            source_text=text_to_translate,
            src_lang=lang,
            target_langs=_retry_targets,
            line_mentions=line_mentions,
            quoted_context_source=getattr(_tl, "quoted_context_source", ""),
            quoted_context_message_id=getattr(_tl, "quoted_context_message_id", ""),
        )
        try:
            _event_log_write("translate_empty_retry_scheduled", {
                "group_id": group_id or "",
                "lang": lang,
                "targets": _retry_targets,
                "scheduled": bool(_retry_scheduled),
                "quoted_message_id": str(quoted_id or ""),
                "text_preview": (text_to_translate or "")[:100],
            })
        except Exception:
            pass
        # Status-only notices are deliberately suppressed.  The durable queue
        # will push the actual translation when a provider becomes usable; the
        # conversation never receives a fake translation or a resend request.
        return

    # v3.10: 多語廣播每個目標語言都算一次,單語/反向翻譯算一次
    if not _translation_failed:
        try:
            _trans_count = len(_trs) if (lang == "zh" and _trs) else 1
        except (NameError, UnboundLocalError):
            _trans_count = 1
        _stats_inc("text_translations", _trans_count)

    # v3.10: TTS — 若該群組開了 TTS,額外推一條語音訊息
    try:
        if (not _translation_failed) and _tts_text and _tts_lang and get_tts_enabled(group_id):
            import threading as _tts_thr
            _tts_thr.Thread(target=push_tts_message,
                            args=(group_id, _tts_text, _tts_lang),
                            daemon=True).start()
    except NameError:
        pass   # v310 ext not loaded

    # Build reply message based on settings
    sender_display = None
    sender_picture = ""
    if sender_id:
        sender_display = (group_user_names.get(group_id, {}).get(sender_id) or
                       get_display_name(group_id, sender_id))
        sender_picture = get_user_picture_url(group_id, sender_id)

    src_flag = LANG_FLAGS.get(lang, "")
    # v3.10: multi-broadcast 時 tgt_flag 顯示所有實際翻譯出來的語言旗幟串
    try:
        if lang == "zh" and _trs and len(_trs) > 1:
            tgt_flag = "+".join(LANG_FLAGS.get(l, "") for l, _ in _trs)
        else:
            tgt_flag = LANG_FLAGS.get("zh" if lang != "zh" else (
                _trs[0][0] if (lang == "zh" and _trs) else "id"), "")
    except (NameError, UnboundLocalError):
        tgt_flag = LANG_FLAGS.get("zh" if lang != "zh" else "id", "")
    translated_text = reply.split(" ", 1)[1] if " " in reply else reply

    # Keep a short-lived, successful-only operational transcript for /交班摘要.
    if not _translation_failed:
        try:
            if lang == "zh" and _trs:
                _recent_translations = {code: value for code, value in _trs if value}
            else:
                _recent_translations = {"zh": translated_text} if translated_text else {}
            _record_recent_group_message(
                group_id,
                sender_id,
                sender_display,
                text,
                lang,
                _recent_translations,
            )
        except Exception as _recent_exc:
            logger.debug("recent group message record skipped: %s", _recent_exc)

    # v3.30: 譯文回填引用快取(未來有人回覆這句時,引用框能顯示對方語言)
    try:
        if (not _translation_failed) and '_trs' in dir() and _trs:
            for _l, _t in _trs:
                _cache_translation(_l, _t)
        if (not _translation_failed) and translated_text:
            _cache_translation((tgt if lang == "zh" else "zh"), translated_text)
        if (not _translation_failed) and lang != "zh":
            _cache_translation("zh", translated_text)
    except Exception:
        pass

    # Flex or plain text based on setting
    flex_msg = None
    _is_multi = False
    try:
        _is_multi = (lang == "zh" and _trs and len(_trs) > 1)
    except (NameError, UnboundLocalError):
        pass
    if (not _translation_failed) and get_group_feature(group_id, 'flex'):
        # v3.10: 改用 build_translation_flex_v2 (含 9 個視覺升級開關)
        try:
            _v2_multilang_on = get_flex_v2(group_id, "multilang")
        except NameError:
            _v2_multilang_on = False
        if _is_multi and _v2_multilang_on:
            # 多語廣播專屬 Flex (LV2 開啟才用)
            try:
                flex_msg = build_multilang_flex_v2(text, _trs, src_lang=lang,
                                                   sender_name_display=sender_display,
                                                   quoted_text=quoted_text,
                                                   group_id=group_id)
            except NameError:
                flex_msg = None
        elif not _is_multi:
            # 單語翻譯,用 v2
            try:
                _msg_id = getattr(event.message, 'id', None)
                _card_tgt = (tgt if lang == "zh" else "zh")
                flex_msg = build_translation_flex_v2(
                    text, translated_text,
                    src_lang=lang,
                    tgt_lang=_card_tgt,
                    sender_name_display=sender_display,
                    quoted_text=_quoted_for(_card_tgt) or quoted_text,
                    group_id=group_id,
                    msg_id=_msg_id,
                )
            except NameError:
                # v310 ext 沒載入 → 用舊版
                flex_msg = build_translation_flex(text, translated_text, src_flag, tgt_flag, sender_display,
                                                  _quoted_for(tgt if lang == "zh" else "zh") or quoted_text)
    # If Flex/LV4 is disabled by an older persisted setting, expose the new
    # translation controls as Quick Reply instead of silently hiding them.
    _action_qr = None
    if not _translation_failed:
        try:
            _msg_id = getattr(event.message, 'id', None)
            _action_tgt = (tgt if lang == "zh" else "zh")
            _flex_has_actions = bool(flex_msg and get_flex_v2(group_id, "buttons"))
            if not _flex_has_actions:
                _action_qr = _build_translation_action_quick_reply(
                    group_id, text, translated_text, lang, _action_tgt, _msg_id
                )
        except Exception as _aqe:
            logger.warning("translation action Quick Reply build failed: %s", _aqe)
    qr = _action_qr or (build_quick_reply(group_id) if get_group_feature(group_id, 'quick_reply') else None)

    # Plan the optional visual before assigning a custom sender.  When a visual
    # accompanies a translation, both messages must visibly come from the bot;
    # otherwise LINE makes the translation look like the user's own message and
    # the separate image appears to be the bot's only response.
    _expression_visual_message = None
    if not _translation_failed:
        try:
            _expression_visual_message = _build_expression_visual_message(
                text, translated_text, lang, group_id, from_image_ocr=False
            )
        except Exception as _visual_exc:
            logger.debug("expression visual selection skipped: %s", _visual_exc)

    custom_sender = None
    if not _expression_visual_message:
        custom_sender = get_sender_object(
            name_override=sender_display, icon_url_override=sender_picture
        )
    # Get quoteToken from original message for reply linking
    qt = get_quote_token(event.message)

    # Stable idempotency key shared by the immediate send and durable retry.
    # This minimizes duplicates if a worker dies after LINE accepted the reply
    # but before the outbox row was removed.
    _retry_key = str(uuid.uuid5(uuid.NAMESPACE_URL, "jy-text-outbox:" + _outbox_key))

    # v3.8: capture last logged entry id BEFORE send, so reaction events can
    # still be mapped when the reply API succeeds.  If the reply token expired,
    # the helper falls back to a plain push message instead of dropping the text.
    _entry_id_for_reaction = getattr(_tl, 'last_entry_id', None)
    if flex_msg:
        if qr:
            flex_msg.quick_reply = qr
        if custom_sender:
            flex_msg.sender = custom_sender
        # LINE only accepts quoteToken on supported outbound message types.
        # The Flex card already renders the current/quoted source internally;
        # attaching quoteToken to Flex can make the API reject the whole reply.
        _message_obj = flex_msg
    else:
        _message_obj = TextMessage(text=_clip_line_text(reply))
        if qr:
            _message_obj.quick_reply = qr
        if custom_sender:
            _message_obj.sender = custom_sender
        if qt:
            try:
                _message_obj.quote_token = qt
            except Exception:
                pass

    _reply_resp, _delivery_method = _send_reply_with_push_fallback(
        reply_token=event.reply_token,
        target_id=group_id,
        message_obj=_message_obj,
        fallback_text=reply,
        retry_key=_retry_key,
        notification_disabled=get_group_feature(group_id, 'silent'),
        append_messages=([_expression_visual_message] if _expression_visual_message else None),
    )
    _complete_durable_text_job(_outbox_key)
    try:
        _event_log_write("text_translation_delivered", {
            "group_id": group_id or "",
            "method": _delivery_method,
            "failed_notice": bool(_translation_failed),
            "visual_attached": bool(_expression_visual_message),
        })
    except Exception:
        pass

    # Only reply responses expose sent-message IDs reliably. Push fallback still
    # delivers the translation but reaction mapping is best-effort.
    try:
        if _reply_resp and _entry_id_for_reaction:
            sent_msgs = getattr(_reply_resp, 'sent_messages', None) or []
            for sm in sent_msgs:
                sm_id = getattr(sm, 'id', None)
                if sm_id:
                    register_sent_message(sm_id, _entry_id_for_reaction, group_id)
    except Exception as _re:
        logger.debug("register_sent_message skipped: %s", _re)


@handler.add(MessageEvent, message=ImageMessageContent)
def handle_image(event):
    """Handle image messages: OCR + translate with layout-preserving text."""
    # v3.9.30c B15 修補: LINE webhook 重發保護
    if _is_redelivery(event) or _is_duplicate_message(getattr(event.message, 'id', None)):
        logger.warning("[handle_image] redelivery or duplicate, skipping msg_id=%s",
                       getattr(event.message, 'id', None))
        return
    
    source = event.source
    group_id = getattr(source, 'group_id', None) or getattr(source, 'room_id', None) or getattr(source, 'user_id', None)
    user_id = getattr(source, 'user_id', None)
    is_dm_img = not getattr(source, 'group_id', None) and not getattr(source, 'room_id', None)
    logger.info("Image received from %s", group_id)
    
    # v3.9.30c B13 修補: 設定 _tl thread-local,避免跨群組污染
    # 之前 handle_image 完全沒設 _tl,OCR 翻譯時會讀到上一次翻譯殘留的 tone / group_id,
    # 導致 A 群組 OCR 圖片用到 B 群組 tone 設定。
    try:
        _tone, _tone_custom = get_group_tone(group_id)
        _tl.tone = _tone
        _tl.tone_custom = _tone_custom
        _tl.group_id = group_id or ""
        _tl.user_id = user_id or ""
        _tl.from_image_ocr = True  # 標記:這次翻譯是 OCR 來的,供下游函式區分
    except Exception:
        pass
    
    # v3.9.19: 寫磁碟 log(跨 worker 共享)
    _event_log_write("image_handler_entered", {
        "msg_id": event.message.id,
        "group_id": group_id or "",
        "user_id_tail": (user_id or "")[-6:],
        "is_dm": is_dm_img,
    })
    
    # v3.9.18: 記錄到 recent images(供 /debug/recent-images 使用)
    try:
        _last_image_received_msgs.append({
            "msg_id": event.message.id,
            "group_id": group_id or "",
            "ts": int(time.time()),
        })
        # 只保留最後 10 張
        if len(_last_image_received_msgs) > 10:
            _last_image_received_msgs.pop(0)
    except Exception:
        pass

    # Cache media messages as quoteable context.  LINE reply events only carry
    # quotedMessageId; without this entry a later text reply to a photo loses all
    # media context.  OCR/scene text is filled by the background worker when
    # available, but the current reply text is always translated independently.
    try:
        _image_mid = str(getattr(event.message, "id", "") or "")
        if _image_mid:
            message_cache[_image_mid] = {
                "text": "",
                "ts": time.time(),
                "tr": {},
                "media_type": "image",
                "ocr_text": "",
                "scene": "",
            }
    except Exception:
        pass

    # Record user for whitelist (even if translation is off)
    if group_id and user_id and not is_dm_img:
        record_user_name(group_id, user_id)

    # Check if translation is on
    is_on = group_settings.get(group_id, True)
    if not is_on:
        _event_log_write("image_skipped", {"reason": "translation_off", "group_id": group_id or ""})
        return

    # Check skip list
    sender_id = user_id
    if sender_id and sender_id in group_skip_users.get(group_id, set()):
        _event_log_write("image_skipped", {"reason": "user_in_skip_list", "user_tail": (sender_id or "")[-6:]})
        return

    # DM master toggle check for image
    if is_dm_img and sender_id:
        if not dm_master_enabled and sender_id not in dm_whitelist:
            _event_log_write("image_skipped", {"reason": "dm_disabled"})
            return

    # v3.9.10: 三種圖片處理模式
    # 1. group_img_settings=True → 自動翻譯(原本行為)
    # 2. group_img_settings=False AND group_img_ask_settings=True → 詢問模式
    # 3. group_img_settings=False AND group_img_ask_settings=False → 完全不處理
    img_on = group_img_settings.get(group_id, True)
    img_ask = group_img_ask_settings.get(group_id, False)
    _event_log_write("image_mode_check", {
        "group_id": group_id or "",
        "img_on": img_on,
        "img_ask": img_ask,
        "decision": "auto_translate" if img_on else ("ask_mode" if img_ask else "fully_off")
    })
    if not img_on:
        if img_ask:
            # === 詢問模式 ===
            # v3.9.13: 用磁碟版 pending(_pending_img_set)跨 worker 共享
            _now = int(time.time())
            _pending_img_set(event.message.id, {
                "group_id": group_id,
                "user_id": user_id or "",
                "ts": _now,
            })
            logger.info("[ImgAsk] pending stored: msg=%s gid=%s", event.message.id, group_id)
            # v3.9.12: 用 Flex 卡片詢問,跟 /help 同視覺風格
            try:
                bubble = build_image_ask_flex(event.message.id)
                with ApiClient(configuration) as api_client:
                    api = MessagingApi(api_client)
                    api.reply_message(ReplyMessageRequest(
                        reply_token=event.reply_token,
                        messages=[FlexMessage(
                            alt_text="📷 收到圖片 - 要翻譯嗎?",
                            contents=FlexContainer.from_dict(bubble),
                        )]
                    ))
                logger.info("[ImgAsk] Flex sent for msg=%s", event.message.id)
            except Exception as _e:
                logger.warning("Image ask-mode Flex failed: %s", _e)
                # Fallback 到純文字 + Quick Reply
                try:
                    from linebot.v3.messaging import (
                        QuickReply, QuickReplyItem, PostbackAction
                    )
                    qr = QuickReply(items=[
                        QuickReplyItem(action=PostbackAction(
                            label="📝 翻譯這張",
                            data="img_translate=" + event.message.id,
                            # v3.9.32: 不設 display_text,過期按按鈕時不會在群組顯示
                        )),
                    ])
                    with ApiClient(configuration) as api_client:
                        api = MessagingApi(api_client)
                        msg = TextMessage(
                            text="📷 收到圖片\n需要翻譯這張圖請按下方按鈕(1 分鐘內有效)\n\n💬 打字/語音會自動翻譯,不用按按鈕\nChat teks/suara otomatis, tanpa tombol",
                            quick_reply=qr
                        )
                        api.reply_message(ReplyMessageRequest(
                            reply_token=event.reply_token,
                            messages=[msg]
                        ))
                except Exception:
                    pass
        return

    # Persist a cross-worker "image classification in flight" marker before
    # starting OCR.  Terse measurement text sent immediately after this photo
    # can now wait only for this specific dependency instead of translating with
    # missing context.  Confirmed work-order or scene context replaces it later.
    try:
        store_pending_image_media_context(group_id, user_id, event.message.id)
    except Exception as _pending_ctx_exc:
        logger.warning("[media_ctx] pending image marker failed: %s", _pending_ctx_exc)

    # If no vision route is currently healthy, persist the media intent and
    # retry after configuration/provider recovery.  Do not post a failure text.
    if not _has_ai_capability("vision"):
        _event_log_write("image_deferred", {"reason": "no_vision_provider"})
        _schedule_image_translation_retry({
            "message_id": event.message.id,
            "quote_token": get_quote_token(event.message),
            "group_id": group_id,
            "user_id": user_id,
            "tgt": group_target_lang.get(group_id, "id"),
        }, delay_seconds=5)
        return

    # v3.9.25: 把整個 OCR + 翻譯 + reply 移到背景 thread,
    # 因為 LINE webhook 必須在短時間內 return,否則會被 LINE 跟 Render 雙重 timeout 殺掉
    _event_log_write("image_step", {"step": "spawning_background_thread", "msg_id": event.message.id})
    
    # 把需要的東西打包成 dict,thread 內用(不要傳整個 event 物件,event 在 webhook 結束後可能無效)
    _ctx = {
        "message_id": event.message.id,
        "reply_token": event.reply_token,
        "quote_token": get_quote_token(event.message),
        # v3.11: token-based mark-as-read,給背景 thread 用
        "mark_as_read_token": getattr(event.message, 'mark_as_read_token', None),
        "group_id": group_id,
        "user_id": user_id,
        "tgt": group_target_lang.get(group_id, "id"),
        "tone_info": get_group_tone(group_id),
        "wo_setting": group_wo_settings.get(group_id, True),
        "mark_read_setting": get_group_feature(group_id, 'mark_read'),
        "is_dm_img": is_dm_img,
    }
    # Persist before starting transient work.  A process crash, deploy or provider
    # outage cannot lose the image translation request.
    _ctx["durable_job_key"] = _schedule_image_translation_retry(
        _ctx, delay_seconds=75
    ) or ""
    
    import threading as _threading
    _bg = _threading.Thread(target=_handle_image_background, args=(_ctx,), daemon=True)
    _bg.start()
    # webhook 立刻 return,LINE 不會 timeout
    return


def _handle_image_background(ctx):
    """v3.9.25: 在背景 thread 跑 OCR + 翻譯 + 回應 LINE。
    webhook 主執行緒已經 return 了,所以可以慢慢做不會 timeout。
    最後用 reply_message(若 token 還活著)或 push_message(fallback)送譯文。
    """
    try:
        # 從 ctx 取出主流程設定
        group_id = ctx["group_id"]
        user_id = ctx["user_id"]
        message_id = ctx["message_id"]
        is_dm_img = ctx["is_dm_img"]
        
        # v3.9.26: 確認 thread 真的開始跑
        _event_log_write("bg_thread_started", {
            "msg_id": message_id,
            "group_id": group_id or "",
        })
        
        # show_loading + mark_read(原本在 webhook 主流程做的,移到背景)
        _event_log_write("image_step", {"step": "before_show_loading"})
        try:
            show_loading(group_id)
        except Exception as _sle:
            _event_log_write("image_step_error", {"step": "show_loading", "err": str(_sle)[:200]})
        if ctx.get("mark_read_setting"):
            try:
                # v3.11: 從 ctx 拿 token,新 SDK 走 token 路徑
                mark_as_read(group_id, mark_as_read_token=ctx.get("mark_as_read_token"))
            except Exception:
                pass
        
        # Download image from LINE
        _event_log_write("image_step", {"step": "downloading", "msg_id": message_id})
        try:
            img_base64, img_raw = download_line_image(message_id)
        except Exception as _de:
            _event_log_write("image_step_error", {"step": "download", "err": str(_de)[:300]})
            logger.exception("Image download exception: %s", _de)
            _send_background_failure_notice(ctx, kind="image", detail="download_exception")
            return
        if not img_base64:
            _event_log_write("image_aborted", {"reason": "download_returned_none"})
            logger.warning("Failed to download image %s", message_id)
            _send_background_failure_notice(ctx, kind="image", detail="download_empty")
            return
        img_mime = detect_image_mime(img_raw)
        _event_log_write("image_step", {
            "step": "downloaded",
            "size_bytes": len(img_raw) if img_raw else 0,
            "mime": img_mime,
            "first_bytes_hex": (img_raw[:16].hex() if img_raw else ""),
        })

        # Determine target language
        tgt = group_target_lang.get(group_id, "id")

        # Quick OCR to check if there's text and detect language
        _bp, _bc = bot_stats.get("tokens_prompt", 0), bot_stats.get("tokens_completion", 0)
        _bcost = bot_stats.get("ant_cost_usd", 0.0) + bot_stats.get("oai_cost_usd", 0.0)
        _event_log_write("image_step", {"step": "before_ocr"})
        try:
            extracted = ocr_image_openai(img_base64, mime_type=img_mime)
        except Exception as _oe:
            _event_log_write("image_step_error", {"step": "ocr", "err": str(_oe)[:500]})
            logger.exception("OCR exception: %s", _oe)
            _send_background_failure_notice(ctx, kind="image", detail="ocr_exception")
            return
        _event_log_write("image_step", {
            "step": "ocr_done",
            "extracted_len": len(extracted) if extracted else 0,
            "extracted_preview": (extracted[:100] if extracted else None),
        })
        logger.info("Image OCR result: %s chars, text: %s", len(extracted) if extracted else 0, (extracted[:100] + "...") if extracted and len(extracted) > 100 else extracted)
        try:
            _entry = message_cache.get(str(message_id))
            if isinstance(_entry, dict) and extracted:
                _entry["ocr_text"] = str(extracted)
                _entry["text"] = str(extracted)
                _entry["ts"] = time.time()
        except Exception:
            pass

        # Classify a work-order document immediately after OCR, before the
        # separate scene-description API call.  The old order delayed the only
        # structured context signal, so a text sent right after the photo could
        # be translated while the work-order fact was still unavailable.
        _work_order_analysis = analyze_work_order(extracted) if extracted else {
            "is_work_order": False, "customer": None, "keyword_count": 0
        }
        if _work_order_analysis.get("is_work_order"):
            store_work_order_media_context(group_id, user_id, message_id)
            _event_log_write("image_step", {
                "step": "work_order_context_stored_early",
                "keyword_count": _work_order_analysis.get("keyword_count", 0),
            })

        # v3.9.39: 場景描述(供下一則文字翻譯的視覺上下文)。
        # 已確認為工單時不再花第二次 vision call 產生自由文字場景，避免
        # 它覆寫剛建立的結構化工單 context，也縮短工單處理延遲。
        if not _work_order_analysis.get("is_work_order"):
            try:
                scene = describe_scene_for_context(img_base64, mime_type=img_mime)
                if scene:
                    store_media_scene(group_id, user_id, message_id, scene)
                    try:
                        _entry = message_cache.get(str(message_id))
                        if isinstance(_entry, dict):
                            _entry["scene"] = str(scene)
                            if not str(_entry.get("text") or "").strip():
                                _entry["text"] = str(scene)
                            _entry["ts"] = time.time()
                    except Exception:
                        pass
                    _event_log_write("scene_described", {
                        "msg_id": message_id, "scene": scene[:50]
                    })
            except Exception as _sce:
                logger.warning("scene describe error: %s", _sce)

        if not extracted or len(extracted.strip()) < 2:
            _event_log_write("image_aborted", {"reason": "ocr_empty_or_too_short", "len": len(extracted) if extracted else 0})
            _send_background_failure_notice(ctx, kind="image_no_text", detail="ocr_empty")
            return

        if _is_factory_reason_ocr_failure_text(extracted):
            _event_log_write("image_deferred", {"reason": "factory_reason_ocr_alignment", "payload": extracted[:120]})
            # Keep the durable image job pending for a fresh OCR attempt.  Never
            # place an OCR/translation warning into the translated conversation.
            return

        # === Check if this is a work order (製造指示書) ===
        try:
            wo_analysis = _work_order_analysis
            wo_customer = wo_analysis.get("customer") if wo_analysis.get("is_work_order") else None
            if wo_customer:
                _event_log_write("image_step", {"step": "work_order_detected", "customer": str(wo_customer)[:50]})
                # It's a work order — never translate work order content
                wo_on = group_wo_settings.get(group_id, True)
                if wo_on:
                    reply = format_storage_for_work_order(wo_customer)
                    if reply:
                        _stats_inc("work_order_detections")
                        qt_wo = ctx["quote_token"]
                        # v3.10+ 修補:加 push fallback。原本只用 reply_message,
                        # work_order 偵測 + storage lookup 若加 OCR 超過 30 秒,
                        # reply_token 就過期,訊息靜默消失,使用者完全不知工單已處理。
                        try:
                            with ApiClient(configuration) as api_client:
                                api = MessagingApi(api_client)
                                msg_obj = TextMessage(text=reply)
                                if qt_wo:
                                    try:
                                        msg_obj.quote_token = qt_wo
                                    except Exception:
                                        pass
                                api.reply_message(ReplyMessageRequest(
                                    reply_token=ctx["reply_token"],
                                    messages=[msg_obj]
                                ))
                            _event_log_write("image_done", {"path": "work_order", "method": "reply"})
                        except Exception as _wo_re:
                            _event_log_write("image_step_error", {
                                "step": "wo_reply", "err": str(_wo_re)[:300], "fallback": "push"
                            })
                            logger.warning("Work order reply failed, trying push: %s", _wo_re)
                            try:
                                with ApiClient(configuration) as api_client:
                                    api = MessagingApi(api_client)
                                    api.push_message(PushMessageRequest(
                                        to=group_id,
                                        messages=[TextMessage(text=reply)]
                                    ))
                                _event_log_write("image_done", {"path": "work_order", "method": "push"})
                            except Exception as _wo_pe:
                                _event_log_write("image_step_error", {"step": "wo_push", "err": str(_wo_pe)[:300]})
                                logger.exception("Work order push also failed: %s", _wo_pe)
                # Whether storage found or not, skip translation for work orders
                track_group_usage(group_id, _bp, _bc, _bcost)
                _complete_durable_image_job(ctx)
                return
        except Exception as e:
            _event_log_write("image_step_error", {"step": "work_order_detect", "err": str(e)[:200]})
            logger.error("Work order detection error: %s", e)
        # === End work order check ===

        _event_log_write("image_step", {"step": "before_lang_detect"})
        lang = detect_language(extracted) or ("zh" if has_chinese(extracted) else "auto")
        _event_log_write("image_step", {"step": "lang_detected", "lang": lang})

        # Determine actual translation target
        if lang == "zh":
            actual_tgt = tgt
        else:
            # v3.10: 與 text/audio handler 一致 — 非中文時只翻已配置語言
            # Incoming non-Chinese/auto-detected image text always translates
            # to Chinese; outbound group target settings no longer discard it.
            actual_tgt = "zh"

        # Translate OCR text using the same translation engine as text messages
        # Set translation tone for this group
        _tone, _tone_custom = get_group_tone(group_id)
        _tl.tone = _tone
        _tl.tone_custom = _tone_custom
        _tl.from_image_ocr = True  # v3.9.27: 標記為圖片來源,觸發強制分段翻譯
        _event_log_write("image_step", {"step": "before_translate", "src": lang, "tgt": (tgt if lang == "zh" else "zh")})

        # v3.12 IMAGE ROOT FIX:圖片只負責 OCR 原文;翻譯必須走 translate() 標準文字管線。
        # 根因不是單一詞表錯誤,而是舊的圖片直譯路徑會繞過使用者提供的工廠用語、glossary、
        # factory context、quality gate 與後處理。這裡統一成 OCR → translate(),並把
        # thread-local 群組/使用者/圖片來源上下文複製進 timeout worker,避免背景執行緒失去工廠語境。
        result = None
        _tl.group_id = group_id or ""
        _tl.user_id = user_id or ""
        _tl.from_image_ocr = True
        _ctx_snapshot = _snapshot_translation_thread_context()

        # v3.9.24: 用 threading 強制限制 translate() 最多 50 秒,
        # 因為 translate() 內部有多個 OpenAI 呼叫(分段、品質檢查、反譯),
        # 即使各別都有 timeout,加總可能超過 LINE webhook 限制。
        import threading
        _trans_result = [None]
        _trans_exc = [None]
        def _do_translate():
            try:
                if lang == "zh":
                    _trans_result[0] = _translate_with_thread_context(
                        translate, extracted, "zh", actual_tgt, _ctx_snapshot
                    )
                else:
                    _trans_result[0] = _translate_with_thread_context(
                        translate, extracted, lang, actual_tgt, _ctx_snapshot
                    )
            except Exception as e:
                _trans_exc[0] = e
        _t = threading.Thread(target=_do_translate, daemon=True)
        _t.start()
        _t.join(timeout=50.0)  # 最多等 50 秒

        if _t.is_alive():
            # The synchronous image deadline expired, but OCR source text is
            # already available. Persist that text and let the durable queue
            # deliver the actual translation later; never post a failure/status
            # message in place of the translation.
            _event_log_write("image_step_error", {"step": "translate", "err": "thread timeout after 50s"})
            logger.error("Translate thread timeout after 50s; queued durably")
            _schedule_text_translation_retry(
                ctx,
                source_text=extracted,
                src_lang=lang,
                target_langs=[actual_tgt],
                line_mentions=[],
                from_image_ocr=True,
            )
            return
        if _trans_exc[0]:
            _event_log_write("image_step_error", {"step": "translate", "err": str(_trans_exc[0])[:300]})
            logger.error("Translate exception queued durably: %s", _trans_exc[0])
            _schedule_text_translation_retry(
                ctx,
                source_text=extracted,
                src_lang=lang,
                target_langs=[actual_tgt],
                line_mentions=[],
                from_image_ocr=True,
            )
            return
        result = _trans_result[0]
        _event_log_write("image_step", {
            "step": "translate_done",
            "result_len": len(result) if result else 0,
            "result_preview": (result[:100] if result else None),
        })

        if not result:
            _event_log_write("image_aborted", {"reason": "translate_returned_empty_queued"})
            track_group_usage(group_id, _bp, _bc, _bcost)
            _schedule_text_translation_retry(
                ctx,
                source_text=extracted,
                src_lang=lang,
                target_langs=[actual_tgt],
                line_mentions=[],
                from_image_ocr=True,
            )
            return

        reply = "\U0001f5bc\ufe0f " + LANG_FLAGS.get(actual_tgt, "") + "\n" + result
        _overlay_token = _store_image_overlay_context(
            img_raw, extracted, result, lang, actual_tgt, group_id
        )
        _overlay_qr = _build_image_translation_action_quick_reply(
            group_id,
            extracted,
            result,
            lang,
            actual_tgt,
            msg_id=message_id,
            overlay_token=_overlay_token,
        )
        _ocr_expression_visual = None
        try:
            _ocr_expression_visual = _build_expression_visual_message(
                extracted, lang, group_id, from_image_ocr=True
            )
        except Exception as _visual_exc:
            logger.debug("OCR expression visual selection skipped: %s", _visual_exc)

        # LINE message limit is 5000 chars
        if len(reply) > 5000:
            reply = reply[:4990] + "\n..."

        track_group_usage(group_id, _bp, _bc, _bcost)
        try:
            _record_recent_group_message(
                group_id, user_id, get_display_name(group_id, user_id),
                extracted, lang, {actual_tgt: result},
            )
        except Exception:
            pass
        _stats_inc("image_translations")
        _event_log_write("image_step", {"step": "before_reply"})
        # v3.8: thread quote_token onto image translation reply.
        qt = ctx["quote_token"]
        _image_delivered = False
        try:
            try:
                with ApiClient(configuration) as api_client:
                    api = MessagingApi(api_client)
                    msg_obj = TextMessage(text=reply)
                    if _overlay_qr:
                        msg_obj.quick_reply = _overlay_qr
                    _img_sender = get_sender_object(
                        name_override=get_display_name(group_id, user_id),
                        icon_url_override=get_user_picture_url(group_id, user_id)
                    )
                    if _img_sender:
                        msg_obj.sender = _img_sender
                    if qt:
                        try:
                            msg_obj.quote_token = qt
                        except Exception:
                            pass
                    api.reply_message(ReplyMessageRequest(
                        reply_token=ctx["reply_token"],
                        messages=[msg_obj] + ([_ocr_expression_visual] if _ocr_expression_visual else [])
                    ))
                _event_log_write("image_done", {"path": "auto_translate", "reply_len": len(reply), "method": "reply"})
                _image_delivered = True
            except Exception as _re_reply:
                # v3.9.23: reply_token 過期或無效 → fallback 用 push
                _event_log_write("image_step_error", {"step": "reply", "err": str(_re_reply)[:300], "fallback": "push"})
                logger.warning("Reply failed, trying push: %s", _re_reply)
                try:
                    with ApiClient(configuration) as api_client:
                        api = MessagingApi(api_client)
                        msg_obj = TextMessage(text=reply)
                        if _overlay_qr:
                            msg_obj.quick_reply = _overlay_qr
                        _img_sender = get_sender_object(
                            name_override=get_display_name(group_id, user_id),
                            icon_url_override=get_user_picture_url(group_id, user_id)
                        )
                        if _img_sender:
                            msg_obj.sender = _img_sender
                        api.push_message(PushMessageRequest(
                            to=group_id,
                            messages=[msg_obj] + ([_ocr_expression_visual] if _ocr_expression_visual else [])
                        ))
                    _event_log_write("image_done", {"path": "auto_translate", "reply_len": len(reply), "method": "push"})
                    _image_delivered = True
                except Exception as _pe:
                    _event_log_write("image_step_error", {"step": "push", "err": str(_pe)[:300]})
                    logger.exception("Push also failed: %s", _pe)
        except Exception as _re:
            _event_log_write("image_step_error", {"step": "reply_outer", "err": str(_re)[:300]})
            logger.exception("Reply exception: %s", _re)
        if _image_delivered:
            _complete_durable_image_job(ctx)



    except Exception as _bg_e:
        _event_log_write("image_step_error", {"step": "bg_uncaught", "err": str(_bg_e)[:300]})
        logger.exception("[BG] handle_image_background uncaught: %s", _bg_e)
        # The durable image job remains pending; the worker will retry.
        _send_background_failure_notice(ctx, kind="image", detail="background_uncaught")


def _process_pending_image_translate(event, message_id):
    """Run ask-mode image translation; persist and retry on every exception."""
    try:
        return _process_pending_image_translate_inner(event, message_id)
    except Exception as exc:
        logger.exception("[ImgAsk] uncaught exception deferred durably: %s", exc)
        source = getattr(event, "source", None)
        group_id = (
            getattr(source, "group_id", None)
            or getattr(source, "room_id", None)
            or getattr(source, "user_id", None)
        )
        user_id = getattr(source, "user_id", None)
        _schedule_image_translation_retry({
            "message_id": str(message_id or ""),
            "quote_token": None,
            "group_id": group_id,
            "user_id": user_id,
            "tgt": group_target_lang.get(group_id, "id"),
        }, delay_seconds=2)
        return None

def _process_pending_image_translate_inner(event, message_id):
    """v3.9.10: 詢問模式下,使用者按了「翻譯這張」之後執行實際翻譯。
    重用 handle_image 的下載/OCR/翻譯邏輯,但 reply_token 來自 postback event。
    
    v3.9.11: 增加全程 logging + 最終 fallback push,避免任何路徑靜默失敗。
    v3.9.13: 改用磁碟版 pending(跨 worker)+ 外層 wrapper catch-all。
    """
    # v3.9.13: 從磁碟讀(支援多 worker)
    _all_pending = _load_pending_imgs()
    logger.info("[ImgAsk] postback triggered for msg=%s, pending_count=%d",
                message_id, len(_all_pending))
    
    # v3.9.15: 直接 push(reply_token 已被外層 "🔄 正在翻譯圖片..." 用掉)
    # 從 event.source 抓 group_id;若失敗才 fallback 用 info 裡的
    _src = getattr(event, 'source', None)
    _push_to = (getattr(_src, 'group_id', None) or
                getattr(_src, 'room_id', None) or
                getattr(_src, 'user_id', None))
    
    def _reply_or_push(text, quick_reply=None, append_messages=None):
        target = _push_to
        if not target and info:
            target = info.get("group_id")
        if not target:
            logger.error("[ImgAsk] no push target! cannot send: %s", text[:80])
            return False
        try:
            with ApiClient(configuration) as api_client:
                api = MessagingApi(api_client)
                _msg = TextMessage(text=text)
                if quick_reply:
                    _msg.quick_reply = quick_reply
                _original_uid = (info or {}).get("user_id", "")
                _img_sender = get_sender_object(
                    name_override=get_display_name(target, _original_uid),
                    icon_url_override=get_user_picture_url(target, _original_uid)
                )
                if _img_sender:
                    _msg.sender = _img_sender
                api.push_message(PushMessageRequest(
                    to=target,
                    messages=[_msg] + list(append_messages or [])
                ))
            logger.info("[ImgAsk] push sent to %s: %s", target[:8], text[:80])
            return True
        except Exception as _pe:
            logger.error("[ImgAsk] push failed: %s | text=%s", _pe, text[:80])
            return False

    info = _pending_img_pop(message_id)
    if not info:
        # v3.9.30: 完全靜默 — 兩種情況:
        # (1) 外層已攔截過(已過期)→ 不應該到這裡,但保險
        # (2) Race condition:另一個 worker 已搶先 pop 並處理中 → 那個 worker 會 push 翻譯結果
        # 兩種情況都不該再發訊息打擾群組
        logger.warning("[ImgAsk] message %s not in pending (expired or other worker fetched) → silent", message_id)
        return

    group_id = info["group_id"]
    _ask_retry_ctx = {
        "message_id": str(message_id or ""),
        "group_id": group_id,
        "user_id": (info or {}).get("user_id", ""),
        "quote_token": None,
        "tgt": group_target_lang.get(group_id, "id"),
    }
    _ask_retry_ctx["durable_job_key"] = _schedule_image_translation_retry(
        _ask_retry_ctx, delay_seconds=75
    ) or ""

    if not _has_ai_capability("vision"):
        logger.warning("[ImgAsk] vision provider unavailable; durable image job remains pending")
        return

    show_loading(group_id)

    # 下載圖片
    logger.info("[ImgAsk] downloading image %s", message_id)
    try:
        img_base64, img_raw = download_line_image(message_id)
    except Exception as _de:
        logger.error("[ImgAsk] download exception; durable image job remains pending: %s", _de)
        return
    if not img_base64:
        logger.warning("[ImgAsk] image content unavailable; durable image job remains pending")
        return
    # v3.9.17: 偵測 MIME 格式
    img_mime = detect_image_mime(img_raw)
    logger.info("[ImgAsk] downloaded %d bytes, mime=%s", len(img_raw) if img_raw else 0, img_mime)

    tgt = group_target_lang.get(group_id, "id")
    _bp, _bc = bot_stats.get("tokens_prompt", 0), bot_stats.get("tokens_completion", 0)
    _bcost = bot_stats.get("ant_cost_usd", 0.0) + bot_stats.get("oai_cost_usd", 0.0)
    
    logger.info("[ImgAsk] running OCR")
    try:
        extracted = ocr_image_openai(img_base64, mime_type=img_mime)
    except Exception as _oe:
        logger.error("[ImgAsk] OCR exception; durable image job remains pending: %s", _oe)
        return
    if not extracted or len(extracted.strip()) < 2:
        logger.info("[ImgAsk] OCR returned no text; durable image worker will retry")
        return
    if _is_factory_reason_ocr_failure_text(extracted):
        logger.warning("[ImgAsk] factory reason OCR degraded; using general OCR/translation path: %s", extracted[:120])
    logger.info("[ImgAsk] OCR ok: %d chars", len(extracted))

    # 工單偵測
    try:
        wo_analysis = analyze_work_order(extracted)
        if wo_analysis.get("is_work_order"):
            store_work_order_media_context(
                group_id, (info or {}).get("user_id", ""), message_id
            )
        wo_customer = wo_analysis.get("customer") if wo_analysis.get("is_work_order") else None
        if wo_customer:
            wo_on = group_wo_settings.get(group_id, True)
            if wo_on:
                wo_reply = format_storage_for_work_order(wo_customer)
                if wo_reply:
                    _stats_inc("work_order_detections")
                    _reply_or_push(wo_reply)
            track_group_usage(group_id, _bp, _bc, _bcost)
            _complete_durable_image_job(_ask_retry_ctx)
            return
    except Exception as e:
        logger.error("[ImgAsk] Work order detection error: %s", e)

    lang = detect_language(extracted) or ("zh" if has_chinese(extracted) else "auto")
    actual_tgt = tgt if lang == "zh" else "zh"
    logger.info("[ImgAsk] translating %s -> %s", lang, actual_tgt)

    _tone, _tone_custom = get_group_tone(group_id)
    _tl.tone = _tone
    _tl.tone_custom = _tone_custom
    _tl.group_id = group_id or ""
    _tl.user_id = (info or {}).get("user_id", "")
    _tl.from_image_ocr = True

    # v3.12 IMAGE ROOT FIX:詢問模式也必須與自動圖片相同,只做 OCR → translate()。
    # 不再走圖片直譯專用 prompt,避免繞過工廠用語/詞庫/品質閘門。
    try:
        if lang == "zh":
            result = translate(extracted, "zh", actual_tgt)
        else:
            result = translate(extracted, lang, actual_tgt)
    except Exception as _te:
        logger.error("[ImgAsk] translate exception queued durably: %s", _te)
        _schedule_text_translation_retry(
            {
                "group_id": group_id,
                "user_id": (info or {}).get("user_id", ""),
                "message_id": str(message_id or ""),
            },
            source_text=extracted,
            src_lang=lang,
            target_langs=[actual_tgt],
            line_mentions=[],
            from_image_ocr=True,
        )
        return

    if not result:
        logger.warning("[ImgAsk] translate returned empty; queued durably")
        _schedule_text_translation_retry(
            {
                "group_id": group_id,
                "user_id": (info or {}).get("user_id", ""),
                "message_id": str(message_id or ""),
            },
            source_text=extracted,
            src_lang=lang,
            target_langs=[actual_tgt],
            line_mentions=[],
            from_image_ocr=True,
        )
        track_group_usage(group_id, _bp, _bc, _bcost)
        return

    reply_text = "\U0001f5bc\ufe0f " + LANG_FLAGS.get(actual_tgt, "") + "\n" + result
    if len(reply_text) > 5000:
        reply_text = reply_text[:4990] + "\n..."

    track_group_usage(group_id, _bp, _bc, _bcost)
    try:
        _record_recent_group_message(
            group_id, (info or {}).get("user_id", ""),
            get_display_name(group_id, (info or {}).get("user_id", "")),
            extracted, lang, {actual_tgt: result},
        )
    except Exception:
        pass
    _overlay_token = _store_image_overlay_context(
        img_raw, extracted, result, lang, actual_tgt, group_id
    )
    _ocr_expression_visual = None
    try:
        _ocr_expression_visual = _build_expression_visual_message(
            extracted, result, lang, group_id, from_image_ocr=True
        )
    except Exception as _visual_exc:
        logger.debug("ImgAsk expression visual selection skipped: %s", _visual_exc)
    _stats_inc("image_translations")
    _ask_delivered = _reply_or_push(
        reply_text,
        quick_reply=_build_image_translation_action_quick_reply(
            group_id,
            extracted,
            result,
            lang,
            actual_tgt,
            msg_id=message_id,
            overlay_token=_overlay_token,
        ),
        append_messages=([_ocr_expression_visual] if _ocr_expression_visual else None),
    )
    if _ask_delivered:
        _complete_durable_image_job(_ask_retry_ctx)
    logger.info("[ImgAsk] DONE")


@handler.add(MessageEvent, message=AudioMessageContent)
def handle_audio(event):
    """Handle audio/voice messages: Whisper STT + detect language + translate."""
    # v3.9.30c B15 修補: LINE webhook 重發保護
    if _is_redelivery(event) or _is_duplicate_message(getattr(event.message, 'id', None)):
        logger.warning("[handle_audio] redelivery or duplicate, skipping msg_id=%s",
                       getattr(event.message, 'id', None))
        return
    
    source = event.source
    group_id = getattr(source, 'group_id', None) or getattr(source, 'room_id', None) or getattr(source, 'user_id', None)
    user_id = getattr(source, 'user_id', None)
    is_dm_aud = not getattr(source, 'group_id', None) and not getattr(source, 'room_id', None)

    # v3.9.30c B14 修補: 重置 _tl thread-local 殘留(同 handle_message)
    try:
        _tl.from_image_ocr = False
        _tl.factory_audit = None
        _tl.rtc_fail_reason = None
        _tl.last_entry_id = None
        _tl.gpt_says_announcement = None
        _tl.struct_self_check = None
        _tl.multi_path_fail = None
    except Exception:
        pass

    # Record user for whitelist
    if group_id and user_id and not is_dm_aud:
        record_user_name(group_id, user_id)

    # Check if translation is on
    is_on = group_settings.get(group_id, True)
    if not is_on:
        return

    # Check skip list
    sender_id = user_id
    if sender_id and sender_id in group_skip_users.get(group_id, set()):
        return

    # DM master toggle check for audio
    if is_dm_aud and sender_id:
        if not dm_master_enabled and sender_id not in dm_whitelist:
            return

    # Check if audio translation is on
    audio_on = group_audio_settings.get(group_id, True)
    if not audio_on:
        return

    # Persist before download/transcription so temporary provider outages or
    # process restarts cannot drop the audio translation request.
    _audio_ctx = {
        "group_id": None if is_dm_aud else group_id,
        "user_id": user_id,
        "message_id": str(getattr(event.message, "id", "") or ""),
        "quote_token": get_quote_token(event.message),
        "tgt": group_target_lang.get(group_id, "id"),
    }
    _audio_job_key = _schedule_media_translation_retry(
        _audio_ctx, "audio", delay_seconds=75
    )
    if not oai:
        logger.warning("Immediate audio STT unavailable; durable job retained")
        return

    show_loading(group_id)
    if get_group_feature(group_id, 'mark_read'):
        # v3.11: 帶 mark_as_read_token
        mark_as_read(group_id, mark_as_read_token=getattr(event.message, 'mark_as_read_token', None))

    # Download audio from LINE
    message_id = event.message.id
    audio_bytes = download_line_audio(message_id)
    if not audio_bytes:
        return

    # Transcribe with Whisper
    transcribed = transcribe_audio_openai(audio_bytes)
    if not transcribed or len(transcribed.strip()) < 2:
        return

    # Detect language
    lang = detect_language(transcribed) or ("zh" if has_chinese(transcribed) else "auto")

    tgt = group_target_lang.get(group_id, "id")

    reply = None
    result = None
    actual_tgt = None
    _bp, _bc = bot_stats.get("tokens_prompt", 0), bot_stats.get("tokens_completion", 0)
    _bcost = bot_stats.get("ant_cost_usd", 0.0) + bot_stats.get("oai_cost_usd", 0.0)
    # Set translation tone for this group
    _tone, _tone_custom = get_group_tone(group_id)
    _tl.tone = _tone
    _tl.tone_custom = _tone_custom
    if lang == "zh":
        actual_tgt = tgt
        result = translate(transcribed, "zh", tgt)
        if result:
            reply = "\U0001f3a4 " + LANG_FLAGS.get(tgt, "") + "\n\U0001f4ac " + transcribed + "\n\U0001f4dd " + result
    else:
        # Every incoming language is translatable; group broadcast settings do
        # not suppress audio sent by a worker in another language.
        actual_tgt = "zh"
        result = translate(transcribed, lang, "zh")
        if result:
            reply = "🎤 " + LANG_FLAGS.get("zh", "") + "\n💬 " + transcribed + "\n📝 " + result
    track_group_usage(group_id, _bp, _bc, _bcost)

    if reply is None:
        # v3.10+ 修補:語音翻譯失敗加 log 才能追,但不發群組噪音
        logger.warning("[audio %s] translate returned empty for lang=%s transcribed=%r",
                       group_id, lang, (transcribed or "")[:80])
        try:
            _event_log_write("audio_translate_empty", {
                "group_id": group_id or "",
                "lang": lang,
                "transcribed_preview": (transcribed or "")[:100],
            })
        except Exception:
            pass
        _schedule_text_translation_retry(
            _audio_ctx,
            source_text=transcribed,
            src_lang=lang,
            target_langs=[actual_tgt or (tgt if lang == "zh" else "zh")],
        )
        _complete_durable_media_job(_audio_job_key)
        return

    if not is_dm_aud:
        try:
            _record_recent_group_message(
                group_id, user_id, get_display_name(group_id, user_id),
                transcribed, lang, {actual_tgt: result},
            )
        except Exception:
            pass
    _stats_inc("voice_translations")
    # v3.8: thread quote_token onto the reply so the translation visually
    # references the original audio bubble. Important in busy group chats.
    qt = get_quote_token(event.message)
    msg_obj = TextMessage(text=_clip_line_text(reply))
    _audio_sender = get_sender_object(
        name_override=get_display_name(group_id, user_id),
        icon_url_override=get_user_picture_url(group_id, user_id)
    )
    if _audio_sender:
        msg_obj.sender = _audio_sender
    if qt:
        try:
            msg_obj.quote_token = qt
        except Exception:
            pass
    try:
        _send_reply_with_push_fallback(
            reply_token=event.reply_token,
            target_id=group_id,
            message_obj=msg_obj,
            fallback_text=reply,
            retry_key=str(uuid.uuid5(uuid.NAMESPACE_URL, "jy-media-outbox:" + str(_audio_job_key))),
        )
        _complete_durable_media_job(_audio_job_key)
    except Exception as _audio_send_exc:
        logger.warning("[audio] LINE delivery failed; durable job retained: %s", _audio_send_exc)

    # Voice input can optionally return target-language speech as a second message.
    # Keep TTS asynchronous so it never delays the text translation reply.
    if result and actual_tgt and get_tts_enabled(group_id):
        _threading.Thread(
            target=push_tts_message,
            args=(group_id, result, actual_tgt),
            daemon=True,
        ).start()


