def _build_personal_language_quick_reply(token="", locale="id"):
    if not PostbackAction:
        return None
    items = []
    safe_token = str(token or "")[:80]
    for code, label in _PERSONAL_LANGUAGE_OPTIONS:
        data = "action=set_personal_language&lang=" + code
        if safe_token:
            data += "&token=" + urllib.parse.quote(safe_token, safe="")
        items.append(QuickReplyItem(action=PostbackAction(
            label=label[:20], data=data, display_text=label[:20]
        )))
    return QuickReply(items=items)


def _execute_translation_variant(context, mode, group_id, user_id, preferred=None):
    """Run one translation action with one shared, tested state boundary."""
    if not context:
        return None, "", ""
    source_text = context.get("original", "")
    src_lang = context.get("src", "")
    tgt_lang = context.get("tgt", "")
    if mode == "backcheck":
        source_text = context.get("translated", "")
        src_lang, tgt_lang = tgt_lang, src_lang
    elif mode == "personal":
        preferred = preferred or user_languages.get(user_id) or dm_target_lang.get(user_id)
        if not preferred:
            return None, src_lang, tgt_lang
        tgt_lang = preferred
    if not source_text or not src_lang or not tgt_lang:
        return None, src_lang, tgt_lang

    previous_tl = dict(getattr(_tl, "__dict__", {}))
    try:
        _tl.__dict__.clear()
        _tl.__dict__.update(previous_tl)
        _tl.group_id = group_id or ""
        _tl.user_id = user_id or ""
        _tl.translation_variant = mode
        _tl.quality_gate_critical = True
        # Preserve the exact semantic relation captured when the original
        # translation was created.  This makes 自然/直譯/正式 share one meaning
        # even if the source photo has already expired from media context.
        stored_measurement_context = context.get("measurement_work_order_context")
        if (src_lang == "id" and tgt_lang == "zh"
                and isinstance(stored_measurement_context, bool)):
            _tl.measurement_work_order_context_override = stored_measurement_context
        else:
            _tl.measurement_work_order_context_override = None
        _tone, _tone_custom = get_group_tone(group_id)
        _tl.tone = _tone
        _tl.tone_custom = _tone_custom

        if mode == "personal" and tgt_lang == context.get("src"):
            result = context.get("original", "")
        elif mode == "personal" and tgt_lang == context.get("tgt"):
            result = context.get("translated", "")
        else:
            canonical = source_text
            if src_lang == "zh" and tgt_lang == "id":
                canonical, _ = resolve_factory_station_aliases(source_text)
            elif src_lang == "id" and id_preprocessing_enabled:
                canonical, _ = normalize_indonesian_text(source_text)
            result = _translate_variant_preserving_mentions(canonical, src_lang, tgt_lang)
        return result, src_lang, tgt_lang
    except Exception as exc:
        logger.exception("[translation_variant] %s failed: %s", mode, exc)
        return None, src_lang, tgt_lang
    finally:
        _tl.__dict__.clear()
        _tl.__dict__.update(previous_tl)

if PostbackEvent:
    @handler.add(PostbackEvent)
    def handle_postback(event):
        """Handle postback actions from Quick Reply / Flex buttons."""
        # v3.9.30c B18 修補: postback 也會 redelivery,且會跑翻譯花錢
        # postback 沒有 message.id,改用 reply_token 當 dedup key(每個 reply_token 唯一)
        if _is_redelivery(event):
            logger.warning("[handle_postback] redelivery, skipping")
            return
        _rtok = getattr(event, 'reply_token', None)
        if _rtok and _is_duplicate_message("pbk:" + _rtok):
            logger.warning("[handle_postback] duplicate reply_token, skipping")
            return
        data = event.postback.data if hasattr(event.postback, 'data') else ""
        logger.info("Postback: %s", data)

        # Parse postback data (format: action=X&lang=Y&...)
        try:
            params = dict(urllib.parse.parse_qsl(data))
        except Exception:
            params = {}

        action = params.get("action", "")

        # Multilingual one-click actions.  Controls are bilingual and use
        # postbacks so users never need to memorise Chinese-only slash commands.
        if action == "handover_summary":
            _group = getattr(event.source, 'group_id', None) or getattr(event.source, 'room_id', None)
            _uid = getattr(event.source, 'user_id', None) or ""
            if not _group:
                result_text = (
                    "⚠️ 交班摘要只能在群組使用。\n"
                    "⚠️ Ringkasan serah terima hanya dapat digunakan di grup."
                )
            else:
                token = params.get("token", "")
                context = _get_translation_action_context(token, _group) if token else None
                extra_rows = []
                if context:
                    src = str(context.get("src", "") or "").strip()
                    tgt = str(context.get("tgt", "") or "").strip()
                    original = str(context.get("original", "") or "").strip()
                    translated = str(context.get("translated", "") or "").strip()
                    if src and tgt and original and translated:
                        extra_rows.append({
                            "timestamp": time.time(),
                            "sender": "",
                            "source_language": src,
                            "source_text": original,
                            "translations": {tgt: translated},
                        })
                result_text = build_group_handover_summary(
                    _group, hours=12, extra_rows=extra_rows
                )
            try:
                with ApiClient(configuration) as api_client:
                    MessagingApi(api_client).reply_message(ReplyMessageRequest(
                        reply_token=event.reply_token,
                        messages=[TextMessage(text=_clip_line_text(result_text))],
                    ))
            except Exception as exc:
                logger.warning("handover postback reply failed: %s", exc)
            return

        if action == "open_interpreter":
            _group = getattr(event.source, 'group_id', None) or getattr(event.source, 'room_id', None)
            _uid = getattr(event.source, 'user_id', None) or ""
            result_text = handle_interpreter_command(_group, _uid)
            try:
                with ApiClient(configuration) as api_client:
                    MessagingApi(api_client).reply_message(ReplyMessageRequest(
                        reply_token=event.reply_token,
                        messages=[TextMessage(text=_clip_line_text(result_text))],
                    ))
            except Exception as exc:
                logger.warning("interpreter postback reply failed: %s", exc)
            return

        if action == "show_language_menu":
            _gid = (getattr(event.source, 'group_id', None)
                    or getattr(event.source, 'room_id', None)
                    or getattr(event.source, 'user_id', None))
            _uid = getattr(event.source, 'user_id', None) or ""
            token = params.get("token", "")
            context = _get_translation_action_context(token, _gid) if token else None
            locale = _translation_action_locale(
                context.get("src") if context else "",
                context.get("tgt") if context else "id",
            )
            current = user_languages.get(_uid) or dm_target_lang.get(_uid)
            try:
                with ApiClient(configuration) as api_client:
                    MessagingApi(api_client).reply_message(ReplyMessageRequest(
                        reply_token=event.reply_token,
                        messages=[TextMessage(
                            text=_personal_language_menu_text(locale, current),
                            quick_reply=_build_personal_language_quick_reply(token, locale),
                        )],
                    ))
            except Exception as exc:
                logger.warning("language menu reply failed: %s", exc)
            return

        if action == "set_personal_language":
            _group = getattr(event.source, 'group_id', None) or getattr(event.source, 'room_id', None)
            _uid = getattr(event.source, 'user_id', None) or ""
            _gid = _group or _uid
            code = translation_extras_module.normalize_personal_language(params.get("lang", ""))
            if not _uid or not code:
                try:
                    with ApiClient(configuration) as api_client:
                        MessagingApi(api_client).reply_message(ReplyMessageRequest(
                            reply_token=event.reply_token,
                            messages=[TextMessage(text=(
                                "⚠️ 無法儲存語言設定。\n"
                                "⚠️ Pengaturan bahasa tidak dapat disimpan."
                            ))],
                        ))
                except Exception:
                    pass
                return

            user_languages[_uid] = code
            dm_target_lang[_uid] = code
            try:
                save_settings(force=True)
            except TypeError:
                save_settings()
            except Exception as exc:
                logger.warning("save personal language failed: %s", exc)

            display = _language_name_bilingual(code)
            confirmation = (
                "✅ 閱讀語言已設定：{}\n"
                "✅ Bahasa bacaan diatur: {}"
            ).format(display, display)
            token = params.get("token", "")
            context = _get_translation_action_context(token, _gid) if token else None
            if not context:
                try:
                    with ApiClient(configuration) as api_client:
                        MessagingApi(api_client).reply_message(ReplyMessageRequest(
                            reply_token=event.reply_token,
                            messages=[TextMessage(text=confirmation)],
                        ))
                except Exception:
                    pass
                return

            show_loading(_gid)
            result, _src_lang, _tgt_lang = _execute_translation_variant(
                context, "personal", _gid, _uid, preferred=code
            )
            if not result:
                result_text = confirmation + (
                    "\n\n⚠️ 這次個人語言版本無法產生。\n"
                    "⚠️ Versi bahasa pribadi belum dapat dibuat."
                )
                try:
                    with ApiClient(configuration) as api_client:
                        MessagingApi(api_client).reply_message(ReplyMessageRequest(
                            reply_token=event.reply_token,
                            messages=[TextMessage(text=_clip_line_text(result_text))],
                        ))
                except Exception:
                    pass
                return

            personal_text = "👤 {}\n{}".format(display, result)
            # In a group, keep the personal version private when LINE permits
            # push messages.  If the user has not friended the bot, reply in the
            # current chat rather than making the button appear broken.
            if _group:
                try:
                    with ApiClient(configuration) as api_client:
                        api = MessagingApi(api_client)
                        api.push_message(PushMessageRequest(
                            to=_uid,
                            messages=[TextMessage(text=_clip_line_text(personal_text))],
                        ))
                        api.reply_message(ReplyMessageRequest(
                            reply_token=event.reply_token,
                            messages=[TextMessage(text=(
                                confirmation +
                                "\n📩 已私訊個人語言版本。\n"
                                "📩 Versi bahasa pribadi dikirim lewat chat pribadi."
                            ))],
                        ))
                    return
                except Exception as exc:
                    logger.info("personal language push unavailable; replying in chat: %s", exc)
            try:
                with ApiClient(configuration) as api_client:
                    MessagingApi(api_client).reply_message(ReplyMessageRequest(
                        reply_token=event.reply_token,
                        messages=[TextMessage(text=_clip_line_text(confirmation + "\n\n" + personal_text))],
                    ))
            except Exception as exc:
                logger.warning("personal language reply failed: %s", exc)
            return

        if action == "translation_variant":
            _gid = (getattr(event.source, 'group_id', None)
                    or getattr(event.source, 'room_id', None)
                    or getattr(event.source, 'user_id', None))
            _uid = getattr(event.source, 'user_id', None) or ""
            mode = (params.get("mode") or "").strip().lower()
            token = params.get("token", "")
            context = _get_translation_action_context(token, _gid)
            if mode == "personal":
                locale = _translation_action_locale(
                    context.get("src") if context else "",
                    context.get("tgt") if context else "id",
                )
                current = user_languages.get(_uid) or dm_target_lang.get(_uid)
                try:
                    with ApiClient(configuration) as api_client:
                        MessagingApi(api_client).reply_message(ReplyMessageRequest(
                            reply_token=event.reply_token,
                            messages=[TextMessage(
                                text=_personal_language_menu_text(locale, current),
                                quick_reply=_build_personal_language_quick_reply(
                                    token if context else "", locale
                                ),
                            )],
                        ))
                except Exception as exc:
                    logger.warning("personal language menu failed: %s", exc)
                return

            allowed_modes = {"natural", "literal", "formal", "backcheck"}
            if mode not in allowed_modes or not context:
                locale = _translation_action_locale(
                    context.get("src") if context else "",
                    context.get("tgt") if context else "id",
                )
                try:
                    with ApiClient(configuration) as api_client:
                        MessagingApi(api_client).reply_message(ReplyMessageRequest(
                            reply_token=event.reply_token,
                            messages=[TextMessage(text=_TRANSLATION_ACTION_UI[locale]["expired"])],
                        ))
                except Exception:
                    pass
                return

            labels = _translation_action_labels(context.get("src"), context.get("tgt"))
            show_loading(_gid)
            result, _src_lang, _tgt_lang = _execute_translation_variant(
                context, mode, _gid, _uid
            )
            if not result:
                fail_text = (
                    "⚠️ 無法產生這個版本。\n"
                    "⚠️ Versi ini belum dapat dibuat."
                )
                try:
                    with ApiClient(configuration) as api_client:
                        MessagingApi(api_client).reply_message(ReplyMessageRequest(
                            reply_token=event.reply_token,
                            messages=[TextMessage(text=fail_text)],
                        ))
                except Exception:
                    pass
                return
            reply_text = labels[mode] + "\n" + result
            try:
                with ApiClient(configuration) as api_client:
                    MessagingApi(api_client).reply_message(ReplyMessageRequest(
                        reply_token=event.reply_token,
                        messages=[TextMessage(text=_clip_line_text(reply_text))],
                    ))
            except Exception as exc:
                logger.warning("[translation_variant] reply failed: %s", exc)
            return

        if action == "image_overlay":
            _gid = (getattr(event.source, 'group_id', None)
                    or getattr(event.source, 'room_id', None)
                    or getattr(event.source, 'user_id', None))
            context = _load_image_overlay_context(params.get("token", ""), _gid)
            public_url = (os.environ.get("PUBLIC_URL") or "").rstrip("/")
            if not context or not public_url or not ImageMessage:
                msg = ("⚠️ 圖片資料已過期，請重新傳送圖片。" if not context else
                       "⚠️ 產生對照圖需要設定 PUBLIC_URL 並使用支援 ImageMessage 的 LINE SDK。")
                try:
                    with ApiClient(configuration) as api_client:
                        MessagingApi(api_client).reply_message(ReplyMessageRequest(
                            reply_token=event.reply_token,
                            messages=[TextMessage(text=msg)],
                        ))
                except Exception:
                    pass
                return
            try:
                with ApiClient(configuration) as api_client:
                    MessagingApi(api_client).reply_message(ReplyMessageRequest(
                        reply_token=event.reply_token,
                        messages=[TextMessage(text="🖼 正在產生原圖＋譯文對照圖…")],
                    ))
            except Exception:
                pass

            def _render_and_push_overlay(target=_gid, payload=context, base_url=public_url):
                try:
                    rendered = translation_extras_module.render_translation_comparison_image(
                        payload["image_bytes"],
                        payload.get("source_text", ""),
                        payload.get("translated_text", ""),
                        source_label="原文 " + LANG_FLAGS.get(payload.get("src_lang", ""), ""),
                        target_label="譯文 " + LANG_FLAGS.get(payload.get("tgt_lang", ""), ""),
                    )
                    media_token = _store_generated_overlay_image(rendered)
                    if not media_token:
                        raise RuntimeError("failed to store rendered image")
                    url = base_url + "/media/translation/" + media_token + ".jpg"
                    with ApiClient(configuration) as api_client:
                        MessagingApi(api_client).push_message(PushMessageRequest(
                            to=target,
                            messages=[ImageMessage(
                                originalContentUrl=url,
                                previewImageUrl=url,
                            )],
                        ))
                except Exception as exc:
                    logger.exception("image overlay rendering failed: %s", exc)
                    try:
                        with ApiClient(configuration) as api_client:
                            MessagingApi(api_client).push_message(PushMessageRequest(
                                to=target,
                                messages=[TextMessage(text="⚠️ 對照圖產生失敗，文字譯文仍可正常使用。")],
                            ))
                    except Exception:
                        pass

            _threading.Thread(target=_render_and_push_overlay, daemon=True).start()
            return

        # v3.10: onboarding 語言選擇按鈕
        if action == "onboard_lang":
            try:
                if handle_onboarding_postback(event, params):
                    return
            except NameError:
                pass

        # v3.14: 語言設定面板切換按鈕(admin)
        if action == "langtoggle":
            try:
                if handle_langtoggle_postback(event, params):
                    return
            except NameError:
                pass

        # v3.14: 開啟語言設定面板(任何人可看,改動仍 admin 限定)
        if action == "langpanel":
            _gid = getattr(event.source, 'group_id', None) or getattr(event.source, 'room_id', None)
            if _gid:
                try:
                    send_lang_panel_flex(event.reply_token, _gid)
                except NameError:
                    pass
            return

        # v3.10: LV4 flex card 互動按鈕 — 查儲區
        if action == "qry":
            q = params.get("q", "").strip()
            if q:
                _gid = getattr(event.source, 'group_id', None) or getattr(event.source, 'room_id', None) or ""
                if not is_cmd_enabled(_gid, "qry"):
                    return
                try:
                    qry_result = handle_qry_command("/qry " + q)
                    # 即使查無結果也要 reply,避免工人按按鈕沒反應
                    reply_text = qry_result or ("🔍 查無此單: " + q + "\n🔍 Tidak ada: " + q)
                    with ApiClient(configuration) as api_client:
                        api = MessagingApi(api_client)
                        api.reply_message(ReplyMessageRequest(
                            reply_token=event.reply_token,
                            messages=[TextMessage(text=_clip_line_text(reply_text))],
                        ))
                except Exception as e:
                    logger.warning("[postback qry] failed: %s", e)
            return

        # v3.10: LV4 flex card 互動按鈕 — 重唸 TTS
        if action == "tts_replay":
            _gid = getattr(event.source, 'group_id', None) or getattr(event.source, 'room_id', None)
            tts_text = params.get("t", "").strip()
            tts_lang = params.get("lang", "id").strip()
            if not _gid or not tts_text:
                return
            try:
                if not get_tts_enabled(_gid):
                    with ApiClient(configuration) as api_client:
                        api = MessagingApi(api_client)
                        api.reply_message(ReplyMessageRequest(
                            reply_token=event.reply_token,
                            messages=[TextMessage(text="⚠️ TTS 未開啟,需 admin 用 /liff 設定")],
                        ))
                    return
                # ack reply (reply_token 1 min 內必須用)
                with ApiClient(configuration) as api_client:
                    api = MessagingApi(api_client)
                    api.reply_message(ReplyMessageRequest(
                        reply_token=event.reply_token,
                        messages=[TextMessage(text="🔊 重唸中... / Memutar ulang...")],
                    ))
                # push TTS (背景)— v3.29: 失敗時推具體原因,不再無聲消失
                def _tts_replay_bg(gid=_gid, t=tts_text, lg=tts_lang):
                    _ok, _reason = push_tts_message(gid, t, lg, want_reason=True)
                    if _ok:
                        return
                    try:
                        with ApiClient(configuration) as _ac:
                            MessagingApi(_ac).push_message(PushMessageRequest(
                                to=gid, messages=[TextMessage(
                                    text="⚠️ 語音合成失敗:" + _reason)]))
                    except Exception:
                        pass
                _threading.Thread(target=_tts_replay_bg, daemon=True).start()
            except Exception as e:
                logger.warning("[postback tts_replay] failed: %s", e)
            return

        # /help language switch: re-send Flex with the other language first
        if action == "help":
            lang = params.get("lang", "zh")
            if lang not in ("zh", "id"):
                lang = "zh"
            # 切換語言時也要重新檢查管理員身分(誰按按鈕就以誰的權限重建)
            _uid = getattr(event.source, "user_id", None)
            send_help_flex(event.reply_token, primary_lang=lang,
                           is_admin=is_group_admin(_uid))
            return

        # v3.9.10: 圖片翻譯詢問模式 — 使用者按了「翻譯這張」
        if "img_translate" in params:
            msg_id = params["img_translate"]
            logger.info("[ImgAsk] postback received, msg_id=%s", msg_id)

            # v3.9.30: 過期 / 已處理 → 完全靜默,不發任何訊息(避免騷擾群組)
            # 先檢查 pending 是否還在;不在就直接 return,連 ack 都不發
            _pending_check = _load_pending_imgs()
            if msg_id not in _pending_check:
                logger.info("[ImgAsk] msg_id=%s not in pending (expired or already processed) → silent ignore", msg_id)
                return

            # 只有確認還在 pending 才 ack + 進入翻譯流程
            # 立刻 reply 確認收到(reply_token 必須在 1 分鐘內用掉)
            # 然後用 push 發實際翻譯結果(OCR + translate 可能需要 10+ 秒)
            try:
                with ApiClient(configuration) as api_client:
                    api = MessagingApi(api_client)
                    api.reply_message(ReplyMessageRequest(
                        reply_token=event.reply_token,
                        messages=[TextMessage(text="🔄 正在翻譯圖片...\nSedang menerjemahkan gambar...")]
                    ))
                logger.info("[ImgAsk] ack reply sent")
            except Exception as _ake:
                logger.warning("[ImgAsk] ack reply failed (token may be expired): %s", _ake)
            # 然後處理 OCR + 翻譯,用 push 送結果
            _process_pending_image_translate(event, msg_id)
            return
        if "img_skip" in params:
            # v3.9.30: 舊版 Flex 殘留的按鈕(新版已移除「跳過」),保留處理避免 500
            # 過期 → 完全靜默;還在 pending → pop 掉並回覆已跳過
            _msgid = params["img_skip"]
            _pending_check = _load_pending_imgs()
            if _msgid not in _pending_check:
                logger.info("[ImgAsk] img_skip msg_id=%s expired → silent ignore", _msgid)
                return
            _pending_img_pop(_msgid)
            try:
                with ApiClient(configuration) as api_client:
                    api = MessagingApi(api_client)
                    api.reply_message(ReplyMessageRequest(
                        reply_token=event.reply_token,
                        messages=[TextMessage(text="✅ 已跳過 / Dilewati")]
                    ))
            except Exception:
                pass
            return


