def batch_unlink_rich_menu(user_ids):
    """Unlink rich menu from multiple users at once."""
    try:
        with ApiClient(configuration) as api_client:
            api = MessagingApi(api_client)
            api.unlink_rich_menu_id_from_users(user_ids=user_ids)
            return True
    except Exception as e:
        logger.warning("Batch rich menu unlink failed: %s", e)
        return False


def add_line_emoji_to_text(text, emoji_product_id="5ac1bfd5040ab15980c9b435", emoji_ids=None):
    """Build a TextMessage with LINE emojis embedded.
    This is a helper - LINE emojis use $placeholder in text + emojis array."""
    # LINE emoji format: text has $ placeholders, emojis array maps each
    # For simplicity, return a TextMessage with emoji support
    try:
        if not emoji_ids:
            return TextMessage(text=text)
        emojis = []
        for i, eid in enumerate(emoji_ids):
            emojis.append({
                "index": text.index("$", sum(1 for c in text[:text.index("$")] if True)),
                "productId": emoji_product_id,
                "emojiId": eid
            })
        return TextMessage(text=text, emojis=emojis)
    except Exception:
        return TextMessage(text=text)


def build_translation_flex(original, translated, src_flag, tgt_flag, sender_name_display=None, quoted_text=None):
    """Build a Flex Message for translation with original + translated text."""
    try:
        body_contents = []
        # Quoted message context (if replying to another message)
        if quoted_text:
            qt = quoted_text[:50] + "..." if len(quoted_text) > 50 else quoted_text
            body_contents.append({
                "type": "text", "text": "↩ " + qt,
                "size": "xxs", "color": "#6a6a7a", "wrap": True, "margin": "none",
                "style": "italic"
            })
            body_contents.append({"type": "separator", "margin": "sm"})
        # Sender name
        if sender_name_display:
            body_contents.append({
                "type": "text", "text": sender_name_display,
                "size": "xs", "color": "#8a8a9a", "margin": "none"
            })
        # Original text
        body_contents.append({
            "type": "text", "text": src_flag + " " + original,
            "size": "sm", "color": "#b0b0b0", "wrap": True, "margin": "sm"
        })
        # Separator
        body_contents.append({"type": "separator", "margin": "md"})
        # Translated text
        body_contents.append({
            "type": "text", "text": tgt_flag + " " + translated,
            "size": "md", "color": "#ffffff", "wrap": True, "margin": "md", "weight": "bold"
        })

        flex_obj = {
            "type": "bubble",
            "size": "kilo",
            "body": {
                "type": "box", "layout": "vertical",
                "contents": body_contents,
                "backgroundColor": "#1a1a2e",
                "paddingAll": "16px",
                "cornerRadius": "12px"
            }
        }
        return FlexMessage(
            alt_text=tgt_flag + " " + translated,
            contents=FlexContainer.from_dict(flex_obj)
        )
    except Exception as e:
        logger.warning("Flex message build failed, falling back to text: %s", e)
        return None


def build_quick_reply(group_id=None):
    """Build Quick Reply buttons from quick_reply_items_settings (v3.11 完全後台化).
    
    - 順序 / 顯示 / label / text 全部從後台設定。
    - cmd_check 欄位仍會檢查 is_cmd_enabled(),指令本身被關掉時按鈕也跳過。
    - external_links_settings 仍動態追加在最後(這個是另一個獨立管理層)。
    - LINE Quick Reply 硬上限 13 顆。
    """
    LINE_QR_HARD_LIMIT = 13
    items = []
    try:
        for cfg in quick_reply_items_settings:
            if len(items) >= LINE_QR_HARD_LIMIT:
                logger.warning("[QuickReply] hit %d-item LINE limit at custom-items stage", LINE_QR_HARD_LIMIT)
                break
            if not cfg.get("enabled", True):
                continue
            cmd_check = cfg.get("cmd_check")
            if cmd_check and not is_cmd_enabled(group_id, cmd_check):
                continue
            label = (cfg.get("label", "") or "").strip()[:20]
            if not label:
                continue
            t = cfg.get("type", "message")
            try:
                if t == "message":
                    text = (cfg.get("text", "") or "").strip()
                    if not text:
                        continue
                    items.append(QuickReplyItem(action=MessageAction(label=label, text=text)))
                elif t == "camera":
                    if not MsgCameraAction:
                        continue
                    items.append(QuickReplyItem(action=MsgCameraAction(label=label)))
                elif t == "camera_roll":
                    if not MsgCameraRollAction:
                        continue
                    items.append(QuickReplyItem(action=MsgCameraRollAction(label=label)))
                elif t == "location":
                    if not MsgLocationAction:
                        continue
                    items.append(QuickReplyItem(action=MsgLocationAction(label=label)))
                elif t == "clipboard":
                    if not MsgClipboardAction:
                        continue
                    clip = cfg.get("clipboard_text", "") or ""
                    items.append(QuickReplyItem(action=MsgClipboardAction(label=label, clipboard_text=clip)))
            except Exception as _bie:
                logger.warning("[QuickReply] build item failed id=%s: %s", cfg.get("id"), _bie)
        # external_links_settings → 動態追加(保留 v3.9.39+ 行為)
        try:
            for _link_key, _link_cfg in external_links_settings.items():
                if len(items) >= LINE_QR_HARD_LIMIT:
                    logger.warning("[QuickReply] hit %d-item LINE limit, skipping remaining external links",
                                   LINE_QR_HARD_LIMIT)
                    break
                if not _link_cfg.get("enabled", True):
                    continue
                if not _link_cfg.get("url", "").strip():
                    continue
                _btn_label_zh = _link_cfg.get("label_zh", "").strip()
                _btn_label_id = _link_cfg.get("label_id", "").strip()
                if _btn_label_zh and _btn_label_id:
                    _full_label = f"{_btn_label_zh}/{_btn_label_id}"
                else:
                    _full_label = _btn_label_zh or _btn_label_id or _link_key
                _full_label = _full_label[:20]
                items.append(QuickReplyItem(action=MessageAction(
                    label=_full_label,
                    text=f"/{_link_key}"
                )))
        except Exception:
            pass
        if not items:
            return None
        return QuickReply(items=items)
    except Exception as e:
        logger.warning("build_quick_reply failed: %s", e)
        return None


