    document.getElementById('glossaryActions').style.display='none';
    document.getElementById('glossaryPreview').innerHTML='<div class="card"><div style="color:#43b581;font-weight:600">✅ 已更新 '+d.count+' 筆詞條</div><div class="card-sub" style="margin-top:4px">'+ghStatus+'</div></div>';
