@app.route("/api/admin/ai-provider/gemini-config", methods=["POST"])
def api_admin_ai_provider_gemini_config():
    """v3.22: Gemini 完整後台設定 — 短/長模型 + reasoning effort,一個端點全收。"""
    if not check_manager_access("aiprovider"):
        return jsonify({"error": "forbidden"}), 403
    data = request.get_json(silent=True) or {}
    msgs = []
    dm = (data.get("default_model") or "").strip()
    um = (data.get("upgrade_model") or "").strip()
    if dm or um:
        # 防呆:只接受 gemini-* 名稱,避免誤存其他家模型名
        for _m in (dm, um):
            if _m and not _m.startswith("gemini"):
                return jsonify({"ok": False, "message": f"模型名須為 gemini-* :{_m}"}), 400
        ok, msg = ai_provider.update_gemini_models(dm or None, um or None)
        if not ok:
            return jsonify({"ok": False, "message": msg}), 500
        msgs.append(msg)
    effort = (data.get("reasoning_effort") or "").strip().lower()
    if effort:
        if effort not in ("minimal", "low", "medium", "high"):
            return jsonify({"ok": False, "message": "reasoning_effort 須為 minimal/low/medium/high"}), 400
        ok, msg = ai_provider.update_gemini_features({"reasoning_effort": effort})
        if not ok:
            return jsonify({"ok": False, "message": msg}), 500
        msgs.append(msg)
    if not msgs:
        return jsonify({"ok": False, "message": "沒有可更新的欄位"}), 400
    save_settings(force=True)
    return jsonify({"ok": True, "message": ";".join(msgs)})


@app.route("/api/admin/ai-provider/count-tokens", methods=["POST"])
def api_admin_ai_provider_count_tokens():
    """v3.1 D3 Phase 16: 預估 token + 成本(基準 prompt + glossary)
    
    跑一個簡短的代表性翻譯場景,讓歐那看到一次完整翻譯會吃多少 token。
    """
    if not check_manager_access("aiprovider"):
        return jsonify({"error": "forbidden"}), 403
    if ai_provider.get_active_provider() != "anthropic":
        return jsonify({"ok": False, "message": "請先切到 Anthropic provider"}), 400
    try:
        # 用一個代表性 prompt + glossary 來估
        sys_prompt = (
            "你是專業的工廠中文↔印尼文翻譯助手。\n"
            "規則:\n"
            "1. 忠實翻譯,不增刪內容\n"
            "2. 不加註解、不加禮貌前綴\n"
            "3. 工廠語氣,直接明白\n"
            "4. 引用 search_result 內的標準譯名\n"
        )
        sample_msg = "鋼帶不夠了,打包機停了,叫主管來看一下"
        result = ai_provider.count_tokens(
            model=ai_provider.DEFAULT_OPENAI_MODEL,
            messages=[
                {"role": "system", "content": sys_prompt},
                {"role": "user", "content": sample_msg},
            ],
        )
        if result is None:
            return jsonify({"ok": False, "message": "count_tokens 失敗,可能 SDK 版本太舊"})
        return jsonify({"ok": True, "result": result})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500


