@app.route("/api/admin/glossary/upload", methods=["POST"])
def api_admin_glossary_upload():
    """Upload Excel 自動解析多 sheet,中文 key 去拼音括號,寫入 GLOSSARY_LOOKUP 並推 GitHub。
    
    Excel 預期格式(第 3 列開始,第 4 列為資料起點):
      欄 A = No / 欄 B = 中文名稱(含拼音) / 欄 C = 印尼名稱 / 欄 D = 中文說明 / 欄 E = 印尼說明
    自動跳過:
      - 表頭列(找到「No」「中文名稱」標題)
      - 空白範本列(「請填入中文名稱」)
      - 任一 zh/idn 為空的列
    """
    global GLOSSARY_LOOKUP
    if not check_manager_access("glossary"):
        return jsonify({"error": "forbidden"}), 403
    if 'file' not in request.files:
        return jsonify({"error": "沒有檔案"}), 400
    f = request.files['file']
    if not f.filename:
        return jsonify({"error": "沒有檔案"}), 400
    try:
        import openpyxl
        wb = openpyxl.load_workbook(f, data_only=True)
        new_data = {}
        sheets_processed = 0
        # 從第 4 列起讀(範本規定:列 1-3 為標題/製作資訊/欄頭)
        for sn in wb.sheetnames:
            ws = wb[sn]
            sheet_hits = 0
            for row in ws.iter_rows(min_row=4, values_only=True):
                if not row or len(row) < 3:
                    continue
                zh, idn = row[1], row[2]
                note_zh = row[3] if len(row) > 3 else ""
                note_id = row[4] if len(row) > 4 else ""
                if not zh or not idn:
                    continue
                zh_s = str(zh).strip()
                idn_s = str(idn).strip()
                if not zh_s or not idn_s:
                    continue
                # 跳過範本/標題/雜訊
                _BLOCKLIST_ZH = {"中文名稱", "No", "設備面盤照片", "操作盤名稱", "印文翻譯"}
                if zh_s.startswith("請填入") or zh_s in _BLOCKLIST_ZH:
                    continue
                if idn_s.startswith("(翻譯填寫)") or idn_s == "印尼名稱":
                    continue
                # 去掉中文 key 的拼音括號跟換行
                zh_clean = re.sub(r'\s*\([^)]*\)\s*', '', zh_s).replace('\\n', '').replace('\n', '').strip()
                idn_clean = idn_s.replace('\\n', ' ').replace('\n', ' ').strip()
                if not zh_clean:
                    continue
                # 同 key 先到先得(因表通常從重要 sheet 開始)
                if zh_clean not in new_data:
                    new_data[zh_clean] = {
                        "idn": idn_clean,
                        "note_zh": str(note_zh).strip() if note_zh else "",
                        "note_id": str(note_id).strip() if note_id else ""
                    }
                    sheet_hits += 1
            if sheet_hits > 0:
                sheets_processed += 1
        if not new_data:
            return jsonify({"error": "無法解析 Excel,請確認格式:\n欄 B=中文名稱 欄 C=印尼名稱 欄 D=中文說明 欄 E=印尼說明,從第 4 列起"}), 400
        # Update in-memory through the same central policy used at startup.
        # This prevents an uploaded descriptive row from becoming a mandatory
        # literal phrase in prompts/TM/enforcement.
        new_data = gp_module.normalize_glossary(new_data)
        GLOSSARY_LOOKUP = new_data
        logger.info("Glossary updated via admin: %d terms from %d sheets", len(new_data), sheets_processed)
        # ★ v2.0: 重新註冊給 ai_provider
        try:
            ai_provider.register_glossary(GLOSSARY_LOOKUP)
            ge_module.invalidate_glossary_cache()
        except Exception as _e:
            logger.warning("re-register_glossary 失敗: %s", _e)
        # v3.9.32: 同步重建印→中反向索引
        try:
            rebuild_glossary_reverse_index()
        except Exception as _e:
            logger.warning("rebuild_glossary_reverse_index 失敗: %s", _e)
        # Auto-commit to GitHub
        json_str = json.dumps(new_data, ensure_ascii=False, indent=2)
        gh_ok = commit_glossary_to_github(json_str)
        msg = "已更新 " + str(len(new_data)) + " 筆詞條(來自 " + str(sheets_processed) + " 個工作表)"
        if gh_ok:
            msg += "(已自動推送 GitHub,將永久生效)"
        else:
            msg += "(GitHub 推送失敗,僅暫時生效)"
        return jsonify({"ok": True, "count": len(new_data), "sheets": sheets_processed, "github": gh_ok, "message": msg})
    except Exception as e:
        logger.error("Glossary upload error: %s", e)
        return jsonify({"error": "解析失敗: " + str(e)}), 400


