# ============================================================================
# Conversation Context Ring Buffer (上下文記憶,讓 AI 看得懂接話)
# ============================================================================
# 目的:解決翻譯時看不到上下文導致誤譯的問題。
#   範例:小麥說「什麼事都沒做就默默升官了」
#        Dato 接話「要被調走了要升一下」
#   沒上下文:AI 把「升一下」翻成 "dinaikkan" (物理抬起來) → 錯
#   有上下文:AI 看到上一句「升官」→ 知道這裡的「升」是升職 → 翻成 "naik jabatan"
#
# 設計原則 (照官方文件):
# 1. 只保留最近 N 對 (預設 4 對 = 8 條 user+assistant)
# 2. 歷史對話只「附加」不「修改」 → 維持 prefix 穩定 → 兩家 API 都能 cache
# 3. OpenAI 自動 prompt caching (≥1024 tokens 自動 50% off, 無需改 code)
# 4. Anthropic 用 cache_control 標記 (cache reads 10% 原價, cache writes 125%)
# 5. 第一次翻譯付 cache write 略貴,第二次起 cache hit 比原本還便宜

from collections import deque

# {group_id: deque([(原文,翻譯,src_lang,tgt_lang,timestamp), ...])}
group_conversation_buffer = {}
_conv_buffer_lock = _threading_v310.Lock()

# {group_id: bool} — 上下文記憶 per-group 開關 (獨立於 flex_v2,因為這是翻譯邏輯不是視覺)
group_conv_settings = globals().get("group_conv_settings", {})

# 預設保留最近 4 對對話 = 8 條 messages。可在後台 per-group 調整。
CONV_BUFFER_DEFAULT_TURNS = 4
CONV_BUFFER_MAX_TURNS = 8         # 上限,避免 token 爆炸
CONV_BUFFER_TTL_SECONDS = 3600    # v3.11(2026-05-26): 10 分鐘改 1 小時
                                  # 原因:工廠對話節奏較慢,班長/組長回覆常隔 20-40 分鐘,
                                  # 10 分鐘 TTL 會把上下文清掉,導致「兩把都放了」這種
                                  # 接話訊息失去「放行」語意(誤譯成 sudah di-taruh)。
                                  # 1 小時內主題不易跨大跳,副作用低。
CONV_BUFFER_MAX_LEN_PER_MSG = 200 # 單條訊息超過 200 字會截斷,避免大段文章吃掉 cache


def _conv_buffer_get(group_id, max_turns=None):
    """取出該群組最近 N 對對話。回傳 list of dict
    [{src, tgt, src_text, tgt_text, ts}, ...]
    舊到新排列。"""
    if not group_id:
        return []
    n = max_turns or CONV_BUFFER_DEFAULT_TURNS
    with _conv_buffer_lock:
        buf = group_conversation_buffer.get(group_id)
        if not buf:
            return []
        now = time.time()
        # 過濾過期項目
        valid = [e for e in buf if (now - e.get("ts", 0)) <= CONV_BUFFER_TTL_SECONDS]
        return valid[-n:]


def _conv_buffer_add(group_id, src_text, tgt_text, src_lang, tgt_lang):
    """新增一對對話到 buffer。"""
    if not group_id or not src_text or not tgt_text:
        return
    # 截長訊息 (整篇文章吃掉 cache 又對上下文沒幫助)
    src_clip = (src_text or "")[:CONV_BUFFER_MAX_LEN_PER_MSG]
    tgt_clip = (tgt_text or "")[:CONV_BUFFER_MAX_LEN_PER_MSG]
    with _conv_buffer_lock:
        if group_id not in group_conversation_buffer:
            group_conversation_buffer[group_id] = deque(maxlen=CONV_BUFFER_MAX_TURNS)
        group_conversation_buffer[group_id].append({
            "src": src_lang,
            "tgt": tgt_lang,
            "src_text": src_clip,
            "tgt_text": tgt_clip,
            "ts": time.time(),
        })


def _conv_buffer_clear(group_id):
    """清掉特定群組的 buffer (用於 admin command 或群組退出)。"""
    if not group_id:
        return
    with _conv_buffer_lock:
        group_conversation_buffer.pop(group_id, None)


def get_conv_context_enabled(group_id):
    """讀 per-group 上下文開關 (預設 ON,沒設定也開)。
    跟視覺升級無關,獨立於 group_flex_v2 的 dict 儲存。
    """
    if not group_id:
        return True
    if group_id in group_conv_settings:
        return bool(group_conv_settings[group_id])
    return True   # 預設開 (因為有 prompt caching,實際成本低)


def set_conv_context_enabled(group_id, value):
    """設 per-group 上下文開關。"""
    if not group_id:
        return False
    group_conv_settings[group_id] = bool(value)
    try:
        save_settings()
    except Exception:
        pass
    return True



def get_group_target_langs(group_id):
    """Get target language list for a group. Falls back to legacy single-lang."""
    if group_id and group_id in group_target_langs:
        v = group_target_langs[group_id]
        if isinstance(v, list):
            lst = [l for l in v if isinstance(l, str) and l in VALID_TARGETS]
            if lst:
                return lst
    legacy = group_target_lang.get(group_id, "id") if group_id else "id"
    return [legacy] if legacy in VALID_TARGETS else ["id"]


def set_group_target_langs(group_id, langs):
    """Set target langs for a group. langs = iterable of valid codes."""
    valid = []
    for l in (langs or []):
        try:
            if not isinstance(l, str):
                continue
            l = l.strip().lower()
        except Exception:
            continue
        if l in VALID_TARGETS and l not in valid:
            valid.append(l)
    if not valid:
        valid = ["id"]
    group_target_langs[group_id] = valid
    # Keep legacy field in sync (first lang) for any code path still reading it
    group_target_lang[group_id] = valid[0]
    try:
        save_settings()
    except Exception as e:
        logger.warning("save_settings failed after set_group_target_langs: %s", e)


def translate_multi(text_to_translate, src, targets, mention_placeholders=None):
    """Translate one source text to multiple targets.
    Returns list of (lang_code, translated_text). Skips failed/empty ones.

    v3.13 速度根治:多目標改並行。原本逐語言串行,每個語言都要跑完整 pipeline
    (embedding lookup + LLM + GE),2 語言 = 2 倍等待、3 語言 = 3 倍。
    並行後總等待 ≈ 最慢的那一個語言。
    供應商容災只由 ai_provider 管理。這一層不再以 force_model
    重跑整條翻譯管線，避免重複成本與 LINE 回覆逾時。
    """
    _set_translation_outcome("started", "multi_target_translation")
    real_targets = [t for t in targets if t != src]
    if not real_targets:
        _set_translation_outcome("skipped", "no_distinct_target_language")
        return []

    # 複製當前 thread-local 上下文給 worker(pipeline 依賴這些)
    _ctx = {}
    for _a in ('group_id', 'user_id', 'from_image_ocr', 'tone', 'tone_custom',
               'line_mentions', 'quoted_context_source', 'quoted_context_message_id'):
        if hasattr(_tl, _a):
            _ctx[_a] = getattr(_tl, _a)

    def _translate_one(tgt_lang, _in_worker):
        if _in_worker:
            for _k, _v in _ctx.items():
                setattr(_tl, _k, _v)
        _previous_external_mentions = getattr(
            _tl, 'external_mention_placeholders', None
        )
        if mention_placeholders:
            _tl.external_mention_placeholders = dict(mention_placeholders)
        try:
            res = None
            try:
                res = translate(text_to_translate, src, tgt_lang)
            except Exception as e:
                logger.warning("translate_multi failed src=%s tgt=%s: %s", src, tgt_lang, e)
                # ai_provider is the only retry/failover owner. Re-running the
                # entire translation pipeline here used to double the API calls,
                # exceed LINE's reply window and still end in a silent return.
                # Keep the failure observable and let the handler send one clear
                # bilingual failure notice.
                res = None
                _set_translation_outcome(
                    "failed", "translate_multi_exception", target=tgt_lang
                )
            if _is_translation_failure_sentinel(res):
                logger.warning("[LegacyFailurePurge] translate_multi dropped legacy failure payload")
                res = None
            if res and mention_placeholders:
                res = restore_mentions(res, mention_placeholders)
                res = _post_restore_mentions_guard(res, mention_placeholders)
            _entry_id = getattr(_tl, 'last_entry_id', None)
            _outcome = _get_translation_outcome()
            return res, _entry_id, _outcome
        finally:
            try:
                if _previous_external_mentions is None:
                    if hasattr(_tl, 'external_mention_placeholders'):
                        delattr(_tl, 'external_mention_placeholders')
                else:
                    _tl.external_mention_placeholders = _previous_external_mentions
            except Exception:
                pass
            if _in_worker:
                # 清 worker 執行緒殘留(executor 執行緒會被重用)
                for _k in list(_ctx.keys()) + [
                    'force_model', 'last_entry_id',
                    'external_mention_placeholders', 'translation_outcome',
                ]:
                    try:
                        if hasattr(_tl, _k):
                            delattr(_tl, _k)
                    except Exception:
                        pass

    out = []
    if len(real_targets) == 1:
        # 單目標:同執行緒直接跑,_tl 原生可用,省一次執行緒切換
        res, _, _outcome = _translate_one(real_targets[0], _in_worker=False)
        if res:
            out.append((real_targets[0], res))
            _set_translation_outcome("delivered", "multi_target_translation")
        elif _outcome.get("status") == "skipped":
            _set_translation_outcome(
                "skipped", _outcome.get("reason") or "intentional_translation_skip"
            )
        else:
            _set_translation_outcome(
                "failed", _outcome.get("reason") or "empty_or_rejected_translation"
            )
        return out

    # 多目標:並行
    futures = [(t, _MULTI_TGT_EXECUTOR.submit(_translate_one, t, True)) for t in real_targets]
    _last_entry = None
    _outcomes = []
    for tgt_lang, fut in futures:
        try:
            res, _eid, _outcome = fut.result(timeout=120)
        except Exception as e:
            logger.warning("translate_multi parallel future failed tgt=%s: %s", tgt_lang, e)
            _outcomes.append({
                "status": "failed",
                "reason": "translate_multi_future_exception",
                "target": tgt_lang,
            })
            continue
        _outcomes.append(_outcome)
        if _eid is not None:
            _last_entry = _eid
        if res:
            out.append((tgt_lang, res))
    # 保留原行為:_tl.last_entry_id 供回覆後 reaction 綁定(取最後一個成功 entry)
    if _last_entry is not None:
        try:
            _tl.last_entry_id = _last_entry
        except Exception:
            pass
    if out:
        _set_translation_outcome("delivered", "multi_target_translation")
    elif _outcomes and all(item.get("status") == "skipped" for item in _outcomes):
        _reasons = sorted({
            str(item.get("reason") or "intentional_translation_skip")
            for item in _outcomes
        })
        _set_translation_outcome("skipped", ",".join(_reasons))
    else:
        _set_translation_outcome("failed", "all_multi_target_translations_empty")
    return out


def format_multi_reply(translations):
    """translations = [(lang, text), ...] → multi-line bilingual reply.
    Single lang: '🇮🇩 result'. Multi: each on its own paragraph."""
    if not translations:
        return None
    lines = []
    for tgt_lang, res in translations:
        if not res or _is_translation_failure_sentinel(res):
            continue
        flag = LANG_FLAGS.get(tgt_lang, "")
        lines.append(("%s %s" % (flag, res)).strip())
    if not lines:
        return None
    return "\n\n".join(lines) if len(lines) > 1 else lines[0]


# ----------------------------------------------------------------------------
# B. /skipterm — dynamic do-not-translate term list (per group)
# ----------------------------------------------------------------------------
# Uses existing `extra_names_by_group` + rebuild_customer_names() pipeline.

SKIPTERM_MAX_PER_GROUP = 100
SKIPTERM_MAX_LEN = 30


def handle_skipterm_command(text, group_id):
    """Handle /skipterm command family.
    /skipterm              → list current group's terms
    /skipterm <term>       → add term
    /skipterm -<term>      → remove term
    /skipterm del <term>   → remove term (alt syntax)
    /skipterm clear        → clear this group's terms
    """
    if not group_id:
        return "⚠️ 只能在群組使用 / Hanya di grup"
    parts = text.strip().split(None, 1)
    arg = parts[1].strip() if len(parts) >= 2 else ""

    if not arg:
        # List
        terms = extra_names_by_group.get(group_id, [])
        if not terms:
            return ("📋 此群組沒有設定不翻譯詞\n"
                    "📋 Belum ada kata yang dikecualikan\n\n"
                    "用法 / Cara pakai:\n"
                    "  /skipterm <詞>      加入\n"
                    "  /skipterm -<詞>     移除\n"
                    "  /skipterm clear     全部清空")
        body = "\n".join("• " + t for t in terms)
        return "📋 不翻譯詞 ({}) / Kata dikecualikan:\n{}".format(len(terms), body)

    if arg.lower() == "clear":
        extra_names_by_group[group_id] = []
        try:
            rebuild_customer_names()
            save_settings()
        except Exception as e:
            logger.warning("skipterm clear save failed: %s", e)
        return "✅ 已清空此群組的不翻譯詞\n✅ Daftar dibersihkan"

    # remove syntax: -term  or  del term
    rm_term = None
    if arg.startswith("-"):
        rm_term = arg[1:].strip()
    elif arg.lower().startswith("del "):
        rm_term = arg[4:].strip()

    if rm_term is not None:
        if not rm_term:
            return "⚠️ 請輸入要刪除的詞 / Masukkan kata yang akan dihapus"
        cur = list(extra_names_by_group.get(group_id, []))
        if rm_term in cur:
            cur.remove(rm_term)
            extra_names_by_group[group_id] = cur
            try:
                rebuild_customer_names()
                save_settings()
            except Exception:
                pass
            return "✅ 已移除「{}」/ Dihapus".format(rm_term)
        return "⚠️ 找不到「{}」/ Tidak ditemukan".format(rm_term)

    # Otherwise: add
    term = arg
    if len(term) < 1 or len(term) > SKIPTERM_MAX_LEN:
        return "⚠️ 詞長度需 1-{} 字 / Panjang 1-{} karakter".format(
            SKIPTERM_MAX_LEN, SKIPTERM_MAX_LEN)
    cur = list(extra_names_by_group.get(group_id, []))
    if term in cur:
        return "⚠️「{}」已存在 / Sudah ada".format(term)
    if len(cur) >= SKIPTERM_MAX_PER_GROUP:
        return "⚠️ 已達上限 {} 個 / Maks {}".format(SKIPTERM_MAX_PER_GROUP, SKIPTERM_MAX_PER_GROUP)
    cur.append(term)
    extra_names_by_group[group_id] = cur
    try:
        rebuild_customer_names()
        save_settings()
    except Exception:
        pass
    return "✅ 已加入「{}」(共 {} 個)\n✅ Ditambah, total {}".format(term, len(cur), len(cur))


