_translation_action_cache = {}
_translation_action_lock = threading.Lock()
_TRANSLATION_ACTION_TTL = int(os.environ.get("TRANSLATION_ACTION_TTL", "1800"))
_TRANSLATION_ACTION_MAX = int(os.environ.get("TRANSLATION_ACTION_MAX", "500"))


def _register_translation_action_context(group_id, original_text, translated_text, src_lang, tgt_lang, msg_id=None):
    """Store source/translation server-side and return a short postback token.

    LINE postback data is limited and must not contain a full factory message.  A
    short opaque token keeps the Flex payload small while allowing one-click
    natural/literal/formal/back-check translations for the exact original text.
    """
    now = time.time()
    token = secrets.token_urlsafe(9)
    # Freeze context-bound measurement semantics together with the original
    # translation.  The action token lives much longer than media context, and
    # all three style buttons must therefore reuse the same meaning instead of
    # silently dropping (or acquiring) a work-order relation later.
    measurement_work_order_context = None
    try:
        if src_lang == "id" and tgt_lang == "zh":
            frame_fn = globals().get("_build_id_zh_measurement_frame")
            if callable(frame_fn):
                frame = frame_fn(original_text or "")
                if frame.get("active") and frame.get("complete"):
                    measurement_work_order_context = bool(frame.get("work_order_context"))
    except Exception as exc:
        logger.warning("[translation_action] measurement semantic snapshot failed open: %s", exc)

    record = {
        "group_id": group_id or "",
        "original": original_text or "",
        "translated": translated_text or "",
        "src": src_lang or "",
        "tgt": tgt_lang or "",
        "msg_id": msg_id or "",
        "expires_at": now + max(60, _TRANSLATION_ACTION_TTL),
    }
    if isinstance(measurement_work_order_context, bool):
        record["measurement_work_order_context"] = measurement_work_order_context
    with _translation_action_lock:
        expired = [k for k, v in _translation_action_cache.items()
                   if float(v.get("expires_at", 0)) <= now]
        for key in expired:
            _translation_action_cache.pop(key, None)
        if len(_translation_action_cache) >= max(20, _TRANSLATION_ACTION_MAX):
            oldest = sorted(
                _translation_action_cache.items(),
                key=lambda item: float(item[1].get("expires_at", 0)),
            )[: max(1, len(_translation_action_cache) - _TRANSLATION_ACTION_MAX + 1)]
            for key, _ in oldest:
                _translation_action_cache.pop(key, None)
        _translation_action_cache[token] = record
    return token


def _get_translation_action_context(token, group_id=None):
    if not token:
        return None
    now = time.time()
    with _translation_action_lock:
        record = _translation_action_cache.get(token)
        if not record:
            return None
        if float(record.get("expires_at", 0)) <= now:
            _translation_action_cache.pop(token, None)
            return None
        if group_id and record.get("group_id") and record.get("group_id") != group_id:
            return None
        return dict(record)


def _translation_action_handover_rows(group_id, max_rows=120):
    """Recover current-group translations from the live action cache.

    This is an independent fallback for handover summaries.  Even if the legacy
    recent-message buffer missed a row, every translation that displayed action
    buttons has enough source/target data here to build a bilingual digest.
    """
    if not group_id:
        return []
    now = time.time()
    rows = []
    with _translation_action_lock:
        for record in _translation_action_cache.values():
            if str(record.get("group_id", "") or "") != str(group_id):
                continue
            if float(record.get("expires_at", 0) or 0) <= now:
                continue
            original = str(record.get("original", "") or "").strip()
            translated = str(record.get("translated", "") or "").strip()
            src = str(record.get("src", "") or "").strip()
            tgt = str(record.get("tgt", "") or "").strip()
            if not original or not translated or not src or not tgt:
                continue
            rows.append({
                "timestamp": max(0.0, float(record.get("expires_at", 0) or 0) - max(60, _TRANSLATION_ACTION_TTL)),
                "sender": "",
                "source_language": src,
                "source_text": original,
                "translations": {tgt: translated},
            })
    rows.sort(key=lambda row: float(row.get("timestamp", 0) or 0))
    return rows[-max(1, int(max_rows or 120)):]


def _translation_variant_button(label, token, mode):
    data = (
        "action=show_language_menu&token=" + token
        if mode == "personal"
        else "action=translation_variant&mode=" + mode + "&token=" + token
    )
    return {
        "type": "button", "style": "secondary", "height": "sm",
        "adjustMode": "shrink-to-fit",
        "action": {
            "type": "postback",
            "label": label,
            "data": data,
            "displayText": label,
        },
    }


def _build_translation_action_quick_reply(group_id, original_text, translated_text,
                                          src_lang, tgt_lang, msg_id=None):
    """Build usable controls in the language of the translated result."""
    if not (PostbackAction and original_text and translated_text and src_lang and tgt_lang):
        return None
    try:
        token = _register_translation_action_context(
            group_id, original_text, translated_text, src_lang, tgt_lang, msg_id
        )
        labels = _translation_action_labels(src_lang, tgt_lang)
        items = []
        for mode in ("natural", "literal", "formal", "backcheck"):
            label = labels[mode][:20]
            items.append(QuickReplyItem(action=PostbackAction(
                label=label,
                data="action=translation_variant&mode=" + mode + "&token=" + token,
                display_text=label,
            )))
        items.extend([
            QuickReplyItem(action=PostbackAction(
                label=labels["personal"][:20],
                data="action=show_language_menu&token=" + token,
                display_text=labels["personal"][:20],
            )),
            QuickReplyItem(action=PostbackAction(
                label=labels["handover"][:20],
                data="action=handover_summary&token=" + token,
                display_text=labels["handover"][:20],
            )),
            QuickReplyItem(action=PostbackAction(
                label=labels["interpreter"][:20],
                data="action=open_interpreter&token=" + token,
                display_text=labels["interpreter"][:20],
            )),
        ])
        return QuickReply(items=items)
    except Exception as exc:
        logger.warning("translation action Quick Reply unavailable: %s", exc)
        return None

def _build_image_translation_action_quick_reply(
        group_id, original_text, translated_text, src_lang, tgt_lang,
        msg_id=None, overlay_token=None):
    """Build independently configurable actions for photo/OCR translations.

    This is separate from the normal text Quick Reply switch and from the fixed
    or custom translation-tone prompt.  Administrators can disable the whole
    photo action row or select exactly which modes are shown.
    """
    if not get_image_translation_actions_enabled(group_id):
        return None
    if not PostbackAction:
        return None

    modes = get_image_translation_action_modes(group_id)
    items = []
    token = None
    labels = _translation_action_labels(src_lang, tgt_lang)
    variant_defs = tuple((mode, labels[mode]) for mode in (
        "natural", "literal", "formal", "backcheck", "personal"
    ))
    try:
        if original_text and translated_text and src_lang and tgt_lang:
            if any(modes.get(mode, False) for mode, _label in variant_defs):
                token = _register_translation_action_context(
                    group_id, original_text, translated_text, src_lang, tgt_lang, msg_id
                )
            if token:
                for mode, label in variant_defs:
                    if not modes.get(mode, False):
                        continue
                    data = (
                        "action=show_language_menu&token=" + token
                        if mode == "personal"
                        else "action=translation_variant&mode=" + mode + "&token=" + token
                    )
                    items.append(QuickReplyItem(action=PostbackAction(
                        label=label,
                        data=data,
                        display_text=label,
                    )))

        if overlay_token and modes.get("overlay", False):
            overlay_label = "🖼 圖文對照/Gambar"
            items.append(QuickReplyItem(action=PostbackAction(
                label=overlay_label[:20],
                data="action=image_overlay&token=" + overlay_token,
                display_text=overlay_label[:20],
            )))

        return QuickReply(items=items[:13]) if items else None
    except Exception as exc:
        logger.warning("image translation action Quick Reply unavailable: %s", exc)
        return None


def _flex_v2_button_row(group_id, original_text, translated_text, tgt_lang, msg_id=None, src_lang=None):
    """LV4 互動按鈕 — 根據內容偵測決定要顯示哪幾顆按鈕。"""
    buttons = []

    # One-click quality controls.  The original/translation stay in a short-lived
    # server-side cache; postback data carries only the opaque token.
    if original_text and translated_text and src_lang and tgt_lang:
        _ctx_token = _register_translation_action_context(
            group_id, original_text, translated_text, src_lang, tgt_lang, msg_id
        )
        _labels = _translation_action_labels(src_lang, tgt_lang)
        buttons.extend([
            _translation_variant_button(_labels["natural"], _ctx_token, "natural"),
            _translation_variant_button(_labels["literal"], _ctx_token, "literal"),
            _translation_variant_button(_labels["formal"], _ctx_token, "formal"),
            _translation_variant_button(_labels["backcheck"], _ctx_token, "backcheck"),
            _translation_variant_button(_labels["personal"], _ctx_token, "personal"),
        ])

    # 偵測工單號 (ABC123, A-12345, 12345 等格式)
    wo_match = re.search(r'[A-Z]{1,5}[-\s]?\d{3,8}|\b\d{5,10}\b', (original_text or "") + " " + (translated_text or ""))
    if wo_match and is_cmd_enabled(group_id, "qry"):
        wo_id = wo_match.group(0).strip()[:50]
        # urlencode 避免特殊字元壞掉 postback parser
        _qry_data = "action=qry&q=" + urllib.parse.quote(wo_id, safe="")
        buttons.append({
            "type": "button", "style": "secondary", "height": "sm",
            "adjustMode": "shrink-to-fit",
            "action": {"type": "postback",
                       "label": "📋 儲區/Gudang",
                       "data": _qry_data,
                       "displayText": "/qry " + wo_id},
        })

    # 重唸 TTS (如果群組開了 TTS)
    if get_tts_enabled(group_id) and translated_text:
        # postback data LINE 限 300 bytes,前綴 ~30 bytes,留 ~230 bytes 給 text
        # urlencode 後 byte 數會膨脹 (中文字 1 char -> 9 bytes 編碼),所以先截更短
        _safe_text = _byte_safe_truncate(translated_text, 80)
        _enc = urllib.parse.quote(_safe_text, safe="")
        # 再次確保 urlencode 後總 length 安全
        while len(("action=tts_replay&lang=" + tgt_lang + "&t=" + _enc).encode("utf-8")) > 280 and _safe_text:
            _safe_text = _safe_text[:-1]
            _enc = urllib.parse.quote(_safe_text, safe="")
        if _safe_text:
            buttons.append({
                "type": "button", "style": "secondary", "height": "sm",
                "adjustMode": "shrink-to-fit",
                "action": {"type": "postback",
                           "label": "🔊 重播/Ulang",
                           "data": "action=tts_replay&lang=" + tgt_lang + "&t=" + _enc,
                           "displayText": "🔊 重唸 / Putar ulang"},
            })

    # v3.11 (2026-05-26): 拿掉「👎 翻錯」按鈕(歐那要求)
    # 工人仍可用打字「/wrong」標錯,後端 mark_only 模式照常運作。

    # 最多 6 顆,每列兩顆。
    # - 1 顆: 單一橫排
    # - 2-3 顆: 雙列 (避免 3 顆並排手機寬度被截)
    if not buttons:
        return None

    buttons = buttons[:6]
    rows = []
    for index in range(0, len(buttons), 2):
        rows.append({
            "type": "box", "layout": "horizontal",
            "spacing": "sm", "margin": "sm",
            "contents": buttons[index:index + 2],
        })

    return {
        "type": "box", "layout": "vertical",
        "margin": "md", "spacing": "none",
        "contents": [{"type": "separator", "margin": "none"}] + rows,
    }


def _flex_v2_text_with_spans(text, highlights=None):
    """LV6 Span — 高亮關鍵詞 (數字、客戶名、時間)。
    highlights 是 [(start, end, style), ...]。"""
    if not text or not highlights:
        return {"type": "text", "text": text, "wrap": True, "color": "#ffffff", "size": "md"}
    spans = []
    last = 0
    for start, end, style in highlights:
        if start > last:
            spans.append({"type": "span", "text": text[last:start], "color": "#ffffff"})
        spans.append({
            "type": "span", "text": text[start:end],
            "color": style.get("color", "#fbbf24"),
            "weight": style.get("weight", "bold"),
            "decoration": style.get("decoration", "none"),
        })
        last = end
    if last < len(text):
        spans.append({"type": "span", "text": text[last:], "color": "#ffffff"})
    return {"type": "text", "contents": spans, "wrap": True, "size": "md"}


def _detect_v2_highlights(text):
    """偵測文字內可以高亮的關鍵詞。回傳 [(start, end, style), ...]。
    保守做法 — 只標數字 + 時間。客戶名因為要查表所以跳過。"""
    if not text:
        return []
    spots = []
    # 時間 HH:MM
    for m in re.finditer(r'\b\d{1,2}:\d{2}\b', text):
        spots.append((m.start(), m.end(), {"color": "#60a5fa", "weight": "bold"}))
    # 工單號 / 大數字 (5+ 位數)
    for m in re.finditer(r'\b\d{5,}\b', text):
        spots.append((m.start(), m.end(), {"color": "#fbbf24", "weight": "bold"}))
    # 中文「N把」「N根」等量詞 (數字+量詞)
    for m in re.finditer(r'\d+\s*(把|根|噸|公斤|kg|m)', text):
        spots.append((m.start(), m.end(), {"color": "#fb7185", "weight": "bold"}))
    # 重疊去重 (取最早出現)
    spots.sort()
    cleaned = []
    last_end = 0
    for s, e, st in spots:
        if s >= last_end:
            cleaned.append((s, e, st))
            last_end = e
    return cleaned


def build_translation_flex_v2(original, translated, src_lang, tgt_lang,
                              sender_name_display=None, quoted_text=None,
                              group_id=None, msg_id=None):
    """v3.10 視覺升級版 translation flex。
    所有 v2 升級都看 group_flex_v2 開關決定要不要套用。
    若全部 OFF → 等同舊版 build_translation_flex 行為。
    """
    try:
        v2 = get_flex_v2_all(group_id)
        body_contents = []

        # LV1.2 Header bar (取代原本的「原文上面什麼都沒有」)
        header_block = None
        if v2["header"]:
            header_block = _flex_v2_header_bar(src_lang, tgt_lang)

        # Quote 區
        if quoted_text:
            if v2["quote"]:
                body_contents.append(_flex_v2_quote_box(quoted_text))
            else:
                # 舊版 fallback
                qt = quoted_text[:50] + "..." if len(quoted_text) > 50 else quoted_text
                body_contents.append({
                    "type": "text", "text": "↩ " + qt,
                    "size": "xxs", "color": "#6a6a7a", "wrap": True, "style": "italic",
                })
                body_contents.append({"type": "separator", "margin": "sm"})

        # Sender chip(v3.16:品牌色點 + 名字)
        if sender_name_display:
            body_contents.append(_flex_v3_sender_chip(sender_name_display, src_lang))

        # 原文區(v3.16:中性色條區塊;emphasis 關閉時放大字級)
        if v2["emphasis"]:
            body_contents.append(_flex_v3_lang_section(src_lang, original, big=False))
        else:
            sec = _flex_v3_lang_section(src_lang, original, big=False)
            try:
                sec["contents"][1]["contents"][1]["size"] = "sm"
                sec["contents"][1]["contents"][1]["color"] = "#c3c9da"
            except Exception:
                pass
            body_contents.append(sec)

        # 譯文區(v3.16:目標語品牌色條 + 大字粗體;LV6 span 開:高亮關鍵詞)
        tgt_flag_str = LANG_FLAGS.get(tgt_lang, "")
        if v2["span"]:
            highlights = _detect_v2_highlights(translated)
            tx = _flex_v2_text_with_spans(translated, highlights)
            body_contents.append({
                "type": "box", "layout": "horizontal", "margin": "sm",
                "backgroundColor": _V3_SURFACE, "cornerRadius": "8px",
                "paddingAll": "10px", "spacing": "md",
                "contents": [
                    _flex_v3_accent_bar(_LANG_BRAND.get(tgt_lang, "#7c6fef")),
                    {
                        "type": "box", "layout": "vertical", "flex": 1,
                        "contents": [
                            {"type": "text",
                             "text": tgt_flag_str + " " + LANG_NAMES_ZH.get(tgt_lang, tgt_lang.upper()),
                             "size": "xxs", "color": _V3_TEXT_MUTE, "weight": "bold"},
                            tx,
                        ],
                    },
                ],
            })
        else:
            sec = _flex_v3_lang_section(tgt_lang, translated, big=True)
            if not v2["emphasis"]:
                try:
                    sec["contents"][1]["contents"][1]["size"] = "md"
                except Exception:
                    pass
            body_contents.append(sec)

        # LV4 互動按鈕
        if v2["buttons"]:
            btn_box = _flex_v2_button_row(group_id, original, translated, tgt_lang, msg_id, src_lang)
            if btn_box:
                body_contents.append(btn_box)

        # v3.16 footer:AI 翻譯標識 + 時間戳
        body_contents.append(_flex_v3_footer_row())

        # LV7 動態 size
        size = _flex_v2_size_for(len(translated)) if v2["dynsize"] else "kilo"

        bubble = {
            "type": "bubble",
            "size": size,
            "body": {
                "type": "box", "layout": "vertical",
                "contents": body_contents,
                "backgroundColor": _V3_BG,
                "paddingAll": "14px",
                "cornerRadius": "12px",
            },
        }
        if header_block:
            bubble["header"] = {
                "type": "box", "layout": "vertical",
                "contents": [header_block],
                "paddingAll": "0px",
            }

        return FlexMessage(
            alt_text=_flex_alt_text(tgt_flag_str, translated),
            contents=FlexContainer.from_dict(bubble),
        )
    except Exception as e:
        logger.warning("build_translation_flex_v2 failed, falling back: %s", e)
        # Fallback 到舊版
        try:
            return build_translation_flex(
                original, translated,
                LANG_FLAGS.get(src_lang, ""),
                LANG_FLAGS.get(tgt_lang, ""),
                sender_name_display, quoted_text,
            )
        except Exception:
            return None


def build_multilang_flex_v2(original, translations, src_lang="zh",
                            sender_name_display=None, quoted_text=None,
                            group_id=None):
    """LV2: 多語廣播專屬 Flex - 每個目標語言獨立 box。
    translations = [(lang_code, text), ...]
    若 v2.carousel 開啟且翻譯 >= 3 種 → 改 carousel 多 bubble。
    """
    try:
        v2 = get_flex_v2_all(group_id)

        # LV3 Carousel 模式 (3+ 語言 + carousel 開啟)
        if v2["carousel"] and len(translations) >= 3:
            bubbles = []
            for lang_code, text in translations[:10]:  # carousel max 10 bubbles
                bubbles.append(_build_single_lang_bubble(
                    original, text, src_lang, lang_code,
                    sender_name_display, quoted_text, group_id, v2,
                ))
            carousel = {"type": "carousel", "contents": bubbles}
            return FlexMessage(
                alt_text="🌐 " + " + ".join(LANG_FLAGS.get(l, "") for l, _ in translations),
                contents=FlexContainer.from_dict(carousel),
            )

        # 預設:單一 bubble 包多個 sub-box
        body_contents = []
        if quoted_text and v2["quote"]:
            body_contents.append(_flex_v2_quote_box(quoted_text))
        if sender_name_display:
            body_contents.append(_flex_v3_sender_chip(sender_name_display, src_lang))
        # 原文(v3.16:中性色條區塊)
        body_contents.append(_flex_v3_lang_section(src_lang, original, big=False))

        # v3.16:每個語言一個「品牌色」語義區塊(取代舊版隨機循環背景色 —
        # 顏色現在有意義:工人看色就知道是自己的語言,跟 header 品牌色一致)
        for lang_code, text in translations:
            body_contents.append(_flex_v3_lang_section(lang_code, text, big=True))

        # v3.11 (2026-05-26): 拿掉「👎 翻錯」按鈕(歐那要求)
        # 多語模式下整段按鈕區塊都拿掉(原本只有這一顆翻錯按鈕,沒按鈕就不加 box)
        # 工人仍可用打字「/wrong」標錯。

        # v3.16 footer
        body_contents.append(_flex_v3_footer_row())

        # Header(v3.16:漸層 + 多語標示)
        header_block = None
        if v2["header"]:
            first_tgt = translations[0][0] if translations else "id"
            header_block = _flex_v2_header_bar(src_lang, first_tgt,
                                               multi=(len(translations) > 1))

        # 動態 size
        total_len = sum(len(t) for _, t in translations)
        size = _flex_v2_size_for(total_len) if v2["dynsize"] else "mega"

        bubble = {
            "type": "bubble", "size": size,
            "body": {
                "type": "box", "layout": "vertical",
                "contents": body_contents,
                "backgroundColor": _V3_BG,
                "paddingAll": "14px",
                "cornerRadius": "12px",
            },
        }
        if header_block:
            bubble["header"] = {
                "type": "box", "layout": "vertical",
                "contents": [header_block],
                "paddingAll": "0px",
            }
        alt = "🌐 " + " + ".join(LANG_FLAGS.get(l, "") for l, _ in translations[:3])
        return FlexMessage(
            alt_text=alt[:400],
            contents=FlexContainer.from_dict(bubble),
        )
    except Exception as e:
        logger.warning("build_multilang_flex_v2 failed: %s", e)
        return None


def _build_single_lang_bubble(original, translated, src_lang, tgt_lang,
                              sender_name_display, quoted_text, group_id, v2):
    """Carousel 用的單一 bubble (內部)。v3.16:同步 v3 視覺系統。"""
    body_contents = []
    if quoted_text and v2["quote"]:
        body_contents.append(_flex_v2_quote_box(quoted_text))
    if sender_name_display:
        body_contents.append(_flex_v3_sender_chip(sender_name_display, src_lang))
    body_contents.append(_flex_v3_lang_section(src_lang, original, big=False))
    body_contents.append(_flex_v3_lang_section(tgt_lang, translated, big=True))
    body_contents.append(_flex_v3_footer_row())
    bubble = {
        "type": "bubble", "size": "kilo",
        "body": {
            "type": "box", "layout": "vertical",
            "contents": body_contents,
            "backgroundColor": _V3_BG,
            "paddingAll": "14px",
            "cornerRadius": "12px",
        },
    }
    if v2["header"]:
        bubble["header"] = {
            "type": "box", "layout": "vertical",
            "contents": [_flex_v2_header_bar(src_lang, tgt_lang)],
            "paddingAll": "0px",
        }
    return bubble





def get_tts_enabled(group_id):
    """Read per-group TTS toggle (default OFF — TTS uses extra money + bandwidth)."""
    return bool(group_tts_settings.get(group_id, False))


def _tts_dir():
    """選擇可寫入目錄存放 m4a 檔案。"""
    for d in ("/var/data", "/data", "/tmp"):
        if os.path.isdir(d) and os.access(d, os.W_OK):
            return d
    return "."


def _tts_meta_path():
    return os.path.join(_tts_dir(), "tts_meta.json")


def _tts_m4a_path(token):
    return os.path.join(_tts_dir(), "tts_{}.m4a".format(token))


def _load_tts_meta():
    """從 disk 載 TTS meta + 清過期。"""
    try:
        p = _tts_meta_path()
        if not os.path.exists(p):
            return {}
        with open(p, "r", encoding="utf-8") as f:
            raw = json.load(f)
        now = time.time()
        clean = {}
        if isinstance(raw, dict):
            for k, v in raw.items():
                if isinstance(v, dict) and v.get("expires_at", 0) > now:
                    clean[k] = v
        return clean
    except Exception as e:
        logger.warning("TTS meta load failed: %s", e)
        return {}


def _save_tts_meta(meta):
    try:
        p = _tts_meta_path()
        tmp = p + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(meta, f)
        os.replace(tmp, p)
    except Exception as e:
        logger.warning("TTS meta save failed: %s", e)


def _tts_cleanup():
    """清過期: 記憶體 cache + disk 檔案"""
    now = time.time()
    with _tts_cache_lock:
        for k in [k for k, v in list(_tts_cache.items()) if v[1] < now]:
            _tts_cache.pop(k, None)
        if len(_tts_cache) > TTS_CACHE_MAX:
            for k, _ in sorted(_tts_cache.items(), key=lambda x: x[1][1])[: len(_tts_cache) - TTS_CACHE_MAX]:
                _tts_cache.pop(k, None)
    # 清 disk
    try:
        meta = _load_tts_meta()
        changed = False
        for tk in list(meta.keys()):
            if meta[tk].get("expires_at", 0) <= now:
                meta.pop(tk, None)
                changed = True
                try:
                    os.remove(_tts_m4a_path(tk))
                except FileNotFoundError:
                    pass
                except Exception:
                    pass
        if changed:
            _save_tts_meta(meta)
    except Exception as e:
        logger.warning("TTS disk cleanup failed: %s", e)


_FFMPEG_BIN = None


def _resolve_ffmpeg():
    """v3.29: 找 ffmpeg 執行檔。
    Render Free 的 Python 環境「沒有」系統 ffmpeg(也不能 apt 安裝)—
    這是 TTS 一直無聲的根因之一。根治:requirements.txt 加 imageio-ffmpeg
    (pip 套件,內含靜態 ffmpeg 二進位),這裡自動 fallback 找它。"""
    global _FFMPEG_BIN
    if _FFMPEG_BIN:
        return _FFMPEG_BIN
    import shutil
    p = shutil.which("ffmpeg")
    if p:
        _FFMPEG_BIN = p
        return p
    try:
        import imageio_ffmpeg
        _FFMPEG_BIN = imageio_ffmpeg.get_ffmpeg_exe()
        logger.info("[TTS] 使用 imageio-ffmpeg 靜態二進位: %s", _FFMPEG_BIN)
        return _FFMPEG_BIN
    except Exception:
        return None


def _ffmpeg_mp3_to_m4a(mp3_bytes):
    """Pipe mp3 → m4a via ffmpeg. Returns m4a_bytes or None.
    v3.29c 根治:mp4 的 +faststart 需要「可 seek」的輸出(要回頭改寫檔頭),
    寫到 pipe 必炸 `muxer does not support non seekable output`(Render log 實證)。
    改為輸出到暫存檔再讀回 — faststart 保留(LINE 播放需要 moov 在前)。"""
    _bin = _resolve_ffmpeg()
    if not _bin:
        logger.error("ffmpeg NOT FOUND — requirements.txt 加 imageio-ffmpeg 後重新部署即可啟用 TTS")
        return None
    import tempfile
    _tmp = tempfile.mktemp(suffix=".m4a", dir="/tmp")
    try:
        proc = subprocess.run(
            [_bin, "-y", "-loglevel", "error",
             "-i", "pipe:0",
             "-c:a", "aac", "-b:a", "64k",
             "-movflags", "+faststart",
             _tmp],
            input=mp3_bytes, capture_output=True, timeout=20, check=False,
        )
        if proc.returncode != 0:
            logger.error("ffmpeg failed rc=%s err=%s", proc.returncode,
                         (proc.stderr or b"")[:300].decode("utf-8", "ignore"))
            return None
        with open(_tmp, "rb") as f:
            return f.read()
    except FileNotFoundError:
        logger.error("ffmpeg NOT FOUND on PATH — install it to enable TTS")
        return None
    except Exception as e:
        logger.error("ffmpeg pipe error: %s", e)
        return None
    finally:
        try:
            os.remove(_tmp)
        except Exception:
            pass


def generate_tts(text, lang):
    """text → (public_url, duration_ms) or (None, 0).
    v3.10: 改用 disk 儲存 m4a,跨 gunicorn worker 共享。
    """
    if not text or not text.strip():
        return None, 0
    if not oai:
        return None, 0
    base_url = (os.environ.get("PUBLIC_URL") or "").rstrip("/")
    if not base_url:
        # silent miss — set PUBLIC_URL env to enable
        return None, 0

    text_clipped = text[:TTS_TEXT_LIMIT]
    try:
        resp = oai.audio.speech.create(
            model=TTS_MODEL,
            voice="alloy",         # voice is language-agnostic
            input=text_clipped,
            response_format="mp3",
        )
        # openai SDK returns a streaming response; handle both shapes
        if hasattr(resp, "read"):
            mp3_bytes = resp.read()
        elif hasattr(resp, "content"):
            mp3_bytes = resp.content
        else:
            mp3_bytes = bytes(resp)
    except Exception as e:
        logger.warning("OpenAI TTS failed: %s", e)
        return None, 0

    m4a_bytes = _ffmpeg_mp3_to_m4a(mp3_bytes)
    if not m4a_bytes:
        return None, 0
    # v3.10: 大小檢查 — m4a 不該超過 5MB (LINE Audio 上限 200MB,但實際我們的 TTS 不會超過 100KB)
    if len(m4a_bytes) > 5 * 1024 * 1024:
        logger.warning("TTS m4a too large (%d bytes), skipping", len(m4a_bytes))
        return None, 0

    # Rough duration estimate. ~140 chars/min for natural narration.
    duration_ms = min(60000, max(1000, len(text_clipped) * 400))

    _tts_cleanup()
    token = secrets.token_urlsafe(16)
    expires_at = time.time() + TTS_CACHE_TTL

    # 1. 寫 m4a 到 disk
    try:
        with open(_tts_m4a_path(token), "wb") as f:
            f.write(m4a_bytes)
    except Exception as e:
        logger.error("TTS m4a write failed: %s", e)
        return None, 0

    # 2. 更新 meta
    try:
        meta = _load_tts_meta()
        meta[token] = {"expires_at": expires_at, "duration_ms": duration_ms}
        _save_tts_meta(meta)
    except Exception as e:
        logger.warning("TTS meta update failed: %s", e)

    # 3. 也放記憶體 cache (同 worker 加速)
    with _tts_cache_lock:
        _tts_cache[token] = (m4a_bytes, expires_at, duration_ms)

    url = "{}/tts/{}.m4a".format(base_url, token)
    return url, duration_ms


@app.route("/tts/<token>.m4a")
def serve_tts(token):
    """LINE servers fetch the m4a from here.
    v3.10: 跨 worker 從 disk 讀,記憶體 cache 加速。"""
    # 安全檢查:token 必須 URL-safe 字元
    if not re.match(r'^[A-Za-z0-9_-]+$', token or ""):
        abort(400)
    _tts_cleanup()

    # 記憶體 cache 優先
    with _tts_cache_lock:
        entry = _tts_cache.get(token)
    if entry:
        m4a_bytes, _, _ = entry
        resp = app.response_class(m4a_bytes, mimetype="audio/mp4")
        resp.headers["Cache-Control"] = "public, max-age=300"
        return resp

    # disk fallback (其他 worker 產出的)
    try:
        path = _tts_m4a_path(token)
        if not os.path.exists(path):
            abort(404)
        meta = _load_tts_meta()
        if token not in meta or meta[token].get("expires_at", 0) <= time.time():
            abort(404)
        with open(path, "rb") as f:
            m4a_bytes = f.read()
        # 放進記憶體 cache 避免下次再讀 disk
        with _tts_cache_lock:
            _tts_cache[token] = (m4a_bytes, meta[token]["expires_at"], meta[token].get("duration_ms", 1000))
        resp = app.response_class(m4a_bytes, mimetype="audio/mp4")
        resp.headers["Cache-Control"] = "public, max-age=300"
        return resp
    except Exception as e:
        logger.warning("serve_tts disk fallback failed: %s", e)
        abort(404)


@app.route("/media/translation/<token>.jpg")
def serve_translation_overlay(token):
    """Serve a short-lived original-image + translation comparison JPEG."""
    if not re.fullmatch(r"[0-9a-f]{32}", token or ""):
        abort(400)
    _cleanup_image_overlay_store()
    path = os.path.join(_image_overlay_dir(), token + ".jpg")
    try:
        if not os.path.isfile(path):
            abort(404)
        if time.time() - os.path.getmtime(path) > max(300, _IMAGE_OVERLAY_TTL):
            try:
                os.remove(path)
            except OSError:
                pass
            abort(404)
        with open(path, "rb") as f:
            data = f.read()
        resp = app.response_class(data, mimetype="image/jpeg")
        resp.headers["Cache-Control"] = "public, max-age=600"
        return resp
    except Exception:
        abort(404)


# v3.10: TTS rate limit (per-group)
# 防止惡意/失控:每群組每分鐘最多 10 次,每天最多 100 次
_tts_usage = {}   # {group_id: [(ts1, ts2, ...), ...]}  (list of timestamps)
_tts_usage_lock = _threading_v310.Lock()
TTS_RATE_PER_MIN = 10
TTS_RATE_PER_DAY = 100


def _tts_check_rate_limit(group_id):
    """檢查是否超過 TTS 速率限制。回傳 (ok, reason)。"""
    if not group_id:
        return False, "no_group"
    now = time.time()
    with _tts_usage_lock:
        lst = _tts_usage.get(group_id, [])
        # 清掉 24 小時前的
        lst = [t for t in lst if now - t < 86400]
        # per-minute check
        recent_min = sum(1 for t in lst if now - t < 60)
        if recent_min >= TTS_RATE_PER_MIN:
            _tts_usage[group_id] = lst
            return False, "rate_per_minute"
        # per-day check
        if len(lst) >= TTS_RATE_PER_DAY:
            _tts_usage[group_id] = lst
            return False, "rate_per_day"
        # 通過 — 記錄
        lst.append(now)
        _tts_usage[group_id] = lst
        return True, "ok"


def push_tts_message(group_id, text, lang, want_reason=False):
    """Generate TTS and push as AudioMessage. Best-effort, never raises.
    v3.29: want_reason=True 時回傳 (ok, reason) 供失敗回報。"""
    def _ret(ok, reason):
        return (ok, reason) if want_reason else ok
    if not AudioMessage:
        return _ret(False, "SDK 缺 AudioMessage")
    if not group_id or not text:
        return _ret(False, "參數缺")
    # v3.10: rate limit check
    ok, reason = _tts_check_rate_limit(group_id)
    if not ok:
        logger.info("TTS rate limited for group %s: %s", group_id, reason)
        _zh = {"rate_per_minute": "本群每分鐘 %d 次上限(連按太快,等 1 分鐘)" % TTS_RATE_PER_MIN,
               "rate_per_day": "本群每日 %d 次上限(明天重置)" % TTS_RATE_PER_DAY}
        return _ret(False, _zh.get(reason, reason))
    try:
        url, dur = generate_tts(text, lang)
        if not url:
            # generate_tts 內部三關:PUBLIC_URL / OpenAI 合成 / ffmpeg 轉檔
            if not (os.environ.get("PUBLIC_URL") or "").strip():
                return _ret(False, "PUBLIC_URL 環境變數未設定")
            if not _resolve_ffmpeg():
                return _ret(False, "ffmpeg 缺(requirements.txt 加 imageio-ffmpeg)")
            if not oai:
                return _ret(False, "OpenAI key 未設定")
            return _ret(False, "合成/轉檔失敗(看 Render log 的 OpenAI TTS 或 ffmpeg 錯誤行)")
        with ApiClient(configuration) as api_client:
            api = MessagingApi(api_client)
            api.push_message(PushMessageRequest(
                to=group_id,
                messages=[AudioMessage(originalContentUrl=url, duration=dur)],
            ))
        return _ret(True, "ok")
    except Exception as e:
        logger.warning("push_tts_message failed: %s", e)
        return _ret(False, "推送失敗: " + str(e)[:80])


